import { test, expect } from '@playwright/test';

test('Explore page structure', async ({ page }) => {
  await page.goto('http://127.0.0.1:8999');
  await page.waitForLoadState('networkidle');

  // Take screenshot
  await page.screenshot({ path: 'homepage.png' });

  // List all links
  const links = await page.getByRole('link').all();
  console.log('Links found:', links.length);
  for (const link of links) {
    const text = await link.textContent();
    console.log(' -', text);
  }

  // List all buttons
  const buttons = await page.getByRole('button').all();
  console.log('Buttons found:', buttons.length);
  for (const button of buttons) {
    const text = await button.textContent();
    console.log(' -', text?.slice(0, 50));
  }
});

import { test, expect } from '@playwright/test';

test('Explore KG page', async ({ page }) => {
  await page.goto('http://127.0.0.1:8999');
  await page.waitForLoadState('networkidle');

  // Look for text containing "Knowledge"
  const knowledgeElements = await page.getByText(/knowledge/i).all();
  console.log('Knowledge elements found:', knowledgeElements.length);
  for (const elem of knowledgeElements) {
    const text = await elem.textContent();
    console.log(' -', text?.slice(0, 100));
  }

  // Try to navigate to a board first, then look for KG
  const boardButtons = await page.getByRole('button', { name: /my board/i }).all();
  if (boardButtons.length > 0) {
    console.log('Clicking My Board button');
    await boardButtons[0].click();
    await page.waitForLoadState('networkidle');

    // Now look for KG
    await page.screenshot({ path: 'board-page.png' });

    const kgButtons = await page.getByText(/kg|knowledge/i).all();
    console.log('KG elements on board page:', kgButtons.length);
    for (const elem of kgButtons) {
      const text = await elem.textContent();
      console.log(' -', text?.slice(0, 100));
    }
  }
});

import { type ReactNode, useEffect, useState } from 'react';
import { Quote, Lightbulb, Microscope, FileCheck2, Rocket } from 'lucide-react';
import { authAdapter, portalAdapter } from '@/adapters';
import toast from 'react-hot-toast';
import { useDashboardApi } from '@/services/api';
import { useDashboardStore } from '@/store/dashboard';
import { Header, Sidebar, CreateBoardModal, AgentsModal } from '@/components/layout';
import { PulseLoader } from '@/components/shared/PulseLoader';
import { PulseToaster } from '@/components/shared/PulseToaster';
import { MetricsSettingsPanel } from '@/components/layout/MetricsSettingsPanel';
import {
  BoardStageContent,
  type StageTabId,
} from '@/components/board/BoardStageContent';
import { AnalyticsPage } from '@/components/analytics';
import { GlobalKGActivityIndicator } from '@/components/knowledge/GlobalKGActivityIndicator';
import { KGHealthView } from '@/components/knowledge/KGHealthView';
import { CognitiveActionCenterView } from '@/components/knowledge/CognitiveActionCenterView';
import { ModalStackProvider, useOptionalModalStack } from '@/contexts/ModalStackContext';
import { useEscapeToClose } from '@/hooks/useEscapeToClose';
import { ModalStackRenderer } from '@/components/modals/ModalStackRenderer';
import { LineageGraphModal } from '@/components/traceability';
import { EvidenceGateSkipBanner } from '@/components/banners/EvidenceGateSkipBanner';
import { GuidedHelpProvider, guidedHelpRegistry, type GuidedHelpSurface } from '@/components/guided-help';
import { getBoardSettings } from '@/services/board-settings-api';
import { useTermsAcceptance } from '@/hooks/useTermsAcceptance';
import { TermsAcceptanceModal } from '@/components/onboarding/TermsAcceptanceModal';
import { OnboardingModal } from '@/components/onboarding/OnboardingModal';
import { isCompleted as isOnboardingCompleted } from '@/components/onboarding/onboardingStorage';
import logoLight from '@/assets/logo-light.png';
import logoDark from '@/assets/logo-dark.png';
import { CURRENT_METRICS_SCHEMA_VERSION, getMetricsSummary } from '@/services/metrics-api';
import { showErrorToast } from '@/lib/toastError';
import { usePermissions } from '@/hooks/usePermissions';

const METRICS_PROMPT_DISMISSED_KEY = `okto-pulse:metrics-opt-in-prompt-dismissed:${CURRENT_METRICS_SCHEMA_VERSION}`;

interface GuidedHelpRootProps {
  children: ReactNode;
  surface: GuidedHelpSurface;
  termsOpen: boolean;
  onboardingOpen: boolean;
  metricsPromptOpen: boolean;
  modalOpen: boolean;
  analyticsOpen: boolean;
  kgHealthOpen: boolean;
}

function GuidedHelpRoot({
  children,
  surface,
  termsOpen,
  onboardingOpen,
  metricsPromptOpen,
  modalOpen,
  analyticsOpen,
  kgHealthOpen,
}: GuidedHelpRootProps) {
  const modalStack = useOptionalModalStack();
  const suppressForModal = modalOpen && surface !== 'agents' && surface !== 'kg';
  const suppressForModalStack = (modalStack?.stack.length ?? 0) > 0 && surface !== 'specs';
  const suppressForAnalytics = analyticsOpen && surface !== 'metrics';
  const suppressForKgHealth = kgHealthOpen && surface !== 'kg';

  return (
    <GuidedHelpProvider
      registry={guidedHelpRegistry}
      surface={surface}
      suppressWhen={{
        termsOpen,
        onboardingOpen,
        metricsPromptOpen,
        modalStackActive: suppressForModal || suppressForModalStack,
        analyticsOpen: suppressForAnalytics,
        kgHealthOpen: suppressForKgHealth,
      }}
    >
      {children}
    </GuidedHelpProvider>
  );
}

interface StageTab {
  id: StageTabId;
  label: string;
  Icon: typeof Quote;
  /** icon colour when this tab is active */
  iconActive: string;
  /** muted icon colour when inactive — the stage keeps its signature hue at a glance */
  iconInactive: string;
  /** label colour applied only on the active tab */
  labelActive: string;
  /** subtle colored ring layered onto the active pill (over its white/surface base) */
  pillActiveRing: string;
}

/**
 * SDLC stage identity for the top tab switcher. Each stage carries a semantic
 * lucide icon + a signature colour that traces the funnel as a temperature arc:
 * slate (raw capture) -> amber (idea spark) -> cyan (investigation) ->
 * violet (the spec contract, brand heart) -> blue (the scheduled run) ->
 * emerald (shipped/done, reusing the kanban-done semantic).
 * Class strings are literal for Tailwind JIT (no interpolation).
 */
const STAGE_TABS: StageTab[] = [
  {
    id: 'stories',
    label: 'Stories',
    Icon: Quote,
    iconActive: 'text-slate-600 dark:text-slate-300',
    iconInactive: 'text-slate-400/80 dark:text-slate-500/70',
    labelActive: 'text-slate-700 dark:text-slate-200',
    pillActiveRing: 'ring-1 ring-slate-200 dark:ring-slate-600/40',
  },
  {
    id: 'ideations',
    label: 'Ideations',
    Icon: Lightbulb,
    iconActive: 'text-amber-500 dark:text-amber-400',
    iconInactive: 'text-amber-500/70 dark:text-amber-400/60',
    labelActive: 'text-amber-700 dark:text-amber-300',
    pillActiveRing: 'ring-1 ring-amber-200 dark:ring-amber-500/30',
  },
  {
    id: 'refinements',
    label: 'Refinements',
    Icon: Microscope,
    iconActive: 'text-cyan-600 dark:text-cyan-400',
    iconInactive: 'text-cyan-500/70 dark:text-cyan-400/60',
    labelActive: 'text-cyan-700 dark:text-cyan-300',
    pillActiveRing: 'ring-1 ring-cyan-200 dark:ring-cyan-500/30',
  },
  {
    id: 'specs',
    label: 'Specs',
    Icon: FileCheck2,
    iconActive: 'text-violet-600 dark:text-violet-400',
    iconInactive: 'text-violet-500/70 dark:text-violet-400/60',
    labelActive: 'text-violet-700 dark:text-violet-300',
    pillActiveRing: 'ring-1 ring-violet-200 dark:ring-violet-500/30',
  },
  {
    id: 'tasks',
    label: 'Tasks',
    Icon: Rocket,
    iconActive: 'text-emerald-600 dark:text-emerald-400',
    iconInactive: 'text-emerald-500/70 dark:text-emerald-400/60',
    labelActive: 'text-emerald-700 dark:text-emerald-300',
    pillActiveRing: 'ring-1 ring-emerald-200 dark:ring-emerald-500/30',
  },
];

function App() {
  const api = useDashboardApi();
  const { isLoaded, isSignedIn } = authAdapter.useAuth();
  const terms = useTermsAcceptance();
  const currentBoard = useDashboardStore((s) => s.currentBoard);
  const boardError = useDashboardStore((s) => s.error);
  const permissions = usePermissions(currentBoard?.id);
  const policyAuthorityReady = (
    !permissions.isLoading
    && !permissions.error
    && !permissions.ownerReviewRequired
  );
  const canReadKGHealth = policyAuthorityReady && permissions.has('kg.operations.health.read');
  const canReadKGCognitive = policyAuthorityReady && permissions.has('kg.operations.cognitive.read');
  const canCreateBoard = permissions.has('board.admin.create');
  const canDeleteBoard = permissions.has('board.admin.delete');
  const canOpenAgents = [
    'agent.entity.read',
    'agent.entity.create',
    'agent.entity.edit',
    'agent.entity.delete',
    'agent.api_key.rotate',
    'agent.board_access.read',
    'agent.board_access.grant',
    'agent.board_access.edit',
    'agent.board_access.revoke',
  ].some((flag) => permissions.has(flag));
  const canOpenBoardShares = [
    'board.share.read',
    'board.share.create',
    'board.share.edit',
    'board.share.revoke',
    'board.share.leave',
  ].some((flag) => permissions.has(flag));
  const setBoards = useDashboardStore((s) => s.setBoards);
  const setSharedBoards = useDashboardStore((s) => s.setSharedBoards);
  const setCurrentBoard = useDashboardStore((s) => s.setCurrentBoard);
  const setColumns = useDashboardStore((s) => s.setColumns);
  const setLoading = useDashboardStore((s) => s.setLoading);
  const setError = useDashboardStore((s) => s.setError);

  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [createBoardOpen, setCreateBoardOpen] = useState(false);
  const [agentsModalOpen, setAgentsModalOpen] = useState(false);
  const [shareModalOpen, setShareModalOpen] = useState(false);
  const [helpPanelOpen, setHelpPanelOpen] = useState(false);
  const [knowledgeGraphOpen, setKnowledgeGraphOpen] = useState(false);
  const [portalBarVisible, setPortalBarVisible] = useState(true);
  const [onboardingOpen, setOnboardingOpen] = useState(false);
  const [metricsPromptOpen, setMetricsPromptOpen] = useState(false);

  // Mount the OnboardingModal on the *first* render after Terms is accepted
  // (or skipped via CLI/env), but only if the user has not completed it yet.
  // Returning users (flag set) never see it — no flash, no nag.
  useEffect(() => {
    if (terms.loading) return;
    if (terms.needsAcceptance) return;
    if (isOnboardingCompleted()) return;
    setOnboardingOpen(true);
  }, [terms.loading, terms.needsAcceptance]);

  useEffect(() => {
    if (!isLoaded || !isSignedIn) return;
    if (terms.loading || terms.needsAcceptance || onboardingOpen) return;
    if (window.localStorage.getItem(METRICS_PROMPT_DISMISSED_KEY)) return;

    let active = true;
    getMetricsSummary()
      .then((summary) => {
        const hasStaleConsent =
          summary.source === 'stale_persisted_consent' ||
          summary.beacon_status.schema_status === 'stale_consent';
        const hasDecision = Boolean(summary.consent.changed_at) && !hasStaleConsent;
        if (active && ((summary.source === 'default' && !hasDecision) || hasStaleConsent)) {
          setMetricsPromptOpen(true);
        }
      })
      .catch(() => undefined);

    return () => {
      active = false;
    };
  }, [isLoaded, isSignedIn, terms.loading, terms.needsAcceptance, onboardingOpen]);

  const closeMetricsPrompt = () => {
    window.localStorage.setItem(METRICS_PROMPT_DISMISSED_KEY, new Date().toISOString());
    setMetricsPromptOpen(false);
  };
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [refreshKey, setRefreshKey] = useState(0);
  const [skipEvidenceActive, setSkipEvidenceActive] = useState(false);
  const [activeTab, setActiveTab] = useState<StageTabId>('stories');
  const [showAnalytics, setShowAnalytics] = useState(
    () => typeof window !== 'undefined' && window.location.pathname.startsWith('/analytics'),
  );
  const [showKGHealth, setShowKGHealth] = useState(
    () => typeof window !== 'undefined' && window.location.pathname.startsWith('/kg-health'),
  );
  const [showCognitiveActionCenter, setShowCognitiveActionCenter] = useState(
    () =>
      typeof window !== 'undefined' &&
      window.location.pathname.startsWith('/cognitive-action-center'),
  );
  const guidedHelpSurface: GuidedHelpSurface = showAnalytics
    ? 'metrics'
    : showKGHealth
      ? 'kg'
      : knowledgeGraphOpen
        ? 'kg'
        : helpPanelOpen
          ? 'help'
          : agentsModalOpen
            ? 'agents'
            : activeTab === 'specs'
              ? 'specs'
              : activeTab === 'tasks'
                ? 'tasks'
                : 'board';

  // Mantém showAnalytics e showKGHealth sincronizados com back/forward do browser.
  useEffect(() => {
    const handlePopstate = () => {
      setShowAnalytics(window.location.pathname.startsWith('/analytics'));
      setShowKGHealth(window.location.pathname.startsWith('/kg-health'));
      setShowCognitiveActionCenter(
        window.location.pathname.startsWith('/cognitive-action-center'),
      );
    };
    window.addEventListener('popstate', handlePopstate);
    return () => window.removeEventListener('popstate', handlePopstate);
  }, []);

  // Cognitive Action Center opens via a custom event (dispatched from the KG
  // Health header drill-down), mirroring the okto:open-board-settings pattern.
  useEffect(() => {
    const open = () => {
      if (!canReadKGCognitive) return;
      if (!window.location.pathname.startsWith('/cognitive-action-center')) {
        window.history.pushState({}, '', '/cognitive-action-center');
      }
      setShowCognitiveActionCenter(true);
    };
    window.addEventListener('okto:open-cognitive-action-center', open);
    return () => window.removeEventListener('okto:open-cognitive-action-center', open);
  }, [canReadKGCognitive]);

  // NC-9 Wave 2 frontend (spec 5cb09dbc): poll board settings to drive the
  // EvidenceGateSkipBanner. Re-runs when the active board changes or when
  // the operator toggles via the Board settings panel (custom
  // event refreshes the flag without a reload).
  //
  // Bug fix (board d0f6bab2): always reset to false on (re-)mount and on
  // board switch BEFORE the new fetch resolves. Without this, switching
  // from a board with skip=true to one with skip=false (or hitting a
  // transient backend error from the lock-contention bug) left the banner
  // "stuck" as SKIP ACTIVE because the catch path silently kept the prior
  // value. Reset-then-refresh guarantees the banner reflects the GET, not
  // the last-rendered state of a different board.
  useEffect(() => {
    setSkipEvidenceActive(false);
    if (!currentBoard) {
      return;
    }
    let active = true;
    const refresh = () => {
      getBoardSettings(currentBoard.id)
        .then((s) => {
          if (active) setSkipEvidenceActive(s?.skip_test_evidence_global ?? false);
        })
        .catch((err) => {
          // Non-fatal: keep banner OFF so we never show a stale "skip
          // active" warning when we can't actually confirm it from the
          // backend. Logged for diagnostics.
          if (active) {
            setSkipEvidenceActive(false);
            // eslint-disable-next-line no-console
            console.warn('[evidence-gate] settings fetch failed:', err);
          }
        });
    };
    refresh();
    const handler = () => refresh();
    window.addEventListener('okto:board-settings-changed', handler);
    return () => {
      active = false;
      window.removeEventListener('okto:board-settings-changed', handler);
    };
  }, [currentBoard?.id]);

  const openBoardSettings = () => {
    window.dispatchEvent(new CustomEvent('okto:open-board-settings'));
  };

  const openAnalytics = () => {
    if (!window.location.pathname.startsWith('/analytics')) {
      window.history.pushState({}, '', '/analytics');
    }
    setShowAnalytics(true);
  };

  const closeAnalytics = () => {
    if (window.location.pathname.startsWith('/analytics')) {
      window.history.pushState({}, '', '/');
    }
    setShowAnalytics(false);
  };

  const openKGHealth = () => {
    if (!canReadKGHealth) return;
    if (!window.location.pathname.startsWith('/kg-health')) {
      window.history.pushState({}, '', '/kg-health');
    }
    setShowKGHealth(true);
  };

  const closeKGHealth = () => {
    if (window.location.pathname.startsWith('/kg-health')) {
      window.history.pushState({}, '', '/');
    }
    setShowKGHealth(false);
  };

  const closeCognitiveActionCenter = () => {
    if (window.location.pathname.startsWith('/cognitive-action-center')) {
      window.history.pushState({}, '', '/');
    }
    setShowCognitiveActionCenter(false);
  };

  useEscapeToClose(closeAnalytics, { enabled: showAnalytics });
  useEscapeToClose(closeKGHealth, { enabled: showKGHealth });
  useEscapeToClose(closeCognitiveActionCenter, { enabled: showCognitiveActionCenter });

  useEffect(() => {
    if (isLoaded && isSignedIn) {
      loadBoards();
    }
  }, [isLoaded, isSignedIn]);

  const loadBoards = async () => {
    setLoading(true);
    setError(null);
    try {
      const [myBoards, shared] = await Promise.all([
        api.listBoards(0, 100, 'my'),
        api.listBoards(0, 100, 'shared'),
      ]);
      setBoards(myBoards);
      setSharedBoards(shared);
      const allBoards = [...myBoards, ...shared];
      if (allBoards.length > 0 && !currentBoard) {
        await selectBoard(allBoards[0].id);
      }
    } catch (error) {
      setError('Failed to load boards');
      showErrorToast(error, 'Failed to load boards');
    } finally {
      setLoading(false);
    }
  };

  const selectBoard = async (boardId: string) => {
    setLoading(true);
    try {
      const board = await api.getBoard(boardId);
      setCurrentBoard(board);
    } catch (error) {
      setError('Failed to load board');
      showErrorToast(error, 'Failed to load board');
    } finally {
      setLoading(false);
    }
  };

  const refreshBoard = async () => {
    if (!currentBoard) return;
    setIsRefreshing(true);
    try {
      const board = await api.getBoard(currentBoard.id);
      setCurrentBoard(board);
      setRefreshKey((k) => k + 1);
      toast.success('Board refreshed!');
    } catch (error) {
      showErrorToast(error, 'Failed to refresh board');
    } finally {
      setIsRefreshing(false);
    }
  };

  const deleteBoard = async () => {
    if (!currentBoard || !canDeleteBoard) return;
    if (!confirm(`Delete board "${currentBoard.name}" and all its cards? This cannot be undone.`)) return;
    try {
      await api.deleteBoard(currentBoard.id);
      setCurrentBoard(null);
      setColumns({} as any);
      await loadBoards();
      toast.success('Board deleted');
    } catch (error) {
      showErrorToast(error, 'Failed to delete board');
    }
  };

  if (!isLoaded) {
    return <PulseLoader fullScreen size="lg" label="Loading..." />;
  }

  if (!isSignedIn) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-surface-50 dark:bg-surface-950">
        <div className="text-center">
          <img src={logoLight} alt="Okto Pulse" className="h-20 w-20 mx-auto mb-4 rounded-xl dark:hidden" />
          <img src={logoDark} alt="Okto Pulse" className="h-20 w-20 mx-auto mb-4 rounded-xl hidden dark:block" />
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white mb-2">
            Okto Pulse
          </h1>
          <p className="text-gray-500 dark:text-gray-400">Sign in to continue</p>
        </div>
      </div>
    );
  }

  return (
    <ModalStackProvider>
    <GuidedHelpRoot
      surface={guidedHelpSurface}
      termsOpen={terms.needsAcceptance}
      onboardingOpen={onboardingOpen}
      metricsPromptOpen={metricsPromptOpen}
      modalOpen={createBoardOpen || agentsModalOpen || shareModalOpen || knowledgeGraphOpen}
      analyticsOpen={showAnalytics}
      kgHealthOpen={showKGHealth}
    >
    {terms.needsAcceptance && (
      <TermsAcceptanceModal onAccept={terms.accept} />
    )}
    {onboardingOpen && (
      <OnboardingModal onClose={() => setOnboardingOpen(false)} />
    )}
    {metricsPromptOpen && !terms.needsAcceptance && !onboardingOpen && (
      <MetricsSettingsPanel
        boardId={currentBoard?.id}
        initialPrompt
        onClose={closeMetricsPrompt}
      />
    )}
    <div className={`flex h-screen min-h-0 flex-col overflow-hidden bg-surface-50 dark:bg-surface-950 ${terms.needsAcceptance ? 'pointer-events-none select-none' : ''}`}>
      {portalAdapter.PortalBar && (
        <portalAdapter.PortalBar
          visible={portalBarVisible}
          onToggleVisibility={() => setPortalBarVisible((v) => !v)}
        />
      )}
      <EvidenceGateSkipBanner
        skipActive={skipEvidenceActive}
        onOpenBoardSettings={openBoardSettings}
      />
      <Header
        onCreateBoard={() => { if (canCreateBoard) setCreateBoardOpen(true); }}
        onOpenAgents={() => { if (canOpenAgents) setAgentsModalOpen(true); }}
        onShareBoard={() => { if (canOpenBoardShares) setShareModalOpen(true); }}
        onRefreshBoard={refreshBoard}
        onDeleteBoard={deleteBoard}
        onBoardUpdated={refreshBoard}
        onOpenAnalytics={openAnalytics}
        onOpenKGHealth={canReadKGHealth ? openKGHealth : undefined}
        helpOpen={helpPanelOpen}
        onHelpOpenChange={setHelpPanelOpen}
        knowledgeGraphOpen={knowledgeGraphOpen}
        onKnowledgeGraphOpenChange={setKnowledgeGraphOpen}
        isRefreshing={isRefreshing}
        sidebarOpen={sidebarOpen}
        onToggleSidebar={() => setSidebarOpen((v) => !v)}
      />
      <PulseToaster />

      <div className="flex min-h-0 flex-1 overflow-hidden">
        <Sidebar
          isOpen={sidebarOpen}
          onSelectBoard={selectBoard}
          onCreateBoard={() => { if (canCreateBoard) setCreateBoardOpen(true); }}
          canCreateBoard={canCreateBoard}
        />

        <main className="flex min-h-0 flex-1 min-w-0 flex-col overflow-hidden p-4">
          {currentBoard ? (
            <>
              {/* Tab switcher */}
              <div
                className="flex max-w-full shrink-0 items-center gap-1 mb-4 overflow-x-auto bg-surface-200/60 dark:bg-surface-800/60 backdrop-blur-sm rounded-xl p-0.5 w-fit border border-surface-200/40 dark:border-surface-700/30"
                data-tour-id="board.tabs"
                role="group"
                aria-label="Board views"
              >
                {STAGE_TABS.map((tab) => {
                  const isActive = activeTab === tab.id;
                  const Icon = tab.Icon;
                  return (
                    <button
                      key={tab.id}
                      onClick={() => setActiveTab(tab.id)}
                      title={tab.label}
                      aria-pressed={isActive}
                      className={`flex shrink-0 items-center gap-1.5 px-3.5 py-1.5 rounded-lg text-sm font-medium transition-all duration-200 ${
                        isActive
                          ? `bg-white dark:bg-surface-700 shadow-sm ${tab.pillActiveRing} ${tab.labelActive}`
                          : 'text-surface-500 dark:text-surface-400 hover:text-surface-900 dark:hover:text-white'
                      }`}
                    >
                      <Icon
                        size={15}
                        className={`shrink-0 transition-colors ${isActive ? tab.iconActive : tab.iconInactive}`}
                      />
                      {tab.label}
                    </button>
                  );
                })}
              </div>

              {/* Content */}
              <div className="min-h-0 min-w-0 flex-1 overflow-hidden">
                <BoardStageContent
                  activeTab={activeTab}
                  boardId={currentBoard.id}
                  refreshKey={refreshKey}
                />
              </div>
            </>
          ) : (
            <div className="h-full flex items-center justify-center">
              <div className="text-center text-gray-500 dark:text-gray-400">
                <p className="mb-4" role={boardError ? 'alert' : undefined}>
                  {boardError ?? 'Select or create a board to get started'}
                </p>
                {boardError ? (
                  <button onClick={() => void loadBoards()} className="btn btn-secondary">
                    Reload boards
                  </button>
                ) : (
                <button
                  onClick={() => { if (canCreateBoard) setCreateBoardOpen(true); }}
                  disabled={!canCreateBoard}
                  className="btn btn-primary"
                >
                  Create Board
                </button>
                )}
              </div>
            </div>
          )}
        </main>
      </div>

      <CreateBoardModal
        isOpen={createBoardOpen}
        onClose={() => setCreateBoardOpen(false)}
        boardId={currentBoard?.id}
      />

      <AgentsModal
        isOpen={agentsModalOpen}
        onClose={() => setAgentsModalOpen(false)}
      />

      {currentBoard && portalAdapter.ShareBoardModal && (
        <portalAdapter.ShareBoardModal
          isOpen={shareModalOpen}
          onClose={() => setShareModalOpen(false)}
          boardId={currentBoard.id}
          boardName={currentBoard.name}
        />
      )}

      {/* Cross-app indicator: reflects KG consolidation work for the current
          board in every tab, not only when the KG page is mounted. */}
      <GlobalKGActivityIndicator boardId={currentBoard?.id ?? null} />

      {/* Analytics fullscreen overlay */}
      {showAnalytics && (
        <div className="fixed inset-0 z-50 bg-gray-50 dark:bg-gray-900 flex flex-col">
          <div className="bg-white dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700 px-8 py-3 flex items-center justify-between shrink-0">
            <h1 className="text-lg font-bold text-gray-900 dark:text-white">Analytics</h1>
            <button
              onClick={closeAnalytics}
              className="btn btn-secondary text-sm"
            >
              ← Back to Board
            </button>
          </div>
          <div className="flex-1 overflow-auto">
            <AnalyticsPage />
          </div>
        </div>
      )}

      {/* KG Health fullscreen overlay (spec d754d004) */}
      {showKGHealth && canReadKGHealth && (
        <div className="fixed inset-0 z-50 bg-gray-50 dark:bg-gray-900 flex flex-col">
          <KGHealthView onClose={closeKGHealth} />
        </div>
      )}

      {/* Cognitive Action Center fullscreen overlay (spec 2731a346 / S3.3) */}
      {showCognitiveActionCenter && currentBoard && canReadKGCognitive && (
        <div className="fixed inset-0 z-50 bg-gray-50 dark:bg-gray-900 flex flex-col">
          <CognitiveActionCenterView
            boardId={currentBoard.id}
            boardName={currentBoard.name}
            onOpenHealth={() => { closeCognitiveActionCenter(); openKGHealth(); }}
            onClose={closeCognitiveActionCenter}
          />
        </div>
      )}

      {/* Root-level drill-down modal renderer — ideação c13f7bd3.
          Mounted here so it's visible from every tab (including
          Knowledge, where the usual entity modals aren't hosted). */}
      {currentBoard && <LineageGraphModal boardId={currentBoard.id} />}
      {currentBoard && <ModalStackRenderer boardId={currentBoard.id} />}
    </div>
    </GuidedHelpRoot>
    </ModalStackProvider>
  );
}

