}) {
  return (
    <div className="flex items-center gap-2 bg-gray-50 dark:bg-gray-700/50 rounded-lg px-3 py-2">
      <div className="text-gray-400">{icon}</div>
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400">
          <span>{label}</span>
          <MetricHelp label={label} description={help.description} targetId={help.targetId} />
        </div>
        <div className="text-sm font-semibold text-gray-900 dark:text-white">{value}</div>
      </div>
    </div>
  );
}

function pctFrom(linked: number, total: number): number {
  return total > 0 ? Math.round((linked / total) * 100) : 0;
}

function coverageItemId(item: any, index: number, prefix: string): string {
  if (item && typeof item === 'object') {
    return String(item.id ?? item.requirement_id ?? item.key ?? `${prefix}-${index}`);
  }
  return `${prefix}-${index}`;
}

function displayText(value: any, fallback: string): string {
  if (value == null || value === '') return fallback;
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) {
    const rendered = value
      .map((item, index) => displayText(item, `#${index}`))
      .filter(Boolean)
      .join(', ');
    return rendered || fallback;
  }
  if (typeof value === 'object') {
    return displayText(
      value.title ?? value.text ?? value.description ?? value.requirement ?? value.rule ?? value.id,
      fallback,
    );
  }
  return fallback;
}

function coverageItemTitle(item: any, index: number, prefix: string): string {
  if (typeof item === 'string') return item;
  if (item && typeof item === 'object') {
    return displayText(item.title ?? item.text ?? item.description ?? item.requirement ?? item.id, `${prefix.toUpperCase()} #${index}`);
  }
  return `${prefix.toUpperCase()} #${index}`;
}

function itemHasLinkedTask(item: any): boolean | null {
  if (!item || typeof item !== 'object' || !Array.isArray(item.linked_task_ids)) return null;
  return item.linked_task_ids.length > 0;
}

// ---------------------------------------------------------------------------
// Spec Detail View
// ---------------------------------------------------------------------------

function SpecDetailView({ data }: { data: SpecAnalytics }) {
  const implCards = data.cards.filter((c) => !c.is_test);
  const testCards = data.cards.filter((c) => c.is_test);
  const avgCompleteness =
    implCards.length > 0
      ? Math.round(implCards.reduce((s, c) => s + (c.completeness ?? 0), 0) / implCards.length)
      : null;
  const avgDrift =
    implCards.length > 0
      ? Math.round(implCards.reduce((s, c) => s + (c.drift ?? 0), 0) / implCards.length)
      : null;
  const coverageSummary = data.coverage_summary ?? {};
  const integrationRequirements = data.integration_requirements ?? [];
  const observabilityRequirements = data.observability_requirements ?? [];
  const irUncoveredIds = coverageSummary.irs_uncovered_ids ?? [];
  const orUncoveredIds = coverageSummary.ors_uncovered_ids ?? [];
  const irTotal = coverageSummary.irs_total ?? integrationRequirements.length;
  const orTotal = coverageSummary.ors_total ?? observabilityRequirements.length;
  const irLinked = coverageSummary.irs_linked ?? Math.max(0, irTotal - irUncoveredIds.length);
  const orLinked = coverageSummary.ors_linked ?? Math.max(0, orTotal - orUncoveredIds.length);
  const irCoverage = coverageSummary.ir_task_linkage_pct ?? pctFrom(irLinked, irTotal);
  const orCoverage = coverageSummary.or_task_linkage_pct ?? pctFrom(orLinked, orTotal);
  const hasIrDetails = irTotal > 0 || integrationRequirements.length > 0 || coverageSummary.skip_ir_coverage !== undefined;
  const hasOrDetails = orTotal > 0 || observabilityRequirements.length > 0 || coverageSummary.skip_or_coverage !== undefined;

  // Scenario status counts
  const scenarioCounts: Record<string, number> = {};
  for (const sc of data.scenario_statuses) {
    scenarioCounts[sc.status] = (scenarioCounts[sc.status] || 0) + 1;
  }
  const totalScenarios = data.scenario_statuses.length;
  const scenarioColors: Record<string, string> = {
    draft: 'bg-gray-400',
    ready: 'bg-blue-500',
    automated: 'bg-cyan-500',
    passed: 'bg-emerald-500',
    failed: 'bg-red-500',
  };

  return (
    <div className="space-y-4">
      {/* Header */}
      <Card>
        <div className="flex items-start justify-between gap-4 mb-4">
          <div className="min-w-0">
            <div className="flex items-center gap-2 mb-1">
              {statusBadge(data.status)}
              <h2 className="text-lg font-bold text-gray-900 dark:text-white truncate">{data.title}</h2>
              <SpecEditionLabel
                edition={data.edition}
                technicalRevision={data.version}
                className="shrink-0 text-xs text-gray-400"
              />
            </div>
            {(data.derivation.ideation_id || data.derivation.refinement_id) && (
              <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                Provenance:{' '}
                {data.derivation.ideation_id && (
                  <span className="font-mono text-xs">Ideation {data.derivation.ideation_id.slice(0, 8)}</span>
                )}
                {data.derivation.ideation_id && data.derivation.refinement_id && ' / '}
                {data.derivation.refinement_id && (
                  <span className="font-mono text-xs">Refinement {data.derivation.refinement_id.slice(0, 8)}</span>
                )}
              </p>
            )}
          </div>
          {data.avg_cycle_hours != null && (
            <div className="flex items-center gap-1.5 text-sm text-gray-600 dark:text-gray-300 shrink-0">
              <Clock className="w-4 h-4" />
              <span>Cycle: {formatHours(data.avg_cycle_hours)}</span>
            </div>
          )}
        </div>
        <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-10 gap-3">
          <KpiMini label="Tasks" value={data.cards.length} icon={<FileText className="w-4 h-4" />} />
          <KpiMini
            label="Completeness"
            value={avgCompleteness != null ? `${avgCompleteness}%` : '--'}
            icon={<Target className="w-4 h-4" />}
          />
          <KpiMini
            label="Drift"
            value={avgDrift != null ? `${avgDrift}%` : '--'}
            icon={<AlertTriangle className="w-4 h-4" />}
          />
          <KpiMini
            label="Test coverage"
            value={testCards.length > 0 ? `${testCards.length} tests` : '--'}
            icon={<CheckCircle className="w-4 h-4" />}
          />
          <KpiMini
            label="Business Rules"
            value={`${(data.business_rules || []).length} (${data.rules_coverage ?? 0}%)`}
            icon={<Scale className="w-4 h-4" />}
          />
          <KpiMini
            label="API Contracts"
            value={`${(data.api_contracts || []).length} (${data.contracts_coverage ?? 0}%)`}
            icon={<Globe className="w-4 h-4" />}
          />
          {/* Spec 233eaad3: TRs e Decisions KPIs com badge vermelho condicional */}
          <div className="relative">
            <KpiMiniWithHelp
              label="TRs"
              value={`${(data.technical_requirements || []).length} (${data.trs_coverage ?? 0}%)`}
              icon={<Target className="w-4 h-4 text-purple-500" />}
              help={{
                description: 'Technical Requirements coverage counts active linked tasks and excludes cancelled work.',
                targetId: 'analytics-tr-detail',
              }}
            />
            {(data.trs_uncovered_indices?.length ?? 0) > 0 && (
              <span
                className="absolute top-1 right-1 px-1 py-0.5 rounded text-[8px] font-bold bg-red-500 text-white"
                title={`${data.trs_uncovered_indices?.length} uncovered`}
              >
                !
              </span>
            )}
          </div>
          {hasIrDetails && (
            <div className="relative">
              <KpiMiniWithHelp
                label="IRs"
                value={coverageSummary.skip_ir_coverage ? `${irTotal} (skip)` : `${irTotal} (${irCoverage}%)`}
                icon={<GitBranch className="w-4 h-4 text-sky-500" />}
                help={{
                  description: 'Integration Requirement coverage shows which integration contracts are linked to active tasks.',
                  targetId: 'analytics-ir-detail',
                }}
              />
              {!coverageSummary.skip_ir_coverage && irUncoveredIds.length > 0 && (
                <span
                  className="absolute top-1 right-1 px-1 py-0.5 rounded text-[8px] font-bold bg-red-500 text-white"
                  title={`${irUncoveredIds.length} uncovered`}
                >
                  !
                </span>
              )}
            </div>
          )}
          {hasOrDetails && (
            <div className="relative">
              <KpiMiniWithHelp
                label="ORs"
                value={coverageSummary.skip_or_coverage ? `${orTotal} (skip)` : `${orTotal} (${orCoverage}%)`}
                icon={<AlertTriangle className="w-4 h-4 text-teal-500" />}
                help={{
                  description: 'Observability Requirement coverage shows which telemetry and operations requirements are linked to active tasks.',
                  targetId: 'analytics-or-detail',
                }}
              />
              {!coverageSummary.skip_or_coverage && orUncoveredIds.length > 0 && (
                <span
                  className="absolute top-1 right-1 px-1 py-0.5 rounded text-[8px] font-bold bg-red-500 text-white"
                  title={`${orUncoveredIds.length} uncovered`}
                >
                  !
                </span>
              )}
            </div>
          )}
          <div className="relative">
            <KpiMiniWithHelp
              label="Decisions"
              value={`${(data.decisions || []).length} (${data.decisions_planning ?? 0}%)`}
              icon={<Scale className="w-4 h-4 text-indigo-500" />}
              help={{
                description: 'Decision coverage shows active decisions linked to implementation or test tasks.',
                targetId: 'analytics-decisions-detail',
              }}
            />
            {(data.decisions_pending_ids?.length ?? 0) > 0 && (
              <span
                className="absolute top-1 right-1 px-1 py-0.5 rounded text-[8px] font-bold bg-red-500 text-white"
                title={`${data.decisions_pending_ids?.length} uncovered`}
              >
                !
              </span>
            )}
          </div>
          {(data.bugs_count ?? 0) > 0 && (
            <KpiMini
              label="Bugs"
              value={`${data.bugs_count} (${data.cards.length > 0 ? Math.round(((data.bugs_count ?? 0) / data.cards.length) * 100) : 0}%)`}
              icon={<Bug className="w-4 h-4 text-red-500" />}
            />
          )}
        </div>
      </Card>

      {/* AC Coverage + Scenario Status */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* AC Coverage */}
        <Card id="analytics-ac-detail">
          <SectionTitle>AC Coverage ({data.covered_ac}/{data.total_ac})</SectionTitle>
          {data.total_ac === 0 ? (
            <p className="text-xs text-gray-400">No acceptance criteria defined.</p>
          ) : (
            <div className="space-y-1.5 max-h-64 overflow-y-auto">
              {(data.ac_details || Array.from({ length: data.total_ac }, (_, i) => ({
                index: i, text: `AC #${i}`, covered: i < data.covered_ac,
              }))).map((ac: any) => (
                <div key={ac.index} className="flex items-start gap-2 text-xs">
                  {ac.covered ? (
                    <CheckCircle className="w-3.5 h-3.5 text-emerald-500 shrink-0 mt-0.5" />
                  ) : (
                    <XCircle className="w-3.5 h-3.5 text-gray-300 dark:text-gray-600 shrink-0 mt-0.5" />
                  )}
                  <span className={`${ac.covered ? 'text-gray-700 dark:text-gray-300' : 'text-gray-400 dark:text-gray-500'} line-clamp-2`}>
                    {displayText(ac.text, `AC #${ac.index}`)}
                  </span>
                </div>
              ))}
            </div>
          )}
        </Card>

        {/* Scenario Status */}
        <Card>
          <SectionTitle>Test Scenario Status ({totalScenarios})</SectionTitle>
          {totalScenarios === 0 ? (
            <p className="text-xs text-gray-400">No test scenarios defined.</p>
          ) : (
            <div className="space-y-3">
              {/* Stacked bar */}
              <div className="flex h-5 rounded-full overflow-hidden">
                {Object.entries(scenarioCounts).map(([st, count]) => (
                  <div
                    key={st}
                    className={`${scenarioColors[st] || 'bg-gray-400'}`}
                    style={{ width: `${(count / totalScenarios) * 100}%` }}
                    title={`${st}: ${count}`}
                  />
                ))}
              </div>
              {/* Legend */}
              <div className="flex flex-wrap gap-3">
                {Object.entries(scenarioCounts).map(([st, count]) => (
                  <div key={st} className="flex items-center gap-1.5 text-xs text-gray-600 dark:text-gray-300">
                    <div className={`w-2.5 h-2.5 rounded-full ${scenarioColors[st] || 'bg-gray-400'}`} />
                    <span className="capitalize">{st}</span>
                    <span className="font-semibold">{count}</span>
                  </div>
                ))}
              </div>
              {/* Scenario list */}
              <div className="space-y-1 max-h-48 overflow-y-auto">
                {data.scenario_statuses.map((sc) => (
                  <div key={sc.id} className="flex items-center justify-between text-xs py-1 border-b border-gray-100 dark:border-gray-700 last:border-0">
                    <span className="text-gray-700 dark:text-gray-300 truncate mr-2">{sc.title}</span>
                    {statusBadge(sc.status)}
                  </div>
                ))}
              </div>
            </div>
          )}
        </Card>
      </div>

      {/* IR + OR Coverage panels */}
      {(hasIrDetails || hasOrDetails) && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {hasIrDetails && (
            <Card id="analytics-ir-detail">
              <SectionTitle>
                IR Coverage ({coverageSummary.skip_ir_coverage ? 'skipped' : `${irLinked}/${irTotal}`})
              </SectionTitle>
              {coverageSummary.skip_ir_coverage ? (
                <p className="text-xs text-gray-400">Integration Requirement coverage is skipped for this spec.</p>
              ) : integrationRequirements.length === 0 ? (
                <p className="text-xs text-gray-400">No integration requirements defined.</p>
              ) : (
                <div className="space-y-1.5 max-h-64 overflow-y-auto">
                  {integrationRequirements.map((ir: any, idx: number) => {
                    const id = coverageItemId(ir, idx, 'ir');
                    const linked = itemHasLinkedTask(ir);
                    const covered = linked ?? !irUncoveredIds.includes(id);
                    const title = coverageItemTitle(ir, idx, 'ir');
                    return (
                      <div key={id} className="flex items-start gap-2 text-xs">
                        {covered ? (
                          <CheckCircle className="w-3.5 h-3.5 text-sky-500 shrink-0 mt-0.5" />
                        ) : (
                          <XCircle className="w-3.5 h-3.5 text-gray-300 dark:text-gray-600 shrink-0 mt-0.5" />
                        )}
                        <span className={`${covered ? 'text-gray-700 dark:text-gray-300' : 'text-gray-400 dark:text-gray-500'} line-clamp-2 flex-1`}>
                          {title}
                        </span>
                        {!covered && (
                          <span className="px-1 py-0.5 rounded text-[9px] bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300">
                            orphan
                          </span>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </Card>
          )}

          {hasOrDetails && (
            <Card id="analytics-or-detail">
              <SectionTitle>
                OR Coverage ({coverageSummary.skip_or_coverage ? 'skipped' : `${orLinked}/${orTotal}`})
              </SectionTitle>
              {coverageSummary.skip_or_coverage ? (
                <p className="text-xs text-gray-400">Observability Requirement coverage is skipped for this spec.</p>
              ) : observabilityRequirements.length === 0 ? (
                <p className="text-xs text-gray-400">No observability requirements defined.</p>
              ) : (
                <div className="space-y-1.5 max-h-64 overflow-y-auto">
                  {observabilityRequirements.map((orReq: any, idx: number) => {
                    const id = coverageItemId(orReq, idx, 'or');
                    const linked = itemHasLinkedTask(orReq);
                    const covered = linked ?? !orUncoveredIds.includes(id);
                    const title = coverageItemTitle(orReq, idx, 'or');
                    return (
                      <div key={id} className="flex items-start gap-2 text-xs">
                        {covered ? (
                          <CheckCircle className="w-3.5 h-3.5 text-teal-500 shrink-0 mt-0.5" />
                        ) : (
                          <XCircle className="w-3.5 h-3.5 text-gray-300 dark:text-gray-600 shrink-0 mt-0.5" />
                        )}
                        <span className={`${covered ? 'text-gray-700 dark:text-gray-300' : 'text-gray-400 dark:text-gray-500'} line-clamp-2 flex-1`}>
                          {title}
                        </span>
                        {!covered && (
                          <span className="px-1 py-0.5 rounded text-[9px] bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300">
                            orphan
                          </span>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </Card>
          )}
        </div>
      )}

      {/* TR + Decisions Coverage panels (spec 233eaad3) */}
      {((data.technical_requirements || []).length > 0 ||
        (data.decisions || []).length > 0) && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* TR Coverage */}
          {(data.technical_requirements || []).length > 0 && (
            <Card id="analytics-tr-detail">
              <SectionTitle>
                TR Coverage ({((data.technical_requirements || []).length - (data.trs_uncovered_indices?.length ?? 0))}/{(data.technical_requirements || []).length})
              </SectionTitle>
              <div className="space-y-1.5 max-h-64 overflow-y-auto">
                {(data.technical_requirements || []).map((tr: any, idx: number) => {
                  const covered = !(data.trs_uncovered_indices ?? []).includes(idx);
                  const text = typeof tr === 'string' ? tr : displayText(tr?.text ?? tr?.title, `TR #${idx}`);
                  return (
                    <div key={idx} className="flex items-start gap-2 text-xs">
                      {covered ? (
                        <CheckCircle className="w-3.5 h-3.5 text-purple-500 shrink-0 mt-0.5" />
                      ) : (
                        <XCircle className="w-3.5 h-3.5 text-gray-300 dark:text-gray-600 shrink-0 mt-0.5" />
                      )}
                      <span className={`${covered ? 'text-gray-700 dark:text-gray-300' : 'text-gray-400 dark:text-gray-500'} line-clamp-2 flex-1`}>
                        {text}
                      </span>
                      {!covered && (
                        <span className="px-1 py-0.5 rounded text-[9px] bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300">
                          orphan
                        </span>
                      )}
                    </div>
                  );
                })}
              </div>
            </Card>
          )}

          {/* Decisions Coverage */}
          {(data.decisions || []).length > 0 && (
            <Card id="analytics-decisions-detail">
              <SectionTitle>
                Decision verification planning ({((data.decisions || []).filter((d: any) => d.status === 'active').length - (data.decisions_pending_ids?.length ?? 0))}/{(data.decisions || []).filter((d: any) => d.status === 'active').length})
              </SectionTitle>
              <div className="space-y-1.5 max-h-64 overflow-y-auto">
                {(data.decisions || []).map((dec: any) => {
                  const decId = typeof dec === 'object' ? dec?.id : null;
                  const covered = decId && dec?.status === 'active' && Array.isArray(data.decisions_pending_ids)
                    && !data.decisions_pending_ids.includes(decId);
                  const title = typeof dec === 'object' ? (dec?.title || dec?.id || 'Decision') : String(dec);
                  const status = typeof dec === 'object' ? dec?.status : null;
                  const isSoftDeleted = status === 'revoked' || status === 'superseded';
                  return (
                    <div key={decId ?? title} className="flex items-start gap-2 text-xs">
                      {covered ? (
                        <CheckCircle className="w-3.5 h-3.5 text-indigo-500 shrink-0 mt-0.5" />
                      ) : (
                        <XCircle className="w-3.5 h-3.5 text-gray-300 dark:text-gray-600 shrink-0 mt-0.5" />
                      )}
                      <span className={`${covered ? 'text-gray-700 dark:text-gray-300' : 'text-gray-400 dark:text-gray-500'} line-clamp-2 flex-1`}>
                        {title}
                      </span>
                      <div className="flex gap-1 shrink-0">
                        {isSoftDeleted && (
                          <span className="px-1 py-0.5 rounded text-[9px] bg-gray-200 dark:bg-gray-700 text-gray-600 dark:text-gray-300">
                            {status}
                          </span>
                        )}
                        {!covered && !isSoftDeleted && (
                          <span className="px-1 py-0.5 rounded text-[9px] bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300">
                            plan pending
                          </span>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </Card>
          )}
        </div>
      )}

      {/* FR Coverage */}
      {data.fr_details && data.fr_details.length > 0 && (
        <Card>
          <SectionTitle>FR Coverage ({data.fr_details.filter((f: any) => f.has_rule).length}/{data.total_fr ?? data.fr_details.length})</SectionTitle>
          <div className="space-y-1.5 max-h-64 overflow-y-auto">
            {data.fr_details.map((fr: any) => (
              <div key={fr.index} className="flex items-start gap-2 text-xs">
                {fr.has_rule ? (
                  <CheckCircle className="w-3.5 h-3.5 text-emerald-500 shrink-0 mt-0.5" />
                ) : fr.has_contract ? (
                  <AlertTriangle className="w-3.5 h-3.5 text-amber-500 shrink-0 mt-0.5" />
                ) : (
                  <XCircle className="w-3.5 h-3.5 text-gray-300 dark:text-gray-600 shrink-0 mt-0.5" />
                )}
                <span className={`${fr.has_rule ? 'text-gray-700 dark:text-gray-300' : 'text-gray-400 dark:text-gray-500'} line-clamp-2 flex-1`}>
                  {displayText(fr.text, `FR #${fr.index}`)}
                </span>
                <div className="flex gap-1 shrink-0">
                  {fr.has_rule && <span className="px-1 py-0.5 rounded text-[9px] bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-300">Rule</span>}
                  {fr.has_contract && <span className="px-1 py-0.5 rounded text-[9px] bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-300">Contract</span>}
                </div>
              </div>
            ))}
          </div>
        </Card>
      )}

      {/* BR + API Contracts Coverage panels (bug 6f152627) */}
      {((data.business_rules || []).length > 0 ||
        (data.api_contracts || []).length > 0) && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {/* BR Coverage */}
          {(data.business_rules || []).length > 0 && (
            <Card>
              <SectionTitle>
                BR Coverage ({(data.business_rules || []).filter((br: any) => (br?.linked_task_ids || []).length > 0).length}/{(data.business_rules || []).length})
              </SectionTitle>
              <div className="space-y-1.5 max-h-64 overflow-y-auto">
                {(data.business_rules || []).map((br: any, idx: number) => {
                  const linkedTasks = (br?.linked_task_ids || []) as string[];
                  const covered = linkedTasks.length > 0;
                  const title = typeof br === 'object' ? (br?.title || br?.rule || `BR #${idx}`) : String(br);
                  return (
                    <div key={br?.id ?? idx} className="flex items-start gap-2 text-xs">
                      {covered ? (
                        <CheckCircle className="w-3.5 h-3.5 text-emerald-500 shrink-0 mt-0.5" />
                      ) : (
                        <XCircle className="w-3.5 h-3.5 text-gray-300 dark:text-gray-600 shrink-0 mt-0.5" />
                      )}
                      <span className={`${covered ? 'text-gray-700 dark:text-gray-300' : 'text-gray-400 dark:text-gray-500'} line-clamp-2 flex-1`}>
                        {title}
                      </span>
                      {covered ? (
                        <span className="px-1 py-0.5 rounded text-[9px] bg-emerald-100 dark:bg-emerald-900/40 text-emerald-700 dark:text-emerald-300 shrink-0">
                          {linkedTasks.length} task{linkedTasks.length !== 1 ? 's' : ''}
                        </span>
                      ) : (
                        <span className="px-1 py-0.5 rounded text-[9px] bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300 shrink-0">
                          orphan
                        </span>
                      )}
                    </div>
                  );
                })}
              </div>
            </Card>
          )}

          {/* API Contracts Coverage */}
          {(data.api_contracts || []).length > 0 && (
            <Card>
              <SectionTitle>
                API Contracts Coverage ({(data.api_contracts || []).filter((c: any) => (c?.linked_task_ids || []).length > 0).length}/{(data.api_contracts || []).length})
              </SectionTitle>
              <div className="space-y-1.5 max-h-64 overflow-y-auto">
                {(data.api_contracts || []).map((ct: any, idx: number) => {
                  const linkedTasks = (ct?.linked_task_ids || []) as string[];
                  const covered = linkedTasks.length > 0;
                  const title = typeof ct === 'object' ? (ct?.title || ct?.endpoint || ct?.method || `Contract #${idx}`) : String(ct);
                  return (
                    <div key={ct?.id ?? idx} className="flex items-start gap-2 text-xs">
                      {covered ? (
                        <CheckCircle className="w-3.5 h-3.5 text-blue-500 shrink-0 mt-0.5" />
                      ) : (
                        <XCircle className="w-3.5 h-3.5 text-gray-300 dark:text-gray-600 shrink-0 mt-0.5" />
                      )}
                      <span className={`${covered ? 'text-gray-700 dark:text-gray-300' : 'text-gray-400 dark:text-gray-500'} line-clamp-2 flex-1`}>
                        {title}
                      </span>
                      {covered ? (
                        <span className="px-1 py-0.5 rounded text-[9px] bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-300 shrink-0">
                          {linkedTasks.length} task{linkedTasks.length !== 1 ? 's' : ''}
                        </span>
                      ) : (
                        <span className="px-1 py-0.5 rounded text-[9px] bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300 shrink-0">
                          orphan
                        </span>
                      )}
                    </div>
                  );
                })}
              </div>
            </Card>
          )}
        </div>
      )}

      {/* Tasks Table */}
      <Card>
        <SectionTitle>Tasks ({data.cards.length})</SectionTitle>
        {data.cards.length === 0 ? (
          <p className="text-xs text-gray-400">No tasks linked to this spec.</p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-xs">
              <thead>
                <tr className="text-left text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700">
                  <th className="pb-2 pr-3 font-medium">Title</th>
                  <th className="pb-2 pr-3 font-medium">Status</th>
                  <th className="pb-2 pr-3 font-medium">Type</th>
                  <th className="pb-2 pr-3 font-medium text-right">Completeness</th>
                  <th className="pb-2 pr-3 font-medium text-right">Drift</th>
                  <th className="pb-2 font-medium text-right">Cycle</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                {data.cards.map((c) => {
                  const cycle =
                    c.created_at && c.updated_at
                      ? ((new Date(c.updated_at).getTime() - new Date(c.created_at).getTime()) / 3600000)
                      : null;
                  return (
                    <tr key={c.id} className="text-gray-700 dark:text-gray-300">
                      <td className="py-2 pr-3 max-w-[200px] truncate">{c.title}</td>
                      <td className="py-2 pr-3">{statusBadge(c.status)}</td>
                      <td className="py-2 pr-3">
                        <span className={`text-xs font-medium ${
                          c.card_type === 'bug' ? 'text-red-500' :
                          c.is_test ? 'text-cyan-600 dark:text-cyan-400' :
                          'text-gray-500'
                        }`}>
                          {c.card_type === 'bug' ? 'Bug' : c.is_test ? 'Test' : 'Impl'}
                        </span>
                      </td>
                      <td className="py-2 pr-3 text-right">
                        <span className={`inline-block px-1.5 py-0.5 rounded text-xs font-medium ${completenessBg(c.completeness)} ${completenessColor(c.completeness)}`}>
                          {c.completeness != null ? `${c.completeness}%` : '--'}
                        </span>
                      </td>
                      <td className="py-2 pr-3 text-right">
                        <span className={`inline-block px-1.5 py-0.5 rounded text-xs font-medium ${driftBg(c.drift)} ${driftColor(c.drift)}`}>
                          {c.drift != null ? `${c.drift}%` : '--'}
                        </span>
                      </td>
                      <td className="py-2 text-right font-mono">{formatHours(cycle != null ? Math.round(cycle * 10) / 10 : null)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </Card>

      {/* Derivation Tree */}
      <Card>
        <SectionTitle>Derivation Tree</SectionTitle>
        <div className="flex items-center gap-2 flex-wrap">
          {data.derivation.ideation_id && (
            <>
              <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-purple-50 dark:bg-purple-900/20 border border-purple-200 dark:border-purple-800 text-xs font-medium text-purple-700 dark:text-purple-300">
                <Layers className="w-3.5 h-3.5" />
                Ideation
              </div>
              <ArrowRight className="w-4 h-4 text-gray-400" />
            </>
          )}
          {data.derivation.refinement_id && (
            <>
              <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-teal-50 dark:bg-teal-900/20 border border-teal-200 dark:border-teal-800 text-xs font-medium text-teal-700 dark:text-teal-300">
                <GitBranch className="w-3.5 h-3.5" />
                Refinement
              </div>
              <ArrowRight className="w-4 h-4 text-gray-400" />
            </>
          )}
          <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 text-xs font-medium text-blue-700 dark:text-blue-300">
            <FileText className="w-3.5 h-3.5" />
            Spec
          </div>
          <ArrowRight className="w-4 h-4 text-gray-400" />
          <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-amber-50 dark:bg-amber-900/20 border border-amber-200 dark:border-amber-800 text-xs font-medium text-amber-700 dark:text-amber-300">
            <FileText className="w-3.5 h-3.5" />
            {data.cards.length} Tasks
          </div>
        </div>
      </Card>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Ideation Detail View
// ---------------------------------------------------------------------------

function IdeationDetailView({ data }: { data: IdeationAnalytics }) {
  const scope = data.scope_assessment;

  function scoreBar(label: string, value: number | undefined) {
    const v = value ?? 0;
    const pct = Math.min(v * 10, 100);
    let barColor = 'bg-emerald-500';
    if (v > 6) barColor = 'bg-red-500';
    else if (v > 3) barColor = 'bg-amber-500';
    return (
      <div className="space-y-1">
        <div className="flex items-center justify-between text-xs">
          <span className="text-gray-600 dark:text-gray-400">{label}</span>
          <span className="font-semibold text-gray-900 dark:text-white">{v}/10</span>
        </div>
        <div className="h-2 rounded-full bg-gray-200 dark:bg-gray-700 overflow-hidden">
          <div className={`h-full rounded-full ${barColor} transition-all`} style={{ width: `${pct}%` }} />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <Card>
        <div className="flex items-start justify-between gap-4 mb-4">
          <div className="min-w-0">
            <div className="flex items-center gap-2 mb-1">
              {statusBadge(data.status)}
              <h2 className="text-lg font-bold text-gray-900 dark:text-white truncate">{data.title}</h2>
            </div>
            <div className="flex items-center gap-3 mt-1">
              {data.complexity && (
                <span className="text-xs text-gray-500 dark:text-gray-400">
                  Complexity: <span className="font-medium capitalize">{data.complexity}</span>
                </span>
              )}
              {data.created_at && (
                <span className="text-xs text-gray-400">
                  Created: {new Date(data.created_at).toLocaleDateString()}
                </span>
              )}
            </div>
          </div>
        </div>
      </Card>

      {/* Scope Assessment */}
      <Card>
        <SectionTitle>Scope Assessment</SectionTitle>
        {scope ? (
          <div className="space-y-3 max-w-md">
            {scoreBar('Domains', scope.domains)}
            {scoreBar('Scope Ambiguity', scope.ambiguity)}
            {scoreBar('Dependencies', scope.dependencies)}
          </div>
        ) : (
          <p className="text-xs text-gray-400">No scope assessment available.</p>
        )}
      </Card>

      {/* Derivation Info */}
      <Card>
        <SectionTitle>Derivation Summary</SectionTitle>
        <div className="grid grid-cols-3 gap-4">
          <KpiMini label="Refinements" value={data.refinement_count} icon={<GitBranch className="w-4 h-4" />} />
          <KpiMini label="Specs" value={data.spec_count} icon={<FileText className="w-4 h-4" />} />
          <KpiMini label="Q&A items" value={data.qa_count} icon={<MessageSquare className="w-4 h-4" />} />
        </div>
      </Card>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Refinement Detail View
// ---------------------------------------------------------------------------

function RefinementDetailView({ data }: { data: RefinementData }) {
  return (
    <div className="space-y-4">
      {/* Header */}
      <Card>
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <div className="flex items-center gap-2 mb-1">
              {statusBadge(data.status)}
              <h2 className="text-lg font-bold text-gray-900 dark:text-white truncate">{data.title}</h2>
            </div>
            <div className="flex items-center gap-3 mt-1 text-xs text-gray-500 dark:text-gray-400">
              <span>Version: {data.version}</span>
              <span>Linked ideation: <span className="font-mono">{data.ideation_id.slice(0, 8)}</span></span>
            </div>
            {data.description && (
              <p className="text-xs text-gray-600 dark:text-gray-300 mt-2 line-clamp-3">{data.description}</p>
            )}
          </div>
        </div>
      </Card>

      {/* Scope */}
      <Card>
        <SectionTitle>Scope</SectionTitle>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <p className="text-xs font-medium text-gray-500 dark:text-gray-400 mb-2">In Scope</p>
            <div className="flex flex-wrap gap-1.5">
              {(data.in_scope && data.in_scope.length > 0) ? (
                data.in_scope.map((item, i) => (
                  <span key={i} className="inline-block px-2 py-0.5 rounded text-xs font-medium bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300">
                    {item}
                  </span>
                ))
              ) : (
                <span className="text-xs text-gray-400">None defined</span>
              )}
            </div>
          </div>
          <div>
            <p className="text-xs font-medium text-gray-500 dark:text-gray-400 mb-2">Out of Scope</p>
            <div className="flex flex-wrap gap-1.5">
              {(data.out_of_scope && data.out_of_scope.length > 0) ? (
                data.out_of_scope.map((item, i) => (
                  <span key={i} className="inline-block px-2 py-0.5 rounded text-xs font-medium bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300">
                    {item}
                  </span>
                ))
              ) : (
                <span className="text-xs text-gray-400">None defined</span>
              )}
            </div>
          </div>
        </div>
      </Card>

      {/* Knowledge Bases */}
      <Card>
        <SectionTitle>Knowledge Bases ({data.knowledge_bases.length})</SectionTitle>
        {data.knowledge_bases.length === 0 ? (
          <p className="text-xs text-gray-400">No knowledge bases attached.</p>
        ) : (
          <div className="space-y-1">
            {data.knowledge_bases.map((kb) => (
              <div key={kb.id} className="flex items-center gap-2 text-xs text-gray-700 dark:text-gray-300 py-1">
                <FileText className="w-3.5 h-3.5 text-gray-400" />
                {kb.title}
              </div>
            ))}
          </div>
        )}
      </Card>

      {/* Derived Specs */}
      <Card>
        <SectionTitle>Derived Specs ({data.specs.length})</SectionTitle>
        {data.specs.length === 0 ? (
          <p className="text-xs text-gray-400">No specs derived yet.</p>
        ) : (
          <div className="space-y-1.5">
            {data.specs.map((sp) => (
              <div key={sp.id} className="flex items-center justify-between text-xs py-1 border-b border-gray-100 dark:border-gray-700 last:border-0">
                <span className="text-gray-700 dark:text-gray-300 truncate mr-2">{sp.title}</span>
                {statusBadge(sp.status)}
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  );
}

// Main Component
// ---------------------------------------------------------------------------

export function EntityDetail({ boardId, entityType, entityId, from, to }: EntityDetailProps) {
  const api = useDashboardApi();
  const [data, setData] = useState<SpecAnalytics | IdeationAnalytics | RefinementData | CardAnalytics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      if (entityType === 'refinement') {
        // Backend doesn't have a refinement analytics endpoint — fetch via regular API
        const refinement = await api.getRefinement(entityId);
        setData({
          id: refinement.id,
          title: refinement.title,
          description: refinement.description,
          status: typeof refinement.status === 'string' ? refinement.status : String(refinement.status),
          version: refinement.version,
          ideation_id: refinement.ideation_id,
          in_scope: refinement.in_scope,
          out_of_scope: refinement.out_of_scope,
          specs: (refinement.specs || []).map((s: any) => ({
            id: s.id,
            title: s.title,
            status: typeof s.status === 'string' ? s.status : String(s.status),
          })),
          knowledge_bases: (refinement.knowledge_bases || []).map((kb: any) => ({
            id: kb.id,
            title: kb.title,
          })),
        } as RefinementData);
      } else {
        const result = await api.getEntityAnalytics(boardId, entityType, entityId, from, to);
        setData(result);
      }
    } catch (err: any) {
      setError(err?.message || 'Failed to load entity analytics');
    } finally {
      setLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [boardId, entityType, entityId, from, to]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="w-6 h-6 animate-spin text-gray-400" />
        <span className="ml-2 text-sm text-gray-500 dark:text-gray-400">Loading entity analytics...</span>
      </div>
    );
  }

  if (error) {
    return (
      <Card>
        <div className="flex items-center gap-2 text-red-600 dark:text-red-400">
          <AlertTriangle className="w-5 h-5" />
          <span className="text-sm">{error}</span>
        </div>
        <button
          onClick={fetchData}
          className="mt-3 text-xs text-blue-600 dark:text-blue-400 hover:underline"
        >
          Retry
        </button>
      </Card>
    );
  }

  if (!data) return null;

  if (entityType === 'spec') return <SpecDetailView data={data as SpecAnalytics} />;
  if (entityType === 'ideation') return <IdeationDetailView data={data as IdeationAnalytics} />;
  if (entityType === 'refinement') return <RefinementDetailView data={data as RefinementData} />;
  if (entityType === 'card') return <CardDetailView data={data as CardAnalytics} />;

  return null;
}

// ---------------------------------------------------------------------------
// Card detail view
// ---------------------------------------------------------------------------

function CardDetailView({ data }: { data: CardAnalytics }) {
  const hasConclusions = Array.isArray(data.conclusions) && data.conclusions.length > 0;
  const latestConcl = hasConclusions ? data.conclusions![data.conclusions!.length - 1] : null;
  const hasValidations = Array.isArray(data.validations) && data.validations.length > 0;

  const statusColor = (() => {
    if (data.status === 'done') return 'bg-green-100 dark:bg-green-900/40 text-green-700 dark:text-green-300';
    if (data.status === 'validation') return 'bg-violet-100 dark:bg-violet-900/40 text-violet-700 dark:text-violet-300';
    if (data.status === 'rejected') return 'bg-rose-100 dark:bg-rose-900/40 text-rose-700 dark:text-rose-300';
    if (data.status === 'in_progress') return 'bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-300';
    if (data.status === 'cancelled') return 'bg-gray-100 dark:bg-gray-800 text-gray-500 dark:text-gray-400';
    return 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300';
  })();

  const typeColor = (() => {
    if (data.card_type === 'test') return 'bg-emerald-100 dark:bg-emerald-900/40 text-emerald-700 dark:text-emerald-300';
    if (data.card_type === 'bug') return 'bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300';
    return 'bg-violet-100 dark:bg-violet-900/40 text-violet-700 dark:text-violet-300';
  })();

  return (
    <div className="space-y-4">
      {/* Header */}
      <Card>
        <div className="flex items-start gap-3 mb-3">
          <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${statusColor}`}>
            {data.status ? data.status.replace(/[_-]+/g, ' ').replace(/\b\w/g, (character) => character.toUpperCase()) : 'Unknown'}
          </span>
          <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${typeColor}`}>
            {data.card_type}
          </span>
          <h2 className="text-lg font-semibold text-gray-800 dark:text-gray-100 flex-1">{data.title}</h2>
          {data.cycle_hours !== null && (
            <span className="inline-flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400">
              <Clock className="w-3.5 h-3.5" />
              Cycle: {data.cycle_hours}h
            </span>
          )}
        </div>
        {data.spec_id && (
          <div className="text-xs text-gray-500 dark:text-gray-400">
            Spec: <span className="font-mono">{data.spec_id.slice(0, 8)}</span>
          </div>
        )}
      </Card>

      {/* KPIs */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <Card>
          <div className="flex items-center gap-1.5 mb-1">
            <Target className="w-3.5 h-3.5 text-gray-400" />
            <span className="text-[10px] uppercase text-gray-500 dark:text-gray-400">Completeness</span>
          </div>
          <div className="text-xl font-bold text-gray-800 dark:text-gray-100">
            {data.completeness !== null ? `${data.completeness}%` : '--'}
          </div>
        </Card>
        <Card>
          <div className="flex items-center gap-1.5 mb-1">
            <AlertTriangle className="w-3.5 h-3.5 text-gray-400" />
            <span className="text-[10px] uppercase text-gray-500 dark:text-gray-400">Drift</span>
          </div>
          <div className="text-xl font-bold text-gray-800 dark:text-gray-100">
            {data.drift !== null ? `${data.drift}%` : '--'}
          </div>
        </Card>
        <Card>
          <div className="flex items-center gap-1.5 mb-1">
            <MessageSquare className="w-3.5 h-3.5 text-gray-400" />
            <span className="text-[10px] uppercase text-gray-500 dark:text-gray-400">Conclusions</span>
          </div>
          <div className="text-xl font-bold text-gray-800 dark:text-gray-100">
            {hasConclusions ? data.conclusions!.length : 0}
          </div>
        </Card>
        <Card>
          <div className="flex items-center gap-1.5 mb-1">
            <CheckCircle className="w-3.5 h-3.5 text-gray-400" />
            <span className="text-[10px] uppercase text-gray-500 dark:text-gray-400">Validations</span>
          </div>
          <div className="text-xl font-bold text-gray-800 dark:text-gray-100">
            {hasValidations ? data.validations!.length : 0}
          </div>
        </Card>
      </div>

      {/* Conclusion body */}
      {latestConcl && (
        <Card>
          <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-200 mb-2">Latest Conclusion</h3>
          <p className="text-sm text-gray-600 dark:text-gray-300 whitespace-pre-wrap">{latestConcl.text}</p>
          {latestConcl.completeness_justification && (
            <div className="mt-3 pt-3 border-t border-gray-100 dark:border-gray-700/50 space-y-2">
              <div>
                <div className="text-[10px] uppercase text-gray-400">Completeness justification</div>
                <div className="text-xs text-gray-600 dark:text-gray-300">{latestConcl.completeness_justification}</div>
              </div>
              {latestConcl.drift_justification && (
                <div>
                  <div className="text-[10px] uppercase text-gray-400">Drift justification</div>
                  <div className="text-xs text-gray-600 dark:text-gray-300">{latestConcl.drift_justification}</div>
                </div>
              )}
            </div>
          )}
        </Card>
      )}

      {/* Validation history timeline */}
      {hasValidations && (
        <Card>
          <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-200 mb-3">Task Validation History</h3>
          <div className="space-y-3">
            {data.validations!.map((v: any, idx: number) => {
              const isSuccess = v.outcome === 'success';
              return (
                <div key={v.id || idx} className="border-l-2 border-gray-200 dark:border-gray-700 pl-3">
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`text-[10px] px-1.5 py-0.5 rounded-full font-medium ${
                      isSuccess
                        ? 'bg-green-100 dark:bg-green-900/40 text-green-700 dark:text-green-300'
                        : 'bg-red-100 dark:bg-red-900/40 text-red-700 dark:text-red-300'
                    }`}>
                      {isSuccess ? 'success' : 'failed'}
                    </span>
                    <span className="text-[10px] text-gray-500 dark:text-gray-400">
                      {v.created_at ? new Date(v.created_at).toLocaleString() : ''}
                    </span>
                  </div>
                  <div className="grid grid-cols-3 gap-2 text-xs mb-1">
                    <div>
                      <span className="text-gray-400">confidence:</span>{' '}
                      <span className="font-semibold text-gray-700 dark:text-gray-200">{v.confidence ?? '--'}%</span>
                    </div>
                    <div>
                      <span className="text-gray-400">completeness:</span>{' '}
                      <span className="font-semibold text-gray-700 dark:text-gray-200">{v.estimated_completeness ?? '--'}%</span>
                    </div>
                    <div>
                      <span className="text-gray-400">drift:</span>{' '}
                      <span className="font-semibold text-gray-700 dark:text-gray-200">{v.estimated_drift ?? '--'}%</span>
                    </div>
                  </div>
                  {v.threshold_violations && v.threshold_violations.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-1">
                      {v.threshold_violations.map((t: string, i: number) => (
                        <span key={i} className="text-[9px] px-1 py-0.5 rounded bg-red-50 dark:bg-red-900/30 text-red-600 dark:text-red-300">
                          {t}
                        </span>
                      ))}
                    </div>
                  )}
                  {(v.general_justification) && (
                    <p className="text-[11px] text-gray-500 dark:text-gray-400 mt-1 italic">
                      {v.general_justification}
                    </p>
                  )}
                </div>
              );
            })}
          </div>
        </Card>
      )}
    </div>
  );
}

