}

function QueryTimeoutSetting({ value, onChange }: { value: number; onChange: (value: number) => void }) {
  const [draft, setDraft] = useState(String(value));
  useEffect(() => setDraft(String(value)), [value]);
  return (
    <input
      aria-label="Graph query timeout (ms)"
      type="number"
      min={1}
      max={30000}
      step={1}
      value={draft}
      onChange={(event) => setDraft(event.target.value)}
      onBlur={() => {
        const parsed = Number(draft);
        if (draft.trim() && Number.isInteger(parsed) && parsed >= 1 && parsed <= 30000) {
          if (parsed !== value) onChange(parsed);
        } else {
          setDraft(String(value));
        }
      }}
      onKeyDown={(event) => { if (event.key === 'Enter') event.currentTarget.blur(); }}
      className="w-24 rounded border border-gray-300 bg-transparent px-2 py-1 text-xs dark:border-gray-600"
    />
  );
}

function SettingRow({
  label,
  description,
  children,
}: {
  label: string;
  description: string;
  children: ReactNode;
}) {
  return (
    <div className="flex items-center justify-between gap-4">
      <div className="min-w-0">
        <label className="block text-xs font-medium text-gray-700 dark:text-gray-300">
          {label}
        </label>
        <p className="mt-0.5 text-[10px] leading-4 text-gray-400 dark:text-gray-500">
          {description}
        </p>
      </div>
      <div className="shrink-0">{children}</div>
    </div>
  );
}

function SettingsSelect({
  ariaLabel,
  value,
  onChange,
  children,
}: {
  ariaLabel: string;
  value: string;
  onChange: (value: string) => void;
  children: ReactNode;
