import { useEffect, useState } from 'react';
import { useDashboardApi } from '@/services/api';
import type { CardSummary } from '@/types';
import { isPersistedReadinessProjection } from '@/types/delivery-readiness';
import { isDeliveryReadiness } from '@/types/delivery-readiness';
import { readinessReadMode } from '@/lib/readinessMode';
import type { DeliveryReadinessState } from './DeliveryReadinessView';
import { isRetriableReadinessError, ReadinessContractError } from './readinessTransport';

/** One indexed generation read per visible Spec; delayed projections are polled. */
export function useBoardDeliveryReadiness(boardId: string, cards: CardSummary[], enabled: boolean, refreshKey: string): Record<string, DeliveryReadinessState> {
  const api = useDashboardApi();
  const mode = readinessReadMode();
  const [revision, setRevision] = useState(0);
  useEffect(() => {
    const refresh = () => setRevision(value => value + 1);
    window.addEventListener('focus', refresh);
    const visible = () => { if (document.visibilityState === 'visible') refresh(); };
    document.addEventListener('visibilitychange', visible);
    window.addEventListener('pulse:delivery-evidence-changed', refresh);
    return () => { window.removeEventListener('focus', refresh); document.removeEventListener('visibilitychange', visible); window.removeEventListener('pulse:delivery-evidence-changed', refresh); };
  }, []);
  const [result, setResult] = useState<{ api: typeof api; cards: CardSummary[]; boardId: string;
    mode: typeof mode; values: Record<string, DeliveryReadinessState> }>();
  const retained = (card: CardSummary): DeliveryReadinessState | undefined => {
    if (result?.api !== api || result.boardId !== boardId || result.mode !== mode) return;
    const old = result.cards.find(row => row.id === card.id && row.spec_id === card.spec_id);
    return old ? result.values[card.id] : undefined;
  };
  useEffect(() => {
    if (!enabled) { setResult(undefined); return; }
    const controller = new AbortController();
    const values: Record<string, DeliveryReadinessState> = Object.fromEntries(cards.map(card => [card.id,
      !card.spec_id ? { error: 'No Spec scope is available for this card.' }
        : retained(card)?.persisted?.summary ? { persisted: { ...retained(card)!.persisted!, freshness: 'updating' } }
          : { loading: true }]));
    const publish = () => { if (!controller.signal.aborted) setResult({ api, cards, boardId, mode, values: { ...values } }); };
    publish();
    const specs = [...new Set(cards.map(card => card.spec_id).filter((id): id is string => !!id))];
    const pending = new Set<string>();
    const inFlight = new Set<string>();
    const retryAt = new Map<string, number>();
    const retryDelay = new Map<string, number>();
    async function loadSpec(specId: string) {
      if (controller.signal.aborted || inFlight.has(specId)) return;
      inFlight.add(specId);
      const selected = cards.filter(card => card.spec_id === specId);
      try {
        if (mode === 'legacy') {
          const legacy = await api.getDeliveryReadinessSummary(boardId, specId, controller.signal);
          if (!isDeliveryReadiness(legacy.delivery_readiness)
            || legacy.delivery_readiness.scope.board_id !== boardId
            || legacy.delivery_readiness.scope.spec_id !== specId)
            throw new ReadinessContractError('Legacy readiness unavailable or incompatible.');
          const byCard = new Map(legacy.cards.map(row => [row.card_id, row.delivery_readiness]));
          for (const card of selected) {
            const value = byCard.get(card.id);
            values[card.id] = value && isDeliveryReadiness(value) ? { value }
              : { error: 'Readiness card scope is unavailable.' };
          }
          pending.delete(specId);
          return;
        }
        const data = await api.getPersistedReadinessProjection(boardId, specId, undefined, controller.signal);
        if (!isPersistedReadinessProjection(data) || data.scope.board_id !== boardId || data.scope.spec_id !== specId
          || data.scope.card_id !== null) throw new ReadinessContractError('Readiness projection unavailable or incompatible.');
        const rows = new Map(data.summaries.map(row => [row.card_id, row]));
        if (rows.size !== data.summaries.length) throw new ReadinessContractError('Readiness card scope is ambiguous.');
        for (const card of selected) {
          const summary = rows.get(card.id);
          if (!summary && data.projection.freshness === 'current') throw new ReadinessContractError('Readiness card scope is unavailable.');
          values[card.id] = { persisted: { summary, freshness: summary ? data.projection.freshness : 'pending_initial',
            generationId: data.projection.generation_id, errorCode: data.projection.error_code } };
        }
        if (data.projection.freshness === 'updating' || data.projection.freshness === 'pending_initial') pending.add(specId);
        else pending.delete(specId);
        retryAt.delete(specId);
        retryDelay.delete(specId);
      } catch (error) {
        if (controller.signal.aborted) return;
        const retriable = isRetriableReadinessError(error);
        for (const card of selected) {
          const previous = values[card.id].persisted;
          values[card.id] = retriable && previous?.summary
            ? { persisted: { ...previous, freshness: 'unavailable', errorCode: 'transport_error' } }
            : { error: error instanceof Error ? error.message : 'Readiness could not be loaded.' };
        }
        if (retriable) {
          pending.add(specId);
          const nextDelay = !retryDelay.has(specId) ? 1000 : retryDelay.get(specId) === 1000 ? 2000 : 5000;
          retryDelay.set(specId, nextDelay);
          retryAt.set(specId, Date.now() + nextDelay);
        } else pending.delete(specId);
      } finally {
        inFlight.delete(specId);
        publish();
      }
    }
    let next = 0;
    async function worker() {
      while (next < specs.length && !controller.signal.aborted) {
        const specId = specs[next++];
        await loadSpec(specId);
      }
    }
    void Promise.all(Array.from({ length: Math.min(3, specs.length) }, worker));
    const interval = window.setInterval(() => {
      if (document.visibilityState !== 'visible') return;
      for (const specId of [...pending].filter(id => !inFlight.has(id) && (retryAt.get(id) ?? 0) <= Date.now())
        .slice(0, Math.max(0, 3 - inFlight.size))) {
        void loadSpec(specId);
      }
    }, 500);
    return () => { controller.abort(); window.clearInterval(interval); };
  }, [api, boardId, cards, enabled, refreshKey, revision, mode]);
  if (!enabled) return {};
  return Object.fromEntries(cards.map(card => [card.id, retained(card) ?? { loading: true }]));
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';

import { GuidedHelpPopover } from './GuidedHelpPopover';
import { isUsableAnchorRect } from './positioning';
import { getTourById } from './registry';
import {
  createGuidedHelpStorage,
  getGuidedHelpTourSummary,
  GUIDED_HELP_PROGRESS_EVENT,
  resolveFirstEligibleStep,
} from './storage';
import type {
  GuidedHelpContextValue,
  GuidedHelpProviderProps,
  GuidedHelpResolvedStep,
  GuidedHelpStep,
  GuidedHelpTour,
} from './types';

const GuidedHelpContext = createContext<GuidedHelpContextValue | null>(null);

interface ManualStepTarget {
  tourId: string;
  stepId: string;
}

function hasSuppression(props: GuidedHelpProviderProps['suppressWhen']): boolean {
  return Boolean(props && Object.values(props).some(Boolean));
}

function resolveStepById(tour: GuidedHelpTour, stepId?: string): GuidedHelpStep | null {
  if (!stepId) return null;
  return tour.steps.find((step) => step.id === stepId) ?? null;
}

function orderedSteps(tour: GuidedHelpTour): GuidedHelpStep[] {
  return tour.steps.slice().sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
}

function resolveManualStep(registry: GuidedHelpProviderProps['registry'], target: ManualStepTarget | null) {
  if (!target) return null;
  const tour = getTourById(registry, target.tourId);
  if (!tour) return null;
  const steps = orderedSteps(tour);
  const stepIndex = steps.findIndex((step) => step.id === target.stepId);
  if (stepIndex < 0) return null;
  return {
    tour,
    step: steps[stepIndex],
    stepIndex,
    totalSteps: steps.length,
  };
}

function findAnchorElement(anchor: string): HTMLElement | null {
  if (typeof document === 'undefined') return null;
  const candidates = Array.from(document.querySelectorAll<HTMLElement>('[data-tour-id]'));
  return candidates.find((element) => element.dataset.tourId === anchor) ?? null;
}

function readAnchorRect(anchor: string): DOMRect | null {
  const element = findAnchorElement(anchor);
  if (!element) return null;

  const style = window.getComputedStyle(element);
  if (style.display === 'none' || style.visibility === 'hidden') return null;

  let rect = element.getBoundingClientRect();
  if (isUsableAnchorRect(rect)) return rect;

  if (typeof element.scrollIntoView === 'function') {
    try {
      element.scrollIntoView({ block: 'center', inline: 'center', behavior: 'smooth' });
    } catch {
      element.scrollIntoView();
    }
  }

  rect = element.getBoundingClientRect();
  return isUsableAnchorRect(rect) ? rect : null;
}

export function GuidedHelpProvider({
  children,
  registry,
  surface,
  suppressWhen,
  storage,
  telemetryAdapter,
  enabled = true,
}: GuidedHelpProviderProps) {
  const storageApi = useMemo(() => storage ?? createGuidedHelpStorage(), [storage]);
  const [progress, setProgress] = useState(() => storageApi.read());
  const [requestedTourId, setRequestedTourId] = useState<string | null>(null);
  const [manualStepTarget, setManualStepTarget] = useState<ManualStepTarget | null>(null);
  const [anchorRect, setAnchorRect] = useState<DOMRect | null>(null);
  const isSuppressed = !enabled || hasSuppression(suppressWhen);
  const tours = registry.tours;

  useEffect(() => {
    const refresh = () => setProgress(storageApi.read());
    window.addEventListener(GUIDED_HELP_PROGRESS_EVENT, refresh);
    return () => window.removeEventListener(GUIDED_HELP_PROGRESS_EVENT, refresh);
  }, [storageApi]);

  useEffect(() => {
    setProgress(storageApi.read());
  }, [storageApi]);

  const activeResolved = useMemo(() => {
    if (isSuppressed) return null;
    const manual = resolveManualStep(registry, manualStepTarget);
    if (manual) return manual;
    const requested = requestedTourId
      ? resolveFirstEligibleStep(progress, tours, { tourId: requestedTourId })
      : null;
    return requested ?? resolveFirstEligibleStep(progress, tours, { surface });
  }, [isSuppressed, manualStepTarget, progress, registry, requestedTourId, surface, tours]);

  useEffect(() => {
    if (!requestedTourId) return;
    if (!activeResolved || activeResolved.tour.id !== requestedTourId) {
      setRequestedTourId(null);
    }
  }, [activeResolved, requestedTourId]);

  useEffect(() => {
    if (!activeResolved) {
      setAnchorRect(null);
      return undefined;
    }

    const updateAnchorRect = () => {
      const nextRect = readAnchorRect(activeResolved.step.anchor);
      setAnchorRect(nextRect);
      return nextRect;
    };

    let attempts = 0;
    const maxAttempts = 24;
    let retryTimer: number | undefined;
    const retryUntilAnchored = () => {
      attempts += 1;
      const rect = updateAnchorRect();
      if (rect || attempts >= maxAttempts) {
        if (retryTimer !== undefined) window.clearInterval(retryTimer);
        retryTimer = undefined;
      }
    };

    const observer =
      typeof MutationObserver !== 'undefined'
        ? new MutationObserver(() => {
            attempts = 0;
            retryUntilAnchored();
          })
        : null;

    const firstRect = updateAnchorRect();
    if (!firstRect && retryTimer === undefined) {
      retryTimer = window.setInterval(retryUntilAnchored, 250);
    }
    observer?.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['class', 'style', 'data-tour-id'],
    });
    window.addEventListener('resize', updateAnchorRect);
    window.addEventListener('scroll', updateAnchorRect, true);
    return () => {
      if (retryTimer !== undefined) window.clearInterval(retryTimer);
      observer?.disconnect();
      window.removeEventListener('resize', updateAnchorRect);
      window.removeEventListener('scroll', updateAnchorRect, true);
    };
  }, [activeResolved]);

  useEffect(() => {
    if (!activeResolved) return;
    const savedTour = progress.tours[activeResolved.tour.id];
    const savedStep = savedTour?.steps[activeResolved.step.id];
    const alreadyTracked =
      savedTour?.version === activeResolved.tour.version &&
      savedStep?.version === activeResolved.tour.version &&
      Boolean(savedStep.status);
    if (alreadyTracked) return;
    setProgress(storageApi.markStepViewed(activeResolved.tour, activeResolved.step));
    void telemetryAdapter?.emit({
      action: 'viewed',
      tour_surface: activeResolved.tour.surface,
      step_kind: activeResolved.step.kind,
      status: 'success',
    });
  }, [activeResolved, progress.tours, storageApi, telemetryAdapter]);

  const refresh = useCallback(() => {
    setProgress(storageApi.read());
  }, [storageApi]);

  const resolveActionTarget = useCallback(
    (tourId?: string, stepId?: string): GuidedHelpResolvedStep | null => {
      if (!tourId && !stepId) return activeResolved;
      const tour = tourId ? getTourById(registry, tourId) : activeResolved?.tour;
      if (!tour) return null;
      const step = resolveStepById(tour, stepId) ?? activeResolved?.step ?? tour.steps[0] ?? null;
      if (!step) return null;
      return {
        tour,
        step,
        stepIndex: tour.steps.findIndex((item) => item.id === step.id),
        totalSteps: tour.steps.length,
      };
    },
    [activeResolved, registry],
  );

  const startTour = useCallback((tourId: string) => {
    setManualStepTarget(null);
    setRequestedTourId(tourId);
  }, []);

  const completeStep = useCallback(
    (tourId?: string, stepId?: string) => {
      const target = resolveActionTarget(tourId, stepId);
      if (!target) return;
      const next = storageApi.completeStep(target.tour, target.step);
      setManualStepTarget(null);
      setProgress(next);
      const completed = resolveFirstEligibleStep(next, [target.tour], { tourId: target.tour.id }) === null;
      void telemetryAdapter?.emit({
        action: completed ? 'completed' : 'step_completed',
        tour_surface: target.tour.surface,
        step_kind: target.step.kind,
        status: 'success',
      });
    },
    [resolveActionTarget, storageApi, telemetryAdapter],
  );

  const skipStep = useCallback(
    (tourId?: string, stepId?: string) => {
      const target = resolveActionTarget(tourId, stepId);
      if (!target) return;
      setManualStepTarget(null);
      setProgress(storageApi.skipStep(target.tour, target.step));
      void telemetryAdapter?.emit({
        action: 'skipped_step',
        tour_surface: target.tour.surface,
        step_kind: target.step.kind,
        status: 'skipped',
      });
    },
    [resolveActionTarget, storageApi, telemetryAdapter],
  );

  const skipAll = useCallback(() => {
    const target = activeResolved;
    setRequestedTourId(null);
    setManualStepTarget(null);
    setProgress(storageApi.skipAll());
    void telemetryAdapter?.emit({
      action: 'skipped_all',
      tour_surface: target?.tour.surface ?? surface,
      step_kind: target?.step.kind ?? 'navigation',
      status: 'skipped',
    });
  }, [activeResolved, storageApi, surface, telemetryAdapter]);

  const undoSkipAll = useCallback(() => {
    setProgress(storageApi.undoSkipAll());
  }, [storageApi]);

  const resetTour = useCallback(
    (tourId: string) => {
      const tour = getTourById(registry, tourId);
      setManualStepTarget(null);
      setRequestedTourId(tourId);
      setProgress(storageApi.resetTour(tourId));
      if (tour) {
        void telemetryAdapter?.emit({
          action: 'reset',
          tour_surface: tour.surface,
          step_kind: tour.steps[0]?.kind ?? 'navigation',
          status: 'success',
        });
      }
    },
    [registry, storageApi, telemetryAdapter],
  );

  const resetAllTours = useCallback(() => {
    setManualStepTarget(null);
    setRequestedTourId(null);
    setProgress(storageApi.resetAllTours());
    void telemetryAdapter?.emit({
      action: 'reset',
      tour_surface: surface,
      step_kind: 'replay',
      status: 'success',
    });
  }, [storageApi, surface, telemetryAdapter]);

  const replayTour = useCallback(
    (tourId: string) => {
      const tour = getTourById(registry, tourId);
      if (!tour) return;
      setManualStepTarget(null);
      setRequestedTourId(tourId);
      setProgress(storageApi.replayTour(tour));
      void telemetryAdapter?.emit({
        action: 'replayed',
        tour_surface: tour.surface,
        step_kind: tour.steps[0]?.kind ?? 'replay',
        status: 'success',
      });
    },
    [registry, storageApi, telemetryAdapter],
  );

  const backStep = useCallback(() => {
    if (!activeResolved || activeResolved.stepIndex <= 0) return;
    const previousStep = orderedSteps(activeResolved.tour)[activeResolved.stepIndex - 1];
    if (!previousStep) return;
    setRequestedTourId(activeResolved.tour.id);
    setManualStepTarget({ tourId: activeResolved.tour.id, stepId: previousStep.id });
  }, [activeResolved]);

  const summaries = useMemo(
    () => tours.map((tour) => getGuidedHelpTourSummary(progress, tour)),
    [progress, tours],
  );

  const contextValue = useMemo<GuidedHelpContextValue>(
    () => ({
      activeTour: activeResolved?.tour ?? null,
      activeStep: activeResolved?.step ?? null,
      activeStepIndex: activeResolved?.stepIndex ?? -1,
      activeTotalSteps: activeResolved?.totalSteps ?? 0,
      surface,
      isSuppressed,
      skippedAll: progress.skippedAll,
      progress,
      summaries,
      startTour,
      completeStep,
      skipStep,
      skipAll,
      undoSkipAll,
      resetTour,
      resetAllTours,
      replayTour,
      refresh,
    }),
    [
      activeResolved,
      completeStep,
      isSuppressed,
      progress,
      refresh,
      replayTour,
      resetTour,
      resetAllTours,
      skipAll,
      skipStep,
      startTour,
      surface,
      summaries,
      undoSkipAll,
    ],
  );

  return (
    <GuidedHelpContext.Provider value={contextValue}>
      {children}
      {activeResolved && (
        <GuidedHelpPopover
          step={activeResolved.step}
          anchorRect={anchorRect}
          placement={activeResolved.step.placement}
          progress={{ current: activeResolved.stepIndex + 1, total: activeResolved.totalSteps }}
          canGoBack={activeResolved.stepIndex > 0}
          onBack={backStep}
          onNext={() => completeStep()}
          onDone={() => completeStep()}
          onSkipStep={() => skipStep()}
          onSkipAll={skipAll}
        />
      )}
    </GuidedHelpContext.Provider>
  );
}

export function useGuidedHelp(): GuidedHelpContextValue {
  const context = useContext(GuidedHelpContext);
  if (!context) {
    throw new Error('useGuidedHelp must be used inside <GuidedHelpProvider>.');
  }
  return context;
}

export function useOptionalGuidedHelp(): GuidedHelpContextValue | null {
  return useContext(GuidedHelpContext);
}

