// Validations Tab Component
function ValidationsTab({
  boardId,
  card,
  onCardChanged,
  api,
  members,
  canSubmit,
  thresholds,
  thresholdsLoading,
  thresholdsError,
  onRetryThresholds,
  canStartRework,
  reworkBusy,
  onStartRework,
}: {
  boardId: string;
  card: Card;
  onCardChanged: (card: Card) => void;
  api: ReturnType<typeof useDashboardApi>;
  members: { id: string; name: string }[];
  canSubmit: boolean;
  thresholds: ResolvedTaskValidationThresholds | null;
  thresholdsLoading: boolean;
  thresholdsError: string | null;
  onRetryThresholds: () => void;
  canStartRework: boolean;
  reworkBusy: boolean;
  onStartRework: () => Promise<boolean>;
}) {
  const [confidence, setConfidence] = useState(80);
  const [completeness, setCompleteness] = useState(80);
  const [drift, setDrift] = useState(20);
  const [confidenceJustification, setConfidenceJustification] = useState('');
  const [completenessJustification, setCompletenessJustification] = useState('');
  const [driftJustification, setDriftJustification] = useState('');
  const [generalJustification, setGeneralJustification] = useState('');
  const [recommendation, setRecommendation] =
    useState<'approve' | 'reject'>('approve');
  const [submitting, setSubmitting] = useState(false);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const validationIntentRef = useRef({ signature: '', idempotencyKey: '' });
  const learningPermissions = usePermissions(boardId);
  const canSelectLearning = !learningPermissions.isLoading && !learningPermissions.error
    && ['board.read', 'card.entity.read', 'card.entity.context_read', 'card.validation.read',
      'card.comments.read', 'card.conclusion.read', 'card.tests.read', 'spec.entity.read',
      'spec.tests.read', 'kg.query.learning_from_bugs'].every(learningPermissions.has);
  const learningScope = `${boardId}:${card.id}:${card.subject_version}`;
  const [learningChoice, setLearningChoice] = useState<{ scope: string; value: LearningCaptureSelection } | null>(null);
  const onLearningChange = useCallback((value: LearningCaptureSelection | null) => {
    setLearningChoice(value ? { scope: learningScope, value } : null);
  }, [learningScope]);
  useEffect(() => {
    if (!canSelectLearning || recommendation !== 'approve') setLearningChoice(null);
  }, [canSelectLearning, recommendation]);
  const validations = card.validations || [];
  const latestFailedValidation = [...validations]
    .reverse()
    .find((validation) => validationVerdict(validation) === 'fail') ?? null;
  const currentRejectionRecord = card.current_rejection_id
    ? (card.rejection_records || []).find(
      (record) => record.id === card.current_rejection_id,
    ) ?? null
    : null;
  const currentRejectionValidation = card.status === 'rejected'
    ? [...validations].reverse().find((validation) => (
      validation.id === card.current_rejection_id
      || validation.id === currentRejectionRecord?.source_id
      || validation.rejection_cause?.id === card.current_rejection_id
      || (
        validation.card_status === 'rejected'
        && validation.completion_outcome === 'rejected'
      )
    )) ?? null
    : null;
  const rejectionFeedbackValidation =
    currentRejectionValidation ?? latestFailedValidation;
  const rejectionFeedbackValidationId = rejectionFeedbackValidation?.id ?? null;
  const formValid =
    confidenceJustification.trim().length >= 10
    && completenessJustification.trim().length >= 10
    && driftJustification.trim().length >= 10
    && generalJustification.trim().length >= 20;

  useEffect(() => {
    if (card.status === 'rejected' && rejectionFeedbackValidationId) {
      setExpandedId(rejectionFeedbackValidationId);
    }
  }, [card.id, card.status, rejectionFeedbackValidationId]);

  const handleSubmit = async () => {
    if (!formValid || !thresholds || thresholdsLoading || thresholdsError) return;
    if (!Number.isInteger(card.subject_version) || Number(card.subject_version) < 1) {
      toast.error('Reload the card before submitting validation; its current version is unavailable.');
      return;
    }
    setSubmitting(true);
    try {
      const request = {
        expected_subject_version: Number(card.subject_version),
        confidence,
        confidence_justification: confidenceJustification.trim(),
        estimated_completeness: completeness,
        completeness_justification: completenessJustification.trim(),
        estimated_drift: drift,
        drift_justification: driftJustification.trim(),
        general_justification: generalJustification.trim(),
        recommendation,
        ...(card.card_type === 'bug' && recommendation === 'approve' && canSelectLearning
          && learningChoice?.scope === learningScope ? { learning_capture: learningChoice.value } : {}),
      };
      const signature = JSON.stringify(request);
      if (
        validationIntentRef.current.signature !== signature
        || !validationIntentRef.current.idempotencyKey
      ) {
        validationIntentRef.current = {
          signature,
          idempotencyKey: uuidv4(),
        };
      }
      const data = {
        ...request,
        idempotency_key: validationIntentRef.current.idempotencyKey,
      };
      const validation = await api.submitTaskValidation(card.id, data);
      let updatedCard: Card;
      try {
        updatedCard = await api.getCard(card.id);
      } catch {
        const cause = validation.rejection_cause ?? null;
        const rejected = validation.card_status === 'rejected';
        updatedCard = {
          ...card,
          status: validation.card_status || card.status,
          subject_version: validation.subject_version ?? card.subject_version,
          current_rejection_kind: rejected
            ? cause?.kind ?? card.current_rejection_kind ?? null
            : null,
          current_rejection_id: rejected
            ? cause?.id ?? card.current_rejection_id ?? null
            : null,
          current_rejection_code: rejected
            ? cause?.code ?? card.current_rejection_code ?? null
            : null,
          current_rejection_summary: rejected
            ? cause?.summary ?? card.current_rejection_summary ?? null
            : null,
          validations: [...(card.validations || []), validation],
        };
      }
      onCardChanged(updatedCard);
      setExpandedId(validation.id);
      // Reset form
      setConfidence(80);
      setCompleteness(80);
      setDrift(20);
      setConfidenceJustification('');
      setCompletenessJustification('');
      setDriftJustification('');
      setGeneralJustification('');
      setRecommendation('approve');
      setLearningChoice(null);
      validationIntentRef.current = { signature: '', idempotencyKey: '' };
      toast.success('Validation submitted');
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to submit validation');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="space-y-6">
      {card.status === 'rejected' && card.card_type !== 'test' && (
        <section
          role="alert"
          aria-labelledby={`rejected-rework-${card.id}`}
          data-testid="task-rejected-rework-panel"
          className="rounded-xl border border-rose-300 bg-rose-50 p-4 text-rose-900 dark:border-rose-800 dark:bg-rose-950/25 dark:text-rose-100"
        >
          <div className="flex items-start gap-3">
            <ShieldX size={20} className="mt-0.5 shrink-0 text-rose-600 dark:text-rose-300" />
            <div className="min-w-0 flex-1">
              <h3 id={`rejected-rework-${card.id}`} className="text-sm font-semibold">
                Rejected — rework required
              </h3>
              <p className="mt-1 text-xs text-rose-800 dark:text-rose-200">
                {card.current_rejection_summary
                  || (rejectionFeedbackValidation
                  ? rejectionFeedbackValidation.general_justification
                    || 'The latest Task Validation did not pass.'
                  : 'The latest governed completion attempt did not pass. Review the available validation, policy and activity feedback before rework.')}
              </p>
              {(rejectionFeedbackValidation?.threshold_violations?.length || 0) > 0 && (
                <ul className="mt-2 list-disc space-y-1 pl-4 text-xs text-rose-800 dark:text-rose-200">
                  {rejectionFeedbackValidation!.threshold_violations!.map((violation) => (
                    <li key={violation}>{violation}</li>
                  ))}
                </ul>
              )}
              {(rejectionFeedbackValidation?.completion_gate_failures?.length || 0) > 0 && (
                <div className="mt-3 rounded-md border border-rose-300/80 bg-white/55 p-3 dark:border-rose-800 dark:bg-rose-950/30">
                  <p className="text-xs font-semibold text-rose-900 dark:text-rose-100">
                    Completion gates requiring action
                  </p>
                  <ul className="mt-1.5 space-y-2 text-xs text-rose-800 dark:text-rose-200">
                    {rejectionFeedbackValidation!.completion_gate_failures!.map((failure) => (
                      <li key={`${failure.code}:${failure.summary}`}>
                        <span className="font-semibold">{failure.summary}</span>
                        {(failure.reason_codes?.length || 0) > 0 && (
                          <span className="mt-0.5 block text-[11px] text-rose-700 dark:text-rose-300">
                            {failure.reason_codes!.join(' · ')}
                          </span>
                        )}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
              <p className="mt-2 text-xs text-rose-700 dark:text-rose-300">
                Move to In Progress to begin a new execution attempt. A new
                execution report and Current technical traceability are
                required before the card can return to Validation.
              </p>
              <div className="mt-3 flex flex-wrap items-center gap-3">
                <button
                  type="button"
                  onClick={() => { void onStartRework(); }}
                  disabled={!canStartRework || reworkBusy}
                  className="rounded-md bg-rose-600 px-3 py-1.5 text-xs font-semibold text-white hover:bg-rose-700 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {reworkBusy ? 'Starting rework…' : 'Move to In Progress for rework'}
                </button>
                <ContextualHelpLink
                  sectionId="tasks"
                  className="text-xs text-rose-700 dark:text-rose-200"
                  ariaLabel="Open help about Rejected task rework"
                >
                  Rejected lifecycle help
                </ContextualHelpLink>
              </div>
              {!canStartRework && (
                <p className="mt-2 text-[11px] text-rose-700 dark:text-rose-300">
                  Your current role cannot start this rework attempt.
                </p>
              )}
            </div>
          </div>
        </section>
      )}

      {/* Section A: Submit Validation Form — only when status === 'validation' */}
      {card.status === 'validation' && canSubmit && thresholds && (
        <div
          className="bg-violet-50 dark:bg-violet-900/20 border border-violet-200 dark:border-violet-700 rounded-xl p-5 space-y-5"
          aria-busy={thresholdsLoading}
        >
          <h3 className="text-sm font-semibold text-violet-800 dark:text-violet-200 flex items-center gap-2">
            <Shield size={16} />
            Submit Validation
          </h3>

          {thresholdsLoading && (
            <div
              role="status"
              className="rounded-lg border border-violet-300 bg-white/70 px-3 py-2 text-xs text-violet-800 dark:border-violet-700 dark:bg-gray-900/40 dark:text-violet-200"
            >
              Refreshing authoritative Task Validation thresholds. Submission is temporarily disabled.
            </div>
          )}

          <div className="grid gap-4 xl:grid-cols-3">
            <ValidationMetricInput
              id="task-validation-confidence"
              label="Confidence"
              value={confidence}
              direction="higher-is-better"
              threshold={thresholds.min_confidence}
              thresholdSource={thresholds.resolved_sources.min_confidence}
              justification={confidenceJustification}
              onValueChange={setConfidence}
              onJustificationChange={setConfidenceJustification}
            />
            <ValidationMetricInput
              id="task-validation-completeness"
              label="Completeness"
              value={completeness}
              direction="higher-is-better"
              threshold={thresholds.min_completeness}
              thresholdSource={thresholds.resolved_sources.min_completeness}
              justification={completenessJustification}
              onValueChange={setCompleteness}
              onJustificationChange={setCompletenessJustification}
            />
            <ValidationMetricInput
              id="task-validation-drift"
              label="Drift"
              value={drift}
              direction="lower-is-better"
              threshold={thresholds.max_drift}
              thresholdSource={thresholds.resolved_sources.max_drift}
              justification={driftJustification}
              onValueChange={setDrift}
              onJustificationChange={setDriftJustification}
            />
          </div>

          {/* General Justification */}
          <div>
            <label className="text-xs font-medium text-gray-600 dark:text-gray-400 block mb-1">General Justification</label>
            <textarea
              value={generalJustification}
              onChange={(e) => setGeneralJustification(e.target.value)}
              placeholder="Overall validation summary..."
              className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg text-xs dark:bg-gray-700 resize-none text-gray-900 dark:text-gray-100"
              rows={3}
            />
          </div>

          {/* Approve/Reject Toggle */}
          <div className="flex items-center gap-2">
            <button
              onClick={() => setRecommendation('approve')}
              type="button"
              className={`flex items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                recommendation === 'approve'
                  ? 'bg-green-600 text-white ring-2 ring-green-300 dark:ring-green-700'
                  : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-600'
              }`}
            >
              <CheckCircle size={16} />
              Approve
            </button>
            <button
              onClick={() => setRecommendation('reject')}
              type="button"
              className={`flex items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                recommendation === 'reject'
                  ? 'bg-red-600 text-white ring-2 ring-red-300 dark:ring-red-700'
                  : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-600'
              }`}
            >
              <XCircle size={16} />
              Reject
            </button>
          </div>

          {card.card_type === 'bug' && recommendation === 'approve' && canSelectLearning && (
            <LearningCaptureSelector key={learningScope} boardId={boardId} bugId={card.id}
              disabled={submitting} onChange={onLearningChange} />
          )}

          {/* Submit */}
          <button
            onClick={handleSubmit}
            disabled={submitting || !formValid || thresholdsLoading || Boolean(thresholdsError)}
            className={`w-full py-2.5 rounded-lg text-sm font-medium transition-colors ${
              recommendation === 'approve'
                ? 'bg-green-600 hover:bg-green-700 text-white'
                : 'bg-red-600 hover:bg-red-700 text-white'
            } disabled:opacity-50`}
          >
            {submitting
              ? 'Submitting...'
              : `Submit Validation (${recommendation === 'approve' ? 'Approve' : 'Reject'})`}
          </button>
          {!formValid && (
            <p className="text-xs text-violet-700 dark:text-violet-300">
              Each metric justification requires at least 10 characters and
              the general justification requires at least 20.
            </p>
          )}
        </div>
      )}
      {card.status === 'validation' && canSubmit && !thresholds && thresholdsError && (
        <div
          role="alert"
          className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-950/20 dark:text-red-200"
        >
          <p>{thresholdsError} Retry before submitting Task Validation.</p>
          <button
            type="button"
            onClick={onRetryThresholds}
            className="mt-2 rounded-md border border-current/30 px-2.5 py-1 text-xs font-semibold hover:bg-red-100 dark:hover:bg-red-900/30"
          >
            Retry thresholds
          </button>
        </div>
      )}
      {card.status === 'validation' && canSubmit && !thresholds && !thresholdsError && (
        <div className="rounded-lg border border-violet-200 bg-violet-50 p-3 text-sm text-violet-800 dark:border-violet-800 dark:bg-violet-950/20 dark:text-violet-200">
          {thresholdsLoading
            ? 'Resolving effective Task Validation thresholds…'
            : 'Task Validation thresholds are not available yet.'}
        </div>
      )}
      {card.status === 'validation' && !canSubmit && (
        <div className="rounded-lg border border-violet-200 bg-violet-50 p-3 text-sm text-violet-800 dark:border-violet-800 dark:bg-violet-950/20 dark:text-violet-200">
          This card is awaiting independent validation. Your current role can
          read the history but cannot submit Task Validation.
        </div>
      )}

      {/* Section B: Validation History — always visible */}
      <div>
        <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3 flex items-center gap-2">
          <Clock size={14} />
          Validation History
        </h3>

        {validations.length === 0 ? (
          <div className="text-center py-8">
            <Shield size={32} className="mx-auto text-gray-300 dark:text-gray-600 mb-2" />
            <p className="text-sm text-gray-500 dark:text-gray-400">No validations yet</p>
            {card.status !== 'validation' && card.status !== 'rejected' && (
              <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">
                Move this card to "Validation" status to submit a validation
              </p>
            )}
          </div>
        ) : (
          <div className="space-y-2">
            {[...validations].reverse().map((v) => {
              const isExpanded = expandedId === v.id;
              const verdict = validationVerdict(v);
              const completenessScore =
                v.estimated_completeness ?? 0;
              const driftScore = v.estimated_drift ?? 0;
              const summary = v.general_justification;
              const evaluatorId = v.reviewer_id;
              return (
                <div key={v.id} className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
                  <div
                    className="flex items-center gap-2 px-3 py-2.5 cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700/30"
                    onClick={() => setExpandedId(isExpanded ? null : v.id)}
                  >
                    <div className={`w-2 h-2 rounded-full shrink-0 ${verdict === 'pass' ? 'bg-green-500' : 'bg-red-500'}`} />
                    <span className={`text-[10px] px-1.5 py-0.5 rounded font-semibold shrink-0 ${
                      verdict === 'pass'
                        ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300'
                        : 'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300'
                    }`}>
                      {verdict === 'pass' ? 'SUCCESS' : 'FAILED'}
                    </span>
                    <span className="text-sm text-gray-700 dark:text-gray-300 truncate flex-1">
                      {summary || (verdict === 'pass' ? 'Validation passed' : 'Validation failed')}
                    </span>
                    <div className="flex items-center gap-2 shrink-0 text-[10px] text-gray-400">
                      <span className="px-1 py-0.5 rounded bg-violet-100 text-violet-600 dark:bg-violet-900/30 dark:text-violet-300">
                        {resolveActorName(evaluatorId, members)}
                      </span>
                      <span>{v.created_at ? new Date(v.created_at).toLocaleString() : ''}</span>
                    </div>
                    <span className="text-gray-400 shrink-0">
                      {isExpanded ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
                    </span>
                  </div>

                  {isExpanded && (
                    <div className="px-4 py-3 border-t border-gray-100 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-800/50 space-y-3">
                      <div className="grid gap-4 lg:grid-cols-3">
                        <ValidationHistoryMetric
                          label="Confidence"
                          value={v.confidence}
                          direction="higher-is-better"
                          threshold={
                            v.resolved_thresholds?.min_confidence ?? null
                          }
                          thresholdSource={
                            v.resolved_thresholds?.resolved_sources
                              ?.min_confidence
                            ?? v.resolved_thresholds?.resolved_from
                          }
                          status={validationMetricStatus(
                            v,
                            'confidence',
                          )}
                          justification={v.confidence_justification}
                          testId={`task-validation-${v.id}-confidence-score`}
                        />
                        <ValidationHistoryMetric
                          label="Completeness"
                          value={completenessScore}
                          direction="higher-is-better"
                          threshold={
                            v.resolved_thresholds?.min_completeness ?? null
                          }
                          thresholdSource={
                            v.resolved_thresholds?.resolved_sources
                              ?.min_completeness
                            ?? v.resolved_thresholds?.resolved_from
                          }
                          status={validationMetricStatus(
                            v,
                            'completeness',
                          )}
                          justification={v.completeness_justification}
                          testId={`task-validation-${v.id}-completeness-score`}
                        />
                        <ValidationHistoryMetric
                          label="Drift"
                          value={driftScore}
                          direction="lower-is-better"
                          threshold={
                            v.resolved_thresholds?.max_drift ?? null
                          }
                          thresholdSource={
                            v.resolved_thresholds?.resolved_sources?.max_drift
                            ?? v.resolved_thresholds?.resolved_from
                          }
                          status={validationMetricStatus(v, 'drift')}
                          justification={v.drift_justification}
                          testId={`task-validation-${v.id}-drift-score`}
                        />
                      </div>

                      {/* Summary */}
                      {summary && (
                        <div className="pt-2 border-t border-gray-200 dark:border-gray-700">
                          <p className="text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Summary</p>
                          <p className="text-sm text-gray-700 dark:text-gray-300">{summary}</p>
                        </div>
                      )}
                      {(v.threshold_violations?.length || 0) > 0 && (
                        <div className="rounded-md border border-red-200 bg-red-50 p-3 dark:border-red-800 dark:bg-red-950/20">
                          <p className="text-xs font-semibold text-red-700 dark:text-red-300">
                            Threshold violations
                          </p>
                          <ul className="mt-1 list-disc space-y-1 pl-4 text-xs text-red-700 dark:text-red-300">
                            {v.threshold_violations!.map((violation) => (
                              <li key={violation}>{violation}</li>
                            ))}
                          </ul>
                        </div>
                      )}
                      {(v.completion_gate_failures?.length || 0) > 0 && (
                        <div className="rounded-md border border-amber-200 bg-amber-50 p-3 dark:border-amber-800 dark:bg-amber-950/20">
                          <p className="text-xs font-semibold text-amber-800 dark:text-amber-200">
                            Completion gate failures
                          </p>
                          <ul className="mt-1.5 space-y-2 text-xs text-amber-800 dark:text-amber-200">
                            {v.completion_gate_failures!.map((failure) => (
                              <li key={`${failure.code}:${failure.summary}`}>
                                <span className="font-medium">{failure.summary}</span>
                                {(failure.reason_codes?.length || 0) > 0 && (
                                  <span className="mt-0.5 block text-[11px] text-amber-700 dark:text-amber-300">
                                    {failure.reason_codes!.join(' · ')}
                                  </span>
                                )}
                              </li>
                            ))}
                          </ul>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

// Activity Tab Component
function ActivityTab({ cardId, api, revision }: { cardId: string; api: ReturnType<typeof useDashboardApi>; revision: number }) {
  const [logs, setLogs] = useState<ActivityLogEntry[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    api.getCardActivity(cardId)
      .then(value => { if (!cancelled) setLogs(value); })
      .catch(() => { if (!cancelled) { setLogs([]); toast.error('Failed to load activity'); } })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [api, cardId, revision]);

  return <ActivityLogList entries={logs} loading={loading} />;
}

// Markdown renderer with prose styling
function Md({ children, className = '' }: { children: string; className?: string }) {
  return <MarkdownContent content={children} className={className} />;
}

// Mention autocomplete dropdown
function MentionInput({
  value,
  onChange,
  members,
  placeholder,
  multiline = false,
}: {
  value: string;
  onChange: (v: string) => void;
  members: { id: string; name: string }[];
  placeholder: string;
  multiline?: boolean;
}) {
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [filter, setFilter] = useState('');

  const handleChange = (text: string) => {
    onChange(text);
    // Check if user just typed @
    const atMatch = text.match(/@(\w*)$/);
    if (atMatch) {
      setFilter(atMatch[1].toLowerCase());
      setShowSuggestions(true);
    } else {
      setShowSuggestions(false);
    }
  };

  const insertMention = (name: string) => {
    const newVal = value.replace(/@\w*$/, `@${name} `);
    onChange(newVal);
    setShowSuggestions(false);
  };

  const filtered = members.filter((m) => m.name.toLowerCase().includes(filter));

  const InputTag = multiline ? 'textarea' : 'input';

  return (
    <div className="relative">
      <InputTag
        value={value}
        onChange={(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => handleChange(e.target.value)}
        placeholder={placeholder}
        className={`w-full px-3 py-2 border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600 text-gray-900 dark:text-gray-100 ${multiline ? 'resize-none' : ''}`}
        rows={multiline ? 3 : undefined}
      />
      {showSuggestions && filtered.length > 0 && (
        <div className="absolute z-10 top-full mt-1 w-48 bg-white dark:bg-gray-700 border border-gray-200 dark:border-gray-600 rounded-lg shadow-lg max-h-32 overflow-y-auto">
          {filtered.map((m) => (
            <button
              key={m.id}
              onClick={() => insertMention(m.name)}
              className="w-full text-left px-3 py-1.5 text-sm hover:bg-blue-50 dark:hover:bg-blue-900/20"
            >
              @{m.name}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

// Comments Tab Component
function ChoiceBoardRenderer({
  comment,
  api,
  card,
  setCard,
  members,
  canRespond,
}: {
  comment: Comment;
  api: ReturnType<typeof useDashboardApi>;
  card: Card;
  setCard: (c: Card) => void;
  members: { id: string; name: string }[];
  canRespond: boolean;
}) {
  const isMulti = comment.comment_type === 'multi_choice';
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [freeText, setFreeText] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const toggle = (optId: string) => {
    setSelected(prev => {
      const next = new Set(prev);
      if (isMulti) {
        if (next.has(optId)) next.delete(optId); else next.add(optId);
      } else {
        next.clear();
        next.add(optId);
      }
      return next;
    });
  };

  const handleSubmit = async () => {
    if (selected.size === 0) return;
    setSubmitting(true);
    try {
      const updated = await api.respondToChoice(comment.id, Array.from(selected), freeText || undefined);
      setCard({ ...card, comments: card.comments.map(c => c.id === comment.id ? updated : c) });
      setSelected(new Set());
      setFreeText('');
      toast.success('Response recorded');
    } catch {
      toast.error('Failed to respond');
    } finally {
      setSubmitting(false);
    }
  };

  const responses = comment.responses || [];
  const totalResponses = responses.length;

  return (
    <div className="space-y-2">
      <p className="font-medium text-sm text-gray-800 dark:text-gray-100">{comment.content}</p>
      <p className="text-xs text-gray-400">{isMulti ? 'Select one or more' : 'Select one'}</p>

      {/* Options */}
      <div className="space-y-1.5">
        {(comment.choices || []).map(opt => {
          const votes = responses.filter(r => r.selected.includes(opt.id)).length;
          const pct = totalResponses > 0 ? Math.round((votes / totalResponses) * 100) : 0;
          const isSelected = selected.has(opt.id);

          return (
            <button
              key={opt.id}
              onClick={() => {
                if (canRespond) toggle(opt.id);
              }}
              disabled={!canRespond}
              className={`w-full text-left relative rounded-lg border px-3 py-2 text-sm transition-colors ${
                isSelected
                  ? 'border-blue-400 bg-blue-50 dark:bg-blue-900/30 dark:border-blue-500/50'
                  : 'border-gray-200 dark:border-gray-600 hover:border-gray-300 dark:hover:border-gray-500'
              } disabled:cursor-default`}
            >
              {/* Progress bar background */}
              {totalResponses > 0 && (
                <div
                  className="absolute inset-0 rounded-lg bg-blue-100/50 dark:bg-blue-900/20 transition-all"
                  style={{ width: `${pct}%` }}
                />
              )}
              <div className="relative flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <span className={`w-4 h-4 rounded-${isMulti ? 'sm' : 'full'} border-2 flex items-center justify-center ${
                    isSelected ? 'border-blue-500 bg-blue-500' : 'border-gray-300 dark:border-gray-500'
                  }`}>
                    {isSelected && <span className="text-white text-[10px]">✓</span>}
                  </span>
                  <span className="text-gray-700 dark:text-gray-200">{opt.label}</span>
                </div>
                {totalResponses > 0 && (
                  <span className="text-xs text-gray-400">{votes} ({pct}%)</span>
                )}
              </div>
            </button>
          );
        })}
      </div>

      {/* Free text */}
      {canRespond && comment.allow_free_text && (
        <input
          type="text"
          value={freeText}
          onChange={e => setFreeText(e.target.value)}
          placeholder="Additional comment (optional)"
          className="w-full px-3 py-1.5 text-sm border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200"
        />
      )}

      {/* Submit */}
      {canRespond && (
        <button
          onClick={handleSubmit}
          disabled={selected.size === 0 || submitting}
          className="btn btn-primary text-sm disabled:opacity-50"
        >
          {submitting ? 'Submitting...' : 'Submit Response'}
        </button>
      )}

      {/* Responses summary */}
      {totalResponses > 0 && (
        <details className="text-xs text-gray-400 dark:text-gray-500">
          <summary className="cursor-pointer hover:text-gray-600">{totalResponses} response(s)</summary>
          <div className="mt-1 space-y-1 pl-2 border-l-2 border-gray-200 dark:border-gray-600">
            {responses.map((r, i) => (
              <div key={i}>
                <span className="font-medium text-gray-600 dark:text-gray-300">
                  {resolveActorName(r.responder_id, members) || r.responder_name}
                </span>
                {': '}
                {r.selected.map(s => (comment.choices || []).find(c => c.id === s)?.label || s).join(', ')}
                {r.free_text && <span className="italic ml-1">"{r.free_text}"</span>}
              </div>
            ))}
          </div>
        </details>
      )}
    </div>
  );
}

function CommentsTab({
  card,
  setCard,
  api,
  members,
  seenStatus,
  canCreate,
  canCreateChoice,
  canRespondToChoice,
}: {
  card: Card;
  setCard: (c: Card) => void;
  api: ReturnType<typeof useDashboardApi>;
  members: { id: string; name: string }[];
  seenStatus: SeenMap;
  canCreate: boolean;
  canCreateChoice: boolean;
  canRespondToChoice: boolean;
}) {
  const [newComment, setNewComment] = useState('');
  const [mode, setMode] = useState<'text' | 'choice' | 'multi_choice'>('text');
  const [choiceOptions, setChoiceOptions] = useState('');
  const [allowFreeText, setAllowFreeText] = useState(false);

  useEffect(() => {
    if (!canCreateChoice && mode !== 'text') setMode('text');
  }, [canCreateChoice, mode]);

  const handleAddComment = async () => {
    if (mode === 'text') {
      if (!newComment.trim()) return;
      try {
        const comment = await api.createComment(card.id, { content: newComment });
        setCard({ ...card, comments: [...card.comments, comment] });
        setNewComment('');
        toast.success('Comment added');
      } catch {
        toast.error('Failed to add comment');
      }
    } else {
      if (!newComment.trim() || !choiceOptions.trim()) return;
      const options = choiceOptions.split('\n').map(s => s.trim()).filter(Boolean);
      if (options.length < 2) {
        toast.error('At least 2 options required');
        return;
      }
      try {
        const comment = await api.createComment(card.id, {
          content: newComment,
          comment_type: mode,
          choices: options.map((label, i) => ({ id: `opt_${i}`, label })),
          allow_free_text: allowFreeText,
        });
        setCard({ ...card, comments: [...card.comments, comment] });
        setNewComment('');
        setChoiceOptions('');
        setMode('text');
        toast.success('Choice board added');
      } catch {
        toast.error('Failed to create choice board');
      }
    }
  };

  return (
    <div className="space-y-4">
      {canCreate && (
        <>
          {/* Mode selector */}
          <div className="flex gap-1 text-xs">
            {([
              ['text', 'Text'],
              ...(canCreateChoice
                ? [
                    ['choice', 'Single Choice'],
                    ['multi_choice', 'Multi Choice'],
                  ] as const
                : []),
            ] as const).map(([m, label]) => (
              <button
                key={m}
                onClick={() => setMode(m)}
                className={`px-2.5 py-1 rounded-md border transition-colors ${
                  mode === m
                    ? 'bg-blue-50 dark:bg-blue-900/30 border-blue-300 dark:border-blue-500/50 text-blue-700 dark:text-blue-300'
                    : 'border-gray-200 dark:border-gray-600 text-gray-500 hover:bg-gray-50 dark:hover:bg-gray-700'
                }`}
              >
                {label}
              </button>
            ))}
          </div>

          {/* Input */}
          <div>
            <MentionInput
              value={newComment}
              onChange={setNewComment}
              members={members}
              placeholder={mode === 'text' ? 'Write a comment... (use @ to mention)' : 'Enter the question or prompt...'}
              multiline
            />

            {/* Choice options */}
            {mode !== 'text' && canCreateChoice && (
              <div className="mt-2 space-y-2">
                <textarea
                  value={choiceOptions}
                  onChange={e => setChoiceOptions(e.target.value)}
                  placeholder="Enter options, one per line..."
                  rows={3}
                  className="w-full px-3 py-2 text-sm border border-gray-200 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-700 dark:text-gray-200"
                />
                <label className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={allowFreeText}
                    onChange={e => setAllowFreeText(e.target.checked)}
                    className="rounded border-gray-300"
                  />
                  Allow free-text response
                </label>
              </div>
            )}

            <div className="flex justify-end mt-2">
              <button onClick={handleAddComment} className="btn btn-primary">
                {mode === 'text' ? 'Comment' : 'Create Choice Board'}
              </button>
            </div>
          </div>
        </>
      )}

      {/* Comments list */}
      <div className="space-y-3">
        {card.comments.map((comment) => (
          <div key={comment.id} className="bg-gray-50 dark:bg-gray-800 rounded-lg p-3 text-gray-700 dark:text-gray-300">
            {/* Author */}
            <div className="flex items-center gap-1.5 mb-1.5">
              <span className="text-xs font-semibold text-gray-600 dark:text-gray-300">
                {resolveActorName(comment.author_id, members)}
              </span>
              <span className="text-xs text-gray-400 dark:text-gray-500">
                {new Date(comment.created_at).toLocaleDateString('en-US', {
                  day: '2-digit',
                  month: 'short',
                  hour: '2-digit',
                  minute: '2-digit',
                })}
              </span>
            </div>

            {comment.comment_type && comment.comment_type !== 'text' ? (
              <ChoiceBoardRenderer
                comment={comment}
                api={api}
                card={card}
                setCard={setCard}
                members={members}
                canRespond={canRespondToChoice}
              />
            ) : (
              <Md>{comment.content}</Md>
            )}
            <SeenByIndicator itemId={comment.id} seenStatus={seenStatus} />
          </div>
        ))}

        {card.comments.length === 0 && (
          <p className="text-gray-400 dark:text-gray-500 text-sm text-center py-4">
            No comments yet
          </p>
        )}
      </div>
    </div>
  );
}

import { loadEffectiveResourceItems } from '@/services/effectiveResources';
/**
 * CreateCardModal - Modal for creating new cards (normal or bug)
 */

import React, { useEffect, useRef, useState, useMemo } from 'react';
import { X, Bug } from 'lucide-react';
import toast from 'react-hot-toast';
import { v4 as uuidv4 } from 'uuid';
import { useDashboardApi } from '@/services/api';
import { useDashboardStore, useColumns } from '@/store/dashboard';
import { useEscapeToClose } from '@/hooks/useEscapeToClose';
import { usePermissions } from '@/hooks/usePermissions';
import type {
  BugSeverity,
  CardPriority,
  CardStatus,
  CardType,
  CreateCardRequest,
  SpecSummary,
} from '@/types';
import { STATUS_LABELS, CREATABLE_CARD_STATUSES, PRIORITY_LABELS, CARD_PRIORITIES, BUG_SEVERITY_LABELS } from '@/types';
import {
  KnowledgePropagationSelector,
} from '@/components/shared/KnowledgePropagationSelector';
import {
  workspaceKnowledgeCandidate,
  mergeKnowledgePropagationCandidates,
  type KnowledgePropagationCandidate,
} from '@/components/shared/knowledgePropagationCandidates';
import {
  buildKnowledgePropagationEnvelope,
  EMPTY_KNOWLEDGE_PROPAGATION_CHOICE,
  isKnowledgePropagationChoiceValid,
  type KnowledgePropagationChoice,
} from '@/components/shared/knowledgePropagationChoice';

interface CreateCardModalProps {
  boardId: string;
  initialStatus: CardStatus;
  onClose: () => void;
}

export function CreateCardModal({ boardId, initialStatus, onClose }: CreateCardModalProps) {
  const api = useDashboardApi();
  const permissions = usePermissions(boardId);
  const { addCardToColumn } = useDashboardStore();
  const columns = useColumns();

  // All board cards for origin task selection
  const allBoardCards = useMemo(() => Object.values(columns).flat(), [columns]);

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [status, setStatus] = useState<CardStatus>(
    CREATABLE_CARD_STATUSES.includes(initialStatus) ? initialStatus : 'not_started',
  );
  const [priority, setPriority] = useState<CardPriority>('none');
  const [assigneeId, setAssigneeId] = useState('');
  const [labels, setLabels] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [boardMembers, setBoardMembers] = useState<{ id: string; name: string }[]>([]);

  useEscapeToClose(onClose, { canClose: !isLoading });

  // Spec selection
  const [specs, setSpecs] = useState<SpecSummary[]>([]);
  const [selectedSpecId, setSelectedSpecId] = useState('');
  const isDraftSpec = specs.some((spec) => spec.id === selectedSpecId && spec.status === 'draft');
  const [specKnowledge, setSpecKnowledge] = useState<KnowledgePropagationCandidate[]>([]);
  const [knowledgeLoading, setKnowledgeLoading] = useState(false);
  const [knowledgeError, setKnowledgeError] = useState<string | null>(null);
  const [knowledgeReload, setKnowledgeReload] = useState(0);
  const [knowledgeChoice, setKnowledgeChoice] = useState<KnowledgePropagationChoice>(
    EMPTY_KNOWLEDGE_PROPAGATION_CHOICE,
  );
  const [knowledgeIdempotencyKey, setKnowledgeIdempotencyKey] = useState<string>(
    () => uuidv4(),
  );
  const lastSubmittedIntentRef = useRef<string | null>(null);

  // Card type
  const [cardType, setCardType] = useState<CardType>('normal');
  const canCreateStandardCard = permissions.has('card.entity.create');
  const canCreateTestCard = permissions.has('card.entity.create_test');
  const canReadBoardAgents = permissions.has('agent.board_access.read');
  const canCreateSelectedType = cardType === 'test'
    ? canCreateTestCard
    : canCreateStandardCard;

  useEffect(() => {
    if (canCreateSelectedType) return;
    if (canCreateStandardCard) setCardType('normal');
    else if (canCreateTestCard) setCardType('test');
  }, [canCreateSelectedType, canCreateStandardCard, canCreateTestCard]);

  // Test fields
  const [testScenarios, setTestScenarios] = useState<{ id: string; title: string; status: string }[]>([]);
  const [selectedScenarioIds, setSelectedScenarioIds] = useState<string[]>([]);

  // Bug fields
  const [originTaskId, setOriginTaskId] = useState('');
  const [severity, setSeverity] = useState<BugSeverity>('major');
  const [expectedBehavior, setExpectedBehavior] = useState('');
  const [observedBehavior, setObservedBehavior] = useState('');
  const [stepsToReproduce, setStepsToReproduce] = useState('');
  const [actionPlan, setActionPlan] = useState('');

  // Filter tasks by selected spec (for bug origin task picker)
  useEffect(() => {
    // Switching from post-delivery Bug/Test work must not retain a hidden Done
    // parent for a normal task. The backend revalidates under its write fence.
    if (specs.some((spec) => spec.id === selectedSpecId && (
      (cardType === 'normal' && spec.status === 'done')
      || (cardType === 'bug' && spec.status === 'draft')
    ))) {
      setSelectedSpecId('');
    }
  }, [cardType, specs, selectedSpecId]);

  useEffect(() => {
    if (isDraftSpec) setStatus('not_started');
  }, [isDraftSpec]);

  const tasksForSpec = useMemo(() => {
    if (!selectedSpecId) return allBoardCards;
    return allBoardCards.filter((c) => c.spec_id === selectedSpecId);
  }, [allBoardCards, selectedSpecId]);

  useEffect(() => {
    if (canReadBoardAgents) {
      api.listAgentsForBoard(boardId)
        .then((agents) => setBoardMembers(agents.map((a) => ({ id: a.id, name: a.name }))))
        .catch(() => {});
    } else {
      setBoardMembers([]);
    }
  }, [boardId, canReadBoardAgents]);

  useEffect(() => {
    // Draft admits planned tasks/tests; each type retains its later-state rules.
    Promise.all([
      api.listSpecs(boardId, 'draft'),
      api.listSpecs(boardId, 'approved'),
      api.listSpecs(boardId, 'validated'),
      api.listSpecs(boardId, 'in_progress'),
      api.listSpecs(boardId, 'done'),
    ]).then(([draft, approved, validated, inProgress, done]) => {
      setSpecs([...draft, ...approved, ...validated, ...inProgress, ...done]);
    }).catch(() => {});
  }, [boardId]);

  useEffect(() => {
    let cancelled = false;
    setKnowledgeChoice(EMPTY_KNOWLEDGE_PROPAGATION_CHOICE);
    setKnowledgeIdempotencyKey(uuidv4());
    lastSubmittedIntentRef.current = null;
    setSpecKnowledge([]);
    setKnowledgeError(null);
    if (!selectedSpecId) {
      setKnowledgeLoading(false);
      return () => {
        cancelled = true;
      };
    }

    setKnowledgeLoading(true);
    loadEffectiveResourceItems(api.getEffectiveResources, boardId, 'spec', selectedSpecId, 'knowledge_base')
      .then((items) => {
        if (!cancelled) setSpecKnowledge(mergeKnowledgePropagationCandidates(items.map(workspaceKnowledgeCandidate)));
      }).catch((error: unknown) => {
        if (!cancelled) setKnowledgeError(error instanceof Error ? error.message : 'Failed to load effective Knowledge resources');
    }).finally(() => {
      if (!cancelled) setKnowledgeLoading(false);
    });

    return () => {
      cancelled = true;
    };
  }, [boardId, selectedSpecId, knowledgeReload]);

  // Load test scenarios when spec changes and card type is test
  useEffect(() => {
    if (cardType === 'test' && selectedSpecId) {
      api.getSpec(selectedSpecId).then((spec) => {
        const scenarios = (spec.test_scenarios || []).map((s: any) => ({
          id: s.id, title: s.title, status: s.status,
        }));
        setTestScenarios(scenarios);
      }).catch(() => setTestScenarios([]));
    } else {
      setTestScenarios([]);
      setSelectedScenarioIds([]);
    }
  }, [cardType, selectedSpecId]);

  // When card type changes to bug, auto-select spec from origin task
  useEffect(() => {
    if (cardType === 'bug' && originTaskId) {
      const originTask = allBoardCards.find((c) => c.id === originTaskId);
      if (originTask?.spec_id) {
        setSelectedSpecId(originTask.spec_id);
      }
    }
  }, [originTaskId, cardType, allBoardCards]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!canCreateSelectedType) {
      toast.error(`Missing permission: ${
        cardType === 'test'
          ? 'card.entity.create_test'
          : 'card.entity.create'
      }`);
      return;
    }

    if (!title.trim()) {
      toast.error('Title is required');
      return;
    }
    if (status === 'rejected') {
      // Defense in depth: Rejected can only be produced by an admitted
      // server-side completion decision, never by card creation.
      toast.error('Rejected is assigned by a failed validation and cannot be selected during creation.');
      return;
    }
    if (!selectedSpecId) {
      toast.error('A spec must be selected');
      return;
    }
    if (cardType === 'test' && selectedScenarioIds.length === 0) {
      toast.error('Select at least one test scenario');
      return;
    }
    if (cardType === 'bug') {
      if (!originTaskId) {
        toast.error('Origin task is required for bug cards');
        return;
      }
      if (!expectedBehavior.trim()) {
        toast.error('Expected behavior is required');
        return;
      }
      if (!observedBehavior.trim()) {
        toast.error('Observed behavior is required');
        return;
      }
    }
    if (!isKnowledgePropagationChoiceValid(knowledgeChoice)) {
      toast.error(
        knowledgeChoice.action === 'reference'
          || knowledgeChoice.action === 'snapshot'
          ? 'Select at least one Knowledge resource and add a justification'
          : 'Add a justification for the Knowledge decision',
      );
      return;
    }

    const request = {
        title: title.trim(),
        description: description.trim() || undefined,
        status: isDraftSpec ? 'not_started' : status,
        priority: priority !== 'none' ? priority : undefined,
        assignee_id: assigneeId || undefined,
        labels: labels ? labels.split(',').map((l) => l.trim()).filter(Boolean) : undefined,
        // Spec
        spec_id: selectedSpecId,
        knowledge_propagation: buildKnowledgePropagationEnvelope(
          knowledgeChoice,
          '__intent_fingerprint__',
        ),
        // Card type
        ...(cardType !== 'normal' ? { card_type: cardType } : {}),
        // Test fields
        ...(cardType === 'test' ? {
          test_scenario_ids: selectedScenarioIds,
        } : {}),
        // Bug fields
        ...(cardType === 'bug' ? {
          origin_task_id: originTaskId,
          severity,
          expected_behavior: expectedBehavior.trim(),
          observed_behavior: observedBehavior.trim(),
          steps_to_reproduce: stepsToReproduce.trim() || undefined,
          action_plan: actionPlan.trim() || undefined,
        } : {}),
    } as CreateCardRequest;
    const intentFingerprint = JSON.stringify(request);
    let idempotencyKey = knowledgeIdempotencyKey;
    if (
      lastSubmittedIntentRef.current !== null
      && lastSubmittedIntentRef.current !== intentFingerprint
    ) {
      idempotencyKey = uuidv4();
      setKnowledgeIdempotencyKey(idempotencyKey);
    }
    lastSubmittedIntentRef.current = intentFingerprint;
    request.knowledge_propagation = buildKnowledgePropagationEnvelope(
      knowledgeChoice,
      idempotencyKey,
    );

    setIsLoading(true);

    try {
      const card = await api.createCard(boardId, request);

      addCardToColumn({
        id: card.id,
        board_id: card.board_id,
        spec_id: card.spec_id,
        title: card.title,
        description: card.description,
        status: card.status,
        priority: card.priority,
        position: card.position,
        assignee_id: card.assignee_id,
        created_by: card.created_by,
        created_at: card.created_at,
        updated_at: card.updated_at,
        due_date: card.due_date,
        labels: card.labels,
        test_scenario_ids: card.test_scenario_ids,
        conclusions: card.conclusions,
        card_type: card.card_type,
        origin_task_id: card.origin_task_id,
        severity: card.severity,
        linked_test_task_ids: card.linked_test_task_ids,
      });

      toast.success('Card created');
      onClose();
    } catch (error: any) {
      const detail = error?.message || 'Failed to create card';
      toast.error(detail);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="modal-overlay" onClick={() => { if (!isLoading) onClose(); }}>
      <div
        className="modal-content max-w-lg max-h-[90vh] flex flex-col"
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-labelledby="create-card-title"
      >
        <div className="modal-header">
          <h2 id="create-card-title" className="font-semibold text-lg">New Card</h2>
          <button
            type="button"
            onClick={onClose}
            disabled={isLoading}
            aria-label="Close new card dialog"
            className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded disabled:opacity-50"
          >
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="flex flex-col min-h-0 flex-1">
          <div className="modal-body space-y-4 overflow-y-auto flex-1">

            {/* Card Type toggle */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Type
              </label>
              <div className="flex gap-2">
                <button
                  type="button"
                  onClick={() => setCardType('normal')}
                  disabled={!canCreateStandardCard}
                  title={canCreateStandardCard ? 'Create a task card' : 'Missing permission: card.entity.create'}
                  className={`flex-1 px-3 py-2 rounded-lg text-sm font-medium border transition-colors ${
                    cardType === 'normal'
                      ? 'bg-blue-50 border-blue-300 text-blue-700 dark:bg-blue-900/30 dark:border-blue-600 dark:text-blue-300'
                      : 'bg-white border-gray-300 text-gray-600 dark:bg-gray-700 dark:border-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-600'
                  } disabled:cursor-not-allowed disabled:opacity-40`}
                >
                  Task
                </button>
                <button
                  type="button"
                  onClick={() => setCardType('test')}
                  disabled={!canCreateTestCard}
                  title={canCreateTestCard ? 'Create a test card' : 'Missing permission: card.entity.create_test'}
                  className={`flex-1 px-3 py-2 rounded-lg text-sm font-medium border transition-colors ${
                    cardType === 'test'
                      ? 'bg-purple-50 border-purple-300 text-purple-700 dark:bg-purple-900/30 dark:border-purple-600 dark:text-purple-300'
                      : 'bg-white border-gray-300 text-gray-600 dark:bg-gray-700 dark:border-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-600'
                  } disabled:cursor-not-allowed disabled:opacity-40`}
                >
                  Test
                </button>
                <button
                  type="button"
                  onClick={() => setCardType('bug')}
                  disabled={!canCreateStandardCard}
                  title={canCreateStandardCard ? 'Create a bug card' : 'Missing permission: card.entity.create'}
                  className={`flex-1 px-3 py-2 rounded-lg text-sm font-medium border transition-colors inline-flex items-center justify-center gap-1.5 ${
                    cardType === 'bug'
                      ? 'bg-red-50 border-red-300 text-red-700 dark:bg-red-900/30 dark:border-red-600 dark:text-red-300'
                      : 'bg-white border-gray-300 text-gray-600 dark:bg-gray-700 dark:border-gray-600 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-gray-600'
                  } disabled:cursor-not-allowed disabled:opacity-40`}
                >
                  <Bug size={14} />
                  Bug
                </button>
              </div>
            </div>

            {/* Spec selector */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Spec *
              </label>
              <select
                value={selectedSpecId}
                onChange={(e) => setSelectedSpecId(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600"
                disabled={cardType === 'bug' && !!originTaskId}
              >
                <option value="">Select a spec...</option>
                {specs
                  .filter((s) => cardType === 'bug'
                    ? ['approved', 'in_progress', 'done'].includes(s.status)
                    : cardType === 'test'
                    ? ['draft', 'approved', 'validated', 'in_progress', 'done'].includes(s.status)
                    : ['draft', 'approved', 'in_progress'].includes(s.status))
                  .map((s) => (
                  <option key={s.id} value={s.id}>{s.title} ({s.status})</option>
                ))}
              </select>
              {cardType === 'bug' && originTaskId && (
                <p className="text-xs text-gray-400 mt-0.5">Auto-resolved from origin task</p>
              )}
            </div>

            {selectedSpecId && (
              <KnowledgePropagationSelector
                items={specKnowledge}
                value={knowledgeChoice}
                onChange={setKnowledgeChoice}
                loading={knowledgeLoading}
                error={knowledgeError}
                onRetry={() => setKnowledgeReload((current) => current + 1)}
                disabled={isLoading}
                title="Knowledge from the selected spec"
                description="Opt in only to resources that this card actually needs."
                testId="create-card-knowledge-propagation"
              />
            )}

            {/* Test: Scenario selector */}
            {cardType === 'test' && selectedSpecId && (
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Test Scenarios * <span className="text-xs text-gray-400 font-normal">({selectedScenarioIds.length} selected, max 3)</span>
                </label>
                {testScenarios.length === 0 ? (
                  <p className="text-xs text-gray-400">No test scenarios in this spec</p>
                ) : (
                  <div className="max-h-40 overflow-y-auto border border-gray-200 dark:border-gray-600 rounded-lg p-2 space-y-1">
                    {testScenarios.map((s) => (
                      <label
                        key={s.id}
                        className={`flex items-center gap-2 p-1.5 rounded text-sm cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 ${
                          selectedScenarioIds.includes(s.id) ? 'bg-purple-50 dark:bg-purple-900/20' : ''
                        }`}
                      >
                        <input
                          type="checkbox"
                          checked={selectedScenarioIds.includes(s.id)}
                          onChange={(e) => {
                            if (e.target.checked) {
                              if (selectedScenarioIds.length < 3) {
                                setSelectedScenarioIds([...selectedScenarioIds, s.id]);
                              } else {
                                toast.error('Max 3 scenarios per card');
                              }
                            } else {
                              setSelectedScenarioIds(selectedScenarioIds.filter((id) => id !== s.id));
                            }
                          }}
                          className="rounded border-gray-300 dark:border-gray-600"
                        />
                        <span className="text-gray-800 dark:text-gray-200 truncate">{s.title}</span>
                      </label>
                    ))}
                  </div>
                )}
              </div>
            )}

            {/* Bug: Origin Task selector */}
            {cardType === 'bug' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Origin Task *
                </label>
                <select
                  value={originTaskId}
                  onChange={(e) => setOriginTaskId(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600"
                >
                  <option value="">Select origin task...</option>
                  {(selectedSpecId ? tasksForSpec : allBoardCards)
                    .filter((c) => c.card_type !== 'bug')
                    .map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.title} ({c.status})
                      </option>
                    ))}
                </select>
                {!selectedSpecId && (
                  <p className="text-xs text-amber-500 mt-0.5">Select a spec first to filter tasks</p>
                )}
              </div>
            )}

            {/* Title */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Title *
              </label>
              <input
                type="text"
                value={title}
                onChange={(e) => setTitle(e.target.value.slice(0, 200))}
                maxLength={200}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600"
                placeholder={cardType === 'bug' ? 'E.g.: Login returns 500 with uppercase email' : 'E.g.: Implement feature X'}
                autoFocus
              />
              <p className="text-xs text-gray-400 mt-0.5 text-right">{title.length}/200</p>
            </div>

            {/* Description */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Description
              </label>
              <textarea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600 resize-none"
                rows={2}
                placeholder="Describe the card..."
              />
            </div>

            {/* Bug-specific fields */}
            {cardType === 'bug' && (
              <>
                {/* Severity */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Severity *
                  </label>
                  <div className="flex gap-2">
                    {(['critical', 'major', 'minor'] as BugSeverity[]).map((sev) => (
                      <button
                        key={sev}
                        type="button"
                        onClick={() => setSeverity(sev)}
                        className={`flex-1 px-3 py-1.5 rounded-md text-xs font-medium transition-colors ${
                          severity === sev
                            ? sev === 'critical' ? 'bg-red-500 text-white ring-2 ring-red-300'
                            : sev === 'major' ? 'bg-orange-500 text-white ring-2 ring-orange-300'
                            : 'bg-yellow-500 text-white ring-2 ring-yellow-300'
                            : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400'
                        }`}
                      >
                        {BUG_SEVERITY_LABELS[sev]}
                      </button>
                    ))}
                  </div>
                </div>

                {/* Expected Behavior */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Expected Behavior *
                  </label>
                  <textarea
                    value={expectedBehavior}
                    onChange={(e) => setExpectedBehavior(e.target.value)}
                    className="w-full px-3 py-2 border border-green-200 rounded-lg bg-green-50 dark:bg-green-900/10 dark:border-green-700/40 resize-none"
                    rows={2}
                    placeholder="What should happen..."
                  />
                </div>

                {/* Observed Behavior */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Observed Behavior *
                  </label>
                  <textarea
                    value={observedBehavior}
                    onChange={(e) => setObservedBehavior(e.target.value)}
                    className="w-full px-3 py-2 border border-red-200 rounded-lg bg-red-50 dark:bg-red-900/10 dark:border-red-700/40 resize-none"
                    rows={2}
                    placeholder="What actually happens..."
                  />
                </div>

                {/* Steps to Reproduce */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Steps to Reproduce
                  </label>
                  <textarea
                    value={stepsToReproduce}
                    onChange={(e) => setStepsToReproduce(e.target.value)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600 resize-none"
                    rows={2}
                    placeholder="1. Do X  2. Click Y  3. Observe error"
                  />
                </div>

                {/* Action Plan */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                    Action Plan
                  </label>
                  <textarea
                    value={actionPlan}
                    onChange={(e) => setActionPlan(e.target.value)}
                    className="w-full px-3 py-2 border border-blue-200 rounded-lg bg-blue-50 dark:bg-blue-900/10 dark:border-blue-700/40 resize-none"
                    rows={2}
                    placeholder="How to fix..."
                  />
                </div>
              </>
            )}

            {/* Status + Priority row */}
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Status
                </label>
                <select
                  value={status}
                  onChange={(e) => setStatus(e.target.value as CardStatus)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600"
                >
                  {CREATABLE_CARD_STATUSES.filter((s) => !isDraftSpec || s === 'not_started').map((s) => (
                    <option key={s} value={s}>{STATUS_LABELS[s]}</option>
                  ))}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Priority
                </label>
                <select
                  value={priority}
                  onChange={(e) => setPriority(e.target.value as CardPriority)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600"
                >
                  {CARD_PRIORITIES.map((p) => (
                    <option key={p} value={p}>{PRIORITY_LABELS[p]}</option>
                  ))}
                </select>
              </div>
            </div>

            {/* Assignee */}
            {boardMembers.length > 0 && (
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                  Assignee
                </label>
                <select
                  value={assigneeId}
                  onChange={(e) => setAssigneeId(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600"
                >
                  <option value="">None</option>
                  {boardMembers.map((m) => (
                    <option key={m.id} value={m.id}>{m.name}</option>
                  ))}
                </select>
              </div>
            )}

            {/* Labels */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                Labels
              </label>
              <input
                type="text"
                value={labels}
                onChange={(e) => setLabels(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600"
                placeholder="Comma separated: feature, urgent"
              />
            </div>
          </div>

          <div className="modal-footer">
            <button type="button" onClick={onClose} disabled={isLoading} className="btn btn-secondary">
              Cancel
            </button>
            <button
              type="submit"
              disabled={isLoading || !canCreateSelectedType}
              title={canCreateSelectedType ? undefined : 'You do not have permission to create this card type'}
              className="btn btn-primary disabled:cursor-not-allowed disabled:opacity-50"
            >
              {isLoading ? 'Creating...' : cardType === 'bug' ? 'Create Bug' : 'Create Card'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

/**
 * KanbanColumn - Column component for the Kanban board
 */

import type { ReactNode } from 'react';
import {
  SortableContext,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import { useDroppable } from '@dnd-kit/core';
import { Bug, FlaskConical, ListChecks, Plus } from 'lucide-react';
import type { CardSummary, CardStatus, CardType } from '@/types';
import { STATUS_LABELS } from '@/types';
import type { KGCognitivePendingBadgeView } from '@/services/kg-health-api';
import { KanbanCard } from './KanbanCard';
import type { DeliveryReadinessState } from '@/components/code-traceability/DeliveryReadinessView';

const columnColors: Record<CardStatus, string> = {
  not_started: 'border-t-gray-400',
  in_progress: 'border-t-amber-500',
  validation: 'border-t-violet-500',
  rejected: 'border-t-rose-600',
  on_hold: 'border-t-red-500',
  done: 'border-t-green-500',
  cancelled: 'border-t-gray-500',
};

export type KanbanCardFilterType = 'task' | 'test' | 'bug';

interface KanbanCardTypeCounts {
  total: number;
  task: number;
  test: number;
  bug: number;
}

export function normalizeKanbanCardType(cardType: CardSummary['card_type'] | { value?: string } | null | undefined): KanbanCardFilterType {
  if (!cardType) return 'task';
  if (typeof cardType === 'object') return normalizeKanbanCardType(cardType.value as CardSummary['card_type']);
  const normalized = String(cardType).replace(/^CardType\./i, '').toLowerCase();
  if (normalized === 'test') return 'test';
  if (normalized === 'bug') return 'bug';
  return 'task';
}

export function deriveKanbanCardTypeCounts(cards: CardSummary[]): KanbanCardTypeCounts {
  return cards.reduce<KanbanCardTypeCounts>(
    (counts, card) => {
      counts.total += 1;
      counts[normalizeKanbanCardType(card.card_type)] += 1;
      return counts;
    },
    { total: 0, task: 0, test: 0, bug: 0 },
  );
}

const DEFAULT_ACTIVE_CARD_TYPES = new Set<KanbanCardFilterType>(['task', 'test', 'bug']);

const CARD_TYPE_TOGGLES = [
  {
    type: 'task',
    label: 'Task',
    icon: ListChecks,
    activeClass: 'bg-slate-100 text-slate-600 dark:bg-slate-800/80 dark:text-slate-300',
  },
  {
    type: 'test',
    label: 'Test',
    icon: FlaskConical,
    activeClass: 'bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300',
  },
  {
    type: 'bug',
    label: 'Bug',
    icon: Bug,
    activeClass: 'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300',
  },
] as const;

export interface KanbanColumnProps {
  deliveryReadiness?: Record<string, DeliveryReadinessState>;
  status: CardStatus;
  cards: CardSummary[];
  countCards?: CardSummary[];
  totalCount?: number;
  cardTypeFacets?: Partial<Record<CardType, number>>;
  canViewAll?: boolean;
  onViewAll?: () => void;
  activeCardTypes?: ReadonlySet<KanbanCardFilterType>;
  availableCardTypes?: readonly KanbanCardFilterType[];
  onToggleCardType?: (type: KanbanCardFilterType) => void;
  onCardClick: (cardId: string) => void;
  onAddCard: (status: CardStatus) => void;
  canAddCard?: boolean;
  allowCardCreation?: boolean;
  canAcceptDrop?: boolean;
  canDragCard?: (card: CardSummary) => boolean;
  nameMap: Record<string, string>;
  /** Optional controls rendered after the cards, inside the column scroll area. */
  footer?: ReactNode;
  /** KG-03.6 — read-only cognitive badges keyed by source_ref.
   * Resolved at the KanbanBoard level in ONE batch HTTP request and
   * passed down so per-card rendering needs no extra fetch. */
  cognitiveBadges?: Record<string, KGCognitivePendingBadgeView>;
}

export function KanbanColumn({
  status,
  cards,
  countCards,
  totalCount,
  cardTypeFacets,
  canViewAll = false,
  onViewAll,
  activeCardTypes = DEFAULT_ACTIVE_CARD_TYPES,
  availableCardTypes = CARD_TYPE_TOGGLES.map(({ type }) => type),
  onToggleCardType,
  onCardClick,
  onAddCard,
  canAddCard = true,
  allowCardCreation = true,
  canAcceptDrop = true,
  canDragCard,
  nameMap,
  footer,
  cognitiveBadges,
  deliveryReadiness,
}: KanbanColumnProps) {
  const { setNodeRef, isOver } = useDroppable({
    id: status,
    disabled: !canAcceptDrop,
  });
  const localCounts = deriveKanbanCardTypeCounts(countCards ?? cards);
  const counts: KanbanCardTypeCounts = cardTypeFacets
    ? {
        total: totalCount ?? localCounts.total,
        task: cardTypeFacets.normal ?? 0,
        test: cardTypeFacets.test ?? 0,
        bug: cardTypeFacets.bug ?? 0,
      }
    : {
        ...localCounts,
        total: totalCount ?? localCounts.total,
      };

  return (
    <div
      ref={setNodeRef}
      data-tour-id={
        status === 'validation'
          ? 'tasks.validation.column'
          : status === 'rejected'
            ? 'tasks.rejected.column'
            : undefined
      }
      className={`kanban-column h-full min-h-0 border-t-4 ${columnColors[status]} transition-all duration-200 ${
        isOver ? 'ring-2 ring-blue-400 ring-inset bg-blue-50/50 dark:bg-blue-900/20' : ''
      }`}
    >
      {/* Header */}
      <div className="mb-3 shrink-0">
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0 flex-1">
            <div className="flex min-w-0 items-center gap-2">
              <h3 className="truncate font-display text-xs font-semibold uppercase tracking-wider text-gray-700 dark:text-gray-200">
                {STATUS_LABELS[status]}
              </h3>
              <span
                className="inline-flex shrink-0 items-center rounded bg-gray-200 px-1.5 py-0.5 text-xs font-semibold text-gray-600 dark:bg-gray-600 dark:text-gray-200"
                title={`${counts.total} total cards`}
                aria-label={`${counts.total} total cards`}
              >
                {counts.total}
              </span>
            </div>
            <div className={`mt-2 grid gap-1.5 text-[10px] font-semibold ${
              availableCardTypes.length === 2 ? 'grid-cols-2' : 'grid-cols-3'
            }`}>
              {CARD_TYPE_TOGGLES.filter(({ type }) => (
                availableCardTypes.includes(type)
              )).map(({ type, label, icon: Icon, activeClass }) => {
                const active = activeCardTypes.has(type);
                const count = counts[type];
                return (
                  <button
                    key={type}
                    type="button"
                    onClick={() => onToggleCardType?.(type)}
                    aria-pressed={active}
                    aria-label={`${count} ${type} cards`}
                    title={`${active ? 'Hide' : 'Show'} ${label} cards (${count})`}
                    className={`inline-flex min-w-0 items-center justify-between gap-1 rounded-md px-1.5 py-1 transition-colors ${
                      active
                        ? activeClass
                        : 'bg-gray-100 text-gray-400 hover:bg-gray-200 dark:bg-gray-800 dark:text-gray-500 dark:hover:bg-gray-700'
                    } ${onToggleCardType ? 'cursor-pointer' : 'cursor-default'}`}
                  >
                    <span className="inline-flex min-w-0 items-center gap-1">
                      <Icon size={11} className="shrink-0" />
                      <span className="truncate">{label}</span>
                    </span>
                    <span>{count}</span>
                  </button>
                );
              })}
            </div>
          </div>
          {allowCardCreation && (
            <button
              onClick={() => onAddCard(status)}
              disabled={!canAddCard}
              className="shrink-0 rounded p-1 text-gray-400 hover:bg-gray-200 hover:text-gray-600 disabled:cursor-not-allowed disabled:opacity-30 dark:hover:bg-gray-700 dark:hover:text-gray-300"
              title={canAddCard ? 'Add card' : 'Missing card creation permission'}
              aria-label={`Add card to ${STATUS_LABELS[status]}`}
            >
              <Plus size={16} />
            </button>
          )}
        </div>
      </div>

      {/* Cards area */}
      <div className="min-h-0 flex-1 space-y-2 overflow-y-auto pr-1">
        <SortableContext items={cards.map((c) => c.id)} strategy={verticalListSortingStrategy}>
          {cards.map((card) => {
            const sourceRef =
              card.card_type === 'test'
                ? `test:${card.id}`
                : card.card_type === 'bug'
                  ? `bug:${card.id}`
                : !card.card_type || card.card_type === 'normal'
                  ? `task:${card.id}`
                  : null;
            return (
              <KanbanCard
                key={card.id}
                card={card}
                onClick={onCardClick}
                nameMap={nameMap}
                deliveryReadiness={deliveryReadiness?.[card.id]}
                canDrag={canDragCard?.(card) ?? true}
                cognitiveBadge={
                  sourceRef ? cognitiveBadges?.[sourceRef] : undefined
                }
              />
            );
          })}
        </SortableContext>

        {/* Empty state / drop placeholder */}
        {cards.length === 0 && (
          <div
            className={`flex items-center justify-center rounded-lg border-2 border-dashed py-10 text-sm transition-colors ${
              isOver
                ? 'border-blue-400 bg-blue-50 text-blue-500 dark:bg-blue-900/30 dark:border-blue-500 dark:text-blue-400'
                : 'border-gray-300 text-gray-400 dark:border-gray-600 dark:text-gray-500'
            }`}
          >
            {isOver
              ? 'Drop here'
              : status === 'rejected'
                ? 'No cards requiring rework'
                : 'No cards'}
          </div>
        )}

        {/* Drop indicator when column has cards and is being hovered */}
        {cards.length > 0 && isOver && (
          <div className="flex items-center justify-center rounded-lg border-2 border-dashed border-blue-400 bg-blue-50 dark:bg-blue-900/30 dark:border-blue-500 py-3 text-sm text-blue-500 dark:text-blue-400">
            Drop here
          </div>
        )}

        {canViewAll && (
          <button
            type="button"
            onClick={onViewAll}
            aria-label={`View all ${counts.total} cards from ${STATUS_LABELS[status]}`}
            className="w-full rounded-lg border border-dashed border-accent-300 bg-white px-3 py-2 text-xs font-medium text-accent-600 transition-colors hover:bg-accent-50 dark:border-accent-700 dark:bg-gray-800 dark:text-accent-300 dark:hover:bg-accent-950/30"
          >
            View all ({counts.total}) →
          </button>
        )}

        {footer}
      </div>
    </div>
  );
}

