    expect(screen.getByTestId('create-amendment-action')).not.toBeDisabled();
    expect(screen.getByTestId('associate-amd-7')).toBeDisabled();
  });

  // Card 62f6f196 / ts_b6d87391 — a blocked bug surfaces a create OR associate
