/**
 * AuditLogView — displays consolidation audit entries for a board.
 * Shows session history: who consolidated what, when, and how many nodes/edges.
 */

import { useState, useEffect } from 'react';
import type { AuditEntry } from '@/types/knowledge-graph';
import * as kgApi from '@/services/kg-api';
import { KGRefreshButton } from './KGRefreshButton';
import { usePermissions } from '@/hooks/usePermissions';

interface Props {
  boardId: string;
}

const STATUS_BADGE: Record<string, string> = {
  none: 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-400',
  undone: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400',
  undo_blocked: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400',
};

export function AuditLogView({ boardId }: Props) {
  const permissions = usePermissions(boardId);
  const canReadAudit = (
    !permissions.isLoading
    && !permissions.error
    && !permissions.ownerReviewRequired
    && permissions.has('kg.operations.audit.read')
  );
  const [entries, setEntries] = useState<AuditEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (permissions.isLoading) return;
    if (!canReadAudit) {
      setLoading(false);
      setError('You do not have permission to read the KG audit log');
      return;
    }
    void loadAudit();
  }, [boardId, canReadAudit, permissions.isLoading]);

  async function loadAudit() {
    if (!canReadAudit) return;
    setLoading(true);
    setError(null);
    try {
      const data = await kgApi.listAudit(boardId, 100);
      setEntries(data.entries || []);
    } catch (err: any) {
      setError(err.message || 'Failed to load audit log');
    } finally {
      setLoading(false);
    }
  }

  if (loading) {
    return (
      <div className="p-6 flex items-center justify-center">
        <div className="animate-pulse text-gray-400">Loading audit log...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6">
        <p className="text-red-500 mb-3">{error}</p>
        <button onClick={loadAudit} className="text-sm text-blue-600 hover:underline">
          Retry
        </button>
      </div>
    );
  }

  if (entries.length === 0) {
    return (
      <div className="p-6 text-center text-gray-500 dark:text-gray-400">
        <div className="text-4xl mb-3">📋</div>
        <h3 className="font-medium mb-1">No audit entries yet</h3>
        <p className="text-sm">Consolidation sessions will appear here once the KG agent processes artifacts.</p>
      </div>
    );
  }

  return (
    <div className="p-6">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-lg font-semibold text-gray-900 dark:text-gray-100">
          Audit Log
        </h2>
        <KGRefreshButton
          onRefresh={loadAudit}
          loading={loading}
          testId="audit-refresh"
        />
      </div>

      <div className="space-y-3">
        {entries.map((entry) => (
          <div
            key={entry.session_id}
            className="border border-gray-200 dark:border-gray-700 rounded-lg p-4"
          >
            <div className="flex items-start justify-between mb-2">
              <div className="flex items-center gap-2">
                <span className={`text-xs px-2 py-0.5 rounded-full ${STATUS_BADGE[entry.undo_status] || STATUS_BADGE.none}`}>
                  {entry.undo_status === 'none' ? 'committed' : entry.undo_status}
                </span>
                <span className="text-xs text-gray-400 font-mono">
                  {entry.session_id.slice(0, 16)}...
                </span>
              </div>
              <span className="text-xs text-gray-500 dark:text-gray-400">
                {entry.committed_at ? new Date(entry.committed_at).toLocaleString() : '—'}
              </span>
            </div>

            <div className="text-sm text-gray-700 dark:text-gray-300 mb-2">
              {entry.summary_text || `Consolidated ${entry.artifact_id?.slice(0, 8) ?? '?'}...`}
            </div>

            <div className="flex gap-4 text-xs text-gray-500 dark:text-gray-400">
              <span title="Nodes added">+{entry.nodes_added} nodes</span>
              {entry.nodes_updated > 0 && (
                <span title="Nodes updated">~{entry.nodes_updated} updated</span>
              )}
              {entry.nodes_superseded > 0 && (
                <span title="Nodes superseded">{entry.nodes_superseded} superseded</span>
              )}
              <span title="Edges added">+{entry.edges_added} edges</span>
              <span className="ml-auto" title="Agent">
                {entry.agent_id?.slice(0, 20) ?? 'unknown'}
              </span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

/**
 * GraphCanvas — interactive KG visualization rendered with Sigma.js (WebGL).
 *
 * Rendering migrated from React Flow to Sigma + graphology + ForceAtlas2
 * (worker) — the same stack used by Marginalia's GraphView — for a modern,
 * fluid and responsive canvas that stays smooth at thousands of nodes.
 *
 * Every capability of the previous React Flow canvas is preserved:
 *   - filters (types / edgeTypes / minRelevance / searchQuery) — client-side
 *   - selection interaction matrix (AC-4):
 *       click on node      → toggle selection (clicking same node clears it)
 *       double-click node  → emit onSelect(node) (opens the detail panel)
 *       click empty pane   → clear selection
 *   - hover tooltip after 500ms (AC-7) + single-click NodePreviewPanel (AC-8)
 *   - node dragging with positions kept until the next data reload
 *   - viewport refit on node-set change and on `refitTrigger`
 *   - dark/light theme reactivity (Tailwind class strategy)
 *   - filtered-empty state with clear-filters / lower-relevance CTAs (AC-19)
 *   - MiniMap (custom canvas — colors per NODE_TYPE_CONFIG) + zoom controls
 *
 * New capabilities inherited from the Marginalia renderer:
 *   - animated ForceAtlas2 layout in a Web Worker (with settling indicator
 *     and an explicit "Re-run layout" action)
 *   - hover dimming: everything not adjacent to the hovered node fades
 *   - edge hover highlight with forced edge labels
 *   - WebGL-unavailable fallback that keeps the node list inspectable (an
 *     accessible list with the same selection semantics, instead of a crash)
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import Graph from 'graphology';
import { Sigma } from 'sigma';
import FA2Layout from 'graphology-layout-forceatlas2/worker';
import { inferSettings } from 'graphology-layout-forceatlas2';
import { Loader2, Maximize, MonitorX, RotateCcw, ZoomIn, ZoomOut } from 'lucide-react';
import type {
  CodeTraceabilityKGKind,
  KGNode,
  KGEdge,
  KGNodeType,
  KGEdgeType,
} from '@/types/knowledge-graph';
import {
  EDGE_TYPE_CONFIG,
  kgEdgeDisplayLabel,
  kgNodeDisplayType,
  kgNodeVisualConfig,
} from '@/types/knowledge-graph';
import { NodeTooltip } from './NodeTooltip';
import { NodePreviewPanel } from './NodePreviewPanel';
import { SigmaMiniMap } from './graph/SigmaMiniMap';

export interface GraphCanvasFilters {
  types: KGNodeType[];
  edgeTypes: KGEdgeType[];
  codeTraceabilityKinds?: CodeTraceabilityKGKind[];
  /** Minimum relevance_score (0..1) — slider in the controls panel.
   *  Operates on KGNode.relevance_score (the conceptually-correct field
   *  shown in the node detail panel as "Relevance"). */
  minRelevance: number;
  searchQuery: string;
}

interface Props {
  nodes: KGNode[];
  edges: KGEdge[];
  filters: GraphCanvasFilters;
  /** Fired on every single-click (used by parent to clear detail panel if needed). */
  onNodeClick?: (node: KGNode | null) => void;
  /** Fired on double-click — the canonical "open detail panel" signal. */
  onSelect?: (node: KGNode) => void;
  /** Optional initial selection (e.g. deep-link). Updates push new value into internal state. */
  initialSelectedNodeId?: string | null;
  /** When `filteredNodes.length === 0` but `nodes.length > 0`, parent can offer to reset filters (S5.4). */
  onClearFilters?: () => void;
  /** Lower the relevance threshold to a specific value (used by the empty-state CTA). */
  onAdjustRelevance?: (value: number) => void;
  /** Bumped by parent (e.g. when the sidebar collapses/expands) to request a
   *  delayed re-fit once the surrounding layout transition has settled. */
  refitTrigger?: number;
  /** Board owning this graph, used to resolve selected-node provenance. */
  boardId?: string;
  /** Promote the inline preview to a full modal when "Show more" is clicked. */
  onShowDetails?: (node: KGNode) => void;
}

function prefersDarkMode(): boolean {
  if (typeof window === 'undefined' || typeof document === 'undefined') return false;
  // The app uses Tailwind's `class` strategy: dark mode is signalled by a
  // `dark` class on <html>, not by the OS preference. Check that first and
  // fall back to the OS hint only when the class isn't present.
  if (document.documentElement.classList.contains('dark')) return true;
  return window.matchMedia?.('(prefers-color-scheme: dark)').matches ?? false;
}

// Sigma renders via WebGL and throws the moment it can't get a context —
// headless browsers (jsdom in tests), GPU disabled. Probe up front so we can
// render an accessible fallback instead of crashing the whole SPA.
function hasWebGL(): boolean {
  try {
    const canvas = document.createElement('canvas');
    return Boolean(
      canvas.getContext('webgl2') ||
        canvas.getContext('webgl') ||
        canvas.getContext('experimental-webgl'),
    );
  } catch {
    return false;
  }
}

// Deterministic-ish initial placement on a circle. Sigma needs x/y on every
// node before render or it piles everything at the origin; FA2 then spreads them.
function seedCoords(i: number, n: number): { x: number; y: number } {
  const a = (2 * Math.PI * i) / Math.max(n, 1);
  const r = 50 + (i % 7) * 8;
  return { x: Math.cos(a) * r, y: Math.sin(a) * r };
}

// Degree → node radius. Sub-linear (sqrt) so a few very-high-degree hubs
// don't dwarf everything; clamped to a sane pixel range for sigma.
function nodeSize(degree: number): number {
  const r = 4 + Math.sqrt(degree) * 1.8;
  return Math.min(r, 22);
}

const LABEL_MAX = 42;
function truncateLabel(title: string): string {
  return title.length > LABEL_MAX ? `${title.slice(0, LABEL_MAX - 1)}…` : title;
}

const THEME = {
  light: {
    dimNode: '#E5E7EB',
    dimEdge: '#F1F5F9',
    edge: '#CBD5E1',
    edgeHover: '#475569',
    label: '#111827',
    edgeLabel: '#64748B',
  },
  dark: {
    dimNode: '#1F2937',
    dimEdge: '#111827',
    edge: '#334155',
    edgeHover: '#94A3B8',
    label: '#E5E7EB',
    edgeLabel: '#94A3B8',
  },
} as const;

const LAYOUT_SETTLE_MS = 2500;

export function GraphCanvas({
  nodes,
  edges,
  filters,
  onNodeClick,
  onSelect,
  initialSelectedNodeId = null,
  onClearFilters,
  onAdjustRelevance,
  boardId,
  onShowDetails,
  refitTrigger = 0,
}: Props) {
  // Selection is internal to the canvas — parent lives independently of it.
  const [selectedId, setSelectedId] = useState<string | null>(initialSelectedNodeId);
  // Hover state drives the NodeTooltip (S5.1 / AC-7).
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [isDark, setIsDark] = useState<boolean>(() => prefersDarkMode());
  const [settling, setSettling] = useState(false);
  // Evaluated once — WebGL support doesn't change within a page load.
  const [webglOk] = useState(hasWebGL);
  // Bumped by the "Re-run layout" button to re-fling node positions.
  const [layoutEpoch, setLayoutEpoch] = useState(0);

  // Imperative sigma/graphology handles — kept out of React state on purpose.
  const containerRef = useRef<HTMLDivElement | null>(null);
  const sigmaRef = useRef<Sigma | null>(null);
  const graphRef = useRef<Graph | null>(null);
  const layoutRef = useRef<FA2Layout | null>(null);
  // Read inside sigma reducers without re-binding them every render.
  const selectedRef = useRef<string | null>(selectedId);
  selectedRef.current = selectedId;
  const hoveredSigmaRef = useRef<string | null>(null);
  const hoveredEdgeRef = useRef<string | null>(null);
  const isDarkRef = useRef(isDark);
  isDarkRef.current = isDark;
  // True when the next data rebuild should re-center the camera.
  const freshLoadRef = useRef(true);
  // Drag overrides — user-moved positions persist across filter re-layouts
  // but NOT across full graph reloads (no backend persistence per Fase 1).
  const dragOverridesRef = useRef<Map<string, { x: number; y: number }>>(new Map());
  // Latest node list for event handlers (avoid stale closures in sigma events).
  const nodesRef = useRef<KGNode[]>(nodes);
  nodesRef.current = nodes;
  const onNodeClickRef = useRef(onNodeClick);
  onNodeClickRef.current = onNodeClick;
  const onSelectRef = useRef(onSelect);
  onSelectRef.current = onSelect;

  // Allow parents to programmatically clear/set selection through a prop change.
  useEffect(() => {
    setSelectedId(initialSelectedNodeId);
  }, [initialSelectedNodeId]);

  // React to theme toggles (Tailwind class strategy) AND OS-level changes.
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const sync = () => setIsDark(prefersDarkMode());
    const observer = new MutationObserver(sync);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ['class'],
    });
    const mq = window.matchMedia?.('(prefers-color-scheme: dark)');
    mq?.addEventListener?.('change', sync);
    return () => {
      observer.disconnect();
      mq?.removeEventListener?.('change', sync);
    };
  }, []);

  const filteredNodes = useMemo(() => {
    let result = nodes;
    if (filters.types.length > 0) {
      result = result.filter((n) => filters.types.includes(n.node_type));
    }
    if ((filters.codeTraceabilityKinds?.length ?? 0) > 0) {
      result = result.filter((n) => filters.codeTraceabilityKinds?.includes(
        n.kind_of as CodeTraceabilityKGKind,
      ));
    }
    if (filters.minRelevance > 0) {
      result = result.filter((n) => (n.relevance_score ?? 0) >= filters.minRelevance);
    }
    if (filters.searchQuery) {
      const q = filters.searchQuery.toLowerCase();
      result = result.filter(
        (n) =>
          n.title.toLowerCase().includes(q) ||
          (n.content?.toLowerCase().includes(q) ?? false),
      );
    }
    return result;
  }, [nodes, filters]);

  const filteredNodeIds = useMemo(
    () => new Set(filteredNodes.map((n) => n.id)),
    [filteredNodes],
  );

  const filteredEdges = useMemo(() => {
    return edges.filter((e) => {
      if (!filteredNodeIds.has(e.source) || !filteredNodeIds.has(e.target)) {
        return false;
      }
      if (filters.edgeTypes.length > 0 && !filters.edgeTypes.includes(e.edge_type)) {
        return false;
      }
      return true;
    });
  }, [edges, filteredNodeIds, filters.edgeTypes]);

  // Degree per visible node — drives node size (Marginalia convention).
  const degrees = useMemo(() => {
    const map = new Map<string, number>();
    for (const e of filteredEdges) {
      map.set(e.source, (map.get(e.source) ?? 0) + 1);
      map.set(e.target, (map.get(e.target) ?? 0) + 1);
    }
    return map;
  }, [filteredEdges]);

  // ── sigma lifecycle ────────────────────────────────────────────────────────
  // The container div unmounts whenever the filtered set goes empty (the
  // early-return empty state) and remounts when nodes come back — so sigma's
  // lifetime is tied to the CONTAINER via a callback ref, not to the
  // component mount. A plain effect would leave a renderer bound to a
  // detached div after an empty→populated round-trip (blank canvas).
  const teardownRef = useRef<(() => void) | null>(null);
  const [sigmaEpoch, setSigmaEpoch] = useState(0);
  const containerCallbackRef = useCallback((el: HTMLDivElement | null) => {
    teardownRef.current?.();
    teardownRef.current = null;
    sigmaRef.current = null;
    graphRef.current = null;
    containerRef.current = el;
    if (!el || !webglOk) return;
    const graph = new Graph({ multi: true });
    graphRef.current = graph;
    const renderer = new Sigma(graph, el, {
      // The container can be mid-layout (width 0) at mount; the
      // ResizeObserver below resizes the renderer as soon as it settles.
      allowInvalidContainer: true,
      renderLabels: true,
      renderEdgeLabels: true,
      enableEdgeEvents: true,
      labelRenderedSizeThreshold: 6,
      labelFont: 'ui-sans-serif, system-ui, sans-serif',
      labelSize: 11,
      edgeLabelFont: 'ui-sans-serif, system-ui, sans-serif',
      edgeLabelSize: 9,
      minCameraRatio: 0.05,
      maxCameraRatio: 12,
      // Theme-dependent colors resolved per render via reducers below.
      labelColor: { color: isDarkRef.current ? THEME.dark.label : THEME.light.label },
      edgeLabelColor: { color: isDarkRef.current ? THEME.dark.edgeLabel : THEME.light.edgeLabel },
    });
    sigmaRef.current = renderer;
    const resizeObserver =
      typeof ResizeObserver !== 'undefined'
        ? new ResizeObserver(() => {
            renderer.resize();
            renderer.refresh();
          })
        : null;
    resizeObserver?.observe(el);

    // ── node dragging (capability preserved from React Flow) ────────────────
    // While dragging we move the node to the cursor's graph position and
    // suppress both camera panning and the click-toggle that follows mouseup.
    let draggedNode: string | null = null;
    let dragMoved = false;
    renderer.on('downNode', ({ node }) => {
      draggedNode = node;
      dragMoved = false;
    });
    const mouseCaptor = renderer.getMouseCaptor();
    mouseCaptor.on('mousemovebody', (e) => {
      if (!draggedNode) return;
      dragMoved = true;
      const pos = renderer.viewportToGraph(e);
      graph.setNodeAttribute(draggedNode, 'x', pos.x);
      graph.setNodeAttribute(draggedNode, 'y', pos.y);
      // Don't pan the camera while a node is being dragged.
      e.preventSigmaDefault();
      e.original.preventDefault();
      e.original.stopPropagation();
    });
    mouseCaptor.on('mouseup', () => {
      if (draggedNode && dragMoved) {
        dragOverridesRef.current.set(draggedNode, {
          x: graph.getNodeAttribute(draggedNode, 'x') as number,
          y: graph.getNodeAttribute(draggedNode, 'y') as number,
        });
      }
      draggedNode = null;
    });

    // ── hover (dim non-neighbors immediately; tooltip handled by React) ─────
    renderer.on('enterNode', ({ node }) => {
      hoveredSigmaRef.current = node;
      scheduleTooltip(node);
      renderer.refresh();
    });
    renderer.on('leaveNode', () => {
      hoveredSigmaRef.current = null;
      cancelTooltip();
      renderer.refresh();
    });
    renderer.on('enterEdge', ({ edge }) => {
      hoveredEdgeRef.current = edge;
      renderer.refresh();
    });
    renderer.on('leaveEdge', () => {
      hoveredEdgeRef.current = null;
      renderer.refresh();
    });

    // ── selection interaction matrix (AC-4, unchanged semantics) ────────────
    renderer.on('clickNode', ({ node }) => {
      if (dragMoved) return; // a drag is not a click
      setSelectedId((current) => (current === node ? null : node));
      if (onNodeClickRef.current) {
        const kgNode = nodesRef.current.find((n) => n.id === node) ?? null;
        onNodeClickRef.current(kgNode);
      }
    });
    renderer.on('doubleClickNode', ({ node, event }) => {
      event.preventSigmaDefault(); // don't zoom on double-click-select
      const kgNode = nodesRef.current.find((n) => n.id === node);
      if (kgNode && onSelectRef.current) onSelectRef.current(kgNode);
    });
    renderer.on('clickStage', () => {
      setSelectedId(null);
      onNodeClickRef.current?.(null);
    });

    // ── reducers: per-render appearance from hover/selection/theme ──────────
    // Graph data stays clean (idiomatic sigma v3); theme colors are resolved
    // here so a dark/light flip only needs a refresh, not a data rebuild.
    renderer.setSetting('nodeReducer', (node, data) => {
      const theme = isDarkRef.current ? THEME.dark : THEME.light;
      const cfg = kgNodeVisualConfig({
        node_type: data.nodeType as KGNodeType,
        kind_of: data.kindOf as string | null | undefined,
      });
      const res = { ...data };
      res.color = cfg ? (isDarkRef.current ? cfg.darkColor : cfg.color) : '#6B7280';
      const sel = selectedRef.current;
      const hov = hoveredSigmaRef.current;
      if (sel === node) {
        res.highlighted = true;
        res.zIndex = 2;
        res.size = (data.size as number) + 3;
      } else if (sel && graph.hasNode(sel)) {
        // Tiered fade (Spec 8 / S4.2): neighbors of the selection stay full;
        // everything else dims gently (not hidden).
        const neighbors = new Set(graph.neighbors(sel));
        if (!neighbors.has(node)) {
          res.color = theme.dimNode;
        }
      }
      if (hov && graph.hasNode(hov)) {
        const neighbors = new Set(graph.neighbors(hov));
        neighbors.add(hov);
        if (!neighbors.has(node)) {
          res.color = theme.dimNode;
          res.label = '';
        }
      }
      return res;
    });
    renderer.setSetting('edgeReducer', (edge, data) => {
      const theme = isDarkRef.current ? THEME.dark : THEME.light;
      const res = { ...data };
      const sel = selectedRef.current;
      const hov = hoveredSigmaRef.current;
      const hovEdge = hoveredEdgeRef.current;
      // Base stroke comes from EDGE_TYPE_CONFIG (stored on the edge); slightly
      // muted until hover/selection pulls it forward.
      res.color = (data.baseColor as string) ?? theme.edge;
      if (hovEdge === edge) {
        res.color = theme.edgeHover;
        res.size = 2.2;
        res.forceLabel = true;
        res.zIndex = 2;
      }
      if (sel && graph.hasNode(sel)) {
        const [s, t] = graph.extremities(edge);
        if (s === sel || t === sel) {
          res.size = Math.max((data.size as number) ?? 1, 1.8);
          res.forceLabel = true;
          res.zIndex = 1;
        } else {
          res.color = theme.dimEdge;
        }
      }
      if (hov && graph.hasNode(hov)) {
        const [s, t] = graph.extremities(edge);
        if (s === hov || t === hov) {
          res.forceLabel = true;
          res.zIndex = 2;
        } else {
          res.hidden = true;
        }
      }
      return res;
    });

    teardownRef.current = () => {
      resizeObserver?.disconnect();
      layoutRef.current?.kill();
      layoutRef.current = null;
      renderer.kill();
    };
    // A fresh renderer starts empty — bump the epoch so the data-rebuild
    // effect repopulates it (covers empty→populated container remounts).
    freshLoadRef.current = true;
    setSigmaEpoch((k) => k + 1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [webglOk]);

  // Tear the renderer down with the component (callback refs only fire with
  // null on unmount of the DOM node, which this covers too — but be safe).
  useEffect(() => {
    return () => {
      teardownRef.current?.();
      teardownRef.current = null;
      sigmaRef.current = null;
      graphRef.current = null;
    };
  }, []);

  // The reducers only run on a sigma render; selection/theme changes don't
  // move the camera, so force a refresh to repaint the styles.
  useEffect(() => {
    sigmaRef.current?.refresh();
  }, [selectedId, isDark]);

  // ── data rebuild + FA2 layout ──────────────────────────────────────────────
  useEffect(() => {
    const graph = graphRef.current;
    const renderer = sigmaRef.current;
    if (!graph || !renderer) return;

    // Stop any running layout before mutating the graph.
    layoutRef.current?.kill();
    layoutRef.current = null;

    // Preserve coords for nodes already placed (avoids a full re-fling on
    // filter changes); explicit re-layout (layoutEpoch) drops them.
    const prevCoords = new Map<string, { x: number; y: number }>();
    if (layoutEpoch === 0 || !freshLoadRef.current) {
      graph.forEachNode((id, attr) => {
        prevCoords.set(id, { x: attr.x as number, y: attr.y as number });
      });
    }

    graph.clear();
    hoveredSigmaRef.current = null;
    hoveredEdgeRef.current = null;
    filteredNodes.forEach((n, i) => {
      const c =
        dragOverridesRef.current.get(n.id) ??
        prevCoords.get(n.id) ??
        seedCoords(i, filteredNodes.length);
      graph.addNode(n.id, {
        x: c.x,
        y: c.y,
        size: nodeSize(degrees.get(n.id) ?? 0),
        label: truncateLabel(n.title || n.id),
        nodeType: n.node_type,
        kindOf: n.kind_of ?? null,
      });
    });
    for (const e of filteredEdges) {
      if (graph.hasNode(e.source) && graph.hasNode(e.target)) {
        const cfg = EDGE_TYPE_CONFIG[e.edge_type];
        graph.addEdgeWithKey(e.id || `${e.source}|${e.edge_type}|${e.target}`, e.source, e.target, {
          type: 'line',
          label: kgEdgeDisplayLabel(e),
          // `contradicts` is always-noisy by spec (S4.3): thicker + its
          // own red so conflicts stay visible without animation.
          size: e.edge_type === 'contradicts' ? 2.2 : 1.2,
          baseColor: cfg?.color ?? '#9CA3AF',
        });
      }
    }
    renderer.refresh();

    if (graph.order < 2) {
      setSettling(false);
      return;
    }
    // Worker-based FA2 so the main thread never freezes; stop after settling.
    const layout = new FA2Layout(graph, {
      settings: { ...inferSettings(graph), slowDown: 10 },
    });
    layoutRef.current = layout;
    setSettling(true);
    layout.start();
    const recenter = freshLoadRef.current;
    freshLoadRef.current = false;
    const timer = window.setTimeout(() => {
      layout.stop();
      setSettling(false);
      if (recenter) renderer.getCamera().animatedReset({ duration: 300 });
    }, LAYOUT_SETTLE_MS);

    return () => {
      window.clearTimeout(timer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filteredNodes, filteredEdges, degrees, layoutEpoch, sigmaEpoch]);

  // Wipe drag overrides + recenter when the underlying data reloads (new
  // fetch / pagination) — same semantics as the React Flow implementation.
  useEffect(() => {
    dragOverridesRef.current = new Map();
    freshLoadRef.current = true;
  }, [nodes]);

  // Re-fit after a surrounding layout transition (sidebar collapse/expand)
  // completes. The 320ms delay matches the sidebar width transition.
  useEffect(() => {
    if (refitTrigger === 0 || filteredNodes.length === 0) return;
    const handle = window.setTimeout(() => {
      sigmaRef.current?.getCamera().animatedReset({ duration: 350 });
    }, 320);
    return () => window.clearTimeout(handle);
  }, [refitTrigger, filteredNodes.length]);

  // ── hover tooltip (500ms delay — AC-7 scrub guard) ─────────────────────────
  const hoverTimerRef = useRef<number | null>(null);
  const cancelTooltip = useCallback(() => {
    if (hoverTimerRef.current !== null) {
      window.clearTimeout(hoverTimerRef.current);
      hoverTimerRef.current = null;
    }
    setHoveredId(null);
  }, []);
  const scheduleTooltip = useCallback((id: string) => {
    if (hoverTimerRef.current !== null) window.clearTimeout(hoverTimerRef.current);
    hoverTimerRef.current = window.setTimeout(() => {
      setHoveredId(id);
      hoverTimerRef.current = null;
    }, 500);
  }, []);

  const selectedNode = useMemo(() => {
    if (!selectedId) return null;
    return filteredNodes.find((n) => n.id === selectedId) ?? null;
  }, [filteredNodes, selectedId]);

  const hoveredNode = useMemo(() => {
    if (!hoveredId) return null;
    return filteredNodes.find((n) => n.id === hoveredId) ?? null;
  }, [filteredNodes, hoveredId]);

  const handlePreviewClose = useCallback(() => {
    setSelectedId(null);
    onNodeClick?.(null);
  }, [onNodeClick]);

  const rerunLayout = useCallback(() => {
    dragOverridesRef.current = new Map();
    freshLoadRef.current = true;
    setLayoutEpoch((k) => k + 1);
  }, []);

  const zoomIn = useCallback(() => {
    sigmaRef.current?.getCamera().animatedZoom({ duration: 200 });
  }, []);
  const zoomOut = useCallback(() => {
    sigmaRef.current?.getCamera().animatedUnzoom({ duration: 200 });
  }, []);
  const fitView = useCallback(() => {
    sigmaRef.current?.getCamera().animatedReset({ duration: 300 });
  }, []);

  // Accessible fallback selection handlers (no-WebGL path keeps the same
  // selection semantics so the data stays explorable everywhere).
  const fallbackClick = useCallback(
    (n: KGNode) => {
      setSelectedId((current) => (current === n.id ? null : n.id));
      onNodeClick?.(n);
    },
    [onNodeClick],
  );
  const fallbackDoubleClick = useCallback(
    (n: KGNode) => {
      onSelect?.(n);
    },
    [onSelect],
  );

  // S5.4 — distinguish "no data yet" (nodes empty) from "filters hid everything"
  // (nodes > 0 but filteredNodes = 0).
  if (filteredNodes.length === 0) {
    const isFilteredEmpty = nodes.length > 0;
    const maxRelevancePresent = isFilteredEmpty
      ? nodes.reduce((m, n) => Math.max(m, n.relevance_score ?? 0), 0)
      : 0;
    const relevanceIsCulprit =
      isFilteredEmpty &&
      filters.minRelevance > 0 &&
      maxRelevancePresent < filters.minRelevance;
    return (
      <div
        className="h-full flex flex-col items-center justify-center gap-3"
        data-testid="kg-canvas-empty"
        data-empty-state={isFilteredEmpty ? 'filtered' : 'yet'}
      >
        <p className="text-gray-400 dark:text-gray-500 text-sm">
          {relevanceIsCulprit
            ? `No nodes match the relevance filter (max present: ${(maxRelevancePresent * 100).toFixed(0)}%, filter: ${(filters.minRelevance * 100).toFixed(0)}%).`
            : isFilteredEmpty
              ? 'No nodes match the current filters.'
              : 'No nodes to display.'}
        </p>
        {isFilteredEmpty && (
          <div className="flex gap-2">
            {relevanceIsCulprit && onAdjustRelevance && (
              <button
                type="button"
                onClick={() => onAdjustRelevance(maxRelevancePresent)}
                data-testid="kg-adjust-relevance"
                className="px-4 py-1.5 text-xs rounded bg-blue-600 text-white hover:bg-blue-700"
              >
                Lower to {(maxRelevancePresent * 100).toFixed(0)}%
              </button>
            )}
            {onClearFilters && (
              <button
                type="button"
                onClick={onClearFilters}
                data-testid="kg-clear-filters"
                className="px-4 py-1.5 text-xs rounded bg-gray-200 text-gray-800 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-100 dark:hover:bg-gray-600"
              >
                Clear filters
              </button>
            )}
          </div>
        )}
      </div>
    );
  }

  return (
    <div
      className="h-full w-full relative"
      role="region"
      aria-label={`Knowledge graph with ${filteredNodes.length} nodes`}
      data-testid="kg-canvas"
      data-selected-id={selectedId ?? ''}
      data-empty-state="populated"
      data-renderer={webglOk ? 'sigma' : 'fallback'}
    >
      {filteredEdges.some((edge) => edge.edge_type === 'violates' && edge.assertion_basis === 'origin_proxy') && (
        <div role="note" data-testid="kg-origin-proxy-note"
          className="absolute top-3 left-3 z-20 max-w-xs rounded border border-gray-200 bg-white/95 px-3 py-2 text-xs text-gray-600 dark:border-gray-700 dark:bg-gray-900/95 dark:text-gray-300">
          Origin association (inferred). Shared cause not established.
        </div>
      )}
      {webglOk ? (
        <>
          {/* sigma mounts here — lifecycle bound to the container element */}
          <div ref={containerCallbackRef} className="absolute inset-0" data-testid="kg-sigma-container" />

          {/* layout status + re-run (Marginalia) */}
          <div className="absolute bottom-3 right-3 z-20 flex items-center gap-2">
            {settling && (
              <span
                className="flex items-center gap-1.5 text-[11px] text-blue-500 dark:text-blue-400"
                data-testid="kg-layout-settling"
              >
                <Loader2 size={12} className="animate-spin" /> settling layout…
              </span>
            )}
            <button
              type="button"
              onClick={rerunLayout}
              data-testid="kg-rerun-layout"
              title="Re-run force layout"
              className="flex items-center gap-1.5 rounded-md border border-gray-200 dark:border-gray-700 bg-white/90 dark:bg-gray-900/90 px-2 py-1 text-[11px] text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800"
            >
              <RotateCcw size={11} /> Re-run layout
            </button>
          </div>

          {/* zoom controls (React Flow Controls parity) */}
          <div
            className="absolute bottom-3 left-3 z-20 flex flex-col rounded-md border border-gray-200 dark:border-gray-700 bg-white/90 dark:bg-gray-900/90 shadow-sm overflow-hidden"
            data-testid="kg-zoom-controls"
          >
            <button
              type="button"
              onClick={zoomIn}
              aria-label="Zoom in"
              className="p-1.5 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800"
            >
              <ZoomIn size={14} />
            </button>
            <button
              type="button"
              onClick={zoomOut}
              aria-label="Zoom out"
              className="p-1.5 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 border-t border-gray-200 dark:border-gray-700"
            >
              <ZoomOut size={14} />
            </button>
            <button
              type="button"
              onClick={fitView}
              aria-label="Fit view"
              className="p-1.5 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 border-t border-gray-200 dark:border-gray-700"
            >
              <Maximize size={14} />
            </button>
          </div>

          {/* MiniMap (React Flow MiniMap parity — custom canvas) */}
          <SigmaMiniMap
            sigmaRef={sigmaRef}
            isDark={isDark}
            epoch={`${sigmaEpoch}:${filteredNodes.length}:${layoutEpoch}:${settling}`}
          />

          <p className="pointer-events-none absolute bottom-3 left-12 z-10 text-[10px] text-gray-400 dark:text-gray-600">
            scroll to zoom · drag to pan · drag node to move · click to preview · double-click for details
          </p>
        </>
      ) : (
        // WebGL unavailable → never instantiate sigma. Keep the data fully
        // explorable through an accessible list with the SAME selection
        // semantics (click = preview/toggle, double-click = detail panel).
        <div className="absolute inset-0 overflow-y-auto p-4" data-testid="kg-webgl-fallback">
          <div className="mb-3 flex items-center gap-2 text-amber-500 dark:text-amber-400">
            <MonitorX size={16} aria-hidden />
            <span className="text-xs">
              WebGL is unavailable — showing the {filteredNodes.length} visible node(s) as a list.
            </span>
          </div>
          <ul className="flex flex-col gap-1">
            {filteredNodes.map((n) => {
              const cfg = kgNodeVisualConfig(n);
              const isSelected = n.id === selectedId;
              return (
                <li key={n.id}>
                  <button
                    type="button"
                    onClick={() => fallbackClick(n)}
                    onDoubleClick={() => fallbackDoubleClick(n)}
                    data-testid={`kg-node-${n.node_type.toLowerCase()}`}
                    data-node-id={n.id}
                    data-kind-of={n.kind_of ?? ''}
                    data-selected={isSelected ? 'true' : 'false'}
                    className={`flex w-full items-center gap-2 rounded px-2 py-1 text-left text-xs ${
                      isSelected
                        ? 'bg-blue-50 dark:bg-blue-950/40 ring-1 ring-blue-400'
                        : 'hover:bg-gray-100 dark:hover:bg-gray-800'
                    }`}
                  >
                    <span
                      className="h-2.5 w-2.5 shrink-0 rounded-full"
                      style={{ backgroundColor: isDark ? cfg?.darkColor : cfg?.color }}
                      aria-hidden
                    />
                    <span className="truncate text-gray-800 dark:text-gray-200">{n.title}</span>
                    <span className="ml-auto shrink-0 text-[10px] text-gray-400">
                      {kgNodeDisplayType(n)}
                    </span>
                  </button>
                </li>
              );
            })}
          </ul>
        </div>
      )}

      <NodeTooltip node={hoveredNode} />
      <NodePreviewPanel
        node={selectedNode}
        onClose={handlePreviewClose}
        boardId={boardId}
        onShowDetails={onShowDetails}
      />
    </div>
  );
}

/**
 * KnowledgeGraphPage — container component orchestrating the KG visualization.
 *
 * Spec 8 / Sprint 4 + Sprint 5 wiring:
 *   - Holds `nodeLimit` (50/100/200/500/1000) + `nextCursor` for paginated fetch.
 *   - Changing `nodeLimit` resets the list and refetches from scratch.
 *   - Clicking the Load More button fetches the next page and APPENDS results.
 *   - The button is only visible while `nextCursor !== null`.
 *   - Sprint 5: filter-reset callback + spec navigation + testable retry.
 *
 * Selection + highlight live inside GraphCanvas (S4.1). The detail panel
 * here is opened by the double-click callback (`onSelect`) per AC-4; the
 * single-click preview is rendered by GraphCanvas itself (AC-8).
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { AlertTriangle, HelpCircle, PanelLeftClose, PanelLeftOpen } from 'lucide-react';
import { GraphCanvas } from './GraphCanvas';
import { KGHelpModal } from './KGHelpModal';
import { NodeDetailPanel } from './NodeDetailPanel';
import { GraphControlsPanel } from './GraphControlsPanel';
import type { Filters } from './GraphControlsPanel';
import { EmptyState } from './EmptyState';
import { AuditLogView } from './AuditLogView';
import { KGSyncIndicator } from './KGSyncIndicator';
import { PrivacyView } from './PrivacyView';
import { GlobalSearchView } from './GlobalSearchView';
import { KGRefreshButton } from './KGRefreshButton';
import { NodeDetailModal } from './NodeDetailModal';
import { useKgLiveEvents } from '@/hooks/useKgLiveEvents';
import {
  isCodeTraceabilityKind,
  type KGNode,
  type KGEdge,
  type KGStats,
} from '@/types/knowledge-graph';
import * as kgApi from '@/services/kg-api';
import { getKGHealth, type KGHealth } from '@/services/kg-health-api';
import { PulseLoader } from '@/components/shared/PulseLoader';
import { usePermissions } from '@/hooks/usePermissions';
import { useOptionalModalStack } from '@/contexts/ModalStackContext';
import { useCodeTraceabilityAuthority } from '@/components/code-traceability';

interface Props {
  boardId: string;
}

export function resolveGraphTotalNodeCount(
  stats: KGStats | null,
  health: KGHealth | null,
): number | undefined {
  const counts = stats?.node_counts_by_type;
  if (counts && Object.keys(counts).length > 0) {
    return Object.values(counts).reduce((sum, count) => (
      Number.isFinite(count) && count > 0 ? sum + count : sum
    ), 0);
  }
  const healthTotal = health?.total_nodes;
  return health?.metric_status === 'available' && typeof healthTotal === 'number' && healthTotal >= 0
    ? healthTotal
    : undefined;
}

type SubView = 'graph' | 'audit' | 'privacy' | 'global';

// 500 (era 100): com a projeção paginada, edges só materializam quando as
// duas pontas chegam ao cliente — páginas pequenas deixavam o grafo
// parecendo desconectado e exigiam dezenas de "Load more". O Sigma/WebGL
// lida bem com 500+ nós por página.
const DEFAULT_NODE_LIMIT = 500;
const HIDE_ALL_NODE_TYPE = '__hide_all__';
const DEFAULT_FILTERS: Filters = {
  types: [],
  edgeTypes: [],
  codeTraceabilityKinds: [],
  graphLayer: 'canonical',
  // Default 0% so the slider doesn't hide nodes until the user opts in.
  // Backend currently sends constant relevance_score for most nodes, so a
  // non-zero default would silently filter without producing visible value.
  minRelevance: 0,
  searchQuery: '',
};

const SIDEBAR_WIDTH_KEY = 'kg-sidebar-width';
const SIDEBAR_COLLAPSED_KEY = 'kg-sidebar-collapsed';
const SIDEBAR_DEFAULT = 256;
const SIDEBAR_MIN = 180;
const SIDEBAR_MAX = 520;

export function GraphVisibilityMismatchState({
  boardId,
  health,
  metadata,
  onRefresh,
}: {
  boardId: string;
  health: KGHealth;
  metadata: kgApi.GraphMetadata | null;
  onRefresh: () => void;
}) {
  const schemaLabel = health.graph_schema_version
    ? `Graph schema ${health.graph_schema_version}`
    : 'Graph schema unavailable';
  const tickLabel = health.last_tick_status
    ? `Last tick: ${health.last_tick_status}`
    : 'No tick result recorded';
  return (
    <div className="flex h-full items-center justify-center bg-surface-50 dark:bg-surface-950 px-6">
      <div className="max-w-xl rounded-lg border border-amber-300 dark:border-amber-700 bg-white dark:bg-surface-900 p-5 shadow">
        <div className="mb-3 flex items-center gap-2 text-amber-700 dark:text-amber-300">
          <AlertTriangle className="h-5 w-5" aria-hidden />
          <h2 className="text-base font-semibold">KG data exists, graph view is empty</h2>
        </div>
        <p className="text-sm text-surface-700 dark:text-surface-300">
          Health reports {health.total_nodes?.toLocaleString() ?? 'an unavailable count of'} node(s) for this board, but
          the visualization endpoint returned no nodes.
        </p>
        <div className="mt-4 grid grid-cols-1 gap-2 text-xs text-surface-600 dark:text-surface-400 sm:grid-cols-2">
          <div className="rounded border border-surface-200 dark:border-surface-700 px-3 py-2">
            <div className="font-semibold text-surface-800 dark:text-surface-200">Board</div>
            <div className="truncate font-mono">{boardId}</div>
          </div>
          <div className="rounded border border-surface-200 dark:border-surface-700 px-3 py-2">
            <div className="font-semibold text-surface-800 dark:text-surface-200">Schemas</div>
            <div>{schemaLabel}</div>
            <div>Health schema {health.health_schema_version}</div>
          </div>
          <div className="rounded border border-surface-200 dark:border-surface-700 px-3 py-2">
            <div className="font-semibold text-surface-800 dark:text-surface-200">Tick</div>
            <div>{tickLabel}</div>
            {health.last_tick_error && (
              <div className="truncate text-rose-600 dark:text-rose-300" title={health.last_tick_error}>
                {health.last_tick_error}
              </div>
            )}
          </div>
          <div className="rounded border border-surface-200 dark:border-surface-700 px-3 py-2">
            <div className="font-semibold text-surface-800 dark:text-surface-200">Edges</div>
            <div>Status {metadata?.edge_read_status ?? 'unknown'}</div>
            <div>{metadata?.edge_tables_failed ?? 0} failed table(s)</div>
          </div>
        </div>
        <button
          type="button"
          onClick={onRefresh}
          data-testid="kg-empty-mismatch-refresh"
          className="mt-4 rounded-md bg-blue-600 px-4 py-2 text-sm font-medium text-white hover:bg-blue-700"
        >
          Refresh graph
        </button>
      </div>
    </div>
  );
}

export function KnowledgeGraphPage({ boardId }: Props) {
  const permissions = usePermissions(boardId);
  const { canReadProjection: canReadCodeTraceability } =
    useCodeTraceabilityAuthority(boardId);
  const policyReady = (
    !permissions.isLoading
    && !permissions.error
    && !permissions.ownerReviewRequired
  );
  const canReadHealth = policyReady && permissions.has('kg.operations.health.read');
  const [nodes, setNodes] = useState<KGNode[]>([]);
  const [edges, setEdges] = useState<KGEdge[]>([]);
  const [graphMetadata, setGraphMetadata] = useState<kgApi.GraphMetadata | null>(null);
  const [healthSnapshot, setHealthSnapshot] = useState<KGHealth | null>(null);
  const [statsSnapshot, setStatsSnapshot] = useState<KGStats | null>(null);
  const [nextCursor, setNextCursor] = useState<string | null>(null);
  const [selectedNode, setSelectedNode] = useState<KGNode | null>(null);
  const [modalNode, setModalNode] = useState<KGNode | null>(null);
  const modalStack = useOptionalModalStack();
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [subView, setSubView] = useState<SubView>('graph');
  const [nodeLimit, setNodeLimit] = useState<number>(DEFAULT_NODE_LIMIT);
  const [filters, setFilters] = useState<Filters>(DEFAULT_FILTERS);

  const authorityNodes = useMemo(
    () => canReadCodeTraceability
      ? nodes
      : nodes.filter((node) => !isCodeTraceabilityKind(node.kind_of)),
    [canReadCodeTraceability, nodes],
  );
  const authorityEdges = useMemo(() => {
    if (canReadCodeTraceability) return edges;
    const visibleIds = new Set(authorityNodes.map((node) => node.id));
    return edges.filter(
      (edge) => visibleIds.has(edge.source) && visibleIds.has(edge.target),
    );
  }, [authorityNodes, canReadCodeTraceability, edges]);
  const totalNodeCount = useMemo(
    () => resolveGraphTotalNodeCount(statsSnapshot, healthSnapshot),
    [healthSnapshot, statsSnapshot],
  );

  useEffect(() => {
    if (canReadCodeTraceability) return;
    setFilters((current) => (
      (current.codeTraceabilityKinds?.length ?? 0) > 0
        ? { ...current, codeTraceabilityKinds: [] }
        : current
    ));
    setSelectedNode((current) => (
      isCodeTraceabilityKind(current?.kind_of) ? null : current
    ));
    setModalNode((current) => (
      isCodeTraceabilityKind(current?.kind_of) ? null : current
    ));
  }, [canReadCodeTraceability]);
  const [sidebarWidth, setSidebarWidth] = useState<number>(() => {
    if (typeof window === 'undefined') return SIDEBAR_DEFAULT;
    const stored = window.localStorage.getItem(SIDEBAR_WIDTH_KEY);
    const parsed = stored ? Number(stored) : NaN;
    return Number.isFinite(parsed) && parsed >= SIDEBAR_MIN && parsed <= SIDEBAR_MAX
      ? parsed
      : SIDEBAR_DEFAULT;
  });
  const [sidebarCollapsed, setSidebarCollapsed] = useState<boolean>(() => {
    if (typeof window === 'undefined') return false;
    return window.localStorage.getItem(SIDEBAR_COLLAPSED_KEY) === '1';
  });
  const dragState = useRef<{ startX: number; startWidth: number } | null>(null);
  const graphRequest = useRef(0);
  const diagnosticsRequest = useRef(0);
  const statsRequest = useRef(0);
  const [helpOpen, setHelpOpen] = useState(false);
  const serverNodeType = useMemo(() => {
    const realTypes = filters.types.filter((type) => String(type) !== HIDE_ALL_NODE_TYPE);
    return filters.types.length > 0 && realTypes.length === 1 ? realTypes[0] : undefined;
  }, [filters.types]);

  // Shift+/ opens the help modal while the KG page is mounted. We bind on
  // window but only while the page is active; preventDefault stops the
  // browser Find-in-page from swallowing the keypress.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === '?' && !helpOpen) {
        const target = e.target as HTMLElement | null;
        const tag = target?.tagName ?? '';
        // Ignore when the user is typing in an input / textarea / contentEditable
        if (tag === 'INPUT' || tag === 'TEXTAREA' || target?.isContentEditable) return;
        e.preventDefault();
        setHelpOpen(true);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [helpOpen]);

  const [refitTrigger, setRefitTrigger] = useState(0);

  const toggleSidebar = useCallback(() => {
    setSidebarCollapsed((prev) => {
      const next = !prev;
      window.localStorage.setItem(SIDEBAR_COLLAPSED_KEY, next ? '1' : '0');
      return next;
    });
    // Re-fit the canvas after the width transition completes so the graph
    // re-frames into the new available area.
    setRefitTrigger((k) => k + 1);
  }, []);

  const loadGraph = useCallback(
    async (limit: number) => {
      const request = ++graphRequest.current;
      setLoading(true);
      setError(null);
      try {
        const data = await kgApi.getSubgraph(boardId, {
          limit,
          min_relevance: 0,
          type: serverNodeType,
          graph_layer: filters.graphLayer,
        });
        if (request !== graphRequest.current) return;
        setNodes(data.nodes || []);
        setEdges(data.edges || []);
        setGraphMetadata(data.metadata ?? null);
        setNextCursor(data.next_cursor ?? null);
      } catch (err) {
        if (request !== graphRequest.current) return;
        setError(err instanceof Error ? err.message : 'Failed to load graph');
      } finally {
        if (request === graphRequest.current) setLoading(false);
      }
    },
    [boardId, filters.graphLayer, serverNodeType],
  );

  const loadDiagnostics = useCallback(async () => {
    const request = ++diagnosticsRequest.current;
    const health = canReadHealth ? await getKGHealth(boardId).catch(() => null) : null;
    if (request === diagnosticsRequest.current) setHealthSnapshot(health);
  }, [boardId, canReadHealth]);

  // Health permissions hydrate independently of the graph census. Do not start
  // another expensive census when those unrelated permissions become ready.
  const loadStats = useCallback(async () => {
    const request = ++statsRequest.current;
    setStatsSnapshot(null);
    const stats = await kgApi.getStats(boardId, {
      graph_layer: filters.graphLayer,
    }).catch(() => null);
    if (request !== statsRequest.current) return;
    setStatsSnapshot(stats);
  }, [boardId, filters.graphLayer]);

  const refreshGraph = useCallback(() => {
    void loadGraph(nodeLimit);
    void loadDiagnostics();
    void loadStats();
  }, [loadDiagnostics, loadGraph, loadStats, nodeLimit]);

  useEffect(() => {
    void loadGraph(nodeLimit);
    return () => {
      graphRequest.current += 1;
    };
  }, [boardId, nodeLimit, loadGraph]);

  useEffect(() => {
    void loadDiagnostics();
    return () => {
      diagnosticsRequest.current += 1;
    };
  }, [loadDiagnostics]);

  useEffect(() => {
    void loadStats();
    return () => {
      statsRequest.current += 1;
    };
  }, [loadStats]);

  // Wire SSE live events. When a commit burst settles, auto-refetch the
  // graph so the canvas reflects the new state — the sync indicator chip
  // surfaces unseen commits + connection state to the user.
  const liveEvents = useKgLiveEvents(boardId, {
    onFlush: () => {
      if (subView === 'graph') loadGraph(nodeLimit);
    },
  });

  // Keyboard shortcut `R` is wired by KGRefreshButton itself via `shortcut`.

  const handleNodeLimitChange = useCallback((limit: number) => {
    setSelectedNode(null);
    setNodeLimit(limit);
  }, []);

  const handleLoadMore = useCallback(async () => {
    if (!nextCursor || loadingMore) return;
    setLoadingMore(true);
    try {
      const data = await kgApi.getSubgraph(boardId, {
        limit: nodeLimit,
        cursor: nextCursor,
        min_relevance: 0,
        type: serverNodeType,
        graph_layer: filters.graphLayer,
      });
      // Dedupe appended nodes/edges on id to defend against overlap if the
      // cursor was advanced by a concurrent consolidation.
      setNodes((prev) => {
        const seen = new Set(prev.map((n) => n.id));
        const appended = (data.nodes ?? []).filter((n) => !seen.has(n.id));
        return [...prev, ...appended];
      });
      setEdges((prev) => {
        const seen = new Set(prev.map((e) => e.id));
        const appended = (data.edges ?? []).filter((e) => !seen.has(e.id));
        return [...prev, ...appended];
      });
      setGraphMetadata(data.metadata ?? graphMetadata);
      setNextCursor(data.next_cursor ?? null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load more');
    } finally {
      setLoadingMore(false);
    }
  }, [
    boardId,
    nodeLimit,
    nextCursor,
    loadingMore,
    graphMetadata,
    serverNodeType,
    filters.graphLayer,
  ]);

  const handleClearFilters = useCallback(() => {
    setFilters(DEFAULT_FILTERS);
  }, []);

  const visibleNodeCount = useMemo(() => {
    const search = filters.searchQuery.trim().toLowerCase();
    return authorityNodes.filter((node) => {
      if (filters.types.length > 0 && !filters.types.includes(node.node_type)) return false;
      if (
        (filters.codeTraceabilityKinds?.length ?? 0) > 0
        && !filters.codeTraceabilityKinds?.includes(
          node.kind_of as NonNullable<Filters['codeTraceabilityKinds']>[number],
        )
      ) return false;
      if ((node.relevance_score ?? 0) < filters.minRelevance) return false;
      if (!search) return true;
      return (
        node.title.toLowerCase().includes(search) ||
        (node.content ?? '').toLowerCase().includes(search) ||
        (node.justification ?? '').toLowerCase().includes(search)
      );
    }).length;
  }, [
    filters.codeTraceabilityKinds,
    filters.minRelevance,
    filters.searchQuery,
    filters.types,
    authorityNodes,
  ]);

  const handleAdjustRelevance = useCallback((value: number) => {
    setFilters((prev) => ({ ...prev, minRelevance: value }));
  }, []);

  // Drag-to-resize on the divider between the controls panel and the canvas.
  // Width is clamped + persisted to localStorage so it survives reloads.
  const handleDividerMouseDown = useCallback(
    (e: React.MouseEvent) => {
      dragState.current = { startX: e.clientX, startWidth: sidebarWidth };
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
    },
    [sidebarWidth],
  );

  useEffect(() => {
    const onMove = (e: MouseEvent) => {
      const drag = dragState.current;
      if (!drag) return;
      const delta = e.clientX - drag.startX;
      const next = Math.max(SIDEBAR_MIN, Math.min(SIDEBAR_MAX, drag.startWidth + delta));
      setSidebarWidth(next);
    };
    const onUp = () => {
      if (!dragState.current) return;
      dragState.current = null;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
      window.localStorage.setItem(SIDEBAR_WIDTH_KEY, String(sidebarWidth));
    };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    return () => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
    };
  }, [sidebarWidth]);

  const handleShowDetails = (node: KGNode) => {
    if (modalStack) modalStack.push({ type: 'kg_node', id: node.id, boardId });
    else setModalNode(node);
  };

  // Graph rendering is independent of technical diagnostics.
  if (loading) {
    return (
      <div
        className="flex items-center justify-center h-full"
        data-testid="kg-loading"
      >
        <PulseLoader size="md" label="Loading Knowledge Graph..." />
      </div>
    );
  }

  if (error) {
    return (
      <div
        className="flex flex-col items-center justify-center h-full gap-4"
        data-testid="kg-error"
        role="alert"
      >
        <p className="text-red-500" data-testid="kg-error-message">
          {error}
        </p>
        <button
          type="button"
          onClick={() => loadGraph(nodeLimit)}
          data-testid="kg-error-retry"
          className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
        >
          Retry
        </button>
      </div>
    );
  }

  if (nodes.length === 0 && subView === 'graph') {
    const mismatchHealth = healthSnapshot;
    if (mismatchHealth && mismatchHealth.metric_status === 'available'
      && mismatchHealth.total_nodes != null && mismatchHealth.total_nodes > 0) {
      return (
        <div data-testid="kg-empty-mismatch" className="h-full">
          <GraphVisibilityMismatchState
            boardId={boardId}
            health={mismatchHealth}
            metadata={graphMetadata}
            onRefresh={refreshGraph}
          />
        </div>
      );
    }
  }

  return (
    <div className="flex h-full">
      {/* Left: Controls panel — width animates between sidebarWidth and 0
          when the user toggles collapse. The inner content keeps its full
          width during the transition (via the inline style on the inner
          wrapper) so it doesn't reflow as the outer width shrinks; the
          outer overflow:hidden clips it cleanly. */}
      <div
        style={{ width: sidebarCollapsed ? 0 : sidebarWidth, flexShrink: 0 }}
        className="relative border-r border-gray-200 dark:border-gray-700 overflow-hidden transition-[width] duration-300 ease-in-out"
        data-testid="kg-sidebar"
        data-collapsed={sidebarCollapsed}
      >
        <div
          style={{ width: sidebarWidth, height: '100%' }}
          className="overflow-y-auto"
        >
          <button
            type="button"
            onClick={toggleSidebar}
            data-testid="kg-sidebar-collapse"
            title="Hide controls panel"
            aria-label="Hide controls panel"
            className="absolute top-2 right-2 z-10 p-1 rounded text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-gray-100 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
          >
            <PanelLeftClose size={14} />
          </button>
          <GraphControlsPanel
            filters={filters}
            onFiltersChange={setFilters}
            subView={subView}
            onSubViewChange={setSubView}
            nodeCount={authorityNodes.length}
            nodeLimit={nodeLimit}
            onNodeLimitChange={handleNodeLimitChange}
            boardId={boardId}
            showCodeTraceabilityFacets={canReadCodeTraceability}
            relevanceScores={authorityNodes.map((n) => n.relevance_score ?? 0)}
            visibleNodeCount={visibleNodeCount}
            nodeTypeCounts={canReadCodeTraceability
              ? statsSnapshot?.node_counts_by_type
              : undefined}
            totalNodeCount={canReadCodeTraceability
              ? totalNodeCount
              : undefined}
          />
        </div>
      </div>

      {/* Resizable divider — width animates to 0 alongside the panel so
          the whole left column collapses smoothly. Drag is disabled in
          collapsed state. */}
      <div
        role="separator"
        aria-orientation="vertical"
        aria-label="Resize controls panel"
        data-testid="kg-sidebar-divider"
        onMouseDown={sidebarCollapsed ? undefined : handleDividerMouseDown}
        onDoubleClick={() => {
          if (sidebarCollapsed) return;
          setSidebarWidth(SIDEBAR_DEFAULT);
          window.localStorage.setItem(SIDEBAR_WIDTH_KEY, String(SIDEBAR_DEFAULT));
        }}
        title="Drag to resize (double-click to reset)"
        style={{ width: sidebarCollapsed ? 0 : 4 }}
        className="cursor-col-resize bg-gray-200 dark:bg-gray-700 hover:bg-blue-500 dark:hover:bg-blue-500 transition-[width,background-color] duration-300 ease-in-out flex-shrink-0 overflow-hidden"
      />

      {/* Re-open strip — width animates 0 → 28 when collapsed. Always in
          the DOM so the icon can fade in via the same transition. */}
      <button
        type="button"
        onClick={toggleSidebar}
        data-testid="kg-sidebar-expand"
        title="Show controls panel"
        aria-label="Show controls panel"
        style={{ width: sidebarCollapsed ? 28 : 0 }}
        className="flex-shrink-0 overflow-hidden flex items-start justify-center pt-2 border-r border-gray-200 dark:border-gray-700 text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-gray-100 hover:bg-gray-100 dark:hover:bg-gray-800 transition-[width] duration-300 ease-in-out"
      >
        <PanelLeftOpen size={16} />
      </button>

      {/* Center: Graph or sub-view */}
      <div className="flex-1 relative">
        {subView === 'graph' ? (
          <>
            {/* KG Refresh button — spec f33eb9ca, BR `Empty State CTA` adjacent
                requirement. Invalidates current graph state and re-fetches.
                Keyboard shortcut `R` works when the canvas has focus. */}
            <div
              className="absolute top-3 right-3 z-10 flex items-center gap-2"
              data-testid="kg-toolbar"
            >
              <KGSyncIndicator
                connectionState={liveEvents.connectionState}
                unseenCommits={liveEvents.unseenCommits}
                lastEventAt={liveEvents.lastEvent?.created_at ?? null}
                onApply={() => {
                  liveEvents.markSeen();
                  loadGraph(nodeLimit);
                }}
              />
              <KGRefreshButton
                onRefresh={refreshGraph}
                loading={loading}
                label="Refresh"
                shortcut
                testId="kg-refresh"
              />
              <button
                type="button"
                onClick={() => setHelpOpen(true)}
                data-testid="kg-help-button"
                title="Help (Shift+/)"
                aria-label="Open Knowledge Graph help"
                className="p-1.5 rounded-md text-gray-500 hover:text-gray-800 dark:text-gray-400 dark:hover:text-gray-100 hover:bg-gray-100 dark:hover:bg-gray-700 border border-gray-200 dark:border-gray-700 transition-colors"
              >
                <HelpCircle size={18} />
              </button>
              {nextCursor && (
                <button
                  type="button"
                  onClick={handleLoadMore}
                  disabled={loadingMore}
                  data-testid="kg-load-more"
                  className="px-3 py-1.5 rounded-md text-xs bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-50 disabled:cursor-wait"
                >
                  {loadingMore
                    ? 'Loading…'
                    : `Load more (${authorityNodes.length}${nextCursor ? '+' : ''})`}
                </button>
              )}
            </div>
            {graphMetadata?.edge_read_status && graphMetadata.edge_read_status !== 'ok' && (
              <div
                className="absolute top-14 right-3 z-10 max-w-lg rounded-md border border-amber-300 dark:border-amber-700 bg-amber-50 dark:bg-amber-950/80 px-3 py-2 text-xs text-amber-900 dark:text-amber-100 shadow"
                data-testid="kg-edge-read-diagnostics"
                role="status"
              >
                <div className="flex items-start gap-2">
                  <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" aria-hidden />
                  <div>
                    <div className="font-semibold">Edge read diagnostics</div>
                    <div>
                      Status: {graphMetadata.edge_read_status}; failed tables:{' '}
                      {graphMetadata.edge_tables_failed ?? 0} of{' '}
                      {graphMetadata.edge_tables_scanned ?? 0}
                    </div>
                  </div>
                </div>
              </div>
            )}
            {nodes.length === 0 ? (
              <div data-testid="kg-empty-yet" className="h-full">
                <EmptyState boardId={boardId} onRefresh={refreshGraph} />
              </div>
            ) : <GraphCanvas
              nodes={authorityNodes}
              edges={authorityEdges}
              filters={filters}
              onSelect={setSelectedNode}
              initialSelectedNodeId={selectedNode?.id ?? null}
              onClearFilters={handleClearFilters}
              onAdjustRelevance={handleAdjustRelevance}
              boardId={boardId}
              onShowDetails={handleShowDetails}
              refitTrigger={refitTrigger}
            />}
          </>
        ) : subView === 'audit' ? (
          <AuditLogView boardId={boardId} />
        ) : subView === 'privacy' ? (
          <PrivacyView boardId={boardId} />
        ) : subView === 'global' ? (
          <GlobalSearchView boardId={boardId} />
        ) : null}
      </div>

      {/* Right: Node detail */}
      {selectedNode && (
        <div className="w-80 border-l border-gray-200 dark:border-gray-700 overflow-y-auto">
          <NodeDetailPanel
            node={selectedNode}
            boardId={boardId}
            onClose={() => setSelectedNode(null)}
            onNodeNavigate={(nodeId) => {
              const target = authorityNodes.find((n) => n.id === nodeId);
              if (target) setSelectedNode(target);
            }}
          />
        </div>
      )}

      {modalNode && (
        <NodeDetailModal
          node={modalNode}
          boardId={boardId}
          onClose={() => setModalNode(null)}
        />
      )}

      {helpOpen && <KGHelpModal onClose={() => setHelpOpen(false)} />}

      {/* Queue progress now surfaced globally via GlobalKGActivityIndicator
          in App.tsx — removed the per-page toast to avoid duplication. */}
    </div>
  );
}

/**
 * NodeDetailPanel — sidebar showing full details of a selected KG node.
 * Shows: type badge, title, content, confidence, validation, source link, actions.
 * Action buttons are wired to real API calls.
 */

import { useEffect, useState } from 'react';
import toast from 'react-hot-toast';
import type { KGNode } from '@/types/knowledge-graph';
import {
  isCodeTraceabilityKind,
  kgNodeDisplayType,
  kgNodeVisualConfig,
} from '@/types/knowledge-graph';
import * as kgApi from '@/services/kg-api';
import { RelevanceBadge } from './RelevanceBadge';
import { NodeSourceLink } from './NodeSourceLink';
import { useOptionalModalStack } from '@/contexts/ModalStackContext';
import { useCodeTraceabilityAuthority } from '@/components/code-traceability';

interface Props {
  node: KGNode;
  boardId: string;
  onClose: () => void;
  onNodeNavigate?: (nodeId: string) => void;
}

interface SimilarResult {
  id: string;
  title: string;
  similarity: number;
  combined_score: number;
}

interface ChainNode {
  id: string;
  title: string;
  created_at?: string;
  superseded_by?: string;
}

export function NodeDetailPanel({ node, boardId, onClose, onNodeNavigate }: Props) {
  const { canReadProjection: canReadCodeTraceability, isLoading: traceabilityLoading } =
    useCodeTraceabilityAuthority(boardId);
  const traceabilityPending = isCodeTraceabilityKind(node.kind_of) && traceabilityLoading;
  const traceabilityDenied = isCodeTraceabilityKind(node.kind_of)
    && !traceabilityLoading
    && !canReadCodeTraceability;
  useEffect(() => {
    if (traceabilityDenied) onClose();
  }, [onClose, traceabilityDenied]);
  const config = kgNodeVisualConfig(node);
  const [similar, setSimilar] = useState<SimilarResult[] | null>(null);
  const [chain, setChain] = useState<ChainNode[] | null>(null);
  const [loadingSimilar, setLoadingSimilar] = useState(false);
  const [loadingHistory, setLoadingHistory] = useState(false);

  // Ideação c13f7bd3: clicking a Find-Similar or supersedence result
  // pushes onto the global modal stack when available, so the current
  // detail stays intact and a "← Back" appears on the next layer. If
  // the panel is rendered outside the provider (standalone sidebar in
  // KnowledgeGraphPage), we fall back to the legacy onNodeNavigate.
  const modalStack = useOptionalModalStack();
  const navigateToNode = (nodeId: string) => {
    if (modalStack) {
      modalStack.push({ type: 'kg_node', id: nodeId, boardId });
    } else if (onNodeNavigate) {
      onNodeNavigate(nodeId);
    }
  };

  async function handleFindSimilar() {
    if (!node.title) return;
    setLoadingSimilar(true);
    setSimilar(null);
    setChain(null);
    try {
      const data = await kgApi.findSimilar(boardId, node.title, 10);
      const filtered = data.results.filter(r => r.id !== node.id);
      setSimilar(filtered);
      if (filtered.length === 0) {
        toast('No similar nodes found', { icon: 'i' });
      }
    } catch (err: any) {
      toast.error(err.message || 'Failed to find similar nodes');
    } finally {
      setLoadingSimilar(false);
    }
  }

  async function handleShowHistory() {
    setLoadingHistory(true);
    setChain(null);
    setSimilar(null);
    try {
      const data = await kgApi.getSupersedenceChain(boardId, node.id);
      setChain(data.chain);
      if (data.chain.length === 0) {
        toast('No supersedence history found', { icon: 'i' });
      }
    } catch (err: any) {
      toast.error(err.message || 'Failed to load history');
    } finally {
      setLoadingHistory(false);
    }
  }

  const displayScore = node.relevance_score ?? 0.5;


  // Loading authority is not a denial. Keep the modal mounted without leaking
  // node content while the first request (or a cross-board lookup) completes.
  if (traceabilityPending) return <p role="status" className="p-4 text-sm text-gray-500 dark:text-gray-400">Checking source permissions…</p>;
  if (traceabilityDenied) return null;

  return (
    <div className="p-4" role="complementary" aria-label="Node detail panel">
      <div className="flex items-center justify-between mb-4">
        <span
          className="px-2 py-1 rounded text-xs font-medium text-white"
          style={{ backgroundColor: config.color }}
        >
          {config.icon} {kgNodeDisplayType(node)}
        </span>
        <button
          onClick={onClose}
          className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
          aria-label="Close panel"
        >
          ESC
        </button>
      </div>

      <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 mb-2">
        {node.title}
      </h3>
      <NodeSourceLink node={node} boardId={boardId} />

      {/* Always show content section, even if empty */}
      <section className="mb-4">
        <h4 className="text-xs font-medium text-gray-500 uppercase mb-1">Content</h4>
        {node.content ? (
          <p className="text-sm text-gray-700 dark:text-gray-300">{node.content}</p>
        ) : (
          <p className="text-sm text-gray-400 italic dark:text-gray-500">No content available</p>
        )}
      </section>

      {node.justification && (
        <section className="mb-4">
          <h4 className="text-xs font-medium text-gray-500 uppercase mb-1">Justification</h4>
          <p className="text-sm text-gray-700 dark:text-gray-300">{node.justification}</p>
        </section>
      )}

      <div className="grid grid-cols-2 gap-2 mb-4 text-xs">
        <div className="bg-gray-50 dark:bg-gray-800 p-2 rounded">
          <span className="text-gray-500">Confidence</span>
          <p className="font-semibold text-gray-900 dark:text-gray-100">
            {(node.source_confidence * 100).toFixed(0)}%
          </p>
        </div>
        <div className="bg-gray-50 dark:bg-gray-800 p-2 rounded">
          <span className="text-gray-500">Relevance</span>
          <div className="mt-1 flex items-center justify-between gap-2">
            <RelevanceBadge score={displayScore} compact />

          </div>
          {typeof node.query_hits === 'number' && (
            <p className="mt-1 text-[10px] text-gray-500">
              hits: {node.query_hits}
            </p>
          )}
        </div>
      </div>

      {/* Always show node type and ID for debugging */}
      <div className="mb-4 text-xs bg-gray-50 dark:bg-gray-800 p-2 rounded">
        <div className="text-gray-500">Node Type</div>
        <div className="font-mono text-gray-900 dark:text-gray-100">{node.node_type}</div>
        {canReadCodeTraceability && node.kind_of && (
          <>
            <div className="text-gray-500 mt-2">Semantic Subtype</div>
            <div className="font-mono text-gray-900 dark:text-gray-100">
              {node.kind_of}
            </div>
          </>
        )}
        <div className="text-gray-500 mt-2">Node ID</div>
        <div className="font-mono text-xs text-gray-600 dark:text-gray-400 break-all">{node.id}</div>
      </div>

      {canReadCodeTraceability && node.kind_of && (
        <section
          className="mb-4 rounded border border-cyan-100 bg-cyan-50/50 p-3 text-xs dark:border-cyan-900/60 dark:bg-cyan-950/20"
          data-testid="kg-code-traceability-metadata"
        >
          <h4 className="mb-2 text-xs font-medium uppercase text-cyan-700 dark:text-cyan-300">
            Agent-attested traceability metadata
          </h4>
          <dl className="space-y-1.5">
            {[
              ['Receipt', node.investigation_receipt_id],
              ['Logical source', node.source_ref],
              ['Attestor', node.attestor_actor_id],
              ['Declared revision', node.declared_revision],
              ['Workspace fingerprint', node.workspace_state_id],
              ['Submitted path', node.code_path],
              ['Submitted symbol', node.symbol_qualified_name],
              ['Symbol kind', node.symbol_kind],
              ['Selector kind', node.selector_kind],
              ['Selector fingerprint', node.selector_fingerprint],
              ['Resolution state', node.resolution_state],
            ].filter((entry): entry is [string, string] => Boolean(entry[1])).map(([label, value]) => (
              <div key={label} className="grid grid-cols-[8rem_minmax(0,1fr)] gap-2">
                <dt className="text-gray-500 dark:text-gray-400">{label}</dt>
                <dd className="break-all font-mono text-gray-700 dark:text-gray-200">{value}</dd>
              </div>
            ))}
          </dl>
        </section>
      )}

      {node.created_at && (
        <div className="text-xs text-gray-400">
          Created: {new Date(node.created_at).toLocaleDateString()}
        </div>
      )}

      {node.superseded_by && (
        <div className="mt-2 text-xs text-yellow-600 dark:text-yellow-400">
          Superseded by: {node.superseded_by.slice(0, 16)}...
        </div>
      )}

      <div className="mt-4 flex flex-col gap-2">
        <button
          onClick={handleFindSimilar}
          disabled={loadingSimilar}
          className="w-full px-3 py-1.5 text-xs bg-blue-50 text-blue-700 rounded hover:bg-blue-100 dark:bg-blue-900/20 dark:text-blue-400 disabled:opacity-50"
        >
          {loadingSimilar ? 'Searching...' : 'Find Similar'}
        </button>
        {node.node_type === 'Decision' && (
          <button
            onClick={handleShowHistory}
            disabled={loadingHistory}
            className="w-full px-3 py-1.5 text-xs bg-gray-50 text-gray-700 rounded hover:bg-gray-100 dark:bg-gray-800 dark:text-gray-400 disabled:opacity-50"
          >
            {loadingHistory ? 'Loading...' : 'Show History'}
          </button>
        )}
      </div>

      {/* Similar nodes results */}
      {similar && similar.length > 0 && (
        <div className="mt-4 border-t border-gray-200 dark:border-gray-700 pt-3">
          <h4 className="text-xs font-medium text-gray-500 uppercase mb-2">
            Similar Nodes ({similar.length})
          </h4>
          <div className="space-y-1.5">
            {similar.map((s) => (
              <button
                key={s.id}
                onClick={() => navigateToNode(s.id)}
                className="w-full text-left p-2 rounded text-xs hover:bg-gray-50 dark:hover:bg-gray-800 border border-gray-100 dark:border-gray-800"
              >
                <div className="font-medium text-gray-900 dark:text-gray-100 truncate">
                  {s.title}
                </div>
                <div className="text-gray-400 mt-0.5">
                  {Math.round(s.similarity * 100)}% similar | Score: {s.combined_score}
                </div>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Supersedence chain results */}
      {chain && chain.length > 0 && (
        <div className="mt-4 border-t border-gray-200 dark:border-gray-700 pt-3">
          <h4 className="text-xs font-medium text-gray-500 uppercase mb-2">
            Supersedence Chain ({chain.length})
          </h4>
          <div className="space-y-1">
            {chain.map((c, i) => (
              <div key={c.id} className="flex items-start gap-2">
                <div className="flex flex-col items-center">
                  <div className="w-2 h-2 rounded-full bg-violet-500 mt-1.5" />
                  {i < chain.length - 1 && (
                    <div className="w-px h-6 bg-violet-300 dark:bg-violet-700" />
                  )}
                </div>
                <button
                  onClick={() => navigateToNode(c.id)}
                  className="text-left text-xs hover:underline"
                >
                  <span className="text-gray-900 dark:text-gray-100">{c.title}</span>
                  {c.created_at && (
                    <span className="text-gray-400 ml-1">
                      ({new Date(c.created_at).toLocaleDateString()})
                    </span>
                  )}
                </button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * KGHealthCognitivePendingPanel unit tests — KG-03.5 / api_897dde99.
 *
 * Mocks getKGCognitivePendingItems at the module boundary. Asserts the
 * UI states (loading | empty | ready | error), counts rendering, and — critically — that the panel exposes NO mutation
 * affordance: no complete/skip/fail button, no free-text cognitive
 * judgement input. The cognitive item mutation surface remains the MCP
 * tool only (br_2065f80b + AC9).
 */

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { cleanup, render, screen, waitFor } from '@testing-library/react';

const permissionHas = vi.hoisted(() => vi.fn((_flag: string) => true));
vi.mock('@/hooks/usePermissions', () => ({
  usePermissions: () => ({ preset: 'Full Control', isLoading: false, error: null, ownerReviewRequired: false, has: permissionHas }),
}));

import { KGHealthCognitivePendingPanel } from '../KGHealthCognitivePendingPanel';
import * as kgHealthApi from '@/services/kg-health-api';
import type { KGCognitivePendingResponse } from '@/services/kg-health-api';
import {
  KG_COGNITIVE_PENDING_PANEL_METRIC_LABELS,
  getKGCognitivePendingPanelEventCount,
  getKGCognitivePendingPanelSamples,
  resetKGCognitivePendingPanelTelemetry,
} from '@/services/kg-cognitive-pending-telemetry';

vi.mock('@/services/kg-health-api');

const BOARD = 'board-kg03-5';

function baseResponse(
  partial: Partial<KGCognitivePendingResponse> = {},
): KGCognitivePendingResponse {
  return {
    board_id: BOARD,
    selected_kg_generation_id: '8c1f0000-0000-4000-8000-000000000000',
    readonly: true,
    counts: {
      pending: 2,
      in_progress: 0,
      consolidated: 1,
      skipped: 0,
      failed: 0,
      total: 3,
    },
    items: [
      {
        item_id: 'cogn_aaaaaaaaaaaa_bbbbbb',
        source_ref: 'spec:s1',
        artifact_type: 'spec',
        status: 'pending',
        recorded_at: '2026-05-26T12:00:00+00:00',
        updated_at: null,
        updated_by_agent_id: null,
        consolidation_session_id: null,
        reason_code: null,
      },
      {
        item_id: 'cogn_cccccccccccc_dddddd',
        source_ref: 'refinement:r1',
        artifact_type: 'refinement',
        status: 'consolidated',
        recorded_at: '2026-05-26T12:00:00+00:00',
        updated_at: '2026-05-26T12:05:00+00:00',
        updated_by_agent_id: 'agent-007',
        consolidation_session_id: 'sess-1',
        reason_code: null,
      },
    ],
    ...partial,
  };
}

function mockApi(
  impl: (
    boardId: string,
    options?: kgHealthApi.GetKGCognitivePendingOptions,
    signal?: AbortSignal,
  ) => Promise<KGCognitivePendingResponse>,
) {
  vi.mocked(kgHealthApi.getKGCognitivePendingItems).mockImplementation(impl);
}

beforeEach(() => {
  vi.useRealTimers();
  vi.clearAllMocks();
  resetKGCognitivePendingPanelTelemetry();
});

afterEach(() => {
  cleanup();
  resetKGCognitivePendingPanelTelemetry();
});


// -------- UI states ------------------------------------------------------


describe('UI state: ready', () => {
  it('renders counts row + items list after a successful fetch', async () => {
    mockApi(() => Promise.resolve(baseResponse()));
    render(
      <KGHealthCognitivePendingPanel
        boardId={BOARD}
        selectedKgGenerationId={null}
        pollIntervalMs={30000}
      />,
    );
    await waitFor(() =>
      expect(kgHealthApi.getKGCognitivePendingItems).toHaveBeenCalledTimes(1),
    );
    await waitFor(() => {
      expect(
        screen.getByTestId('kg-cognitive-pending-counts'),
      ).toBeInTheDocument();
      expect(
        screen.getByTestId('kg-cognitive-pending-items'),
      ).toBeInTheDocument();
    });
    // counts.total = 3 → exposed in the Total tile.
    const totalTile = screen.getByTestId('kg-cognitive-pending-count-total');
    expect(totalTile.textContent).toContain('3');
    // pending = 2, consolidated = 1 (from baseResponse).
    expect(screen.getByTestId('kg-cognitive-pending-count-pending').textContent).toContain('2');
    expect(screen.getByTestId('kg-cognitive-pending-count-consolidated').textContent).toContain('1');
  });

  it('renders every status bucket in counts row even when zero', async () => {
    mockApi(() => Promise.resolve(baseResponse()));
    render(
      <KGHealthCognitivePendingPanel
        boardId={BOARD}
        selectedKgGenerationId={null}
        pollIntervalMs={30000}
      />,
    );
    await waitFor(() =>
      expect(screen.getByTestId('kg-cognitive-pending-counts')).toBeInTheDocument(),
    );
    for (const tile of [
      'count-pending',
      'count-in_progress',
      'count-consolidated',
      'count-skipped',
      'count-failed',
      'count-total',
    ]) {
      expect(
        screen.getByTestId(`kg-cognitive-pending-${tile}`),
      ).toBeInTheDocument();
    }
  });
});


describe('UI state: empty', () => {
  it('shows the empty hint when counts.total is 0', async () => {
    mockApi(() =>
      Promise.resolve(
        baseResponse({
          items: [],
          counts: {
            pending: 0,
            in_progress: 0,
            consolidated: 0,
            skipped: 0,
            failed: 0,
            total: 0,
          },
        }),
      ),
    );
    render(
      <KGHealthCognitivePendingPanel
        boardId={BOARD}
        selectedKgGenerationId={null}
        pollIntervalMs={30000}
      />,
    );
    await waitFor(() =>
      expect(
        screen.getByTestId('kg-cognitive-pending-empty'),
      ).toBeInTheDocument(),
    );
  });
});


describe('UI state: error', () => {
  it('renders a non-blocking error state when the first fetch fails', async () => {
    mockApi(() => Promise.reject(new Error('cognitive_pending_unavailable')));
    render(
      <KGHealthCognitivePendingPanel
        boardId={BOARD}
        selectedKgGenerationId={null}
        pollIntervalMs={30000}
      />,
    );
    await waitFor(() =>
      expect(
        screen.getByTestId('kg-cognitive-pending-error'),
      ).toBeInTheDocument(),
    );
    expect(screen.getByText(/cognitive_pending_unavailable/i)).toBeInTheDocument();
  });
});


// -------- Generation id display -----------------------------------------


describe('selected generation id display', () => {
  it('annotates "(latest)" when caller did not pin a generation', async () => {
    mockApi(() => Promise.resolve(baseResponse()));
    render(
      <KGHealthCognitivePendingPanel
        boardId={BOARD}
        selectedKgGenerationId={null}
        pollIntervalMs={30000}
      />,
    );
    await waitFor(() =>
      expect(
        screen.getByTestId('kg-cognitive-pending-generation'),
      ).toBeInTheDocument(),
    );
    expect(
      screen.getByTestId('kg-cognitive-pending-generation').textContent,
    ).toContain('latest');
  });

  it('omits the "(latest)" annotation when caller pinned a generation', async () => {
    mockApi(() => Promise.resolve(baseResponse()));
    render(
      <KGHealthCognitivePendingPanel
        boardId={BOARD}
        selectedKgGenerationId="8c1f0000-0000-4000-8000-000000000000"
        pollIntervalMs={30000}
      />,
    );
    await waitFor(() =>
      expect(
        screen.getByTestId('kg-cognitive-pending-generation'),
      ).toBeInTheDocument(),
    );
    expect(
      screen.getByTestId('kg-cognitive-pending-generation').textContent,
    ).not.toContain('latest');
  });
});


// -------- No mutation affordance (br_2065f80b + AC9) --------------------


describe('br_2065f80b — panel exposes no cognitive mutation affordance', () => {
  it('renders NO complete / skip / fail button and NO free-text input', async () => {
    mockApi(() => Promise.resolve(baseResponse()));
    const { container } = render(
      <KGHealthCognitivePendingPanel
        boardId={BOARD}
        selectedKgGenerationId={null}
        pollIntervalMs={30000}
      />,
    );
    await waitFor(() =>
      expect(screen.getByTestId('kg-cognitive-pending-items')).toBeInTheDocument(),
    );

    // Only buttons in the panel are the Refresh button + (on error) Retry.
    const buttons = container.querySelectorAll('button');
    const labels = Array.from(buttons).map((b) =>
      (b.textContent || '').trim().toLowerCase(),
    );
    const forbiddenButtonText = [
      'complete',
      'consolidate',
      'mark consolidated',
      'skip',
      'mark skipped',
      'fail',
      'mark failed',
    ];
    for (const forbidden of forbiddenButtonText) {
      for (const label of labels) {
        expect(label.includes(forbidden)).toBe(false);
      }
    }
    // No text input / textarea (no free-text cognitive judgement).
    expect(container.querySelector('input[type="text"]')).toBeNull();
    expect(container.querySelector('textarea')).toBeNull();
    // No select element (no inline status dropdown).
    expect(container.querySelector('select')).toBeNull();
  });
});


// -------- Item rendering ------------------------------------------------


describe('item list rendering', () => {
  it('shows each item with status badge + artifact type + source_ref', async () => {
    mockApi(() => Promise.resolve(baseResponse()));
    render(
      <KGHealthCognitivePendingPanel
        boardId={BOARD}
        selectedKgGenerationId={null}
        pollIntervalMs={30000}
      />,
    );
    await waitFor(() =>
      expect(
        screen.getByTestId('kg-cognitive-pending-items'),
      ).toBeInTheDocument(),
    );
    const items = screen.getAllByTestId('kg-cognitive-pending-item');
