/**
 * Agents Modal - Global agent management + board access control
 */

import React, { useState, useEffect } from 'react';
import { X, Plus, Copy, RefreshCw, Trash2, Key, FileJson, Terminal, Shield, ChevronRight } from 'lucide-react';
import toast from 'react-hot-toast';
import { useDashboardApi } from '@/services/api';
import { useCurrentBoard } from '@/store/dashboard';
import {
  applyBoardCeiling,
  applyPermissionDelta,
  boardCeilingDelta,
  permissionDelta,
  PermissionDiffView,
  PermissionFlagsEditor,
  resolveAgentPermissionBase,
} from '@/components/permissions';
import type { AgentPermissionBase } from '@/components/permissions';
import type { Agent, AgentSummary, PermissionPreset } from '@/types';
import { useEscapeToClose } from '@/hooks/useEscapeToClose';
import { usePermissions } from '@/hooks/usePermissions';

type McpFormat = 'claude' | 'cursor' | 'vscode' | 'windsurf' | 'claude-cli' | 'codex';
type Tab = 'my-agents' | 'board-access';

const MCP_CONSUMERS: { format: McpFormat; label: string; file: string; icon: 'json' | 'terminal' }[] = [
  { format: 'claude', label: 'Claude Desktop / Claude Code', file: 'claude_desktop_config.json', icon: 'json' },
  { format: 'claude-cli', label: 'Claude Code (CLI)', file: 'terminal', icon: 'terminal' },
  { format: 'codex', label: 'Codex (CLI)', file: 'terminal', icon: 'terminal' },
  { format: 'cursor', label: 'Cursor', file: '.cursor/mcp.json', icon: 'json' },
  { format: 'vscode', label: 'VS Code (Copilot)', file: '.vscode/mcp.json', icon: 'json' },
  { format: 'windsurf', label: 'Windsurf / Cline', file: 'cline_mcp_settings.json', icon: 'json' },
];

// Get MCP base URL from runtime configuration (injected by server)
function getMcpBaseUrl(): string {
  if (typeof window !== 'undefined' && (window as any).OKTO_PULSE_CONFIG?.MCP_URL) {
    return (window as any).OKTO_PULSE_CONFIG.MCP_URL;
  }
  // Fallback to build-time env var or default
  const mcpPort = import.meta.env.VITE_MCP_PORT || '8101';
  return `http://127.0.0.1:${mcpPort}`;
}

function getMcpConfigJson(format: McpFormat, apiKey: string): string {
  const mcpUrl = getMcpBaseUrl().replace(/\/+$/, '');
  const url = `${mcpUrl}/mcp?api_key=${encodeURIComponent(apiKey)}`;

  if (format === 'claude-cli') {
    return `claude mcp add -t http okto-pulse "${url}"`;
  }

  if (format === 'codex') {
    return `codex mcp add okto-pulse --url "${url}"`;
  }

  if (format === 'vscode') {
    return JSON.stringify({ servers: { 'okto-pulse': { type: 'http', url } } }, null, 2);
  }

  return JSON.stringify({ mcpServers: { 'okto-pulse': { url } } }, null, 2);
}

interface AgentsModalProps {
  isOpen: boolean;
  onClose: () => void;
}

function hasPermissionDelta(delta: Record<string, unknown>): boolean {
  return Object.keys(delta).length > 0;
}

function PermissionBaseReviewNotice({
  resolution,
}: {
  resolution: AgentPermissionBase;
}) {
  if (!resolution.ownerReviewRequired) return null;
  return (
    <p
      role="alert"
      className="text-[10px] rounded border border-red-200 bg-red-50 px-2 py-1 text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300"
    >
      Owner review required for {resolution.label}
      {resolution.reviewReason ? ` · ${resolution.reviewReason}` : ''}
    </p>
  );
}

export function AgentsModal({ isOpen, onClose }: AgentsModalProps) {
  const api = useDashboardApi();
  const currentBoard = useCurrentBoard();
  const permissions = usePermissions(currentBoard?.id);
  const canReadAgents = permissions.has('agent.entity.read');
  const canCreateAgent = permissions.has('agent.entity.create');
  const canEditAgent = permissions.has('agent.entity.edit');
  const canDeleteAgent = permissions.has('agent.entity.delete');
  const canRotateAgentKey = permissions.has('agent.api_key.rotate');
  const canReadBoardAccess = permissions.has('agent.board_access.read');
  const canGrantBoardAccess = permissions.has('agent.board_access.grant');
  const canEditBoardAccess = permissions.has('agent.board_access.edit');
  const canRevokeBoardAccess = permissions.has('agent.board_access.revoke');
  const canReadPresets = permissions.has('permission_preset.entity.read');

  const [activeTab, setActiveTab] = useState<Tab>('my-agents');
  const [myAgents, setMyAgents] = useState<Agent[]>([]);
  const [boardAgents, setBoardAgents] = useState<AgentSummary[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [newAgentName, setNewAgentName] = useState('');
  const [newAgentDescription, setNewAgentDescription] = useState('');
  const [newAgentObjective, setNewAgentObjective] = useState('');
  const [newAgentPresetId, setNewAgentPresetId] = useState('');
  const [expandedAgentId, setExpandedAgentId] = useState<string | null>(null);
  const [grantAgentId, setGrantAgentId] = useState('');
  const [presets, setPresets] = useState<PermissionPreset[]>([]);
  const [revealedAgentKeys, setRevealedAgentKeys] = useState<Record<string, string>>({});

  useEscapeToClose(onClose, { enabled: isOpen });

  // Load my agents and presets on open
  useEffect(() => {
    if (isOpen) {
      void loadMyAgents();
      void loadPresets();
    } else {
      setRevealedAgentKeys({});
      setExpandedAgentId(null);
    }
  }, [isOpen, canReadAgents, canReadPresets]);

  const loadPresets = async () => {
    if (!canReadPresets) {
      setPresets([]);
      return;
    }
    try {
      const data = await api.listPresets();
      setPresets(data);
    } catch { /* ignore */ }
  };

  // Load board agents when switching to board-access tab
  useEffect(() => {
    if (isOpen && activeTab === 'board-access' && currentBoard) {
      void loadBoardAgents();
    }
  }, [isOpen, activeTab, currentBoard?.id, canReadBoardAccess]);

  const loadMyAgents = async () => {
    if (!canReadAgents) {
      setMyAgents([]);
      return;
    }
    setIsLoading(true);
    try {
      const agents = await api.listMyAgents();
      setMyAgents(agents);
    } catch {
      toast.error('Failed to load agents');
    } finally {
      setIsLoading(false);
    }
  };

  const loadBoardAgents = async () => {
    if (!currentBoard || !canReadBoardAccess) {
      setBoardAgents([]);
      return;
    }
    setIsLoading(true);
    try {
      const agents = await api.listAgentsForBoard(currentBoard.id);
      setBoardAgents(agents);
    } catch {
      toast.error('Failed to load board agents');
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreateAgent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!canCreateAgent || !newAgentName.trim()) return;

    try {
      const result = await api.createAgent({
        name: newAgentName.trim(),
        description: newAgentDescription.trim() || undefined,
        objective: newAgentObjective.trim() || undefined,
        preset_id: newAgentPresetId || undefined,
      });
      setMyAgents((prev) => [...prev, result.agent]);
      setRevealedAgentKeys((prev) => ({
        ...prev,
        [result.agent.id]: result.reveal_once_secret,
      }));
      setExpandedAgentId(result.agent.id);
      setNewAgentName('');
      setNewAgentDescription('');
      setNewAgentObjective('');
      setNewAgentPresetId('');
      setShowCreateForm(false);
      toast.success('Agent created. Copy the key now.');
    } catch {
      toast.error('Failed to create agent');
    }
  };

  const handleCopy = (text: string | undefined, label: string) => {
    if (!text) {
      toast.error(`${label} is hidden. Regenerate to reveal a new one.`);
      return;
    }
    navigator.clipboard.writeText(text);
    toast.success(`${label} copied!`);
  };

  const handleRegenerateKey = async (agentId: string) => {
    if (!canRotateAgentKey) return;
    if (!confirm('Are you sure? The old key will stop working.')) return;
    try {
      const result = await api.regenerateAgentKey(agentId);
      setMyAgents((prev) => prev.map((a) => (a.id === agentId ? result.agent : a)));
      setRevealedAgentKeys((prev) => ({
        ...prev,
        [agentId]: result.reveal_once_secret,
      }));
      setExpandedAgentId(agentId);
      toast.success('Key regenerated. Copy it now.');
    } catch {
      toast.error('Failed to regenerate key');
    }
  };

  const handleDeleteAgent = async (agentId: string) => {
    if (!canDeleteAgent) return;
    if (!confirm('Are you sure you want to delete this agent?')) return;
    try {
      await api.deleteAgent(agentId);
      setMyAgents((prev) => prev.filter((a) => a.id !== agentId));
      setRevealedAgentKeys((prev) => {
        const next = { ...prev };
        delete next[agentId];
        return next;
      });
      toast.success('Agent deleted');
    } catch {
      toast.error('Failed to delete agent');
    }
  };

  const handleGrantAccess = async () => {
    if (!canGrantBoardAccess || !currentBoard || !grantAgentId) return;
    try {
      await api.grantAgentBoardAccess(grantAgentId, currentBoard.id);
      toast.success('Access granted!');
      setGrantAgentId('');
      void loadBoardAgents();
    } catch (err: any) {
      const msg = err?.message?.includes('409') ? 'Access already granted' : 'Failed to grant access';
      toast.error(msg);
    }
  };

  const handleRevokeAccess = async (agentId: string) => {
    if (!canRevokeBoardAccess || !currentBoard) return;
    if (!confirm('Revoke this agent access to the board?')) return;
    try {
      await api.revokeAgentBoardAccess(agentId, currentBoard.id);
      toast.success('Access revoked');
      void loadBoardAgents();
    } catch {
      toast.error('Failed to revoke access');
    }
  };

  if (!isOpen) return null;

  // Agents that have no access to the current board (for grant select)
  const boardAgentIds = new Set(boardAgents.map((a) => a.id));
  const agentsWithoutAccess = myAgents.filter((a) => !boardAgentIds.has(a.id));

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div
        className="modal-content max-w-2xl"
        data-tour-id="agents.modal.entry"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="modal-header">
          <h2 className="font-semibold text-lg flex items-center gap-2">
            <Key size={20} />
            Agents
          </h2>
          <button onClick={onClose} className="p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded">
            <X size={20} />
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-gray-200 dark:border-gray-700">
          <button
            onClick={() => setActiveTab('my-agents')}
            className={`flex-1 py-2 px-4 text-sm font-medium border-b-2 transition-colors ${
              activeTab === 'my-agents'
                ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                : 'border-transparent text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            <Key size={14} className="inline mr-1.5 -mt-0.5" />
            My Agents
          </button>
          {currentBoard && (
            <button
              onClick={() => setActiveTab('board-access')}
              className={`flex-1 py-2 px-4 text-sm font-medium border-b-2 transition-colors ${
                activeTab === 'board-access'
                  ? 'border-blue-500 text-blue-600 dark:text-blue-400'
                  : 'border-transparent text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'
              }`}
            >
              <Shield size={14} className="inline mr-1.5 -mt-0.5" />
              Board Access
            </button>
          )}
        </div>

        <div className="modal-body space-y-4">
          {/* ================ TAB 1: MY AGENTS ================ */}
          {activeTab === 'my-agents' && (
            <>
              {/* Create agent form */}
              {showCreateForm ? (
                <form onSubmit={handleCreateAgent} className="space-y-3 p-4 bg-gray-50 dark:bg-gray-800 text-gray-700 dark:text-gray-300 rounded-lg">
                  <div>
                    <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Agent Name *</label>
                    <input
                      type="text"
                      value={newAgentName}
                      onChange={(e) => setNewAgentName(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 text-gray-700 dark:text-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600"
                      placeholder="Ex: Claude Assistant"
                      disabled={!canCreateAgent}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Description</label>
                    <input
                      type="text"
                      value={newAgentDescription}
                      onChange={(e) => setNewAgentDescription(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 text-gray-700 dark:text-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600"
                      placeholder="E.g.: Task automation agent"
                      disabled={!canCreateAgent}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Agent Objective</label>
                    <textarea
                      value={newAgentObjective}
                      onChange={(e) => setNewAgentObjective(e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 text-gray-700 dark:text-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600 resize-none"
                      rows={2}
                      placeholder="E.g.: Review PRs and create feedback cards"
                      disabled={!canCreateAgent}
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium mb-1 text-gray-700 dark:text-gray-300">Permission Preset</label>
                    <select
                      value={newAgentPresetId}
                      onChange={(e) => setNewAgentPresetId(e.target.value)}
                      disabled={!canCreateAgent}
                      className="w-full px-3 py-2 border border-gray-300 text-gray-700 dark:text-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600"
                    >
                      <option value="">Full Control (default)</option>
                      {presets.map((p) => (
                        <option key={p.id} value={p.id}>
                          {p.name}{p.is_builtin ? ' (built-in)' : ''}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div className="flex gap-2">
                    <button type="submit" disabled={!canCreateAgent} className="btn btn-primary">
                      Create Agent
                    </button>
                    <button type="button" onClick={() => setShowCreateForm(false)} className="btn btn-secondary">
                      Cancel
                    </button>
                  </div>
                </form>
              ) : (
                <button
                  onClick={() => setShowCreateForm(true)}
                  disabled={!canCreateAgent}
                  className="w-full py-2 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg text-gray-500 dark:text-gray-400 hover:border-blue-500 hover:text-blue-500 flex items-center justify-center gap-2"
                >
                  <Plus size={16} />
                  New Agent
                </button>
              )}

              {/* Agents list */}
              {!canReadAgents ? (
                <div className="text-center py-8 text-gray-500 dark:text-gray-400">
                  You do not have permission to view agents
                </div>
              ) : isLoading ? (
                <div className="text-center py-8 text-gray-500 dark:text-gray-400">Loading...</div>
              ) : myAgents.length === 0 ? (
                <div className="text-center py-8 text-gray-500 dark:text-gray-400">
                  No agents registered
                </div>
              ) : (
                <div className="space-y-2">
                  {myAgents.map((agent) => {
                    const isExpanded = expandedAgentId === agent.id;
                    const revealedKey = revealedAgentKeys[agent.id];
                    const permissionResolution = resolveAgentPermissionBase(
                      agent.preset_id,
                      presets,
                    );
                    const permissionBase = permissionResolution.flags;
                    const effectivePermissions = permissionBase
                      ? applyPermissionDelta(
                          permissionBase as unknown as Record<string, unknown>,
                          agent.permission_flags,
                        )
                      : null;
                    return (
                      <div key={agent.id} className="bg-gray-50 dark:bg-gray-800 text-gray-700 dark:text-gray-300 rounded-lg overflow-hidden">
                        {/* Agent header */}
                        <div className="flex items-center justify-between p-3">
                          <button
                            aria-label={`Edit agent ${agent.name}`}
                            onClick={() => setExpandedAgentId(isExpanded ? null : agent.id)}
                            className="flex-1 min-w-0 text-left flex items-center gap-2"
                          >
                            <ChevronRight size={14} className={`shrink-0 transition-transform ${isExpanded ? 'rotate-90' : ''}`} />
                            <div className="min-w-0">
                              <h4 className="font-medium text-gray-900 dark:text-gray-100 truncate">{agent.name}</h4>
                              {agent.description && (
                                <p className="text-sm text-gray-500 dark:text-gray-400 truncate">{agent.description}</p>
                              )}
                            </div>
                          </button>
                          <div className="flex items-center gap-1 shrink-0">
                            <button
                              onClick={() => handleCopy(revealedKey, 'Key')}
                              disabled={!revealedKey}
                              className="p-1.5 text-gray-400 dark:text-gray-500 hover:text-green-600 hover:bg-green-50 dark:hover:bg-green-900/20 rounded disabled:opacity-40 disabled:hover:text-gray-400 disabled:hover:bg-transparent"
                              title={revealedKey ? 'Copy API key' : 'Key hidden; regenerate to reveal a new key'}
                            >
                              <Copy size={14} />
                            </button>
                            <button
                              onClick={() => handleRegenerateKey(agent.id)}
                              disabled={!canRotateAgentKey}
                              className="p-1.5 text-gray-400 dark:text-gray-500 hover:text-blue-600 hover:bg-blue-50 dark:hover:bg-blue-900/20 rounded"
                              title="Regenerate key"
                            >
                              <RefreshCw size={14} />
                            </button>
                            <button
                              onClick={() => handleDeleteAgent(agent.id)}
                              disabled={!canDeleteAgent}
                              className="p-1.5 text-gray-400 dark:text-gray-500 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded"
                              title="Delete agent"
                            >
                              <Trash2 size={14} />
                            </button>
                          </div>
                        </div>

                        {/* Expanded details */}
                        {isExpanded && (
                          <div className="px-3 pb-3 pt-0 space-y-3 border-t border-gray-200 dark:border-gray-700">
                            {/* API Key */}
                            <div className="mt-3">
                              <label className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wide">API Key</label>
                              <div className="flex items-center gap-2 mt-1">
                                {revealedKey ? (
                                  <>
                                    <code className="flex-1 bg-white dark:bg-gray-900 px-3 py-1.5 rounded text-xs font-mono break-all border border-gray-200 dark:border-gray-700">
                                      {revealedKey}
                                    </code>
                                    <button
                                      onClick={() => handleCopy(revealedKey, 'Key')}
                                      className="p-1.5 bg-green-600 text-white rounded hover:bg-green-700 shrink-0"
                                    >
                                      <Copy size={12} />
                                    </button>
                                  </>
                                ) : (
                                  <div className="flex-1 bg-white dark:bg-gray-900 px-3 py-1.5 rounded text-xs text-gray-500 dark:text-gray-400 border border-gray-200 dark:border-gray-700">
                                    Hidden. Regenerate to reveal a new key.
                                  </div>
                                )}
                              </div>
                            </div>

                            {agent.objective && (
                              <div>
                                <label className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wide">Objective</label>
                                <p className="text-sm text-blue-500 dark:text-blue-400 mt-0.5">{agent.objective}</p>
                              </div>
                            )}

                            <p className="text-xs text-gray-400 dark:text-gray-500">
                              ID: {agent.id} • {agent.is_active ? 'Active' : 'Inactive'}
                            </p>

                            {/* Permissions */}
                            <div>
                              <label className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wide">Permissions</label>
                              <div className="mt-1 space-y-2">
                                <div className="flex items-center gap-2">
                                  <select
                                    value={agent.preset_id || ''}
                                    onChange={async (e) => {
                                      if (!canEditAgent) return;
                                      try {
                                        // Send explicit null (not undefined) so JSON.stringify keeps the
                                        // field — the backend uses its presence to reset permission_flags
                                        // from the chosen preset (or to full registry when null).
                                        await api.updateAgent(agent.id, { preset_id: e.target.value || null } as any);
                                        await loadMyAgents();
                                        toast.success('Preset updated');
                                      } catch { toast.error('Failed to update preset'); }
                                    }}
                                    disabled={!canEditAgent}
                                    className="flex-1 px-2 py-1.5 border border-gray-300 text-gray-700 dark:text-gray-300 rounded text-xs dark:bg-gray-700 dark:border-gray-600"
                                  >
                                    <option value="">Full Control</option>
                                    {presets.map((p) => (
                                      <option key={p.id} value={p.id}>
                                        {p.name}{p.is_builtin ? ' (built-in)' : ''}
                                      </option>
                                    ))}
                                  </select>
                                </div>
                                <PermissionBaseReviewNotice
                                  resolution={permissionResolution}
                                />
                                {/* Always edit the resolved effective tree. The API
                                    receives only the direct delta from its base. */}
                                {permissionBase && effectivePermissions ? (
                                  <>
                                    <PermissionDiffView
                                      baseFlags={permissionBase}
                                      effectiveFlags={effectivePermissions}
                                      baseLabel={permissionResolution.label}
                                      restrictionLabel="direct agent customization"
                                    />
                                    <PermissionFlagsEditor
                                      flags={effectivePermissions}
                                      readOnly={!canEditAgent}
                                      onChange={async (newFlags) => {
                                        if (!canEditAgent) return;
                                        const delta = permissionDelta(
                                          permissionBase as unknown as Record<string, unknown>,
                                          newFlags as unknown as Record<string, unknown>,
                                        );
                                        const permissionFlags = hasPermissionDelta(delta)
                                          ? delta
                                          : agent.preset_id
                                            ? {}
                                            : null;
                                        try {
                                          await api.updateAgent(agent.id, {
                                            permission_flags: permissionFlags,
                                          });
                                          await loadMyAgents();
                                          toast.success('Permissions updated');
                                        } catch { toast.error('Failed to update'); }
                                      }}
                                    />
                                  </>
                                ) : (
                                  <p className="text-[10px] text-amber-600 dark:text-amber-400">
                                    Permission base unavailable. Refresh presets before editing.
                                  </p>
                                )}
                              </div>
                            </div>

                            {/* MCP Config buttons */}
                            <div>
                              <label className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wide">MCP Configuration</label>
                              <div className="grid grid-cols-2 lg:grid-cols-3 gap-2 mt-1">
                                {MCP_CONSUMERS.map(({ format, label, file, icon }) => (
                                  <button
                                    key={format}
                                    onClick={() => {
                                      if (!revealedKey) {
                                        toast.error('Key is hidden. Regenerate to reveal a new one.');
                                        return;
                                      }
                                      navigator.clipboard.writeText(getMcpConfigJson(format, revealedKey));
                                      toast.success('Configuration copied!');
                                    }}
                                    disabled={!revealedKey}
                                    className="flex items-center gap-2 px-3 py-2 text-xs bg-white dark:bg-gray-900 rounded border border-gray-200 dark:border-gray-700 hover:bg-blue-50 dark:hover:bg-blue-900/20 text-left text-gray-700 dark:text-gray-300 disabled:opacity-50 disabled:hover:bg-white dark:disabled:hover:bg-gray-900"
                                    title={revealedKey ? (format === 'codex' ? 'Copy the command to add or update Pulse in Codex; run it in your terminal' : icon === 'terminal' ? 'Terminal command' : file) : 'Key hidden; regenerate to copy config'}
                                  >
                                    {icon === 'terminal' ? (
                                      <Terminal size={14} className="shrink-0 text-gray-500 dark:text-gray-400" />
                                    ) : (
                                      <FileJson size={14} className="shrink-0 text-gray-500 dark:text-gray-400" />
                                    )}
                                    <span className="truncate">{label}</span>
                                  </button>
                                ))}
                              </div>
                              <p className="mt-2 text-xs text-gray-500 dark:text-gray-400">
                                Codex: copy the command and run it in your terminal with Codex CLI installed.
                                After regenerating a key, run the new command and restart your Codex session.
                                Copied configurations contain your API key; keep them private.
                              </p>
                            </div>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}

              {/* MCP Server info */}
              <div className="border-t pt-4">
                <p className="text-xs text-gray-400 dark:text-gray-500">
                  MCP Server: <code>{getMcpBaseUrl()}/mcp</code>
                </p>
              </div>
            </>
          )}

          {/* ================ TAB 2: BOARD ACCESS ================ */}
          {activeTab === 'board-access' && currentBoard && (
            <>
              {/* Board ID copiable */}
              <div className="flex items-center gap-2 p-3 bg-gray-50 dark:bg-gray-800 text-gray-700 dark:text-gray-300 rounded-lg">
                <span className="text-sm font-medium text-gray-600 dark:text-gray-300">Board ID:</span>
                <code
                  className="flex-1 bg-white dark:bg-gray-900 px-3 py-1 rounded text-xs font-mono cursor-pointer hover:bg-blue-50 dark:hover:bg-blue-900/20 border border-gray-200 dark:border-gray-700"
                  onClick={() => handleCopy(currentBoard.id, 'board_id')}
                >
                  {currentBoard.id}
                </code>
                <button
                  onClick={() => handleCopy(currentBoard.id, 'board_id')}
                  className="p-1.5 text-gray-400 dark:text-gray-500 hover:text-blue-600 rounded"
                >
                  <Copy size={14} />
                </button>
              </div>

              {/* Grant access */}
              <div className="flex gap-2">
                <select
                  value={grantAgentId}
                  onChange={(e) => setGrantAgentId(e.target.value)}
                  disabled={!canGrantBoardAccess}
                  className="flex-1 px-3 py-2 border border-gray-300 text-gray-700 dark:text-gray-300 rounded-lg dark:bg-gray-700 dark:border-gray-600 text-sm"
                >
                  <option value="">Select an agent...</option>
                  {agentsWithoutAccess.map((a) => (
                    <option key={a.id} value={a.id}>
                      {a.name}
                    </option>
                  ))}
                </select>
                <button
                  onClick={handleGrantAccess}
                  disabled={!canGrantBoardAccess || !grantAgentId}
                  className="btn btn-primary whitespace-nowrap disabled:opacity-50"
                >
                  <Plus size={14} className="inline mr-1 -mt-0.5" />
                  Grant Access
                </button>
              </div>

              {/* Board agents list */}
              {!canReadBoardAccess ? (
                <div className="text-center py-8 text-gray-500 dark:text-gray-400">
                  You do not have permission to view board access
                </div>
              ) : isLoading ? (
                <div className="text-center py-8 text-gray-500 dark:text-gray-400">Loading...</div>
              ) : boardAgents.length === 0 ? (
                <div className="text-center py-8 text-gray-500 dark:text-gray-400">
                  No agents with access to this board
                </div>
              ) : (
                <div className="space-y-2">
                  {boardAgents.map((agent) => {
                    const isBoardExpanded = expandedAgentId === `board-${agent.id}`;
                    return (
                      <div key={agent.id} className="bg-gray-50 dark:bg-gray-800 text-gray-700 dark:text-gray-300 rounded-lg overflow-hidden">
                        <div className="flex items-center justify-between p-3">
                          <button
                            aria-label={`Edit board access for ${agent.name}`}
                            onClick={() => setExpandedAgentId(isBoardExpanded ? null : `board-${agent.id}`)}
                            className="flex-1 min-w-0 text-left flex items-center gap-2"
                          >
                            <ChevronRight size={14} className={`shrink-0 transition-transform ${isBoardExpanded ? 'rotate-90' : ''}`} />
                            <div className="min-w-0">
                              <h4 className="font-medium text-gray-900 dark:text-gray-100">{agent.name}</h4>
                              {agent.description && (
                                <p className="text-sm text-gray-500 dark:text-gray-400 truncate">{agent.description}</p>
                              )}
                              <p className="text-xs text-gray-400 dark:text-gray-500 mt-0.5">
                                {agent.is_active ? 'Active' : 'Inactive'}
                              </p>
                            </div>
                          </button>
                          <button
                            onClick={() => handleRevokeAccess(agent.id)}
                            disabled={!canRevokeBoardAccess}
                            className="px-3 py-1.5 text-xs text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded border border-red-200 dark:border-red-800 shrink-0"
                          >
                            Revoke
                          </button>
                        </div>
                        {isBoardExpanded && (() => {
                          const myAgent = myAgents.find((a) => a.id === agent.id);
                          const presetId = agent.preset_id !== undefined
                            ? agent.preset_id
                            : myAgent?.preset_id;
                          const directDelta = agent.permission_flags !== undefined
                            ? agent.permission_flags
                            : myAgent?.permission_flags;
                          const permissionResolution = resolveAgentPermissionBase(
                            presetId,
                            presets,
                          );
                          const presetBase = permissionResolution.flags;
                          const baseFlags = presetBase
                            ? applyPermissionDelta(
                                presetBase as unknown as Record<string, unknown>,
                                directDelta,
                              )
                            : null;
                          const effectiveFlags = baseFlags
                            ? applyBoardCeiling(
                                baseFlags as unknown as Record<string, unknown>,
                                agent.permission_overrides,
                              )
                            : null;
                          return (
                            <div className="px-3 pb-3 border-t border-gray-200 dark:border-gray-700 space-y-2">
                              <div className="mt-2">
                                <label className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wide">
                                  Permission Overrides (ceiling model)
                                </label>
                                <p className="text-[10px] text-gray-400 mt-0.5 mb-1.5">
                                  Restrict agent permissions on this board. Overrides can only remove permissions, never add.
                                </p>
                                <PermissionBaseReviewNotice
                                  resolution={permissionResolution}
                                />
                                <div className="flex items-center gap-2 mb-2">
                                  <select
                                    defaultValue=""
                                    onChange={async (e) => {
                                      if (!canEditBoardAccess || !currentBoard) return;
                                      const presetId = e.target.value;
                                      if (!presetId) {
                                        try {
                                          await api.updateAgentBoardOverrides(agent.id, currentBoard.id, null);
                                          toast.success('Overrides cleared');
                                          void loadBoardAgents();
                                        } catch { toast.error('Failed'); }
                                        return;
                                      }
                                      const preset = presets.find((p) => p.id === presetId);
                                      if (preset && baseFlags) {
                                        const restrictedToPreset = applyBoardCeiling(
                                          baseFlags as unknown as Record<string, unknown>,
                                          preset.flags,
                                        );
                                        const ceiling = boardCeilingDelta(
                                          baseFlags as unknown as Record<string, unknown>,
                                          restrictedToPreset as unknown as Record<string, unknown>,
                                        );
                                        try {
                                          await api.updateAgentBoardOverrides(
                                            agent.id,
                                            currentBoard.id,
                                            ceiling,
                                          );
                                          toast.success(`Overrides set to ${preset.name}`);
                                          void loadBoardAgents();
                                        } catch { toast.error('Failed'); }
                                      }
                                    }}
                                    disabled={!canEditBoardAccess}
                                    className="flex-1 px-2 py-1.5 border border-gray-300 text-gray-700 dark:text-gray-300 rounded text-xs dark:bg-gray-700 dark:border-gray-600"
                                  >
                                    <option value="">No overrides (full agent permissions)</option>
                                    {presets.map((p) => (
                                      <option key={p.id} value={p.id}>
                                        Restrict to: {p.name}{p.is_builtin ? ' (built-in)' : ''}
                                      </option>
                                    ))}
                                  </select>
                                  <button
                                    onClick={async () => {
                                      if (!canEditBoardAccess || !currentBoard) return;
                                      try {
                                        await api.updateAgentBoardOverrides(agent.id, currentBoard.id, null);
                                        toast.success('Overrides cleared');
                                        void loadBoardAgents();
                                      } catch { toast.error('Failed'); }
                                    }}
                                    disabled={!canEditBoardAccess}
                                    className="text-[10px] px-2 py-1 rounded bg-gray-200 text-gray-600 hover:bg-gray-300 dark:bg-gray-700 dark:text-gray-400 shrink-0"
                                  >
                                    Clear
                                  </button>
                                </div>
                                {baseFlags && effectiveFlags ? (
                                  <>
                                    <PermissionDiffView
                                      baseFlags={baseFlags}
                                      effectiveFlags={effectiveFlags}
                                      baseLabel={`Effective agent permissions (${permissionResolution.label})`}
                                    />
                                    <PermissionFlagsEditor
                                      flags={effectiveFlags}
                                      readOnly={!canEditBoardAccess}
                                      onChange={async (newFlags) => {
                                        if (!canEditBoardAccess || !currentBoard) return;
                                        const ceiling = boardCeilingDelta(
                                          baseFlags as unknown as Record<string, unknown>,
                                          newFlags as unknown as Record<string, unknown>,
                                        );
                                        try {
                                          await api.updateAgentBoardOverrides(
                                            agent.id,
                                            currentBoard.id,
                                            ceiling,
                                          );
                                          toast.success('Board permissions updated');
                                          void loadBoardAgents();
                                        } catch { toast.error('Failed'); }
                                      }}
                                    />
                                  </>
                                ) : (
                                  <p className="text-[10px] text-amber-600 dark:text-amber-400">
                                    Permission base unavailable. Refresh agents and presets before editing.
                                  </p>
                                )}
                              </div>
                            </div>
                          );
                        })()}
                      </div>
                    );
                  })}
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { Info, RotateCcw, X } from 'lucide-react';
import toast from 'react-hot-toast';

import {
  CURRENT_METRICS_SCHEMA_VERSION,
  getMetricsSummary,
  updateMetricsMode,
  type MetricsMode,
  type MetricsSummary,
} from '@/services/metrics-api';
import { useEscapeToClose } from '@/hooks/useEscapeToClose';
import { usePermissions } from '@/hooks/usePermissions';

interface MetricsSettingsPanelProps {
  onClose: () => void;
  initialPrompt?: boolean;
  boardId: string | null | undefined;
}

const ACK_ITEMS = [
  {
    id: 'schema',
    label: `Telemetry schema ${CURRENT_METRICS_SCHEMA_VERSION} reviewed`,
    description: 'Only the documented anonymous aggregate fields are eligible for upload.',
  },
  {
    id: 'privacy_policy',
    label: 'Privacy terms reviewed',
    description: 'Metrics sharing is optional and can be turned off from this panel.',
  },
  {
    id: 'hourly_aggregates',
    label: 'Hourly aggregates only',
    description: 'Events are summarized before upload; raw local event files stay on this machine.',
  },
  {
    id: 'product_aggregates',
    label: 'Product aggregates reviewed',
    description: 'Feature usage, flow origins, completion counts, and work item totals are sent only as counts.',
  },
  {
    id: 'no_pii',
    label: 'No PII or project content',
    description: 'Titles, descriptions, board IDs, paths, emails, and payload bodies are not sent.',
  },
  {
    id: 'local_control',
    label: 'User control retained',
    description: 'You can turn metrics off at any time.',
  },
] as const;

const ACK_IDS = ACK_ITEMS.map((item) => item.id);

function modeLabel(mode: MetricsMode): string {
  return mode === 'anonymous_beacon' ? 'On' : 'Off';
}

export function MetricsSettingsPanel({
  onClose,
  initialPrompt = false,
  boardId,
}: MetricsSettingsPanelProps) {
  useEscapeToClose(onClose);
  const permissions = usePermissions(boardId);
  const policyReady = (
    !permissions.isLoading
    && !permissions.error
    && !permissions.ownerReviewRequired
  );
  const canReadSummary = policyReady && permissions.has('metrics.local.summary.read');
  const canEditSettings = policyReady && permissions.has('metrics.settings.edit');
  const [data, setData] = useState<MetricsSummary | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [draftMode, setDraftMode] = useState<MetricsMode>('disabled');

  const refresh = useCallback(async () => {
    if (!canReadSummary) {
      setData(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const summary = await getMetricsSummary();
      setData(summary);
      setDraftMode(summary.ui_mode === 'on' ? 'anonymous_beacon' : 'disabled');
    } catch (err: any) {
      toast.error(err?.message ?? 'Failed to load metrics');
    } finally {
      setLoading(false);
    }
  }, [canReadSummary]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const saveSettings = async (nextMode: MetricsMode) => {
    if (!data || saving || !canEditSettings) return;
    const previousMode = data.ui_mode === 'on' ? 'anonymous_beacon' : 'disabled';
    setDraftMode(nextMode);
    setSaving(true);
    try {
      await updateMetricsMode(nextMode, nextMode === 'anonymous_beacon' ? ACK_IDS : []);
      await refresh();
      toast.success('Metrics settings saved');
      if (initialPrompt) onClose();
    } catch (err: any) {
      setDraftMode(previousMode);
      toast.error(err?.message ?? 'Failed to update metrics');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-end bg-black/20 pt-14" onClick={onClose}>
      <div
        className="mr-4 max-h-[calc(100vh-4rem)] w-[520px] max-w-[calc(100vw-2rem)] overflow-y-auto rounded-lg border border-gray-200 bg-white p-4 shadow-xl dark:border-gray-700 dark:bg-gray-900"
        onClick={(e) => e.stopPropagation()}
        data-testid="metrics-settings-panel"
      >
        <div className="mb-4 flex items-center justify-between">
          <div>
            <h2 className="text-sm font-semibold text-gray-900 dark:text-gray-100">
              {initialPrompt ? 'Metrics opt-in' : 'Metrics'}
            </h2>
            <p className="text-xs text-gray-500 dark:text-gray-400">
              {data
                ? `Current setting: ${modeLabel(draftMode)}${saving ? ' · saving...' : ''}`
                : 'Loading'}
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded p-1.5 text-gray-400 hover:bg-gray-100 hover:text-gray-700 dark:hover:bg-white/10 dark:hover:text-gray-200"
            aria-label="Close metrics settings"
          >
            <X size={18} />
          </button>
        </div>

        {(loading || permissions.isLoading) && (
          <div className="text-sm text-gray-500 dark:text-gray-400">Loading metrics...</div>
        )}

        {!permissions.isLoading && !canReadSummary && (
          <div className="rounded-md border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900 dark:border-amber-900/70 dark:bg-amber-950/30 dark:text-amber-100">
            You do not have permission to read local metrics.
          </div>
        )}

        {!loading && data && (
          <div className="space-y-5">
            {initialPrompt && (
              <div className="rounded-md border border-blue-200 bg-blue-50 p-3 text-sm text-blue-950 dark:border-blue-900/70 dark:bg-blue-950/30 dark:text-blue-100">
                Okto Pulse starts with metrics off. You can turn on anonymous hourly aggregates here.
              </div>
            )}

            <div className="flex items-center justify-between rounded-lg border border-gray-200 p-4 dark:border-gray-700">
              <div>
                <div className="text-sm font-medium text-gray-900 dark:text-gray-100">Send metrics</div>
                <div className="mt-1 text-xs text-gray-500 dark:text-gray-400">{modeLabel(draftMode)}</div>
              </div>
              <button
                type="button"
                role="switch"
                aria-checked={draftMode === 'anonymous_beacon'}
                disabled={saving || !canEditSettings}
                title={canEditSettings ? 'Change metrics sharing' : 'Requires metrics.settings.edit'}
                data-testid="metrics-on-off-toggle"
                onClick={() => {
                  const nextMode = draftMode === 'anonymous_beacon' ? 'disabled' : 'anonymous_beacon';
                  saveSettings(nextMode);
                }}
                className={`relative h-7 w-12 rounded-full transition ${
                  draftMode === 'anonymous_beacon'
                    ? 'bg-blue-600'
                    : 'bg-gray-300 dark:bg-gray-700'
                }`}
              >
                <span
                  className={`absolute top-1 h-5 w-5 rounded-full bg-white shadow transition ${
                    draftMode === 'anonymous_beacon' ? 'left-6' : 'left-1'
                  }`}
                />
              </button>
            </div>

            <div className="rounded-lg border border-gray-200 p-3 dark:border-gray-700" data-testid="metrics-scope">
              <div className="text-xs font-medium text-gray-900 dark:text-gray-100">Metrics scope</div>
              <div className="mt-1 text-xs leading-5 text-gray-500 dark:text-gray-400">
                All eligible anonymous aggregate metrics are included when sending is on.
              </div>
            </div>

            <div className="space-y-2">
              <div className="flex items-center justify-between gap-2">
                <div className="text-xs font-medium text-gray-700 dark:text-gray-300">Anonymous metrics included</div>
              </div>
              <div className="space-y-2">
                {ACK_ITEMS.map((item) => (
                  <div
                    key={item.id}
                    className="flex gap-3 rounded-md border border-gray-200 p-3 text-left dark:border-gray-700"
                  >
                    <span className="mt-0.5 flex h-4 w-4 shrink-0 items-center justify-center text-blue-600 dark:text-blue-300">
                      <Info size={14} aria-hidden="true" />
                    </span>
                    <span className="min-w-0">
                      <span className="block text-xs font-medium text-gray-800 dark:text-gray-100">
                        {item.label}
                      </span>
                      <span className="mt-0.5 block text-xs leading-5 text-gray-500 dark:text-gray-400">
                        {item.description}
                      </span>
                    </span>
                  </div>
                ))}
              </div>
            </div>

            <div className="space-y-2 text-xs">
              <div className="flex items-center justify-between">
                <span className="text-gray-500">Schema</span>
                <span className="font-mono text-gray-700 dark:text-gray-300">{data.schema_version}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-gray-500">Consent status</span>
                <span className="text-gray-700 dark:text-gray-300">{data.beacon_status.schema_status}</span>
              </div>
              {data.next_opt_in_prompt_after && (
                <div className="flex items-center justify-between">
                  <span className="text-gray-500">Prompt after</span>
                  <span className="text-gray-700 dark:text-gray-300">{data.next_opt_in_prompt_after.slice(0, 10)}</span>
                </div>
              )}
            </div>

            <div className="flex items-center justify-end gap-2 border-t border-gray-200 pt-3 dark:border-gray-700">
              <button type="button" onClick={refresh} className="btn btn-secondary flex items-center gap-1 text-xs">
                <RotateCcw size={14} />
                Refresh
              </button>
              {initialPrompt && (
                <button type="button" onClick={onClose} className="btn btn-secondary text-xs">
                  Not now
                </button>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * Share Board Modal - Manage board sharing with other users
 */

import React, { useState, useEffect } from 'react';
import { X, Trash2, UserPlus } from 'lucide-react';
import toast from 'react-hot-toast';
import { useDashboardApi } from '@/services/api';
import type { BoardShare } from '@/types';
import { useEscapeToClose } from '@/hooks/useEscapeToClose';
import { usePermissions } from '@/hooks/usePermissions';

interface ShareBoardModalProps {
  isOpen: boolean;
  onClose: () => void;
  boardId: string;
  boardName: string;
}

export function ShareBoardModal({ isOpen, onClose, boardId, boardName }: ShareBoardModalProps) {
  const api = useDashboardApi();
  const permissions = usePermissions(boardId);
  const canReadShares = permissions.has('board.share.read');
  const canCreateShare = permissions.has('board.share.create');
  const canEditShare = permissions.has('board.share.edit');
  const canRevokeShare = permissions.has('board.share.revoke');
  const [shares, setShares] = useState<BoardShare[]>([]);
  const [userId, setUserId] = useState('');
  const [permission, setPermission] = useState<'viewer' | 'editor' | 'admin'>('viewer');
  const [isLoading, setIsLoading] = useState(false);

  useEscapeToClose(onClose, { enabled: isOpen });

  useEffect(() => {
    if (isOpen && boardId && canReadShares) {
      void loadShares();
    } else if (!canReadShares) {
      setShares([]);
    }
  }, [isOpen, boardId, canReadShares]);

  const loadShares = async () => {
    if (!canReadShares) return;
    try {
      const data = await api.listBoardShares(boardId);
      setShares(data);
    } catch {
      toast.error('Failed to load shares');
    }
  };

  const handleShare = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!canCreateShare) return;
    if (!userId.trim()) {
      toast.error('User ID is required');
      return;
    }

    setIsLoading(true);
    try {
      await api.shareBoard(boardId, { user_id: userId.trim(), permission });
      toast.success('Board shared!');
      setUserId('');
      await loadShares();
    } catch {
      toast.error('Failed to share board');
    } finally {
      setIsLoading(false);
    }
  };

  const handleUpdatePermission = async (shareId: string, newPermission: 'viewer' | 'editor' | 'admin') => {
    if (!canEditShare) return;
    try {
      await api.updateBoardShare(boardId, shareId, { permission: newPermission });
      toast.success('Permission updated');
      await loadShares();
    } catch {
      toast.error('Failed to update permission');
    }
  };

  const handleRevoke = async (shareId: string) => {
    if (!canRevokeShare) return;
    if (!confirm('Revoke access for this user?')) return;
    try {
      await api.revokeBoardShare(boardId, shareId);
      toast.success('Access revoked');
      await loadShares();
    } catch {
      toast.error('Failed to revoke access');
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="fixed inset-0 bg-black/50" onClick={onClose} />
      <div className="relative bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-md mx-4 max-h-[80vh] flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-700">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
            Share "{boardName}"
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
            <X size={20} />
          </button>
        </div>

        {/* Add share form */}
        <form onSubmit={handleShare} className="p-4 border-b border-gray-200 dark:border-gray-700">
          <div className="flex gap-2">
            <input
              type="text"
              value={userId}
              onChange={(e) => setUserId(e.target.value)}
              placeholder="User ID"
              disabled={!canCreateShare}
              className="flex-1 px-3 py-2 text-sm border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 outline-none"
            />
            <select
              value={permission}
              onChange={(e) => setPermission(e.target.value as 'viewer' | 'editor' | 'admin')}
              disabled={!canCreateShare}
              className="px-2 py-2 text-sm border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
            >
              <option value="viewer">Viewer</option>
              <option value="editor">Editor</option>
              <option value="admin">Admin</option>
            </select>
            <button
              type="submit"
              disabled={isLoading || !canCreateShare}
              className="px-3 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center gap-1 text-sm"
            >
              <UserPlus size={14} />
            </button>
          </div>
        </form>

        {/* Share list */}
        <div className="flex-1 overflow-y-auto p-4">
          {!canReadShares ? (
            <p className="text-center text-gray-400 dark:text-gray-500 text-sm py-4">
              You do not have permission to view board shares
            </p>
          ) : shares.length === 0 ? (
            <p className="text-center text-gray-400 dark:text-gray-500 text-sm py-4">
              Not shared with anyone yet
            </p>
          ) : (
            <ul className="space-y-2">
              {shares.map((share) => (
                <li
                  key={share.id}
                  className="flex items-center justify-between p-2 rounded-lg bg-gray-50 dark:bg-gray-700/50"
                >
                  <div>
                    <div className="text-sm font-medium text-gray-900 dark:text-white">
                      {share.user_id}
                    </div>
                    <div className="text-xs text-gray-400">
                      Shared by {share.shared_by}
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <select
                      value={share.permission}
                      onChange={(e) => handleUpdatePermission(share.id, e.target.value as 'viewer' | 'editor' | 'admin')}
                      disabled={!canEditShare}
                      className="text-xs px-2 py-1 border border-gray-300 dark:border-gray-600 rounded bg-white dark:bg-gray-700 text-gray-900 dark:text-white"
                    >
                      <option value="viewer">Viewer</option>
                      <option value="editor">Editor</option>
                      <option value="admin">Admin</option>
                    </select>
                    <button
                      onClick={() => handleRevoke(share.id)}
                      disabled={!canRevokeShare}
                      className="p-1 text-red-400 hover:text-red-600"
                      title="Revoke access"
                    >
                      <Trash2 size={14} />
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
}

/**
 * CreateBoardModal tests.
 *
 * AC6 — error surfacing (IMPL-2):
 *   When api.createBoard rejects with a backend Error, the component calls
 *   toast.error with the error's message (the detail surfaced by authFetch)
 *   instead of the old hardcoded 'Failed to create board' string.
 *   Also verifies that the loading state resets after the rejection.
 *
 * AC4 — sidebar freshness (IMPL-3, FR3):
 *   When api.createBoard resolves successfully, addBoard is called with the
 *   returned BoardResponse so the sidebar reflects the new board immediately.
 */

import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import toast from 'react-hot-toast';
import { CreateBoardModal } from '../CreateBoardModal';

const apiMock = vi.hoisted(() => ({
  createBoard: vi.fn(),
}));

const storeMock = vi.hoisted(() => ({
  addBoard: vi.fn(),
}));
const permissionState = vi.hoisted(() => ({ allowed: true }));

vi.mock('@/services/api', () => ({
  useDashboardApi: () => apiMock,
}));

vi.mock('@/hooks/usePermissions', () => ({
  usePermissions: () => ({
    preset: 'full_control',
    isLoading: false,
    error: null,
    ownerReviewRequired: false,
    has: (flag: string) => flag === 'board.admin.create' && permissionState.allowed,
  }),
}));

vi.mock('@/store/dashboard', () => ({
  useDashboardStore: () => storeMock,
}));

vi.mock('react-hot-toast', () => ({
  default: { error: vi.fn(), success: vi.fn() },
}));

describe('CreateBoardModal error surfacing (AC6)', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    permissionState.allowed = true;
  });

  it('shows backend detail (not fallback) when createBoard rejects', async () => {
    const backendDetail = 'detail do backend';
    apiMock.createBoard.mockRejectedValue(new Error(backendDetail));

    render(<CreateBoardModal isOpen={true} onClose={vi.fn()} />);

    // Fill in the required Name field
    fireEvent.change(screen.getByPlaceholderText('E.g.: Project X'), {
      target: { value: 'My Board' },
    });

    // Submit the form
    fireEvent.click(screen.getByRole('button', { name: /create board/i }));

    await waitFor(() => {
      expect((toast as any).error).toHaveBeenCalledWith(backendDetail);
    });

    // Must NOT be called with the old hardcoded fallback
    expect((toast as any).error).not.toHaveBeenCalledWith('Failed to create board');

    // Loading resets: the submit button should be re-enabled (not showing 'Creating...')
    await waitFor(() => {
      expect(screen.getByRole('button', { name: /create board/i })).not.toBeDisabled();
    });
  });
});

describe('CreateBoardModal sidebar freshness (AC4)', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    permissionState.allowed = true;
  });

  it('calls addBoard with the returned board on successful submit', async () => {
    const newBoard = {
      id: 'board-new',
      name: 'My Board',
      description: null,
      owner_id: 'owner-1',
      settings: null,
      created_at: '2026-01-01T00:00:00Z',
      updated_at: '2026-01-01T00:00:00Z',
    };
    apiMock.createBoard.mockResolvedValue(newBoard);

    const onClose = vi.fn();
    render(<CreateBoardModal isOpen={true} onClose={onClose} />);

    fireEvent.change(screen.getByPlaceholderText('E.g.: Project X'), {
      target: { value: 'My Board' },
    });

    fireEvent.click(screen.getByRole('button', { name: /create board/i }));

    await waitFor(() => {
      expect(storeMock.addBoard).toHaveBeenCalledWith(newBoard);
    });

    expect((toast as any).success).toHaveBeenCalledWith('Board created');
    expect(onClose).toHaveBeenCalled();
  });
});

describe('CreateBoardModal authorization', () => {
  it('requires the exact board.admin.create leaf before calling the API', () => {
    vi.clearAllMocks();
    permissionState.allowed = false;
    render(<CreateBoardModal isOpen={true} onClose={vi.fn()} boardId="board-1" />);

    const submit = screen.getByRole('button', { name: /create board/i });
    expect(submit).toBeDisabled();
    fireEvent.submit(submit.closest('form')!);
    expect(apiMock.createBoard).not.toHaveBeenCalled();
  });
});

/**
 * ModalStackRenderer — renders the top entry of the modal stack.
 *
 * Ideação c13f7bd3. Lives at the root of the app (inside
 * ModalStackProvider) and:
 *
 *   - Picks the correct entity modal based on `stack.top.type`.
 *   - Passes `onClose={clear}` so that every modal's own X control
 *     collapses the whole stack ("X fecha todas as modais, independente
 *     do nível de drill down").
 *   - When `stack.length > 1`, overlays a small "← Back (N)" pill in
 *     the top-left that calls `pop()`. It sits above the modal backdrop
 *     (z-60) so the user always sees it, regardless of the underlying
 *     modal's layout.
 *
 * Each entity modal remains self-contained; the renderer is a thin
 * dispatcher + floating control, so no modal needed structural changes
 * to participate in the stack.
 */

import { useEffect, useState } from 'react';
import { ArrowLeft } from 'lucide-react';
import { useModalStack } from '@/contexts/ModalStackContext';
import { CardModal } from '@/components/kanban/CardModal';
import { StoryModal } from '@/components/stories';
import { SpecModal } from '@/components/specs/SpecModal';
import { IdeationModal } from '@/components/ideations/IdeationModal';
import { RefinementModal } from '@/components/refinements/RefinementModal';
import { NodeDetailModal } from '@/components/knowledge/NodeDetailModal';
import { useDashboardApi } from '@/services/api';
import { useDashboardStore } from '@/store/dashboard';
import type { TopicSummary } from '@/types';

interface Props {
  /** Current board id. Required by most entity modals to scope lookups. */
  boardId: string;
}

export function ModalStackRenderer({ boardId: currentBoardId }: Props) {
  const api = useDashboardApi();
  const { stack, pop, clear } = useModalStack();
  const openCardInStore = useDashboardStore((s) => s.openCardModal);
  const closeCardInStore = useDashboardStore((s) => s.closeCardModal);
  const [storyTopics, setStoryTopics] = useState<TopicSummary[]>([]);
  const top = stack[stack.length - 1];
  const cardTarget = top?.type === 'card' ? top.target : undefined;
  // Discovery can open an artifact from an accessible board other than the active one.
  const boardId = top?.boardId ?? currentBoardId;

  // Every card reference must initialize the store consumed by CardModal.
  // Callers that only push a stack entry (e.g. Spec references) otherwise
  // render a closed modal or reopen the previously selected card.
  useEffect(() => {
    if (top?.type === 'card') {
      if (cardTarget) openCardInStore(top.id, cardTarget);
      else openCardInStore(top.id);
    }
  }, [boardId, top?.type, top?.id, cardTarget, openCardInStore]);

  useEffect(() => {
    if (top?.type !== 'story') return;
    let active = true;
    api.listTopics(boardId, true)
      .then((topics) => {
        if (active) setStoryTopics(topics);
      })
      .catch(() => {
        if (active) setStoryTopics([]);
      });
    return () => {
      active = false;
    };
  }, [boardId, top?.id, top?.type]);

  if (!top) return null;

  // Clear the stack AND sync the dashboard store for card-type modals so
  // that navigating back to the tasks tab reflects the closed state.
  const handleClose = () => {
    if (top.type === 'card') closeCardInStore();
    clear();
  };

  // The pop handler also resyncs the card store when we're leaving a
  // card layer; otherwise the CardModal stays visually "open" in the
  // tasks tab even after the user drilled back.
  const handleBack = () => {
    if (top.type === 'card') closeCardInStore();
    pop();
    // If the newly-revealed entry is a card, let the store know so
    // CardModal re-opens for that id.
    const next = stack[stack.length - 2];
    if (next && next.type === 'card') {
      if (next.target) openCardInStore(next.id, next.target);
      else openCardInStore(next.id);
    }
  };

  return (
    <>
      {/* Back pill — only when we have somewhere to go back to. */}
      {stack.length > 1 && (
        <button
          type="button"
          onClick={handleBack}
          data-testid="modal-stack-back"
          className="fixed top-4 left-4 z-[60] inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-white dark:bg-gray-900 text-gray-700 dark:text-gray-200 shadow-lg border border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-800 text-xs font-medium"
          title={`Back to previous (${stack.length - 1} layer${stack.length - 1 === 1 ? '' : 's'} behind)`}
        >
          <ArrowLeft size={14} />
          Back
          <span className="text-gray-400 dark:text-gray-500">
            ({stack.length - 1})
          </span>
        </button>
      )}

      {/* Dispatch on the top of the stack. A render-key forces React to
          remount the modal when the top changes to a different id of the
          same type — otherwise the modal's internal useEffect that
          fetches by id might keep stale state. */}
      {top.type === 'card' && (
        <CardModal
          key={`card-${boardId}-${top.id}`}
          boardId={boardId}
          onClose={handleClose}
          onEscape={stack.length > 1 ? handleBack : handleClose}
        />
      )}
      {top.type === 'story' && (
        <StoryModal
          key={`story-${boardId}-${top.id}`}
          boardId={boardId}
          storyId={top.id}
          topics={storyTopics}
          onClose={handleClose}
          onEscape={stack.length > 1 ? handleBack : handleClose}
          onChanged={() => {
            /* drill-down is read-only from here */
          }}
        />
      )}
      {top.type === 'spec' && (
        <SpecModal
          key={`spec-${boardId}-${top.id}-${top.initialTab ?? 'default'}-${top.focusProjectNodeId ?? 'root'}-${top.focusReadinessRef ?? ''}`}
          specId={top.id}
          boardId={boardId}
          initialTab={top.initialTab}
          focusProjectNodeId={top.focusProjectNodeId}
          focusReadinessRef={top.focusReadinessRef}
          onClose={handleClose}
          onEscape={stack.length > 1 ? handleBack : handleClose}
          onChanged={() => {
            /* drill-down is read-only from here */
          }}
        />
      )}
      {top.type === 'ideation' && (
        <IdeationModal
          key={`ideation-${boardId}-${top.id}`}
          ideationId={top.id}
          boardId={boardId}
          onClose={handleClose}
          onEscape={stack.length > 1 ? handleBack : handleClose}
          onChanged={() => {
            /* drill-down is read-only from here */
          }}
        />
      )}
      {top.type === 'refinement' && (
        <RefinementModal
          key={`refinement-${boardId}-${top.id}`}
          refinementId={top.id}
          boardId={boardId}
          onClose={handleClose}
          onEscape={stack.length > 1 ? handleBack : handleClose}
          onChanged={() => {
            /* drill-down is read-only from here */
          }}
        />
      )}
      {top.type === 'kg_node' && (
        <NodeDetailModal
          key={`kg-${boardId}-${top.id}`}
          boardId={boardId}
          nodeId={top.id}
          onClose={handleClose}
          onEscape={stack.length > 1 ? handleBack : handleClose}
        />
      )}
    </>
  );
}

/**
 * Sprint C1 — TC-1, TC-2, TC-3, TC-5
 *
 * Combined vitest suite for the terms acceptance flow:
 * - TC-1: modal renders and acts as a blocker
 * - TC-2: scroll-to-end enables Accept; click persists localStorage
 * - TC-3: re-prompt when stored hash diverges from current TERMS_HASH
 * - TC-5: aggregated suite (this file)
 */

import { describe, expect, it, vi, beforeEach, afterEach } from 'vitest';
import { fireEvent, render, screen, act } from '@testing-library/react';
import { TermsAcceptanceModal } from '../TermsAcceptanceModal';
import { renderHook } from '@testing-library/react';
import { useTermsAcceptance } from '@/hooks/useTermsAcceptance';
import { saveAcceptance, clearAcceptance, loadAcceptance } from '@/services/terms-acceptance-api';
import { TERMS_HASH } from '@/constants/terms';

beforeEach(() => {
  localStorage.clear();
  document.body.innerHTML = '';
  // jsdom doesn't compute layout; force scrollHeight so handleScroll can fire.
  Object.defineProperty(HTMLElement.prototype, 'scrollHeight', {
    configurable: true,
    get() { return 1000; },
  });
  Object.defineProperty(HTMLElement.prototype, 'clientHeight', {
    configurable: true,
    get() { return 400; },
  });
});

afterEach(() => {
  vi.restoreAllMocks();
});

describe('TermsAcceptanceModal — TC-1 + TC-2', () => {
  it('consumes Escape without dismissing the required acceptance dialog', () => {
    const onAccept = vi.fn();
    render(<TermsAcceptanceModal onAccept={onAccept} />);
    const event = new KeyboardEvent('keydown', {
      key: 'Escape',
      bubbles: true,
      cancelable: true,
    });

    document.dispatchEvent(event);

    expect(event.defaultPrevented).toBe(true);
    expect(onAccept).not.toHaveBeenCalled();
    expect(screen.getByTestId('terms-acceptance-modal')).toBeInTheDocument();
  });

  it('TC-1: renders the modal with title and disabled accept button', () => {
    render(<TermsAcceptanceModal onAccept={() => {}} />);
    expect(screen.getByTestId('terms-acceptance-modal')).toBeTruthy();
    const btn = screen.getByTestId('terms-modal-accept') as HTMLButtonElement;
    expect(btn.disabled).toBe(true);
  });

  it('TC-2: scrolling to end enables the accept button and click invokes onAccept', () => {
    const onAccept = vi.fn();
    render(<TermsAcceptanceModal onAccept={onAccept} />);
    const scroller = screen.getByTestId('terms-modal-scroll');
    // Simulate reaching the bottom
    Object.defineProperty(scroller, 'scrollTop', { configurable: true, get() { return 600; } });
    fireEvent.scroll(scroller);
    const btn = screen.getByTestId('terms-modal-accept') as HTMLButtonElement;
    expect(btn.disabled).toBe(false);
    fireEvent.click(btn);
    expect(onAccept).toHaveBeenCalledTimes(1);
  });

  it('TC-2: saveAcceptance writes a record to localStorage with current hash', () => {
    const rec = saveAcceptance('modal');
    expect(rec.source).toBe('modal');
    expect(rec.hash).toBe(TERMS_HASH);
    const persisted = loadAcceptance();
    expect(persisted).not.toBeNull();
    expect(persisted!.hash).toBe(TERMS_HASH);
  });
});

describe('useTermsAcceptance — TC-3 (re-prompt on hash mismatch)', () => {
  it('treats a stored record with a mismatched hash as missing (re-prompt)', async () => {
    // Pre-populate with a stale hash from a previous version
    localStorage.setItem(
      'okto.terms.acceptance',
      JSON.stringify({
        accepted_at: '2026-01-01T00:00:00Z',
        version: '0.0.0',
        hash: 'old-hash-different-from-current',
        source: 'modal',
      }),
    );
    // Stub fetch so the bootstrap doesn't try the backend
    const fetchSpy = vi.spyOn(global, 'fetch').mockResolvedValue({
      ok: true,
      json: async () => ({ terms_acceptance: { pre_accepted: false, source: null } }),
    } as any);

    const { result } = renderHook(() => useTermsAcceptance());
    // Wait for the async bootstrap
    await act(async () => { await Promise.resolve(); await Promise.resolve(); });

    expect(result.current.needsAcceptance).toBe(true);
    expect(result.current.acceptance).toBeNull();
    fetchSpy.mockRestore();
  });

  it('honors a fresh cached acceptance when hash matches', async () => {
    saveAcceptance('modal');
    const { result } = renderHook(() => useTermsAcceptance());
    await act(async () => { await Promise.resolve(); });
    expect(result.current.needsAcceptance).toBe(false);
    expect(result.current.acceptance).not.toBeNull();
    expect(result.current.acceptance!.hash).toBe(TERMS_HASH);
  });

  it('honors backend pre-acceptance via /api/v1/me/system-flags', async () => {
    clearAcceptance();
    const fetchSpy = vi.spyOn(global, 'fetch').mockResolvedValue({
      ok: true,
      json: async () => ({
        terms_acceptance: { pre_accepted: true, source: 'env', record: null, current_hash: TERMS_HASH },
      }),
    } as any);
    const { result } = renderHook(() => useTermsAcceptance());
    await act(async () => { await Promise.resolve(); await Promise.resolve(); await Promise.resolve(); });
    expect(result.current.needsAcceptance).toBe(false);
    expect(result.current.acceptance?.source).toBe('env');
    fetchSpy.mockRestore();
  });

  it('honors window.OKTO_PULSE_TERMS_ACCEPTED=1 (env injection)', async () => {
    clearAcceptance();
    (window as any).OKTO_PULSE_TERMS_ACCEPTED = '1';
    const { result } = renderHook(() => useTermsAcceptance());
    await act(async () => { await Promise.resolve(); });
    expect(result.current.needsAcceptance).toBe(false);
    expect(result.current.acceptance?.source).toBe('env');
    delete (window as any).OKTO_PULSE_TERMS_ACCEPTED;
  });

  it('honors ?accept_terms=1 URL param (CLI redirector) and removes it from the URL', async () => {
    clearAcceptance();
    window.history.replaceState({}, '', '/?accept_terms=1');
    const { result } = renderHook(() => useTermsAcceptance());
    await act(async () => { await Promise.resolve(); });
    expect(result.current.needsAcceptance).toBe(false);
    expect(result.current.acceptance?.source).toBe('cli');
    expect(window.location.search).not.toContain('accept_terms');
  });
});

/**
 * PermissionFlagsEditor — Reusable component for viewing/editing permission flags.
 *
 * Renders permission trees of arbitrary depth with toggle switches.
 * Supports read-only mode for built-in presets and editable mode for custom.
 * Counters update in real-time on toggle.
 */

import { useState } from 'react';
import { ChevronRight, ChevronDown } from 'lucide-react';
import type { PermissionFlags, PermissionFlagTree } from '@/types';
import { getEntityLabel, getEntityTextClasses } from './permissionLabels';

type FlagValue = boolean;
// The canonical registry may introduce groups at any depth (for example
// spec.structured_entity.<type>.<action>). Keep this shape recursive so the
// frontend never needs its own depth-specific permission catalog.
export type FlagTree = PermissionFlagTree;
export type FlagsMap = PermissionFlags;

function isFlagTree(value: unknown): value is FlagTree {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** Count total and enabled flags in a nested structure */
function countFlags(obj: FlagTree): { total: number; enabled: number } {
  let total = 0;
  let enabled = 0;
  for (const val of Object.values(obj)) {
    if (typeof val === 'boolean') {
      total++;
      if (val) enabled++;
    } else if (isFlagTree(val)) {
      const nested = countFlags(val);
      total += nested.total;
      enabled += nested.enabled;
    }
  }
  return { total, enabled };
}

function replaceAtPath(
  tree: FlagTree,
  path: string[],
  replace: (value: FlagValue | FlagTree) => FlagValue | FlagTree,
): FlagTree {
  const [key, ...rest] = path;
  if (!key || !(key in tree)) return tree;

  const current = tree[key];
  let next: FlagValue | FlagTree;
  if (rest.length === 0) {
    next = replace(current);
  } else if (isFlagTree(current)) {
    next = replaceAtPath(current, rest, replace);
  } else {
    return tree;
  }

  return next === current ? tree : { ...tree, [key]: next };
}

function setFlagsInTree(tree: FlagTree, value: boolean): FlagTree {
  const updated: FlagTree = {};
  for (const [key, current] of Object.entries(tree)) {
    updated[key] = typeof current === 'boolean'
      ? value
      : setFlagsInTree(current, value);
  }
  return updated;
}

function countBadgeColor(enabled: number, total: number): string {
  if (enabled === total) return 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300';
  if (enabled === 0) return 'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300';
  return 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300';
}

interface PermissionFlagsEditorProps {
  flags: FlagsMap;
  onChange?: (flags: FlagsMap) => void;
  readOnly?: boolean;
}

export function PermissionFlagsEditor({ flags, onChange, readOnly = false }: PermissionFlagsEditorProps) {
  const [expandedEntity, setExpandedEntity] = useState<string | null>(null);
  const entities = Object.keys(flags).filter((entity) => entity !== 'sprint');

  // Global counts
  let globalTotal = 0;
  let globalEnabled = 0;
  for (const entity of entities) {
    const c = countFlags(flags[entity]);
    globalTotal += c.total;
    globalEnabled += c.enabled;
  }

  const toggleFlag = (path: string[]) => {
    if (readOnly || !onChange) return;
    const updated = replaceAtPath(flags, path, (current) => (
      typeof current === 'boolean' ? !current : current
    ));
    onChange(updated as FlagsMap);
  };

  const setSubtreeAll = (path: string[], value: boolean) => {
    if (readOnly || !onChange) return;
    const updated = replaceAtPath(flags, path, (current) => (
      isFlagTree(current) ? setFlagsInTree(current, value) : current
    ));
    onChange(updated as FlagsMap);
  };

  return (
    <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
      {entities.map((entity) => {
        const entityData = flags[entity];
        const entityLabel = getEntityLabel(entity);
        const isExpanded = expandedEntity === entity;
        const { total, enabled } = countFlags(entityData);

        return (
          <div key={entity} className="border-b last:border-b-0 border-gray-200 dark:border-gray-700">
            <button
              type="button"
              aria-label={`Edit ${entityLabel} permissions`}
              aria-expanded={isExpanded}
              onClick={() => setExpandedEntity(isExpanded ? null : entity)}
              className="w-full flex items-center justify-between px-4 py-2.5 text-sm hover:bg-gray-50 dark:hover:bg-gray-700/30"
            >
              <div className="flex items-center gap-2">
                {isExpanded ? <ChevronDown size={14} className="text-gray-400" /> : <ChevronRight size={14} className="text-gray-400" />}
                <span className={`font-medium ${getEntityTextClasses(entity)}`}>
                  {entityLabel}
                </span>
              </div>
              <span className={`text-[10px] px-1.5 py-0.5 rounded ${countBadgeColor(enabled, total)}`}>
                {enabled}/{total}
              </span>
            </button>
            {isExpanded && (
              <div className="px-4 pb-3">
                <PermissionTreeRows
                  tree={entityData}
                  path={[entity]}
                  onToggle={toggleFlag}
                  onSetSubtree={setSubtreeAll}
                  readOnly={readOnly}
                />
              </div>
            )}
          </div>
        );
      })}

      {/* Global footer */}
      <div className="px-4 py-2 bg-gray-50 dark:bg-gray-700/20 border-t border-gray-200 dark:border-gray-700">
        <span className="text-[10px] text-gray-400">{globalEnabled} of {globalTotal} flags enabled</span>
      </div>
    </div>
  );
}

function PermissionTreeRows({
  tree,
  path,
  onToggle,
  onSetSubtree,
  readOnly,
  depth = 0,
}: {
  tree: FlagTree;
  path: string[];
  onToggle: (path: string[]) => void;
  onSetSubtree: (path: string[], value: boolean) => void;
  readOnly: boolean;
  depth?: number;
}) {
  const leaves = Object.entries(tree).filter((entry): entry is [string, boolean] => (
    typeof entry[1] === 'boolean'
  ));
  const groups = Object.entries(tree).filter((entry): entry is [string, FlagTree] => (
    isFlagTree(entry[1])
  ));

  return (
    <div className="space-y-2">
      {leaves.length > 0 && (
        <div className="space-y-1">
          {leaves.map(([key, enabled]) => {
            const flagPath = [...path, key];
            return (
              <div
                key={key}
                className="flex items-center justify-between py-0.5"
                style={{ paddingLeft: `${(depth + 1) * 1.5}rem` }}
              >
                <span className="text-xs text-gray-700 dark:text-gray-300">{key}</span>
                <ToggleSwitch
                  enabled={enabled}
                  label={flagPath.join('.')}
                  onToggle={() => onToggle(flagPath)}
                  readOnly={readOnly}
                />
              </div>
            );
          })}
        </div>
      )}

      {groups.map(([key, subtree]) => {
        const groupPath = [...path, key];
        const fullPath = groupPath.join('.');
        const { total, enabled } = countFlags(subtree);
        return (
          <div key={key} style={{ marginLeft: `${depth}rem` }}>
            <div className="flex items-center justify-between py-1.5 px-2 rounded bg-gray-50 dark:bg-gray-700/30">
              <span className="text-[10px] font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">{key}</span>
              <div className="flex items-center gap-2">
                <span className="text-[10px] text-gray-400">{enabled}/{total}</span>
                {!readOnly && (
                  <>
                    <button
                      type="button"
                      aria-label={`Turn all on in ${fullPath}`}
                      onClick={() => onSetSubtree(groupPath, true)}
                      className="text-[10px] text-blue-500 hover:text-blue-600"
                    >
                      all on
                    </button>
                    <button
                      type="button"
                      aria-label={`Turn all off in ${fullPath}`}
                      onClick={() => onSetSubtree(groupPath, false)}
                      className="text-[10px] text-red-400 hover:text-red-500"
                    >
                      all off
                    </button>
                  </>
                )}
              </div>
            </div>
            <div className="mt-0.5">
              <PermissionTreeRows
                tree={subtree}
                path={groupPath}
                onToggle={onToggle}
                onSetSubtree={onSetSubtree}
                readOnly={readOnly}
                depth={depth + 1}
              />
            </div>
          </div>
        );
      })}
    </div>
  );
}

/** Simple toggle switch */
function ToggleSwitch({
  enabled,
  label,
  onToggle,
  readOnly,
}: {
  enabled: boolean;
  label: string;
  onToggle: () => void;
  readOnly?: boolean;
}) {
  return (
    <button
      type="button"
      aria-label={`Toggle ${label}`}
      aria-pressed={enabled}
      onClick={readOnly ? undefined : onToggle}
      className={`relative w-8 h-4 rounded-full transition-colors shrink-0 ${
        enabled ? 'bg-green-500' : 'bg-gray-300 dark:bg-gray-600'
      } ${readOnly ? 'opacity-50 cursor-default' : 'cursor-pointer'}`}
      disabled={readOnly}
    >
      <span
        className={`absolute top-0.5 w-3 h-3 rounded-full bg-white transition-transform ${
          enabled ? 'right-0.5' : 'left-0.5'
        }`}
      />
    </button>
  );
}

/** Utility: count total enabled/total in a FlagsMap */
export function countAllFlags(flags: FlagsMap): { total: number; enabled: number } {
  let total = 0;
  let enabled = 0;
  for (const [entity, tree] of Object.entries(flags)) {
    if (entity === 'sprint') continue;
    const c = countFlags(tree);
    total += c.total;
    enabled += c.enabled;
  }
  return { total, enabled };
}

/** Utility: count per-entity */
export function countPerEntity(flags: FlagsMap): Record<string, { total: number; enabled: number }> {
  const result: Record<string, { total: number; enabled: number }> = {};
  for (const [entity, data] of Object.entries(flags)) {
    if (entity === 'sprint') continue;
    result[entity] = countFlags(data);
  }
  return result;
}

/** Utility: set all flags to a value */
export function setAllFlags(flags: FlagsMap, value: boolean): FlagsMap {
  return Object.fromEntries(
    Object.entries(flags).map(([entity, tree]) => [
      entity, entity === 'sprint' ? tree : setFlagsInTree(tree, value),
    ]),
  );
}

export { countFlags, countBadgeColor };
export { ENTITY_COLORS, ENTITY_LABELS } from './permissionLabels';

/**
 * PresetEditorModal — Create/edit/view a permission preset with granular flag toggles.
 */

import { useState } from 'react';
import { X, Shield } from 'lucide-react';
import toast from 'react-hot-toast';
import { useDashboardApi } from '@/services/api';
import { PermissionFlagsEditor, countAllFlags, setAllFlags } from './PermissionFlagsEditor';
import type { FlagsMap } from './PermissionFlagsEditor';
import type { PermissionPreset } from '@/types';
import { useEscapeToClose } from '@/hooks/useEscapeToClose';
import { PresetLineageInfo } from './PresetLineageInfo';
import { resolvePresetLineage } from './presetResolution';
import { usePermissions } from '@/hooks/usePermissions';
import { useCurrentBoard } from '@/store/dashboard';

interface PresetEditorModalProps {
  /** Preset to edit. Null = create new. */
  preset: PermissionPreset | null;
  /** Complete visible catalog used to resolve immutable lineage identities. */
  presets: readonly PermissionPreset[];
  /** Template flags for new preset (all false by default). */
  templateFlags?: FlagsMap;
  onClose: () => void;
  onSaved: () => void;
  /** Optional explicit scope; existing callers fall back to the current board. */
  boardId?: string | null;
}

export function PresetEditorModal({
  preset,
  presets,
  templateFlags,
  onClose,
  onSaved,
  boardId,
}: PresetEditorModalProps) {
  const api = useDashboardApi();
  const currentBoard = useCurrentBoard();
  const permissions = usePermissions(boardId ?? currentBoard?.id);
  const policyAuthorityReady = (
    !permissions.isLoading
    && !permissions.error
    && !permissions.ownerReviewRequired
  );
  const canCreatePreset = policyAuthorityReady
    && permissions.has('permission_preset.entity.create');
  const canEditPreset = policyAuthorityReady
    && permissions.has('permission_preset.entity.edit');
  const canClonePreset = policyAuthorityReady
    && permissions.has('permission_preset.clone');
  const isBuiltIn = preset?.is_builtin ?? false;
  const isNew = !preset;
  const canModifyPreset = isNew ? canCreatePreset : canEditPreset;
  const lineage = preset && !preset.is_builtin
    ? resolvePresetLineage(preset, presets)
    : null;
  const baseFlags = lineage?.canResetToBase && lineage.directBase
    ? lineage.directBase.flags as unknown as FlagsMap
    : null;

  const [name, setName] = useState(preset?.name || '');
  const [description, setDescription] = useState(preset?.description || '');
  const [flags, setFlags] = useState<FlagsMap>(
    preset?.flags || templateFlags || {}
  );
  const [flagsEdited, setFlagsEdited] = useState(false);
  const editFlags = (next: FlagsMap) => {
    setFlags(next);
    setFlagsEdited(true);
  };
  const [saving, setSaving] = useState(false);

  useEscapeToClose(onClose, { canClose: !saving, priority: 10 });

  const { total, enabled } = countAllFlags(flags);

  const handleSave = async () => {
    if (!canModifyPreset) return;
    if (!name.trim()) {
      toast.error('Preset name is required');
      return;
    }
    setSaving(true);
    try {
      if (isNew) {
        await api.createPreset({ name: name.trim(), description: description.trim() || undefined, flags });
        toast.success('Preset created');
      } else {
        await api.updatePreset(preset!.id, {
          name: name.trim(),
          description: description.trim() || undefined,
          // Metadata edits must not submit a projected flag tree as a new
          // policy decision or silently clear a pending migration review.
          ...(flagsEdited ? { flags } : {}),
        });
        toast.success('Preset updated');
      }
      onSaved();
      onClose();
    } catch (err: any) {
      toast.error(err?.message || 'Failed to save preset');
    } finally {
      setSaving(false);
    }
  };

  const handleCloneBuiltIn = async () => {
    if (!preset || !canClonePreset) return;
    setSaving(true);
    try {
      await api.clonePreset(preset.id, {
        name: `${preset.name} (copy)`,
        description: `Cloned from ${preset.name}`,
        flags: JSON.parse(JSON.stringify(preset.flags)),
      });
      toast.success('Preset cloned — you can now edit it');
      onSaved();
      onClose();
    } catch (err: any) {
      toast.error(err?.message || 'Failed to clone');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[60]" onClick={onClose}>
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-2xl flex flex-col max-h-[85vh]" onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200 dark:border-gray-700 shrink-0">
          <div>
            <div className="flex items-center gap-2">
              <Shield size={18} className="text-violet-500" />
              <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
                {isNew
                  ? 'New Preset'
                  : isBuiltIn || !canEditPreset
                    ? `View: ${preset.name}`
                    : `Edit: ${preset.name}`}
              </h2>
              {isBuiltIn && (
                <span className="text-[10px] px-2 py-0.5 rounded-full bg-gray-100 text-gray-500 dark:bg-gray-700 dark:text-gray-400 font-medium">
                  view only
                </span>
              )}
              {!isBuiltIn && !isNew && (
                <span className="text-[10px] px-2 py-0.5 rounded-full bg-violet-100 text-violet-600 font-medium">custom</span>
              )}
              {preset?.owner_review_required && (
                <span
                  className="text-[10px] px-2 py-0.5 rounded-full bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300 font-medium"
                  title={preset.review_reason || 'Preset lineage requires owner review'}
                >
                  owner review required
                </span>
              )}
            </div>
            <p className="text-xs text-gray-400 mt-0.5">{enabled} of {total} flags enabled</p>
          </div>
          <button onClick={onClose} className="p-1.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
            <X size={20} />
          </button>
        </div>

        {/* Name / Description */}
        {!isBuiltIn && (
          <div className="px-6 py-3 border-b border-gray-100 dark:border-gray-700 space-y-2 shrink-0">
            {preset && (
              <PresetLineageInfo preset={preset} presets={presets} />
            )}
            <div className="flex gap-3">
              <div className="flex-1">
                <label className="text-[10px] text-gray-400 uppercase tracking-wide">Name</label>
                <input
                  type="text"
                  value={name}
                  disabled={!canModifyPreset}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Preset name..."
                  className="w-full px-3 py-1.5 border border-gray-300 dark:border-gray-600 rounded-lg text-sm dark:bg-gray-700 dark:text-gray-200 mt-0.5"
                />
              </div>
              <div className="flex-1">
                <label className="text-[10px] text-gray-400 uppercase tracking-wide">Description</label>
                <input
                  type="text"
                  value={description}
                  disabled={!canModifyPreset}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="What this preset is for..."
                  className="w-full px-3 py-1.5 border border-gray-300 dark:border-gray-600 rounded-lg text-sm dark:bg-gray-700 dark:text-gray-200 mt-0.5"
                />
              </div>
            </div>
            <div className="flex gap-2">
              <button disabled={!canModifyPreset} onClick={() => editFlags(setAllFlags(flags, true))} className="text-[10px] px-2 py-1 rounded bg-green-100 text-green-700 hover:bg-green-200 disabled:opacity-40 dark:bg-green-900/30 dark:text-green-300">
                Enable All
              </button>
              <button disabled={!canModifyPreset} onClick={() => editFlags(setAllFlags(flags, false))} className="text-[10px] px-2 py-1 rounded bg-red-100 text-red-700 hover:bg-red-200 disabled:opacity-40 dark:bg-red-900/30 dark:text-red-300">
                Disable All
              </button>
              {baseFlags && (
                <button
                  onClick={() => editFlags(JSON.parse(JSON.stringify(baseFlags)))}
                  disabled={!canModifyPreset}
                  className="text-[10px] px-2 py-1 rounded bg-blue-100 text-blue-700 hover:bg-blue-200 dark:bg-blue-900/30 dark:text-blue-300"
                  title={`Restore flags from ${lineage?.baseLabel ?? 'base preset'}`}
                >
                  Reset to Base
                </button>
              )}
            </div>
          </div>
        )}

        {/* Flags editor */}
        <div className="flex-1 overflow-y-auto">
          <PermissionFlagsEditor
            flags={flags}
            onChange={isBuiltIn || !canModifyPreset ? undefined : editFlags}
            readOnly={isBuiltIn || !canModifyPreset}
          />
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between px-6 py-4 border-t border-gray-200 dark:border-gray-700 shrink-0">
          <span className="text-xs text-gray-400">{enabled} of {total} flags enabled</span>
          <div className="flex gap-2">
            <button onClick={onClose} className="px-4 py-2 text-sm text-gray-600 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg">
              {isBuiltIn ? 'Close' : 'Cancel'}
            </button>
            {isBuiltIn ? (
              <button onClick={handleCloneBuiltIn} disabled={saving || !canClonePreset} className="px-4 py-2 text-sm bg-violet-500 text-white rounded-lg hover:bg-violet-600 font-medium disabled:opacity-50">
                {saving ? 'Cloning...' : 'Clone to customize'}
              </button>
            ) : (
              <button onClick={handleSave} disabled={saving || !canModifyPreset || !name.trim()} className="px-4 py-2 text-sm bg-violet-500 text-white rounded-lg hover:bg-violet-600 font-medium disabled:opacity-50">
                {saving ? 'Saving...' : isNew ? 'Create Preset' : 'Save Preset'}
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

/**
 * PresetListModal — List, create, clone, edit, delete permission presets.
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import { X, Plus, Shield, Copy, Pencil, Trash2 } from 'lucide-react';
import toast from 'react-hot-toast';
import { useDashboardApi } from '@/services/api';
import {
  type ImportExportEnvelope,
  useImportExportApi,
} from '@/services/import-export-api';
import {
  ExportItemButton,
  ImportExportButtons,
} from '@/components/shared/ImportExportButtons';
import { countPerEntity, countAllFlags } from './PermissionFlagsEditor';
import { getEntityChipClasses, getEntityLabel } from './permissionLabels';
import { PresetEditorModal } from './PresetEditorModal';
import type { FlagsMap } from './PermissionFlagsEditor';
import { PresetLineageInfo } from './PresetLineageInfo';
import { disabledFullControlTemplate } from './presetResolution';
import type { PermissionPreset } from '@/types';
import { useEscapeToClose } from '@/hooks/useEscapeToClose';
import { usePermissions } from '@/hooks/usePermissions';
import { useCurrentBoard } from '@/store/dashboard';

interface PresetListModalProps {
  onClose: () => void;
  /** Optional explicit scope; existing callers fall back to the current board. */
  boardId?: string | null;
}

export function PresetListModal({ onClose, boardId }: PresetListModalProps) {
  const api = useDashboardApi();
  const apiRef = useRef(api);
  apiRef.current = api;
  const importExportApi = useImportExportApi();
  const importExportRef = useRef(importExportApi);
  importExportRef.current = importExportApi;
  const currentBoard = useCurrentBoard();
  const resolvedBoardId = boardId ?? currentBoard?.id;
  const permissions = usePermissions(resolvedBoardId);
  const policyAuthorityReady = (
    !permissions.isLoading
    && !permissions.error
    && !permissions.ownerReviewRequired
  );
  const canReadPresets = policyAuthorityReady
    && permissions.has('permission_preset.entity.read');
  const canCreatePreset = policyAuthorityReady
    && permissions.has('permission_preset.entity.create');
  const canEditPreset = policyAuthorityReady
    && permissions.has('permission_preset.entity.edit');
  const canDeletePreset = policyAuthorityReady
    && permissions.has('permission_preset.entity.delete');
  const canClonePreset = policyAuthorityReady
    && permissions.has('permission_preset.clone');
  const canImportPresets = policyAuthorityReady
    && permissions.has('permission_preset.import');
  const canExportPresets = policyAuthorityReady
    && permissions.has('permission_preset.export');
  const [presets, setPresets] = useState<PermissionPreset[]>([]);
  const [loading, setLoading] = useState(true);
  const [editorPreset, setEditorPreset] = useState<PermissionPreset | null | 'new'>(null);

  useEscapeToClose(onClose);

  const loadPresets = useCallback(async () => {
    if (!policyAuthorityReady) {
      setPresets([]);
      setLoading(permissions.isLoading);
      return;
    }
    if (!canReadPresets) {
      setPresets([]);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      const data = await apiRef.current.listPresets();
      setPresets(data);
    } catch { toast.error('Failed to load presets'); }
    finally { setLoading(false); }
  }, [canReadPresets, permissions.isLoading, policyAuthorityReady]);

  useEffect(() => { void loadPresets(); }, [loadPresets]);

  const handleClone = async (preset: PermissionPreset) => {
    if (!canClonePreset) return;
    try {
      await apiRef.current.clonePreset(preset.id, {
        name: `${preset.name} (copy)`,
        description: `Cloned from ${preset.name}`,
        flags: JSON.parse(JSON.stringify(preset.flags)),
      });
      toast.success('Preset cloned');
      await loadPresets();
    } catch (err: any) {
      toast.error(err?.message || 'Failed to clone');
    }
  };

  const handleDelete = async (preset: PermissionPreset) => {
    if (!canDeletePreset) return;
    if (!confirm(`Delete preset "${preset.name}"? This cannot be undone.`)) return;
    try {
      await apiRef.current.deletePreset(preset.id);
      toast.success('Preset deleted');
      await loadPresets();
    } catch (err: any) {
      toast.error(err?.message || 'Failed to delete');
    }
  };

  const builtIn = presets.filter((p) => p.is_builtin);
  const custom = presets.filter((p) => !p.is_builtin);

  return (
    <>
      <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50" onClick={onClose}>
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-3xl flex flex-col max-h-[80vh]" onClick={(e) => e.stopPropagation()}>
          {/* Header */}
          <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200 dark:border-gray-700 shrink-0">
            <div className="flex items-center gap-2">
              <Shield size={20} className="text-violet-500" />
              <h2 className="text-lg font-semibold text-gray-900 dark:text-white">Permission Presets</h2>
              <span className="text-xs text-gray-400">({presets.length})</span>
            </div>
            <div className="flex items-center gap-2">
              <ImportExportButtons
                kind="presets"
                onExport={() => importExportRef.current.exportPresets()}
                onImport={(envelope, options) => importExportRef.current.importPresets(envelope, options)}
                onImported={() => loadPresets()}
                confirmReplacements
                canExport={canExportPresets}
                canImport={canImportPresets}
              />
              <button
                disabled={!canCreatePreset}
                onClick={() => {
                  if (canCreatePreset) setEditorPreset('new');
                }}
                className="px-3 py-1.5 bg-violet-500 text-white rounded-lg text-sm font-medium hover:bg-violet-600 disabled:cursor-not-allowed disabled:opacity-50 flex items-center gap-1"
              >
                <Plus size={14} />
                New Preset
              </button>
              <button onClick={onClose} className="p-1.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
                <X size={20} />
              </button>
            </div>
          </div>

          {/* List */}
          <div className="flex-1 overflow-y-auto p-6 space-y-3">
            {loading ? (
              <div className="text-center py-8 text-gray-500 dark:text-gray-400">Loading presets...</div>
            ) : !canReadPresets ? (
              <div data-testid="preset-read-unavailable" className="text-center py-8 text-gray-500 dark:text-gray-400">
                Presets are hidden until <code>permission_preset.entity.read</code> is granted.
              </div>
            ) : (
              <>
                {/* Built-in */}
                <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wide">Built-in Presets</h3>
                {builtIn.map((preset) => (
                  <PresetCard
                    key={preset.id}
                    preset={preset}
                    presets={presets}
                    onView={() => setEditorPreset(preset)}
                    onClone={() => handleClone(preset)}
                    onExport={() => importExportRef.current.exportPreset(preset.id)}
                    canClone={canClonePreset}
                    canExport={canExportPresets}
                  />
                ))}

                {/* Custom */}
                <h3 className="text-xs font-semibold text-gray-400 uppercase tracking-wide mt-6">Custom Presets</h3>
                {custom.length === 0 ? (
                  <p className="text-xs text-gray-400 italic">No custom presets yet. Clone a built-in or create from scratch.</p>
                ) : (
                  custom.map((preset) => (
                    <PresetCard
                      key={preset.id}
                      preset={preset}
                      presets={presets}
                      onView={() => setEditorPreset(preset)}
                      onClone={() => handleClone(preset)}
                      onExport={() => importExportRef.current.exportPreset(preset.id)}
                      onEdit={() => setEditorPreset(preset)}
                      onDelete={() => handleDelete(preset)}
                      canClone={canClonePreset}
                      canEdit={canEditPreset}
                      canDelete={canDeletePreset}
                      canExport={canExportPresets}
                    />
                  ))
                )}

                <button
                  disabled={!canCreatePreset}
                  onClick={() => {
                    if (canCreatePreset) setEditorPreset('new');
                  }}
                  className="w-full py-3 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-xl text-gray-400 hover:border-violet-400 hover:text-violet-500 disabled:cursor-not-allowed disabled:opacity-50 flex items-center justify-center gap-2 text-sm"
                >
                  <Plus size={14} />
                  Create custom preset
                </button>
              </>
            )}
          </div>
        </div>
      </div>

      {/* Editor overlay */}
      {editorPreset !== null && (
        <PresetEditorModal
          preset={editorPreset === 'new' ? null : editorPreset}
          boardId={resolvedBoardId}
          presets={presets}
          templateFlags={
            editorPreset === 'new'
              ? disabledFullControlTemplate(presets) ?? undefined
              : undefined
          }
          onClose={() => setEditorPreset(null)}
          onSaved={loadPresets}
        />
      )}
    </>
  );
}

function PresetCard({
  preset,
  presets,
  onView,
  onClone,
  onEdit,
  onDelete,
  onExport,
  canClone,
  canEdit = false,
  canDelete = false,
  canExport,
}: {
  preset: PermissionPreset;
  presets: readonly PermissionPreset[];
  onView: () => void;
  onClone: () => void;
  onEdit?: () => void;
  onDelete?: () => void;
  onExport: () => Promise<ImportExportEnvelope>;
  canClone: boolean;
  canEdit?: boolean;
  canDelete?: boolean;
  canExport: boolean;
}) {
  const flags = preset.flags as FlagsMap;
  const perEntity = countPerEntity(flags);
  const { total, enabled } = countAllFlags(flags);

  return (
    <div
      onClick={onView}
      className={`border rounded-xl p-4 cursor-pointer transition-colors ${
        preset.is_builtin
          ? 'border-gray-200 dark:border-gray-700 hover:border-violet-300 dark:hover:border-violet-600'
          : 'border-violet-200 dark:border-violet-700 bg-violet-50/30 dark:bg-violet-900/5 hover:border-violet-400'
      }`}
    >
      <div className="flex items-center justify-between">
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h4 className="font-medium text-gray-900 dark:text-white">{preset.name}</h4>
            <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium ${
              preset.is_builtin
                ? 'bg-gray-100 text-gray-500 dark:bg-gray-700 dark:text-gray-400'
                : 'bg-violet-100 text-violet-600 dark:bg-violet-900/40 dark:text-violet-300'
            }`}>
              {preset.is_builtin ? 'built-in' : 'custom'}
            </span>
            {preset.owner_review_required && (
              <span
                className="text-[10px] px-2 py-0.5 rounded-full font-medium bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300"
                title={preset.review_reason || 'Preset lineage requires owner review'}
              >
                owner review
              </span>
            )}
          </div>
          {preset.description && (
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5 truncate">{preset.description}</p>
          )}
        </div>
        <div className="flex items-center gap-2 shrink-0 ml-3" onClick={(e) => e.stopPropagation()}>
          <span className={`text-[10px] px-1.5 py-0.5 rounded ${
            enabled === total ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300' :
            'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300'
          }`}>
            {enabled}/{total}
          </span>
          <ExportItemButton
            kind="presets"
            itemId={preset.id}
            itemLabel={preset.name}
            onExport={onExport}
            canExport={canExport}
          />
          {onEdit && (
            <button disabled={!canEdit} onClick={onEdit} className="p-1 text-gray-400 hover:text-blue-500 disabled:opacity-40" title="Edit">
              <Pencil size={13} />
            </button>
          )}
          <button disabled={!canClone} onClick={onClone} className="p-1 text-gray-400 hover:text-blue-500 disabled:opacity-40" title="Clone">
            <Copy size={13} />
          </button>
          {onDelete && (
            <button disabled={!canDelete} onClick={onDelete} className="p-1 text-gray-400 hover:text-red-500 disabled:opacity-40" title="Delete">
              <Trash2 size={13} />
            </button>
          )}
        </div>
      </div>
      {/* Entity breakdown */}
      <div className="flex flex-wrap gap-1.5 mt-2.5">
        {Object.entries(perEntity).map(([entity, { total: t, enabled: e }]) => (
          <span key={entity} className={`text-[10px] px-2 py-0.5 rounded ${getEntityChipClasses(entity)}`}>
            {getEntityLabel(entity)} {e}/{t}
          </span>
        ))}
      </div>
      <PresetLineageInfo preset={preset} presets={presets} compact />
    </div>
  );
}

