import { useEffect, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { AlertTriangle, CheckCircle2, CircleSlash, Database, GitBranch, Monitor, RefreshCw, RotateCcw } from 'lucide-react';
import toast from 'react-hot-toast';
import { useDashboardApi } from '@/services/api';
import type {
  ResourceGateEntityType,
  ResourceGateResource,
  ResourceGateResourceType,
  ResourceGateSummary as ResourceGateSummaryType,
} from '@/types';

interface ResourceGateSummaryProps {
  boardId: string;
  entityType: ResourceGateEntityType;
  entityId: string;
  compact?: boolean;
  onChanged?: (summary: ResourceGateSummaryType) => void;
}

const RESOURCE_LABELS: Record<ResourceGateResourceType, string> = {
  architecture: 'Architecture',
  mockup: 'Mockup',
  knowledge_base: 'Knowledge Base',
};

const RESOURCE_ICONS: Record<ResourceGateResourceType, ReactNode> = {
  architecture: <GitBranch size={15} />,
  mockup: <Monitor size={15} />,
  knowledge_base: <Database size={15} />,
};

const STATE_META: Record<ResourceGateResource['state'], { label: string; badge: string; icon: ReactNode }> = {
  provided: {
    label: 'Provided',
    badge: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/35 dark:text-emerald-300',
    icon: <CheckCircle2 size={13} />,
  },
  not_applicable: {
    label: 'N/A',
    badge: 'bg-slate-100 text-slate-700 dark:bg-slate-700 dark:text-slate-200',
    icon: <CircleSlash size={13} />,
  },
  missing: {
    label: 'Missing',
    badge: 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300',
    icon: <AlertTriangle size={13} />,
  },
};

function resourceCounts(resource: ResourceGateResource): string {
  const direct = resource.direct_count || 0;
  const inherited = resource.inherited_count || 0;
  if (!direct && !inherited) return 'No resources linked';
  const parts = [];
  if (direct) parts.push(`${direct} direct`);
  if (inherited) parts.push(`${inherited} inherited`);
  return parts.join(' + ');
}

function naDescription(resource: ResourceGateResource): string | null {
  const mark = resource.na_mark;
  if (!mark) return null;
  if (mark.justification) return mark.justification;
  return 'Marked as not applicable';
}

export function ResourceGateSummary({
  boardId,
  entityType,
  entityId,
  compact = false,
  onChanged,
}: ResourceGateSummaryProps) {
  const api = useDashboardApi();
  const [summary, setSummary] = useState<ResourceGateSummaryType | null>(null);
  const [loading, setLoading] = useState(true);
  const [busyType, setBusyType] = useState<ResourceGateResourceType | null>(null);
  const [drafts, setDrafts] = useState<Record<string, string>>({});

  const load = async () => {
    setLoading(true);
    try {
      const data = await api.getResourceGateSummary(boardId, entityType, entityId);
      setSummary(data);
      onChanged?.(data);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load Resource Gate');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
  }, [boardId, entityType, entityId]);

  const byType = useMemo(() => {
    const map = new Map<ResourceGateResourceType, ResourceGateResource>();
    summary?.resources.forEach((resource) => map.set(resource.resource_type, resource));
    return map;
  }, [summary]);

  const markNotApplicable = async (resourceType: ResourceGateResourceType) => {
    setBusyType(resourceType);
    try {
      const result = await api.markResourceNotApplicable(boardId, entityType, entityId, {
        resource_type: resourceType,
        source_channel: 'ui',
        justification: drafts[resourceType]?.trim() || undefined,
      });
      setSummary(result.summary);
      onChanged?.(result.summary);
      setDrafts((current) => ({ ...current, [resourceType]: '' }));
      toast.success(`${RESOURCE_LABELS[resourceType]} marked N/A`);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to mark N/A');
    } finally {
      setBusyType(null);
    }
  };

  const clearNotApplicable = async (resourceType: ResourceGateResourceType) => {
    setBusyType(resourceType);
    try {
      const result = await api.clearResourceNotApplicable(boardId, entityType, entityId, resourceType, {
        source_channel: 'ui',
        reason: 'Cleared from dashboard Resource Gate summary',
      });
      setSummary(result.summary);
      onChanged?.(result.summary);
      toast.success(`${RESOURCE_LABELS[resourceType]} N/A cleared`);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to clear N/A');
    } finally {
      setBusyType(null);
    }
  };

  if (loading && !summary) {
    return (
      <section className="rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50/80 dark:bg-gray-900/30 p-3">
        <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
          <RefreshCw size={14} className="animate-spin" />
          Loading Resource Gate...
        </div>
      </section>
    );
  }

  const resources: ResourceGateResourceType[] = ['architecture', 'mockup', 'knowledge_base'];

  return (
    <section data-testid="resource-gate-summary" className="rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900/30">
      <div className="flex items-center justify-between gap-3 border-b border-gray-100 dark:border-gray-700 px-3 py-2.5">
        <div>
          <h4 className="text-sm font-semibold text-gray-800 dark:text-gray-100">Resource Gate</h4>
          <p className="text-xs text-gray-500 dark:text-gray-400">
            Architecture and Mockup are blocking; Knowledge Base is advisory
          </p>
        </div>
        <button
          type="button"
          onClick={() => void load()}
          className="p-1.5 rounded-lg text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
          title="Refresh Resource Gate"
        >
          <RefreshCw size={14} className={loading ? 'animate-spin' : ''} />
        </button>
      </div>

      <div className={compact ? 'divide-y divide-gray-100 dark:divide-gray-800' : 'grid gap-2 p-3'}>
        {resources.map((resourceType) => {
          const resource = byType.get(resourceType);
          if (!resource) return null;
          const meta = STATE_META[resource.state];
          const advisory = resource.authority === 'advisory' || resourceType === 'knowledge_base';
          const disabled = busyType === resourceType;
          return (
            <div
              key={resourceType}
              data-testid={`resource-gate-row-${resourceType}`}
              className={`${compact ? 'px-3 py-3' : 'rounded-lg border border-gray-100 dark:border-gray-800 bg-gray-50/70 dark:bg-gray-950/30 p-3'} space-y-2`}
            >
              <div className="flex items-start justify-between gap-3">
                <div className="flex items-start gap-2 min-w-0">
                  <span className="mt-0.5 text-gray-500 dark:text-gray-400">{RESOURCE_ICONS[resourceType]}</span>
                  <div className="min-w-0">
                    <div className="text-sm font-medium text-gray-800 dark:text-gray-100">{RESOURCE_LABELS[resourceType]}</div>
                    <div className="text-xs text-gray-500 dark:text-gray-400">{resourceCounts(resource)}</div>
                  </div>
                </div>
                <div className="flex shrink-0 items-center gap-1">
                  {advisory && (
                    <span className="inline-flex items-center rounded-full bg-violet-100 px-2 py-0.5 text-[10px] font-medium text-violet-700 dark:bg-violet-900/40 dark:text-violet-200">
                      Advisory
                    </span>
                  )}
                  <span className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium ${meta.badge}`}>
                    {meta.icon}
                    {meta.label}
                  </span>
                </div>
              </div>

              {advisory && resource.state === 'missing' && (
                <p className="text-xs text-violet-600 dark:text-violet-300">
                  Optional context only — this absence does not block the transition.
                </p>
              )}

              {resource.state === 'missing' && (
                <div className="flex flex-col gap-2 sm:flex-row">
                  <input
                    value={drafts[resourceType] || ''}
                    onChange={(event) => setDrafts((current) => ({ ...current, [resourceType]: event.target.value }))}
                    placeholder="Optional N/A reason"
                    className="min-w-0 flex-1 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-950 px-2.5 py-1.5 text-xs text-gray-800 dark:text-gray-100 placeholder:text-gray-400"
                  />
                  <button
                    type="button"
                    disabled={disabled}
                    onClick={() => void markNotApplicable(resourceType)}
                    className="inline-flex items-center justify-center gap-1.5 rounded-lg bg-slate-700 px-3 py-1.5 text-xs font-medium text-white hover:bg-slate-600 disabled:opacity-50"
                  >
                    <CircleSlash size={13} />
                    Mark N/A
                  </button>
                </div>
              )}

              {resource.state === 'not_applicable' && (
                <div className="flex items-start justify-between gap-3 rounded-lg bg-slate-100 dark:bg-slate-800/80 px-2.5 py-2">
                  <p className="text-xs text-slate-600 dark:text-slate-300">{naDescription(resource)}</p>
                  <button
                    type="button"
                    disabled={disabled}
                    onClick={() => void clearNotApplicable(resourceType)}
                    className="inline-flex shrink-0 items-center gap-1 text-xs font-medium text-blue-600 hover:text-blue-500 dark:text-blue-400 dark:hover:text-blue-300 disabled:opacity-50"
                  >
                    <RotateCcw size={13} />
                    Clear
                  </button>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </section>
  );
}

/**
 * ContextSelector - Select which parts of a parent entity to carry into a derived entity
 */

import { useState } from 'react';
import { Check, ChevronDown, ChevronUp } from 'lucide-react';
import { MarkdownContent } from './MarkdownContent';
import { useEscapeToClose } from '@/hooks/useEscapeToClose';
import {
  KnowledgePropagationSelector,
} from './KnowledgePropagationSelector';
import type { KnowledgePropagationCandidate } from './knowledgePropagationCandidates';
import {
  EMPTY_KNOWLEDGE_PROPAGATION_CHOICE,
  isKnowledgePropagationChoiceValid,
  type KnowledgePropagationChoice,
} from './knowledgePropagationChoice';

export interface SelectableItem {
  id: string;
  label: string;
  content: string;
  category: string; // e.g. "Problem Statement", "Q&A", "Decision"
}

interface ContextSelectorProps {
  title: string;
  description: string;
  items: SelectableItem[];
  knowledgeItems?: KnowledgePropagationCandidate[];
  knowledgeLoading?: boolean;
  knowledgeError?: string | null;
  onKnowledgeRetry?: () => void;
  knowledgeOnly?: boolean;
  onConfirm: (
    selectedItems: SelectableItem[],
    title: string,
    knowledgeChoice: KnowledgePropagationChoice,
  ) => void | Promise<void>;
  onCancel: () => void;
  targetLabel: string; // e.g. "Refinement", "Spec Draft"
  busy?: boolean;
}

export function ContextSelector({
  title: _title,
  description,
  items,
  knowledgeItems,
  knowledgeLoading = false,
  knowledgeError = null,
  onKnowledgeRetry,
  knowledgeOnly = false,
  onConfirm,
  onCancel,
  targetLabel,
  busy = false,
}: ContextSelectorProps) {
  const [selected, setSelected] = useState<Set<string>>(new Set(items.map((i) => i.id)));
  const [entityTitle, setEntityTitle] = useState('');
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [knowledgeChoice, setKnowledgeChoice] = useState<KnowledgePropagationChoice>(
    EMPTY_KNOWLEDGE_PROPAGATION_CHOICE,
  );

  useEscapeToClose(onCancel, { priority: 10, canClose: !busy });

  const toggle = (id: string) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const selectAll = () => setSelected(new Set(items.map((i) => i.id)));
  const selectNone = () => setSelected(new Set());

  // Group items by category
  const categories = Array.from(new Set(items.map((i) => i.category)));
  const grouped = categories.map((cat) => ({
    category: cat,
    items: items.filter((i) => i.category === cat),
  }));

  const selectedItems = items.filter((i) => selected.has(i.id));
  const titleValid = knowledgeOnly || Boolean(entityTitle.trim());

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-[70] p-4">
      <div
        className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-2xl h-[85vh] flex flex-col"
        role="dialog"
        aria-modal="true"
        aria-labelledby="context-selector-title"
        aria-describedby="context-selector-description"
      >
        {/* Header */}
        <div className="px-6 py-4 border-b border-gray-200 dark:border-gray-700">
          <h2 id="context-selector-title" className="text-lg font-semibold text-gray-900 dark:text-white">
            Create {targetLabel}
          </h2>
          <p id="context-selector-description" className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            {description}
          </p>
        </div>

        {!knowledgeOnly && (
          <>
            {/* Title input */}
            <div className="px-6 py-3 border-b border-gray-100 dark:border-gray-700/50">
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                {targetLabel} Title <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                value={entityTitle}
                onChange={(e) => setEntityTitle(e.target.value)}
                placeholder={`What will this ${targetLabel.toLowerCase()} focus on?`}
                className={`w-full px-3 py-2 border rounded-lg text-sm dark:bg-gray-700 ${
                  !entityTitle.trim()
                    ? 'border-amber-400 dark:border-amber-600 ring-1 ring-amber-200 dark:ring-amber-800'
                    : 'border-gray-300 dark:border-gray-600'
                }`}
                autoFocus
              />
              {!entityTitle.trim() && (
                <p className="text-xs text-amber-600 dark:text-amber-400 mt-1">Title is required to proceed</p>
              )}
            </div>

            {/* Selection controls */}
            <div className="px-6 py-2 border-b border-gray-100 dark:border-gray-700/50 flex items-center justify-between">
              <span className="text-xs text-gray-500 dark:text-gray-400">
                {selected.size} of {items.length} items selected
              </span>
              <div className="flex gap-2">
                <button type="button" onClick={selectAll} disabled={busy} className="text-xs text-blue-600 dark:text-blue-400 hover:underline">Select all</button>
                <button type="button" onClick={selectNone} disabled={busy} className="text-xs text-gray-500 dark:text-gray-400 hover:underline">Clear</button>
              </div>
            </div>
          </>
        )}

        {/* Selectable items */}
        <div className="flex-1 overflow-y-auto px-6 py-3 space-y-4">
          {!knowledgeOnly && grouped.map((group) => (
            <div key={group.category}>
              <h4 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-2">
                {group.category}
              </h4>
              <div className="space-y-1">
                {group.items.map((item) => {
                  const isSelected = selected.has(item.id);
                  const isExpanded = expandedId === item.id;
                  return (
                    <div
                      key={item.id}
                      className={`rounded-lg border transition-colors ${
                        isSelected
                          ? 'border-blue-300 dark:border-blue-600 bg-blue-50/50 dark:bg-blue-900/10'
                          : 'border-gray-200 dark:border-gray-700'
                      }`}
                    >
                      <div className="flex items-center gap-2 px-3 py-2">
                        <button
                          type="button"
                          onClick={() => toggle(item.id)}
                          disabled={busy}
                          aria-label={`${isSelected ? 'Exclude' : 'Include'} ${item.label}`}
                          aria-pressed={isSelected}
                          className={`w-5 h-5 rounded border-2 flex items-center justify-center shrink-0 transition-colors ${
                            isSelected
                              ? 'border-blue-500 bg-blue-500 text-white'
                              : 'border-gray-300 dark:border-gray-600'
                          }`}
                        >
                          {isSelected && <Check size={12} />}
                        </button>
                        <span className="text-sm text-gray-700 dark:text-gray-300 flex-1 truncate">
                          {item.label}
                        </span>
                        <button
                          type="button"
                          onClick={() => setExpandedId(isExpanded ? null : item.id)}
                          disabled={busy}
                          aria-label={`${isExpanded ? 'Collapse' : 'Expand'} ${item.label}`}
                          aria-expanded={isExpanded}
                          className="p-1 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                        >
                          {isExpanded ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
                        </button>
                      </div>
                      {isExpanded && (
                        <div className="px-3 pb-2 ml-7">
                          <div className="text-xs text-gray-500 dark:text-gray-400 bg-gray-50 dark:bg-gray-800 rounded p-2 max-h-32 overflow-y-auto">
                            <MarkdownContent content={item.content} className="text-xs" />
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          ))}

          {knowledgeItems !== undefined && (
            <KnowledgePropagationSelector
              items={knowledgeItems}
              value={knowledgeChoice}
              onChange={setKnowledgeChoice}
              disabled={busy}
              loading={knowledgeLoading}
              error={knowledgeError}
              onRetry={onKnowledgeRetry}
              title="Knowledge propagation"
              description={`Choose the Knowledge resources to carry into this ${targetLabel.toLowerCase()}.`}
              testId="context-knowledge-propagation"
            />
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-gray-200 dark:border-gray-700 flex items-center justify-between">
          <span className="text-xs text-gray-400">
            {!knowledgeOnly && (
              items.length === 0
                ? 'No context items available — will create with title only'
                : selected.size === 0
                  ? 'No context selected — will create with title only'
                  : ''
            )}
          </span>
          <div className="flex gap-2">
            <button type="button" onClick={onCancel} disabled={busy} className="btn btn-secondary">Cancel</button>
            <button
              type="button"
              onClick={() => {
                if (
                  titleValid
                  && isKnowledgePropagationChoiceValid(knowledgeChoice)
                ) {
                  void onConfirm(
                    knowledgeOnly ? [] : selectedItems,
                    knowledgeOnly ? '' : entityTitle.trim(),
                    knowledgeChoice,
                  );
                }
              }}
              disabled={
                busy
                || !titleValid
                || !isKnowledgePropagationChoiceValid(knowledgeChoice)
              }
              className={`btn ${
                titleValid
                && isKnowledgePropagationChoiceValid(knowledgeChoice)
                && !busy
                  ? 'btn-primary'
                  : 'btn-secondary opacity-50 cursor-not-allowed'
              }`}
            >
              {busy
                ? 'Creating…'
                : `Create ${targetLabel}${
                  !knowledgeOnly && selected.size > 0
                    ? ` (${selected.size} items)`
                    : ''
                }`}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

type ContextQAItem = {
  question: string;
  answer: string | null;
  asked_by: string;
  answered_at: string | null;
  choices?: { id: string; label: string }[] | null;
  selected?: string[] | null;
};

function qaContextContent(item: ContextQAItem): string {
  const labelsById = new Map((item.choices || []).map((choice) => [choice.id, choice.label]));
  const selectedLabels = (item.selected || []).map(
    (choiceId) => labelsById.get(choiceId) || choiceId,
  );
  return [
    `**Q:** ${item.question}`,
    selectedLabels.length ? `**Selected:** ${selectedLabels.join(', ')}` : '',
    item.answer ? `**A:** ${item.answer}` : '',
  ].filter(Boolean).join('\n');
}

/**
 * Helper to build selectable items from an ideation
 */
export function buildIdeationItems(ideation: {
  problem_statement?: string | null;
  proposed_approach?: string | null;
  scope_assessment?: { domains: number; ambiguity: number; dependencies: number } | null;
  complexity?: string | null;
  description?: string | null;
  qa_items?: ContextQAItem[];
}): SelectableItem[] {
  const items: SelectableItem[] = [];

  if (ideation.problem_statement) {
    items.push({
      id: 'problem_statement',
      label: 'Problem Statement',
      content: ideation.problem_statement,
      category: 'Context',
    });
  }
  if (ideation.proposed_approach) {
    items.push({
      id: 'proposed_approach',
      label: 'Proposed Approach',
      content: ideation.proposed_approach,
      category: 'Context',
    });
  }
  if (ideation.description) {
    items.push({
      id: 'description',
      label: 'Description',
      content: ideation.description,
      category: 'Context',
    });
  }
  if (ideation.scope_assessment) {
    const sa = ideation.scope_assessment;
    items.push({
      id: 'scope_assessment',
      label: `Scope Assessment (D:${sa.domains} SA:${sa.ambiguity} Dep:${sa.dependencies})`,
      content: `- Domains: ${sa.domains}/5\n- Scope Ambiguity: ${sa.ambiguity}/5\n- Dependencies: ${sa.dependencies}/5\n- Complexity: ${ideation.complexity || 'not evaluated'}`,
      category: 'Context',
    });
  }

  const answered = (ideation.qa_items || []).filter((q) => q.answered_at != null);
  answered.forEach((qa, i) => {
    items.push({
      id: `qa_${i}`,
      label: qa.question.length > 80 ? qa.question.slice(0, 77) + '...' : qa.question,
      content: qaContextContent(qa),
      category: 'Q&A Decisions',
    });
  });

  return items;
}

/**
 * Helper to build selectable items from a refinement
 */
export function buildRefinementItems(refinement: {
  description?: string | null;
  in_scope?: string[] | null;
  out_of_scope?: string[] | null;
  analysis?: string | null;
  decisions?: string[] | null;
  qa_items?: ContextQAItem[];
}): SelectableItem[] {
  const items: SelectableItem[] = [];

  if (refinement.description) {
    items.push({ id: 'description', label: 'Description', content: refinement.description, category: 'Context' });
  }
  (refinement.in_scope || []).forEach((s, i) => {
    items.push({ id: `in_scope_${i}`, label: s.length > 80 ? s.slice(0, 77) + '...' : s, content: s, category: 'In Scope' });
  });
  (refinement.out_of_scope || []).forEach((s, i) => {
    items.push({ id: `out_scope_${i}`, label: s.length > 80 ? s.slice(0, 77) + '...' : s, content: s, category: 'Out of Scope' });
  });
  if (refinement.analysis) {
    items.push({ id: 'analysis', label: 'Analysis', content: refinement.analysis, category: 'Context' });
  }
  (refinement.decisions || []).forEach((d, i) => {
    items.push({ id: `decision_${i}`, label: d.length > 80 ? d.slice(0, 77) + '...' : d, content: d, category: 'Decisions' });
  });

  const answered = (refinement.qa_items || []).filter((q) => q.answered_at != null);
  answered.forEach((qa, i) => {
    items.push({
      id: `qa_${i}`,
      label: qa.question.length > 80 ? qa.question.slice(0, 77) + '...' : qa.question,
      content: qaContextContent(qa),
      category: 'Q&A Decisions',
    });
  });

  return items;
}

/**
 * Compile selected items into a markdown context string
 */
export function compileSelectedContext(items: SelectableItem[]): string {
  const grouped = new Map<string, SelectableItem[]>();
  items.forEach((item) => {
    const list = grouped.get(item.category) || [];
    list.push(item);
    grouped.set(item.category, list);
  });

  const parts: string[] = [];
  grouped.forEach((categoryItems, category) => {
    parts.push(`## ${category}`);
    categoryItems.forEach((item) => {
      parts.push(item.content);
    });
  });

  return parts.join('\n\n');
}

import { GitBranch } from 'lucide-react';

import type {
  IdeationComplexity,
  IdeationStatus,
  RefinementStatus,
} from '@/types';

export const IDEATION_PENDING_REFINEMENT_LABEL = 'No refinement';
export const REFINEMENT_PENDING_SPEC_LABEL = 'No spec';

interface DerivationChild {
  status?: string | null;
  archived?: boolean | null;
  refinement_id?: string | null;
}

interface IdeationDerivationSource {
  status: IdeationStatus;
  complexity?: IdeationComplexity | null;
  active_refinement_count?: number | null;
  active_spec_count?: number | null;
  refinements?: DerivationChild[] | null;
  specs?: DerivationChild[] | null;
}

interface RefinementDerivationSource {
  status: RefinementStatus;
  active_spec_count?: number | null;
  specs?: DerivationChild[] | null;
}

interface DerivationPendingBadgeProps {
  label: string | null | undefined;
  compact?: boolean;
  className?: string;
}

export function isActiveDerivationChild(child: DerivationChild): boolean {
  return !child.archived && child.status !== 'cancelled';
}

export function countActiveDerivations(children: DerivationChild[] | null | undefined): number {
  return (children || []).filter(isActiveDerivationChild).length;
}

function resolveActiveCount(
  summaryCount: number | null | undefined,
  children: DerivationChild[] | null | undefined,
): number {
  return children ? countActiveDerivations(children) : summaryCount ?? 0;
}

function countActiveDirectSpecs(children: DerivationChild[] | null | undefined): number {
  return (children || []).filter(
    (child) => isActiveDerivationChild(child) && child.refinement_id == null,
  ).length;
}

function resolveActiveDirectSpecCount(
  summaryCount: number | null | undefined,
  children: DerivationChild[] | null | undefined,
): number {
  return children ? countActiveDirectSpecs(children) : summaryCount ?? 0;
}

export function getIdeationPendingDerivationLabel(
  ideation: IdeationDerivationSource,
): string | null {
  if (ideation.status !== 'done') {
    return null;
  }
  if (ideation.complexity === 'small') {
    const activeSpecs = resolveActiveDirectSpecCount(ideation.active_spec_count, ideation.specs);
    return activeSpecs === 0 ? REFINEMENT_PENDING_SPEC_LABEL : null;
  }
  if (ideation.complexity !== 'medium' && ideation.complexity !== 'large') {
    return null;
  }
  const activeRefinements = resolveActiveCount(
    ideation.active_refinement_count,
    ideation.refinements,
  );
  return activeRefinements === 0 ? IDEATION_PENDING_REFINEMENT_LABEL : null;
}

export function getRefinementPendingDerivationLabel(
  refinement: RefinementDerivationSource,
): string | null {
  if (refinement.status !== 'done') {
    return null;
  }
  const activeSpecs = resolveActiveCount(refinement.active_spec_count, refinement.specs);
  return activeSpecs === 0 ? REFINEMENT_PENDING_SPEC_LABEL : null;
}

export function DerivationPendingBadge({
  label,
  compact = false,
  className = '',
}: DerivationPendingBadgeProps) {
  if (!label) {
    return null;
  }

  const sizeClasses = compact
    ? 'gap-0.5 px-1.5 py-0.5 text-[10px]'
    : 'gap-1 px-2 py-0.5 text-[10px]';

  return (
    <span
      data-testid="derivation-pending-badge"
      role="status"
      title={label}
      aria-label={label}
      className={`inline-flex items-center shrink-0 rounded-full font-semibold uppercase tracking-wide bg-cyan-100 text-cyan-800 dark:bg-cyan-900/40 dark:text-cyan-200 ${sizeClasses} ${className}`}
    >
      <GitBranch className="h-3 w-3 shrink-0" aria-hidden />
      <span>{label}</span>
    </span>
  );
}

/**
 * MentionInput - Text input with @mention autocomplete dropdown
 */

import { useEffect, useRef, useState } from 'react';

export interface Mentionable {
  id: string;
  name: string;
  type: 'agent' | 'user';
}

interface MentionInputProps {
  value: string;
  onChange: (value: string) => void;
  onSubmit?: () => void;
  placeholder?: string;
  mentionables: Mentionable[];
  className?: string;
  multiline?: boolean;
  rows?: number;
  autoFocus?: boolean;
}

const INPUT_CLASSES =
  'w-full px-3 py-2 border border-gray-300 rounded-lg text-sm bg-white dark:bg-gray-700 dark:border-gray-600 dark:text-gray-100 placeholder:text-gray-400 dark:placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent';

export function MentionInput({
  value,
  onChange,
  onSubmit,
  placeholder,
  mentionables,
  className = '',
  multiline = false,
  rows = 1,
  autoFocus = false,
}: MentionInputProps) {
  const [showDropdown, setShowDropdown] = useState(false);
  const [filter, setFilter] = useState('');
  const [selectedIdx, setSelectedIdx] = useState(0);
  const [cursorPos, setCursorPos] = useState(0);
  const inputRef = useRef<HTMLInputElement | HTMLTextAreaElement>(null);

  const filtered = mentionables.filter((m) =>
    m.name.toLowerCase().includes(filter.toLowerCase())
  );

  useEffect(() => {
    setSelectedIdx(0);
  }, [filter]);

  const getMentionContext = (text: string, pos: number): { start: number; query: string } | null => {
    let i = pos - 1;
    while (i >= 0) {
      if (text[i] === '@') {
        const query = text.slice(i + 1, pos);
        if (query.includes(' ') && query.length > 20) return null;
        return { start: i, query };
      }
      if (text[i] === ' ' && i < pos - 1) {
        if (pos - i > 30) return null;
      }
      if (text[i] === '\n') return null;
      i--;
    }
    return null;
  };

  const handleChange = (newValue: string, newCursorPos: number) => {
    onChange(newValue);
    setCursorPos(newCursorPos);

    const ctx = getMentionContext(newValue, newCursorPos);
    if (ctx) {
      setFilter(ctx.query);
      setShowDropdown(true);
    } else {
      setShowDropdown(false);
    }
  };

  const insertMention = (mentionable: Mentionable) => {
    const ctx = getMentionContext(value, cursorPos);
    if (!ctx) return;

    const before = value.slice(0, ctx.start);
    const after = value.slice(cursorPos);
    const mention = `@${mentionable.name}`;
    const newValue = `${before}${mention} ${after}`;
    onChange(newValue);
    setShowDropdown(false);

    setTimeout(() => {
      const el = inputRef.current;
      if (el) {
        el.focus();
        const newPos = before.length + mention.length + 1;
        el.setSelectionRange(newPos, newPos);
      }
    }, 0);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (showDropdown && filtered.length > 0) {
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setSelectedIdx((prev) => (prev + 1) % filtered.length);
        return;
      }
      if (e.key === 'ArrowUp') {
        e.preventDefault();
        setSelectedIdx((prev) => (prev - 1 + filtered.length) % filtered.length);
        return;
      }
      if (e.key === 'Enter' || e.key === 'Tab') {
        e.preventDefault();
        insertMention(filtered[selectedIdx]);
        return;
      }
      if (e.key === 'Escape') {
        e.preventDefault();
        e.stopPropagation();
        setShowDropdown(false);
        return;
      }
    }
    if (e.key === 'Enter' && !e.shiftKey && !showDropdown && onSubmit) {
      e.preventDefault();
      onSubmit();
    }
  };

  const sharedProps = {
    ref: inputRef as any,
    value,
    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      handleChange(e.target.value, e.target.selectionStart || 0);
    },
    onKeyDown: handleKeyDown,
    onSelect: (e: React.SyntheticEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      setCursorPos((e.target as HTMLInputElement).selectionStart || 0);
    },
    onClick: () => {
      const el = inputRef.current;
      if (el) setCursorPos(el.selectionStart || 0);
    },
    placeholder,
    className: INPUT_CLASSES,
    autoFocus,
  };

  return (
    <div className={`relative ${className}`}>
      {multiline ? (
        <textarea {...sharedProps} rows={rows} />
      ) : (
        <input type="text" {...sharedProps} />
      )}

      {showDropdown && filtered.length > 0 && (
        <div className="absolute left-0 top-full mt-1 w-64 max-h-48 overflow-y-auto bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-lg shadow-lg z-[60]">
          {filtered.map((m, idx) => (
            <button
              key={m.id}
              onMouseDown={(e) => {
                e.preventDefault();
                insertMention(m);
              }}
              className={`flex items-center gap-2 w-full px-3 py-2 text-left text-sm transition-colors ${
                idx === selectedIdx
                  ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300'
                  : 'text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700'
              }`}
            >
              <span className={`w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold shrink-0 ${
                m.type === 'agent'
                  ? 'bg-violet-100 text-violet-700 dark:bg-violet-900/40 dark:text-violet-300'
                  : 'bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300'
              }`}>
                {m.type === 'agent' ? 'A' : 'U'}
              </span>
              <span className="truncate">{m.name}</span>
              <span className="text-[10px] text-gray-400 ml-auto shrink-0">{m.type}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import type { DecisionReviewInput, DecisionReviewProjection, DecisionReviewResult } from '@/types/decision-reviews';
import { AuthenticatedFetchError } from '@/lib/authFetch';

export const decisionStatusLabel = (status: string) => ({
  verified: 'Verified', planning_pending: 'Plan required', obligations_pending: 'Obligation evidence pending',
  inspection_pending: 'Inspection pending', conflict: 'Conflicting observations', passed: 'Passed',
  failed: 'Failed', inconclusive: 'Inconclusive', unavailable: 'Unavailable', revoked: 'Revoked', aborted: 'Aborted',
}[status] || 'Verification pending');

/** A review is a batch: retain every observation instead of guessing one Decision. */
export function DecisionInspectionDetails({ data, recordId }: { data: DecisionReviewProjection; recordId: string }) {
  const records = data.history.filter(record => record.id === recordId);
  if (records.length !== 1) return <p role="alert">The referenced inspection is unavailable in this Spec scope.</p>;
  const record = records[0];
  return <article data-readiness-ref={`inspection:${record.id}`} tabIndex={-1} aria-label="Decision inspection record"
    className="space-y-3 rounded-lg border border-gray-200 p-3 text-sm dark:border-gray-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-sky-500">
    <h3 className="font-semibold">Decision inspection</h3>
    <p className="break-all">{record.id} · Edition {record.edition}{record.edition !== data.edition ? ' · Previous version' : ''}{record.revoked ? ' · Revoked' : ''}</p>
    <p className="break-words">{record.actor_id} · {record.actor_kind} · {new Date(record.created_at).toLocaleString()}</p>
    <p className="text-xs text-gray-500 dark:text-gray-400">Authenticated reviewer observation. This historical record does not establish current verification by itself.</p>
    {record.observations.map(observation => <details key={observation.decision_id} className="rounded-lg border border-gray-200 dark:border-gray-700">
      <summary className="cursor-pointer break-words px-3 py-2 font-medium">{observation.decision_id} · {decisionStatusLabel(observation.result)}</summary>
      <dl className="space-y-2 border-t border-gray-200 p-3 dark:border-gray-700">
        <div><dt className="font-medium">Expected</dt><dd className="whitespace-pre-wrap break-words">{observation.expected}</dd></div>
        <div><dt className="font-medium">Observed</dt><dd className="whitespace-pre-wrap break-words">{observation.observed}</dd></div>
        <div><dt className="font-medium">Scope fingerprint</dt><dd className="break-all font-mono text-xs">{observation.expected_scope_sha256}</dd></div>
        <div><dt className="font-medium">Sources</dt><dd>{observation.sources.map(source => <p key={source.reference} className="break-all">{source.reference} · {source.revision} · {source.sha256}</p>)}</dd></div>
        {observation.reconciles.length > 0 && <div><dt className="font-medium">Reconciles</dt><dd className="break-all">{observation.reconciles.join(', ')}</dd></div>}
        {observation.separation.warning && <p className="text-amber-700 dark:text-amber-400">Reviewer separation warning was recorded.</p>}
      </dl>
    </details>)}
  </article>;
}

interface DecisionReviewSectionProps {
  data: DecisionReviewProjection; decisionId: string; canReview: boolean;
  onSubmit: (body: DecisionReviewInput) => Promise<void>;
  readCurrent?: boolean;
  onDraftChange?: (decisionId: string, active: boolean) => void;
}

export function DecisionReviewSection(props: DecisionReviewSectionProps) {
  const denied = props.data.decisions.find(d => d.decision_id === props.decisionId)?.separation?.allowed === false;
  return <DecisionReviewEditor key={JSON.stringify([props.data.board_id, props.data.spec_id, props.decisionId, props.canReview, denied])} {...props} />;
}

function DecisionReviewEditor({ data, decisionId, canReview, onSubmit, readCurrent = true, onDraftChange }: DecisionReviewSectionProps) {
  const [observed, setObserved] = useState('');
  const [result, setResult] = useState<DecisionReviewResult>('inconclusive');
  const [reconcile, setReconcile] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [uncertain, setUncertain] = useState(false);
  const [base, setBase] = useState<{ edition: number; version: number; review: string; decision: DecisionReviewProjection['decisions'][number] } | null>(null);
  const retry = useRef<{ payload: string; body: DecisionReviewInput }>();
  const mounted = useRef(true);
  const inFlight = useRef(false);
  useEffect(() => { mounted.current = true; return () => { mounted.current = false; }; }, []);
  const current = data.decisions.find(d => d.decision_id === decisionId);
  const displayed = current?.basis ? current : base?.decision;
  useEffect(() => { onDraftChange?.(decisionId, base !== null); }, [onDraftChange, decisionId, base]);
  const snapshot = current ? { edition: data.edition, version: data.version, review: data.review_revision, decision: current } : null;
  const changed = Boolean(base && JSON.stringify(base) !== JSON.stringify(snapshot));
  const ready = readCurrent && data.complete && Boolean(current?.basis && current.separation?.allowed);
  const begin = () => { if (!base && snapshot && ready) setBase(snapshot); };
  const history = data.history.filter(r => r.observations.some(o => o.decision_id === decisionId));
  const prior = history.filter(r => r.edition !== data.edition);
  const currentHistory = history.filter(r => r.edition === data.edition);
  const submit = async () => {
    if (!canReview || inFlight.current || (!uncertain && (!ready || changed || !observed.trim()))) return;
    const original = base ?? snapshot;
    if (!uncertain) {
      if (!original?.decision.basis) return;
      const request = { expected_edition: original.edition, expected_version: original.version, expected_review_revision: original.review,
        entries: [{ decision_id: decisionId, expected_scope_sha256: original.decision.basis.scope_sha256, observed: observed.trim(), result,
          sources: original.decision.basis.sources, reconciles: reconcile ? original.decision.record_ids : [] }] };
      const payload = JSON.stringify(request);
      if (retry.current?.payload !== payload) retry.current = { payload, body: { ...request, idempotency_key: crypto.randomUUID() } };
    }
    if (!retry.current) return;
    inFlight.current = true;
    setSaving(true); setError('');
    try {
      await onSubmit(retry.current.body);
      if (!mounted.current) return;
      setObserved(''); setReconcile(false); setBase(null); setUncertain(false); retry.current = undefined;
    } catch (e) {
      if (!mounted.current) return;
      const definite = e instanceof AuthenticatedFetchError && [400, 401, 403, 404, 409, 413, 422].includes(e.status);
      if (uncertain || !definite) {
        setUncertain(true); setError('The observation outcome is unknown. Retry the original observation before editing or starting another one.');
      } else setError(e instanceof Error ? e.message : 'Observation could not be recorded. Refresh the current scope and retry.');
    } finally { inFlight.current = false; if (mounted.current) setSaving(false); }
  };
  const renderHistory = (rows: typeof history) => rows.map(record => {
    const observation = record.observations.find(o => o.decision_id === decisionId)!;
    return <details key={record.id} className="rounded-lg border border-gray-200 dark:border-gray-700">
      <summary className="cursor-pointer px-3 py-2 text-sm">{record.revoked ? 'Revoked' : decisionStatusLabel(observation.result)} · {record.actor_id} · {new Date(record.created_at).toLocaleString()}</summary>
      <dl className="space-y-2 border-t border-gray-200 p-3 text-sm dark:border-gray-700">
        <div><dt className="font-medium">Expected</dt><dd className="whitespace-pre-wrap">{observation.expected}</dd></div>
        <div><dt className="font-medium">Observed</dt><dd className="whitespace-pre-wrap">{observation.observed}</dd></div>
        <div><dt className="font-medium">Sources</dt><dd>{observation.sources.map(s => <p key={s.reference} className="break-all">{s.reference} · {s.revision} · {s.sha256.slice(0, 12)}</p>)}</dd></div>
        {observation.reconciles.length > 0 && <div><dt className="font-medium">Reconciles</dt><dd className="break-all">{observation.reconciles.join(', ')}</dd></div>}
        {observation.separation.warning && <p className="text-amber-700 dark:text-amber-400">Reviewer separation warning was recorded.</p>}
      </dl>
    </details>;
  });
  return <section className="space-y-3 border-t border-gray-200 pt-3 dark:border-gray-700" aria-label="Decision verification">
    <h4 className="text-sm font-semibold">{readCurrent ? decisionStatusLabel(current?.status || 'planning_pending') : 'Current verification unavailable'}</h4>
    {!readCurrent && <p role="status" className="text-sm">Current inspection data is unavailable. Your draft is preserved and recording is disabled.</p>}
    {changed && <div className="space-y-2 rounded-lg border border-amber-300 p-3 text-sm dark:border-amber-700">
      <p>Your observation belongs to an earlier inspection base. Review the current condition and sources before recording it.</p>
      <p className="whitespace-pre-wrap">Original condition: {base?.decision.basis?.expected}</p>
      <button type="button" className="btn btn-secondary text-xs" disabled={!ready || saving || uncertain} onClick={() => {
        setBase(snapshot); setReconcile(false); retry.current = undefined; setError('');
      }}>Review inspection base</button>
    </div>}
    {displayed?.basis && <>
      {!current?.basis && <p role="status">This inspection basis is no longer available. The preserved draft cannot be recorded.</p>}
      <p className="text-sm">{displayed.basis.expected}</p>
      <details className="rounded-lg border border-gray-200 dark:border-gray-700"><summary className="cursor-pointer px-3 py-2 text-sm">Observed scope</summary>
        <div className="space-y-1 p-3 text-xs">{displayed.basis.sources.map(s => <p key={s.reference} className="break-all">{s.reference} · {s.revision} · {s.sha256.slice(0, 12)}</p>)}</div>
      </details>
      {canReview && displayed.separation?.allowed && <details className="rounded-lg border border-gray-200 dark:border-gray-700">
        <summary className="cursor-pointer px-3 py-2 text-sm font-medium">Record inspection</summary>
        <div className="space-y-3 border-t border-gray-200 p-3 dark:border-gray-700">
          <p className="text-xs text-gray-500">Record what you inspected against this scope. Your authenticated observation is preserved; Pulse does not execute the inspection.</p>
          {readCurrent && current?.separation?.warning && <p role="status" className="text-sm text-amber-700 dark:text-amber-400">The Board permits this review with a separation warning.</p>}
          <label className="block text-sm">Observed result<textarea disabled={!ready || saving || uncertain} aria-label="Observed result" rows={3} maxLength={2000} value={observed} onChange={e => { begin(); setObserved(e.target.value); }} className="mt-1 w-full rounded-lg border p-2 dark:border-gray-600 dark:bg-gray-800" /></label>
          <label className="block text-sm">Conclusion<select disabled={!ready || saving || uncertain} aria-label="Inspection conclusion" value={result} onChange={e => { begin(); setResult(e.target.value as DecisionReviewResult); }} className="ml-2 rounded-lg border p-2 dark:border-gray-600 dark:bg-gray-800">
            {(['inconclusive', 'passed', 'failed', 'unavailable', 'aborted'] as const).map(v => <option key={v} value={v}>{decisionStatusLabel(v)}</option>)}
          </select></label>
          {!!displayed.record_ids.length && <label className="flex items-center gap-2 text-sm"><input disabled={!ready || saving || uncertain || changed} type="checkbox" checked={reconcile} onChange={e => { begin(); setReconcile(e.target.checked); }} />Reconcile all current observations with this conclusion</label>}
          {error && <p role="alert" className="text-sm text-red-600">{error}</p>}
          <button type="button" className="btn btn-primary text-sm" disabled={saving || uncertain || changed || !ready || !observed.trim()} onClick={() => void submit()}>{saving ? 'Recording…' : 'Record observation'}</button>
          {uncertain && <button type="button" className="btn btn-secondary text-sm" disabled={saving} onClick={() => void submit()}>Retry original observation</button>}
          {base && !uncertain && <button type="button" className="btn btn-secondary text-sm" disabled={saving} onClick={() => {
            setObserved(''); setResult('inconclusive'); setReconcile(false); setBase(null); setError(''); retry.current = undefined;
          }}>Discard inspection draft</button>}
        </div>
      </details>}
      {canReview && current?.separation && !current.separation.allowed && <p className="text-sm text-amber-700 dark:text-amber-400">An independent reviewer with known authorship is required by the Board.</p>}
    </>}
    {readCurrent && currentHistory.length > 0 && <details><summary className="cursor-pointer text-sm">Observations in this edition ({currentHistory.length})</summary><div className="mt-2 space-y-2">{renderHistory(currentHistory)}</div></details>}
    {readCurrent && prior.length > 0 && <details><summary className="cursor-pointer text-sm">Previous versions</summary><div className="mt-2 space-y-2">{renderHistory(prior)}</div></details>}
  </section>;
}

import type { Spec } from '@/types';
import type { DecisionVerification } from '@/types/decision-reviews';

export function decisionObligationOptions(spec: Spec) {
  const groups = [
    ['fr', 'Functional', spec.functional_requirements], ['br', 'Business', spec.business_rules],
    ['tr', 'Technical', spec.technical_requirements], ['ir', 'Integration', spec.integration_requirements],
    ['or', 'Observability', spec.observability_requirements], ['ac', 'Acceptance', spec.acceptance_criteria],
    ['api', 'Contract', spec.api_contracts],
  ] as const;
  return groups.flatMap(([prefix, label, values]) => (values || []).filter(v =>
    !['superseded', 'revoked', 'deprecated', 'cancelled'].includes(('status' in v && v.status) || 'active'))
    .map(v => ({ ref: `${prefix}:${v.id}`, label: `${label} · ${('title' in v && v.title) || ('text' in v && v.text) || ('description' in v && v.description) || v.id}` })));
}

export function DecisionVerificationEditor({ spec, value, onChange }: {
  spec: Spec; value: DecisionVerification | null; onChange: (value: DecisionVerification | null) => void;
}) {
  const options = decisionObligationOptions(spec);
  const inspection = value?.inspection;
  const refs = value?.obligation_refs || [];
  const update = (next: DecisionVerification) => onChange(next.obligation_refs.length || next.inspection ? next : null);
  return <fieldset className="space-y-3 rounded-lg border border-gray-200 p-3 dark:border-gray-700">
    <legend className="px-1 text-sm font-semibold">How will this decision be verified?</legend>
    <p className="text-xs text-gray-500">Reuse relevant obligation evidence, inspect an observable condition, or require both.</p>
    <label className="block space-y-1 text-sm">Obligations that demonstrate this choice
      <select multiple aria-label="Verification obligations" value={refs}
        onChange={e => update({ ...value, obligation_refs: Array.from(e.target.selectedOptions, o => o.value) })}
        className="w-full rounded-lg border border-gray-300 bg-white p-2 text-sm dark:border-gray-600 dark:bg-gray-800">
        {options.map(o => <option key={o.ref} value={o.ref}>{o.label}</option>)}
      </select>
    </label>
    <label className="flex items-center gap-2 text-sm">
      <input type="checkbox" checked={!!inspection} onChange={e => update({ obligation_refs: refs,
        inspection: e.target.checked ? { condition: '', scope_refs: [{ kind: 'spec', id: spec.id }] } : null })} />
      Inspect an observable condition
    </label>
    {inspection && <>
      <label className="block space-y-1 text-sm">Expected condition
        <textarea aria-label="Expected condition" value={inspection.condition} maxLength={2000} rows={3}
          onChange={e => update({ obligation_refs: refs, inspection: { ...inspection, condition: e.target.value } })}
          className="w-full rounded-lg border border-gray-300 p-2 text-sm dark:border-gray-600 dark:bg-gray-800" />
      </label>
      <label className="block space-y-1 text-sm">Scope to inspect
        <select multiple aria-label="Inspection scope" value={inspection.scope_refs.map(r => r.kind === 'spec' ? '__spec' : r.id)}
          onChange={e => update({ obligation_refs: refs, inspection: { ...inspection, scope_refs:
            Array.from(e.target.selectedOptions, o => o.value === '__spec' ? { kind: 'spec' as const, id: spec.id } : { kind: 'obligation' as const, id: o.value }) } })}
          className="w-full rounded-lg border border-gray-300 bg-white p-2 text-sm dark:border-gray-600 dark:bg-gray-800">
          <option value="__spec">Entire specification and delivery</option>
          {options.map(o => <option key={o.ref} value={o.ref}>{o.label}</option>)}
        </select>
      </label>
    </>}
    <p className="text-xs text-gray-500">{refs.length && inspection ? 'Both paths must be satisfied.' : !refs.length && !inspection ? 'Planning pending. Select a path before validation.' : 'Task links remain contextual; no extra task or test is required for the decision.'}</p>
  </fieldset>;
}

/**
 * DecisionsTab — structured management for Decisions on a spec.
 *
 * Ideação #10 Fase 3: paridade end-to-end com TR/BR/Contract.
 * Mirrors RulesTab pattern — form to add/edit, expandable rows with badge
 * colored by status (active/superseded/revoked), link-to-task picker,
 * explicit verification planning and current, attributable inspections.
 */

import { useCallback, useEffect, useMemo, useState } from 'react';
import {
  CheckCircle, ChevronDown, ChevronUp, GitBranch, Pencil, Plus, Trash2, XCircle,
} from 'lucide-react';
import type { Decision, DecisionStatus, Spec } from '@/types';
import { CognitivePendingBadge } from '@/components/knowledge/CognitivePendingBadge';
import { useCognitivePendingBadges } from '@/hooks/useCognitivePendingBadges';
import { DecisionImpactPanel } from './DecisionImpactPanel';
import { useDashboardApi } from '@/services/api';
import { PulseLoader } from '@/components/shared/PulseLoader';
import type { DecisionReviewProjection, DecisionVerification } from '@/types/decision-reviews';
import { DecisionVerificationEditor, decisionObligationOptions } from './DecisionVerificationEditor';
import { DecisionInspectionDetails, DecisionReviewSection, decisionStatusLabel } from './DecisionReviewSection';
import { useSpecCollectionEditor } from './useSpecCollectionEditor';
import { SpecCollectionDraftNotice } from './SpecCollectionDraftNotice';
import { AuthenticatedFetchError } from '@/lib/authFetch';

interface DecisionsTabProps {
  spec: Spec;
  onUpdate: (decisions: Decision[], expectedVersion: number) => void | Promise<void>;
  readCurrent?: boolean;
  onSpecUpdate?: (patch: Record<string, any>) => void;
  specCards?: Array<{ id: string; title: string }>;
  onLinkTask?: (decisionId: string, cardId: string) => void | Promise<void>;
  onUnlinkTask?: (decisionId: string, cardId: string) => void | Promise<void>;
  canCreate?: boolean;
  canEdit?: boolean;
  canDelete?: boolean;
  canLinkTask?: boolean;
  canReview?: boolean;
  focusEditId?: string | null;
  focusInspectionId?: string | null;
  focusCreateToken?: number | null;
  onFocusHandled?: () => void;
}

const STATUS_COLORS: Record<DecisionStatus, string> = {
  active: 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300 ring-1 ring-green-400',
  superseded: 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300',
  revoked: 'bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400',
};

export function DecisionsTab(props: DecisionsTabProps) {
  return <DecisionsTabEditor key={`${props.spec.board_id}:${props.spec.id}:${props.canCreate}:${props.canEdit}`} {...props} />;
}

function DecisionsTabEditor({
  spec,
  onUpdate,
  readCurrent = true,
  specCards = [],
  onLinkTask,
  onUnlinkTask,
  canCreate = true,
  canEdit = true,
  canDelete = true,
  canLinkTask = true,
  canReview = false,
  focusEditId = null,
  focusInspectionId = null,
  focusCreateToken = null,
  onFocusHandled,
}: DecisionsTabProps) {
  const editor = useSpecCollectionEditor(spec, readCurrent);
  const begin = editor.begin;
  const api = useDashboardApi();
  const [reviewData, setReviewData] = useState<DecisionReviewProjection | null>(null);
  const [reviewError, setReviewError] = useState('');
  const [reviewRefresh, setReviewRefresh] = useState(0);
  const [reviewReadKey, setReviewReadKey] = useState('');
  const [retainedInspections, setRetainedInspections] = useState<Map<string, Decision>>(new Map());
  const [formVerification, setFormVerification] = useState<DecisionVerification | null>(null);
  const [adding, setAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [linkPickerId, setLinkPickerId] = useState<string | null>(null);
  const [impactId, setImpactId] = useState<string | null>(null);

  const [formTitle, setFormTitle] = useState('');
  const [formRationale, setFormRationale] = useState('');
  const [formContext, setFormContext] = useState('');
  const [formAlternatives, setFormAlternatives] = useState('');
  const [formSupersedesId, setFormSupersedesId] = useState('');
  const [formLinkedFRs, setFormLinkedFRs] = useState<string[]>([]);
  const [formNotes, setFormNotes] = useState('');

  const decisions = spec.decisions || [];
  const inspectionReadKey = JSON.stringify([spec.board_id, spec.id, spec.version, spec.edition, reviewRefresh, readCurrent, canReview, focusInspectionId]);
  const reviewCurrent = readCurrent && reviewReadKey === inspectionReadKey && !reviewError;
  const shouldReadReviews = Boolean(readCurrent && spec.board_id && (decisions.length || focusInspectionId || retainedInspections.size));
  const displayDecisions = [...decisions, ...[...retainedInspections.values()].filter(row => !decisions.some(current => current.id === row.id))];
  const onInspectionDraft = useCallback((id: string, active: boolean) => {
    setRetainedInspections(previous => {
      const row = spec.decisions?.find(decision => decision.id === id) ?? previous.get(id);
      if (active ? !row || previous.get(id) === row : !previous.has(id)) return previous;
      const next = new Map(previous);
      if (active && row) next.set(id, row); else next.delete(id);
      return next;
    });
  }, [spec.decisions]);
  useEffect(() => {
    const controller = new AbortController();
    setReviewReadKey(''); setReviewError('');
    if (shouldReadReviews && spec.board_id) {
      api.getDecisionReviews(spec.board_id, spec.id, controller.signal).then(value => {
        if (value.board_id !== spec.board_id || value.spec_id !== spec.id || value.version !== spec.version || value.edition !== spec.edition)
          throw new Error('Decision inspection scope changed. Refresh the Spec.');
        if (!controller.signal.aborted) { setReviewData(value); setReviewReadKey(inspectionReadKey); }
      }).catch(e => {
        if (controller.signal.aborted) return;
        if (e instanceof AuthenticatedFetchError && [401, 403, 404].includes(e.status)) {
          setReviewData(null); setRetainedInspections(new Map());
          setReviewError('Decision inspection access is unavailable.');
        } else setReviewError('Decision verification could not be loaded. Refresh to retry; your draft is preserved.');
      });
    }
    return () => controller.abort();
  }, [api, spec.board_id, spec.id, spec.version, spec.edition, spec.decisions, inspectionReadKey, shouldReadReviews]);
  const frs = spec.functional_requirements || [];
  // Canonical source_ref shape per board_source_store.py + cognitive_badge_resolver.py
  // is `decision:<spec_id>:<decision_id>` — keep the UI in lockstep so badges
  // resolve against real rebuild/marker entries (KG-03A.6 val_ff050455).
  const decisionSourceRefs = useMemo(
    () => decisions.map((d) => `decision:${spec.id}:${d.id}`),
    [decisions, spec.id],
  );
  const { badges: decisionBadges } = useCognitivePendingBadges(
    spec.board_id ?? null,
    decisionSourceRefs,
  );

  const resetForm = () => {
    setFormTitle('');
    setFormRationale('');
    setFormContext('');
    setFormAlternatives('');
    setFormSupersedesId('');
    setFormLinkedFRs([]);
    setFormNotes('');
    setFormVerification(null);
  };

  const parseAlternatives = (raw: string): string[] | null => {
    const trimmed = raw.trim();
    if (!trimmed) return null;
    return trimmed.split(/\n|;|\|/).map((x) => x.trim()).filter(Boolean);
  };

  const handleAdd = async () => {
    if (!formTitle.trim() || !formRationale.trim()) return;
    const id = `dec_${Date.now()}`;
    const newDecision: Decision = {
      id,
      title: formTitle.trim(),
      rationale: formRationale.trim(),
      context: formContext.trim() || null,
      alternatives_considered: parseAlternatives(formAlternatives),
      supersedes_decision_id: formSupersedesId || null,
      linked_requirements: formLinkedFRs.length > 0 ? formLinkedFRs : null,
      linked_task_ids: null,
      status: 'active',
      notes: formNotes.trim() || null,
      verification: formVerification,
    };
    // Auto-superseding: if new.supersedes references an existing active decision,
    // flip that one's status to 'superseded' to keep the chain coherent.
    let next = [...decisions, newDecision];
    if (formSupersedesId) {
      next = next.map((d) =>
        d.id === formSupersedesId && d.status === 'active' ? { ...d, status: 'superseded' as DecisionStatus } : d
      );
    }
    if (missing.length || !canCreate || !await editor.save(version => onUpdate(next, version))) return;
    setAdding(false);
    resetForm();
  };

  const handleEdit = (d: Decision) => {
    if (!canEdit || !editor.begin()) return;
    setEditingId(d.id);
    setFormTitle(d.title);
    setFormRationale(d.rationale);
    setFormContext(d.context || '');
    setFormAlternatives((d.alternatives_considered || []).join('\n'));
    setFormSupersedesId(d.supersedes_decision_id || '');
    setFormLinkedFRs(d.linked_requirements || []);
    setFormNotes(d.notes || '');
    setFormVerification(d.verification || null);
  };

  useEffect(() => {
    if (!focusEditId || !canEdit) return;
    if (editingId || adding) return;
    const target = decisions.find((decision) => decision.id === focusEditId);
    if (!target) return;
    handleEdit(target);
    setExpandedId(null);
    onFocusHandled?.();
  }, [focusEditId, canEdit, spec.decisions, onFocusHandled, editingId, adding]);

  useEffect(() => {
    if (!focusCreateToken || !canCreate) return;
    if (editingId || adding) return;
    if (!begin()) return;
    resetForm();
    setAdding(true);
    setEditingId(null);
    onFocusHandled?.();
  }, [focusCreateToken, canCreate, onFocusHandled, editingId, adding, begin]);

  const handleSaveEdit = async () => {
    if (!editingId || !formTitle.trim() || !formRationale.trim()) return;
    if (removed || missing.length || !canEdit || !await editor.save(version => onUpdate(decisions.map((d) =>
      d.id === editingId
        ? {
            ...d,
            title: formTitle.trim(),
            rationale: formRationale.trim(),
            context: formContext.trim() || null,
            alternatives_considered: parseAlternatives(formAlternatives),
            supersedes_decision_id: formSupersedesId || null,
            linked_requirements: formLinkedFRs.length > 0 ? formLinkedFRs : null,
            notes: formNotes.trim() || null,
            verification: formVerification,
          }
        : d
    ), version))) return;
    setEditingId(null);
    resetForm();
  };

  const handleRevoke = async (id: string) => {
    if (!confirm('Revoke this decision? Soft-delete — it stays in the history with status=revoked.')) return;
    if (canDelete) await editor.save(version => onUpdate(decisions.map((d) => (d.id === id ? { ...d, status: 'revoked' as DecisionStatus } : d)), version), true);
  };

  const toggleFR = (key: string) => {
    setFormLinkedFRs((prev) => (prev.includes(key) ? prev.filter((x) => x !== key) : [...prev, key]));
  };

  const availableSupersedesTargets = useMemo(
    () => decisions.filter((d) => d.id !== editingId && d.status !== 'revoked'),
    [decisions, editingId]
  );

  const isFormValid = formTitle.trim() && formRationale.trim() && (!formVerification?.inspection ||
    (formVerification.inspection.condition.trim() && formVerification.inspection.scope_refs.length > 0));
  const removed = !!editingId && !decisions.some(item => item.id === editingId);
  const currentDecision = decisions.find(item => item.id === editingId);
  const missing = [
    ...formLinkedFRs.filter(id => !frs.some(fr => fr.id === id && (fr.status || 'active') === 'active')),
    ...(formSupersedesId && !availableSupersedesTargets.some(item => item.id === formSupersedesId) ? [formSupersedesId] : []),
    ...(formVerification?.obligation_refs || []).filter(ref => !decisionObligationOptions(spec).some(option => option.ref === ref)),
    ...(formVerification?.inspection?.scope_refs || []).filter(ref => ref.kind === 'spec' ? ref.id !== spec.id : !decisionObligationOptions(spec).some(option => option.ref === ref.id)).map(ref => ref.id),
  ];

  const activeDecisions = decisions.filter((d) => d.status === 'active');
  const activeTotal = activeDecisions.length;
  const verified = reviewData?.decisions.filter(d => d.status === 'verified').length ?? 0;
  const coveragePct = activeTotal === 0 ? 0 : Math.round((verified / activeTotal) * 100);

  const renderForm = (onSubmit: () => void, submitLabel: string, onCancel: () => void) => (
    <fieldset disabled={editor.saving} className="border border-indigo-200 dark:border-indigo-700 rounded-lg p-3 space-y-2 bg-indigo-50/50 dark:bg-indigo-900/10">
      <input
        type="text"
        value={formTitle}
        onChange={(e) => setFormTitle(e.target.value)}
        placeholder="Decision title — e.g. 'Use embedded graph storage over an external graph database'"
        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
        autoFocus
      />
      <textarea
        value={formRationale}
        onChange={(e) => setFormRationale(e.target.value)}
        placeholder="Rationale — why this choice was made"
        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600 resize-none"
        rows={2}
      />
      <textarea
        value={formContext}
        onChange={(e) => setFormContext(e.target.value)}
        placeholder="Context (optional) — when/where the decision applies"
        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600 resize-none"
        rows={1}
      />
      <textarea
        value={formAlternatives}
        onChange={(e) => setFormAlternatives(e.target.value)}
        placeholder="Alternatives considered (one per line, or separated by ; or |)"
        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600 resize-none"
        rows={2}
      />
      {availableSupersedesTargets.length > 0 && (
        <select
          value={formSupersedesId}
          onChange={(e) => setFormSupersedesId(e.target.value)}
          className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
        >
          <option value="">(Optional) Supersedes… — pick an existing decision</option>
          {availableSupersedesTargets.map((d) => (
            <option key={d.id} value={d.id}>
              {d.title}
            </option>
          ))}
        </select>
      )}
      <textarea
        value={formNotes}
        onChange={(e) => setFormNotes(e.target.value)}
        placeholder="Notes (optional)"
        className="w-full px-2 py-1.5 border border-gray-300 rounded-lg text-xs dark:bg-gray-700 dark:border-gray-600 resize-none"
        rows={1}
      />
      {frs.length > 0 && (
        <div>
          <span className="text-[10px] text-gray-500 dark:text-gray-400 block mb-1">
            Link to functional requirements:
          </span>
          <div className="flex flex-wrap gap-1">
            {frs.map((fr, i) => {
              const key = fr.id;
              const isLinked = formLinkedFRs.includes(key);
              return (
                <button
                  key={i}
                  onClick={() => toggleFR(key)}
                  className={`text-[10px] px-1.5 py-0.5 rounded transition-colors ${
                    isLinked
                      ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300 ring-1 ring-indigo-400'
                      : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 hover:bg-gray-200'
                  }`}
                >
                  FR{i}: {fr.text.length > 50 ? fr.text.slice(0, 47) + '...' : fr.text}
                </button>
              );
            })}
          </div>
        </div>
      )}
      <DecisionVerificationEditor spec={spec} value={formVerification} onChange={setFormVerification} />
      <div className="flex justify-end gap-2">
        <button onClick={() => { editor.cancel(); onCancel(); }} className="btn btn-secondary text-xs">Cancel</button>
        <button onClick={onSubmit} disabled={!isFormValid || editor.blocked || removed || missing.length > 0} className="btn btn-primary text-xs">
          {submitLabel}
        </button>
      </div>
    </fieldset>
  );

  return (
    <div className="space-y-4">
      <SpecCollectionDraftNotice editor={editor} active={adding || !!editingId} removed={removed} missing={missing}
        currentText={currentDecision && [currentDecision.title, currentDecision.rationale, currentDecision.context, currentDecision.notes].filter(Boolean).join('\n')}
        onRemoveMissing={() => {
          setFormLinkedFRs(formLinkedFRs.filter(id => !missing.includes(id)));
          if (missing.includes(formSupersedesId)) setFormSupersedesId('');
          if (formVerification) setFormVerification({ ...formVerification,
            obligation_refs: formVerification.obligation_refs.filter(ref => !missing.includes(ref)),
            inspection: formVerification.inspection && { ...formVerification.inspection, scope_refs: formVerification.inspection.scope_refs.filter(ref => !missing.includes(ref.id)) },
          });
        }} />
      {removed && renderForm(handleSaveEdit, 'Save', () => { setEditingId(null); resetForm(); })}
      {/* Legacy banner — decisions inline em Description ficam visíveis, mas esta aba é canônica */}


      {/* Coverage summary — active-only */}
      {activeTotal > 0 && (
        <div className="border border-gray-200 dark:border-gray-700 rounded-lg p-3">
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">
              Decision adherence ({reviewCurrent && reviewData?.complete ? verified : '—'}/{activeTotal})
            </h4>
            <span
              className={`text-[10px] px-1.5 py-0.5 rounded font-medium ${
                reviewCurrent && reviewData?.complete && coveragePct === 100
                  ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300'
                  : 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300'
              }`}
            >
              {reviewCurrent && reviewData?.complete ? `${coveragePct}% verified` : 'Incomplete / unavailable'}
            </span>
          </div>
          {reviewCurrent && reviewData?.complete && <div role="progressbar" aria-label="Decision adherence" aria-valuemin={0} aria-valuemax={100} aria-valuenow={coveragePct} className="h-2 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
            <div
              className={`h-full transition-all duration-500 rounded-full ${
                coveragePct === 100 ? 'bg-green-500' : 'bg-amber-500'
              }`}
              style={{ width: `${coveragePct}%` }}
            />
          </div>}
        </div>
      )}

      {(activeTotal > 0 || focusInspectionId || retainedInspections.size > 0) && !reviewCurrent && !reviewError && <PulseLoader label="Loading decision verification…" size="sm" />}
      {reviewError && <p role="alert" className="text-sm text-red-600">{reviewError}</p>}
      {(activeTotal > 0 || retainedInspections.size > 0) && <button type="button" className="btn btn-secondary text-xs" onClick={() => setReviewRefresh(v => v + 1)}>Refresh verification</button>}

      {/* Empty state */}
      {displayDecisions.length === 0 && !adding && (
        <div className="text-center py-6">
          <GitBranch size={32} className="mx-auto text-gray-300 dark:text-gray-600 mb-2" />
          <p className="text-sm text-gray-500 dark:text-gray-400">No decisions recorded</p>
          <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">
            Decisions capture the <em>why</em> behind design choices, with alternatives and supersedence
          </p>
        </div>
      )}

      {reviewCurrent && focusInspectionId && reviewData?.board_id === spec.board_id && reviewData?.spec_id === spec.id
        && <DecisionInspectionDetails data={reviewData} recordId={focusInspectionId} />}

      {/* Decisions list */}
      {displayDecisions.map((d) => {
        const inspectionRemoved = !decisions.some(current => current.id === d.id);
        const isExpanded = expandedId === d.id;
        const isEditing = editingId === d.id;

        if (isEditing) {
          return (
            <div key={d.id}>
              {renderForm(handleSaveEdit, 'Save', () => { setEditingId(null); resetForm(); })}
            </div>
          );
        }

        const linkedTasksCount = d.linked_task_ids?.length ?? 0;
        const isActive = d.status === 'active';

        return (
          <div key={d.id} data-readiness-ref={`decision:${d.id}`} tabIndex={-1} className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden focus-visible:outline focus-visible:outline-2 focus-visible:outline-sky-500">
            <div
              className="flex items-center gap-2 px-3 py-2 cursor-pointer bg-gray-50 dark:bg-gray-700/50"
              onClick={() => setExpandedId(isExpanded ? null : d.id)}
              data-readiness-expand
              role="button" tabIndex={0} aria-expanded={isExpanded}
              onKeyDown={e => { if (e.target === e.currentTarget && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); setExpandedId(isExpanded ? null : d.id); } }}
            >
              <GitBranch size={14} className="text-indigo-500 shrink-0" />
              <span className="text-sm font-medium text-gray-900 dark:text-white truncate flex-1">
                {d.title}
              </span>
              <span className={`text-[10px] px-1.5 py-0.5 rounded ${STATUS_COLORS[d.status]}`}>
                {d.status}
              </span>
              <CognitivePendingBadge
                badge={decisionBadges[`decision:${spec.id}:${d.id}`]}
                compact
              />
              {isActive && <span className="rounded bg-indigo-50 px-2 py-0.5 text-xs text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-300">{reviewCurrent && !inspectionRemoved ? decisionStatusLabel(reviewData?.decisions.find(row => row.decision_id === d.id)?.status || 'planning_pending') : 'Current verification unavailable'}</span>}

              {(d.linked_requirements?.length ?? 0) > 0 && (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300">
                  {d.linked_requirements!.length} FR
                </span>
              )}
              {linkedTasksCount > 0 && <span className="rounded bg-gray-100 px-2 py-0.5 text-xs text-gray-600 dark:bg-gray-700 dark:text-gray-300">{linkedTasksCount} contextual task links</span>}
              <button
                onClick={(e) => { e.stopPropagation(); handleEdit(d); }}
                disabled={inspectionRemoved || !canEdit || editor.saving || !readCurrent}
                className={`p-0.5 ${canEdit ? 'text-gray-400 hover:text-blue-500' : 'text-gray-300 cursor-not-allowed'}`}
                title={canEdit ? 'Edit' : 'Requires spec.structured_entity.decision.update'}
              >
                <Pencil size={12} />
              </button>
              {d.status !== 'revoked' && (
                <button
                  onClick={(e) => { e.stopPropagation(); handleRevoke(d.id); }}
                  disabled={inspectionRemoved || !canDelete || editor.saving || !readCurrent || adding || !!editingId}
                  className={`p-0.5 ${canDelete ? 'text-gray-400 hover:text-red-500' : 'text-gray-300 cursor-not-allowed'}`}
                  title={canDelete ? 'Revoke (soft-delete)' : 'Requires spec.structured_entity.decision.revoke'}
                >
                  <Trash2 size={12} />
                </button>
              )}
              {isExpanded ? (
                <ChevronUp size={14} className="text-gray-400" />
              ) : (
                <ChevronDown size={14} className="text-gray-400" />
              )}
            </div>

            {isExpanded && (
              <div className="px-3 py-2 space-y-2 text-sm">
                {inspectionRemoved && <p role="status">This Decision was removed. Its inspection draft is preserved; discard it when finished reviewing.</p>}
                <div className="space-y-1">
                  <h4 className="font-medium">Verification plan</h4>
                  {!d.verification && <p className="text-amber-700 dark:text-amber-400">Select verification obligations or an inspection condition before validation.</p>}
                  {!!d.verification?.obligation_refs.length && <ul className="list-inside list-disc">{d.verification.obligation_refs.map(ref => <li key={ref}>{decisionObligationOptions(spec).find(o => o.ref === ref)?.label || ref}</li>)}</ul>}
                  {d.verification?.inspection && <p>{d.verification.inspection.condition}</p>}
                  {!!d.verification?.obligation_refs.length && d.verification.inspection && <p className="text-xs text-gray-500">Obligation evidence and inspection are both required.</p>}
                </div>
                {reviewData && <DecisionReviewSection key={`${spec.id}:${d.id}`} data={reviewData} decisionId={d.id}
                  readCurrent={Boolean(reviewCurrent && !inspectionRemoved)} onDraftChange={onInspectionDraft}
                  canReview={canReview && isActive && !['done', 'cancelled'].includes(spec.status)} onSubmit={async body => {
                    await api.recordDecisionReviews(spec.board_id!, spec.id, body);
                    setReviewRefresh(v => v + 1);
                  }} />}
                <div>
                  <span className="text-[10px] font-semibold text-gray-500 uppercase">Rationale</span>
                  <p className="text-xs text-gray-600 dark:text-gray-400 mt-0.5">{d.rationale}</p>
                </div>
                {d.context && (
                  <div>
                    <span className="text-[10px] font-semibold text-gray-500 uppercase">Context</span>
                    <p className="text-xs text-gray-600 dark:text-gray-400 mt-0.5">{d.context}</p>
                  </div>
                )}
                {d.alternatives_considered && d.alternatives_considered.length > 0 && (
                  <div>
                    <span className="text-[10px] font-semibold text-gray-500 uppercase">Alternatives</span>
                    <ul className="text-xs text-gray-600 dark:text-gray-400 mt-0.5 list-disc list-inside">
                      {d.alternatives_considered.map((alt, i) => (
                        <li key={i}>{alt}</li>
                      ))}
                    </ul>
                  </div>
                )}
                {d.supersedes_decision_id && (
                  <div className="flex items-center gap-1 text-xs text-amber-600 dark:text-amber-400">
                    <GitBranch size={12} />
                    Supersedes: <code className="text-[10px]">{d.supersedes_decision_id}</code>
                  </div>
                )}
                {d.linked_requirements && d.linked_requirements.length > 0 && (
                  <div className="flex flex-wrap gap-1">
                    <span className="text-[10px] text-gray-400 mr-1">Linked FRs:</span>
                    {d.linked_requirements.map((idx, i) => {
                      const txt = frs.find((fr) => fr.id === idx)?.text;
                      return (
                        <span
                          key={i}
                          className="text-[10px] px-1.5 py-0.5 rounded bg-indigo-50 text-indigo-700 dark:bg-indigo-900/20 dark:text-indigo-300"
                        >
                          {idx}{txt ? `: ${txt.length > 40 ? txt.slice(0, 37) + '...' : txt}` : ''}
                        </span>
                      );
                    })}
                  </div>
                )}
                {d.linked_task_ids && d.linked_task_ids.length > 0 && (
                  <div className="flex flex-wrap gap-1 items-center">
                    <span className="text-[10px] text-gray-400 mr-1">Linked tasks:</span>
                    {d.linked_task_ids.map((tid, i) => (
                      <span
                        key={i}
                        className="text-[10px] px-1.5 py-0.5 rounded bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-300 inline-flex items-center gap-0.5"
                      >
                        {tid.slice(0, 8)}…
                        {!inspectionRemoved && canLinkTask && onUnlinkTask && (
                          <button
                            onClick={() => onUnlinkTask(d.id, tid)}
                            disabled={!readCurrent}
                            className="ml-0.5 text-green-600 hover:text-red-500"
                            title="Unlink"
                          >
                            <XCircle size={10} />
                          </button>
                        )}
                      </span>
                    ))}
                  </div>
                )}
                {d.notes && (
                  <p className="text-xs text-gray-500 dark:text-gray-400 italic border-l-2 border-gray-300 dark:border-gray-600 pl-2">
                    {d.notes}
                  </p>
                )}

                {/* Task picker */}
                {!inspectionRemoved && spec.board_id && <div className="pt-2 border-t dark:border-gray-700">
                  <button type="button" className="btn btn-secondary text-xs" onClick={() => setImpactId(impactId === d.id ? null : d.id)}>
                    {impactId === d.id ? 'Hide impact' : 'Show impact'}
                  </button>
                  {impactId === d.id && <DecisionImpactPanel key={`${spec.board_id}:${spec.id}:${d.id}`}
                    boardId={spec.board_id} specId={spec.id} decisionId={d.id} revision={JSON.stringify(spec)}
                    onOpenDecision={id => { setExpandedId(id); setImpactId(id); }} />}
                </div>}
                {!inspectionRemoved && canLinkTask && onLinkTask && d.status !== 'revoked' && specCards.length > 0 && (
                  <div className="pt-1">
                    {linkPickerId === d.id ? (
                      <div className="space-y-1">
                        <span className="text-[10px] text-gray-500 block">Pick a card to link:</span>
                        <div className="flex flex-wrap gap-1 max-h-32 overflow-y-auto">
                          {specCards
                            .filter((c) => !(d.linked_task_ids || []).includes(c.id))
                            .map((c) => (
                              <button
                                key={c.id}
                                disabled={!readCurrent}
                                onClick={async () => {
                                  await onLinkTask(d.id, c.id);
                                  setLinkPickerId(null);
                                }}
                                className="text-[10px] px-1.5 py-0.5 rounded bg-gray-100 text-gray-700 dark:bg-gray-700 dark:text-gray-300 hover:bg-indigo-100 dark:hover:bg-indigo-900/40"
                              >
                                {c.title.length > 30 ? c.title.slice(0, 27) + '...' : c.title}
                              </button>
                            ))}
                        </div>
                        <button
                          onClick={() => setLinkPickerId(null)}
                          className="text-[10px] text-gray-500 hover:text-gray-700"
                        >
                          Cancel
                        </button>
                      </div>
                    ) : (
                      <button
                        onClick={() => setLinkPickerId(d.id)}
                        disabled={!readCurrent}
                        className="flex items-center gap-1 text-[10px] text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300"
                      >
                        <CheckCircle size={10} /> Link task…
                      </button>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>
        );
      })}

      {/* Add form */}
      {adding ? (
        renderForm(handleAdd, 'Add Decision', () => { setAdding(false); resetForm(); })
      ) : (
        !editingId && (
          <button
            onClick={() => { if (editor.begin()) setAdding(true); }}
            disabled={!canCreate || editor.saving || !readCurrent}
            title={canCreate ? 'Add Decision' : 'Requires spec.structured_entity.decision.create'}
            className={`flex items-center gap-1 text-sm ${canCreate ? 'text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300' : 'text-gray-300 cursor-not-allowed'}`}
          >
            <Plus size={14} /> Add Decision
          </button>
        )
      )}
    </div>
  );
}

import { useSpecCollectionEditor } from './useSpecCollectionEditor';
import { SpecCollectionDraftNotice } from './SpecCollectionDraftNotice';
import { useEffect, useMemo, useState } from 'react';
import { CheckCircle, ChevronDown, ChevronUp, Link, Network, Pencil, Plus, Trash2, Unlink, XCircle } from 'lucide-react';
import type { ApiContract, CardSummaryForSpec, IntegrationRequirement, IntegrationRequirementType, Spec } from '@/types';

interface IntegrationRequirementsTabProps {
  spec: Spec;
  onUpdate: (requirements: IntegrationRequirement[], expectedVersion: number) => void | Promise<void>;
  readCurrent?: boolean;
  onSpecUpdate?: (patch: Record<string, unknown>) => Promise<void>;
  specCards?: CardSummaryForSpec[];
  onLinkTask?: (requirementId: string, cardId: string) => Promise<void>;
  onUnlinkTask?: (requirementId: string, cardId: string) => Promise<void>;
  canCreate?: boolean;
  canEdit?: boolean;
  canDelete?: boolean;
  canLinkTask?: boolean;
  canEditCoverageFlags?: boolean;
  focusEditId?: string | null;
  focusCreateToken?: number | null;
  onFocusHandled?: () => void;
}

const TYPES: IntegrationRequirementType[] = ['api', 'queue', 'stored_procedure', 'data_contract', 'event', 'file', 'other'];

const TYPE_LABELS: Record<IntegrationRequirementType, string> = {
  api: 'API',
  queue: 'Queue',
  stored_procedure: 'SP',
  data_contract: 'Data',
  event: 'Event',
  file: 'File',
  other: 'Other',
};

function parseJSON(value: string): Record<string, unknown> | null {
  if (!value.trim()) return null;
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed as Record<string, unknown> : null;
  } catch {
    return null;
  }
}

function LinkTaskPicker({
  requirementId,
  linkedIds,
  cards,
  onLink,
}: {
  requirementId: string;
  linkedIds: string[];
  cards: CardSummaryForSpec[];
  onLink: (requirementId: string, cardId: string) => Promise<void>;
}) {
  const [open, setOpen] = useState(false);
  const available = cards.filter((card) => !linkedIds.includes(card.id));
  if (available.length === 0) return null;
  return (
    <div className="mt-1">
      <button onClick={() => setOpen(!open)} className="text-[10px] text-blue-500 hover:text-blue-600 dark:text-blue-400">
        {open ? 'Cancel' : '+ Link task'}
      </button>
      {open && (
        <div className="mt-1 border border-gray-200 dark:border-gray-700 rounded p-1.5 max-h-32 overflow-y-auto space-y-0.5">
          {available.map((card) => (
            <button
              key={card.id}
              onClick={async () => { await onLink(requirementId, card.id); setOpen(false); }}
              className="w-full text-left px-2 py-1 rounded text-[11px] text-gray-600 dark:text-gray-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 truncate flex items-center gap-1"
            >
              <Link size={9} className="shrink-0 text-gray-400" />
              {card.title}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

export function IntegrationRequirementsTab(props: IntegrationRequirementsTabProps) {
  return <IntegrationRequirementsTabEditor key={`${props.spec.board_id}:${props.spec.id}:${props.canCreate}:${props.canEdit}`} {...props} />;
}

function IntegrationRequirementsTabEditor({
  spec,
  onUpdate,
  readCurrent = true,
  onSpecUpdate,
  specCards = [],
  onLinkTask,
  onUnlinkTask,
  canCreate = true,
  canEdit = true,
  canDelete = true,
  canLinkTask = true,
  canEditCoverageFlags = true,
  focusEditId = null,
  focusCreateToken = null,
  onFocusHandled,
}: IntegrationRequirementsTabProps) {
  const editor = useSpecCollectionEditor(spec, readCurrent);
  const begin = editor.begin;
  const [adding, setAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [formTitle, setFormTitle] = useState('');
  const [formType, setFormType] = useState<IntegrationRequirementType>('api');
  const [formDescription, setFormDescription] = useState('');
  const [formProvider, setFormProvider] = useState('');
  const [formConsumer, setFormConsumer] = useState('');
  const [formContractRef, setFormContractRef] = useState('');
  const [formEndpoint, setFormEndpoint] = useState('');
  const [formMethod, setFormMethod] = useState('');
  const [formDataContract, setFormDataContract] = useState('');
  const [formLinkedFRs, setFormLinkedFRs] = useState<string[]>([]);
  const [formLinkedContracts, setFormLinkedContracts] = useState<string[]>([]);
  const [formNotes, setFormNotes] = useState('');

  const requirements = (spec.integration_requirements || []).filter((item) => item.status === 'active');
  const activeRequirements = requirements.filter((item) => item.status === 'active');
  const frs = spec.functional_requirements || [];
  const contracts = spec.api_contracts || [];

  const coverage = useMemo(() => {
    const linked = activeRequirements.filter((item) => (item.linked_task_ids?.length ?? 0) > 0).length;
    return {
      linked,
      total: activeRequirements.length,
      pct: activeRequirements.length > 0 ? Math.round((linked / activeRequirements.length) * 100) : 0,
    };
  }, [activeRequirements]);

  const resetForm = () => {
    setFormTitle('');
    setFormType('api');
    setFormDescription('');
    setFormProvider('');
    setFormConsumer('');
    setFormContractRef('');
    setFormEndpoint('');
    setFormMethod('');
    setFormDataContract('');
    setFormLinkedFRs([]);
    setFormLinkedContracts([]);
    setFormNotes('');
  };

  const buildRequirement = (id: string, current?: IntegrationRequirement): IntegrationRequirement => ({
    ...current,
    id,
    title: formTitle.trim(),
    integration_type: formType,
    description: formDescription.trim(),
    provider: formProvider.trim() || null,
    consumer: formConsumer.trim() || null,
    contract_ref: formContractRef.trim() || null,
    endpoint: formEndpoint.trim() || null,
    method: formMethod.trim() || null,
    data_contract: parseJSON(formDataContract),
    linked_requirements: formLinkedFRs.length > 0 ? formLinkedFRs : null,
    linked_api_contracts: formLinkedContracts.length > 0 ? formLinkedContracts : null,
    linked_task_ids: current?.linked_task_ids || null,
    status: current?.status || 'active',
    notes: formNotes.trim() || null,
  });

  const handleAdd = async () => {
    if (!formTitle.trim() || !formDescription.trim()) return;
    if (missing.length || !canCreate || !await editor.save(version => onUpdate([...requirements, buildRequirement(`ir_${Date.now()}`)], version))) return;
    setAdding(false);
    resetForm();
  };

  const handleEdit = (item: IntegrationRequirement) => {
    if (!canEdit || !editor.begin()) return;
    setEditingId(item.id);
    setFormTitle(item.title);
    setFormType(item.integration_type || 'api');
    setFormDescription(item.description || '');
    setFormProvider(item.provider || '');
    setFormConsumer(item.consumer || '');
    setFormContractRef(item.contract_ref || '');
    setFormEndpoint(item.endpoint || '');
    setFormMethod(item.method || '');
    setFormDataContract(item.data_contract ? JSON.stringify(item.data_contract, null, 2) : '');
    setFormLinkedFRs(item.linked_requirements || []);
    setFormLinkedContracts(item.linked_api_contracts || []);
    setFormNotes(item.notes || '');
  };

  useEffect(() => {
    if (!focusEditId || !canEdit || editingId || adding) return;
    const target = requirements.find((item) => item.id === focusEditId);
    if (!target) return;
    handleEdit(target);
    setExpandedId(null);
    onFocusHandled?.();
  }, [focusEditId, canEdit, spec.integration_requirements, onFocusHandled, editingId, adding]);

  useEffect(() => {
    if (!focusCreateToken || !canCreate || editingId || adding) return;
    if (!begin()) return;
    resetForm();
    setAdding(true);
    setEditingId(null);
    onFocusHandled?.();
  }, [focusCreateToken, canCreate, onFocusHandled, editingId, adding, begin]);

  const handleSaveEdit = async () => {
    if (!editingId || !formTitle.trim() || !formDescription.trim()) return;
    if (removed || missing.length || !canEdit || !await editor.save(version => onUpdate(requirements.map((item) => item.id === editingId ? buildRequirement(editingId, item) : item), version))) return;
    setEditingId(null);
    resetForm();
  };

  const handleRemove = async (id: string) => {
    if (!confirm('Remove this integration requirement?')) return;
    if (canDelete) await editor.save(version => onUpdate(requirements.filter((item) => item.id !== id), version), true);
  };

  const toggleFR = (frIndex: string) => {
    setFormLinkedFRs((current) => current.includes(frIndex) ? current.filter((item) => item !== frIndex) : [...current, frIndex]);
  };

  const toggleContract = (contractId: string) => {
    setFormLinkedContracts((current) => current.includes(contractId) ? current.filter((item) => item !== contractId) : [...current, contractId]);
  };

  const currentRequirement = requirements.find(item => item.id === editingId);
  const removed = !!editingId && !requirements.some(item => item.id === editingId);
  const missing = [
    ...formLinkedFRs.filter(id => !frs.some(fr => fr.id === id && (fr.status || 'active') === 'active')),
    ...formLinkedContracts.filter(id => !contracts.some(item => item.id === id && (item.status || 'active') === 'active')),
  ];

  const isFormValid = Boolean(formTitle.trim() && formDescription.trim());

  const renderForm = (onSubmit: () => void, submitLabel: string, onCancel: () => void) => (
    <fieldset disabled={editor.saving} className="border border-sky-200 dark:border-sky-700 rounded-lg p-3 space-y-2 bg-sky-50/50 dark:bg-sky-900/10">
      <div className="grid grid-cols-[150px_minmax(0,1fr)] gap-2">
        <select value={formType} onChange={(event) => setFormType(event.target.value as IntegrationRequirementType)} className="px-2 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600">
          {TYPES.map((type) => <option key={type} value={type}>{TYPE_LABELS[type]}</option>)}
        </select>
        <input value={formTitle} onChange={(event) => setFormTitle(event.target.value)} placeholder="Integration requirement title" className="px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" autoFocus />
      </div>
      <textarea value={formDescription} onChange={(event) => setFormDescription(event.target.value)} placeholder="Contract, queue, API, stored procedure, event, or file integration expectation" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600 resize-none" rows={2} />
      <div className="grid grid-cols-2 gap-2">
        <input value={formProvider} onChange={(event) => setFormProvider(event.target.value)} placeholder="Provider" className="px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" />
        <input value={formConsumer} onChange={(event) => setFormConsumer(event.target.value)} placeholder="Consumer" className="px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" />
        <input value={formEndpoint} onChange={(event) => setFormEndpoint(event.target.value)} placeholder="Endpoint, topic, procedure, or file" className="px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" />
        <input value={formMethod} onChange={(event) => setFormMethod(event.target.value)} placeholder="Method/action" className="px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" />
      </div>
      <input value={formContractRef} onChange={(event) => setFormContractRef(event.target.value)} placeholder="Contract reference" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" />
      <textarea value={formDataContract} onChange={(event) => setFormDataContract(event.target.value)} placeholder='Data contract JSON, e.g. {"event":"metric.created"}' className="w-full px-2 py-1.5 border border-gray-300 rounded-lg text-xs font-mono dark:bg-gray-700 dark:border-gray-600 resize-none" rows={3} />
      <textarea value={formNotes} onChange={(event) => setFormNotes(event.target.value)} placeholder="Notes (optional)" className="w-full px-2 py-1.5 border border-gray-300 rounded-lg text-xs dark:bg-gray-700 dark:border-gray-600 resize-none" rows={1} />

      {frs.length > 0 && (
        <div>
          <span className="text-[10px] text-gray-500 dark:text-gray-400 block mb-1">Link to functional requirements:</span>
          <div className="flex flex-wrap gap-1">
            {frs.map((fr, index) => {
              const key = fr.id;
              const linked = formLinkedFRs.includes(key);
              return (
                <button key={key} onClick={() => toggleFR(key)} className={`text-[10px] px-1.5 py-0.5 rounded transition-colors ${linked ? 'bg-sky-100 text-sky-700 dark:bg-sky-900/40 dark:text-sky-300 ring-1 ring-sky-400' : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 hover:bg-gray-200'}`}>
                  FR{index}: {fr.text.length > 42 ? fr.text.slice(0, 39) + '...' : fr.text}
                </button>
              );
            })}
          </div>
        </div>
      )}

      {contracts.length > 0 && (
        <div>
          <span className="text-[10px] text-gray-500 dark:text-gray-400 block mb-1">Link to API contracts:</span>
          <div className="flex flex-wrap gap-1">
            {contracts.map((contract: ApiContract) => {
              const linked = formLinkedContracts.includes(contract.id);
              return (
                <button key={contract.id} onClick={() => toggleContract(contract.id)} className={`text-[10px] px-1.5 py-0.5 rounded transition-colors ${linked ? 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/40 dark:text-cyan-300 ring-1 ring-cyan-400' : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 hover:bg-gray-200'}`}>
                  {contract.method} {contract.path}
                </button>
              );
            })}
          </div>
        </div>
      )}

      <div className="flex justify-end gap-2">
        <button onClick={() => { editor.cancel(); onCancel(); }} className="btn btn-secondary text-xs">Cancel</button>
        <button onClick={onSubmit} disabled={!isFormValid || editor.blocked || removed || missing.length > 0} className="btn btn-primary text-xs">{submitLabel}</button>
      </div>
    </fieldset>
  );

  return (
    <div className="space-y-4">
      <SpecCollectionDraftNotice editor={editor} active={adding || !!editingId} removed={removed} missing={missing}
        currentText={currentRequirement && [currentRequirement.title, currentRequirement.description, currentRequirement.notes].filter(Boolean).join('\n')}
        onRemoveMissing={() => { setFormLinkedFRs(formLinkedFRs.filter(id => !missing.includes(id))); setFormLinkedContracts(formLinkedContracts.filter(id => !missing.includes(id))); }} />
      {removed && renderForm(handleSaveEdit, 'Save', () => { setEditingId(null); resetForm(); })}
      {activeRequirements.length > 0 && (
        <div className="border border-gray-200 dark:border-gray-700 rounded-lg p-3">
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">IR Task Coverage ({coverage.linked}/{coverage.total})</h4>
            <span className={`text-[10px] px-1.5 py-0.5 rounded font-medium ${coverage.linked === coverage.total ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300' : 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300'}`}>
              {coverage.pct}% linked
            </span>
          </div>
          <div className="h-2 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
            <div className={`h-full transition-all duration-500 rounded-full ${coverage.linked === coverage.total ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: `${coverage.pct}%` }} />
          </div>
        </div>
      )}

      {onSpecUpdate && canEditCoverageFlags && (
        <div className="flex items-center justify-between px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-700/20">
          <div>
            <span className="text-xs font-medium text-gray-700 dark:text-gray-300">Skip IR coverage requirement</span>
            <p className="text-[10px] text-gray-400">Allow validation without full IR-to-task coverage</p>
          </div>
          <button onClick={() => onSpecUpdate({ skip_ir_coverage: !spec.skip_ir_coverage })} className={`relative w-10 h-5 rounded-full transition-colors ${spec.skip_ir_coverage ? 'bg-amber-500' : 'bg-gray-300 dark:bg-gray-600'}`}>
            <span className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white transition-transform ${spec.skip_ir_coverage ? 'translate-x-5' : ''}`} />
          </button>
        </div>
      )}

      {requirements.length === 0 && !adding && (
        <div className="text-center py-6">
          <Network size={32} className="mx-auto text-gray-300 dark:text-gray-600 mb-2" />
          <p className="text-sm text-gray-500 dark:text-gray-400">No integration requirements defined</p>
        </div>
      )}

      {requirements.map((item) => {
        const expanded = expandedId === item.id;
        const editing = editingId === item.id;
        const taskCount = item.linked_task_ids?.length ?? 0;
        if (editing) {
          return <div key={item.id}>{renderForm(handleSaveEdit, 'Save', () => { setEditingId(null); resetForm(); })}</div>;
        }
        return (
          <div key={item.id} data-readiness-ref={`ir:${item.id}`} tabIndex={-1} className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden focus-visible:outline focus-visible:outline-2 focus-visible:outline-sky-500">
            <div data-readiness-expand aria-expanded={expanded} className="flex items-center gap-2 px-3 py-2 cursor-pointer bg-gray-50 dark:bg-gray-700/50" onClick={() => setExpandedId(expanded ? null : item.id)}>
              {taskCount > 0 ? <CheckCircle size={14} className="text-green-500 shrink-0" /> : <XCircle size={14} className="text-gray-300 dark:text-gray-600 shrink-0" />}
              <span className="text-[10px] px-1.5 py-0.5 rounded bg-sky-100 text-sky-700 dark:bg-sky-900/40 dark:text-sky-300 font-medium">{TYPE_LABELS[item.integration_type]}</span>
              <span className="text-sm font-medium text-gray-900 dark:text-white truncate flex-1">{item.title}</span>
              <span className={`text-[10px] px-1.5 py-0.5 rounded ${taskCount > 0 ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300' : 'bg-gray-100 text-gray-400 dark:bg-gray-700 dark:text-gray-500'}`}>{taskCount} tasks</span>
              {canEdit && (
                <button disabled={editor.saving || !readCurrent || adding} title="Edit" onClick={(event) => { event.stopPropagation(); handleEdit(item); }} className="p-0.5 text-gray-400 hover:text-blue-500"><Pencil size={12} /></button>
              )}
              {canDelete && (
                <button disabled={editor.saving || !readCurrent || adding || !!editingId} title="Remove" onClick={(event) => { event.stopPropagation(); handleRemove(item.id); }} className="p-0.5 text-gray-400 hover:text-red-500"><Trash2 size={12} /></button>
              )}
              {expanded ? <ChevronUp size={14} className="text-gray-400" /> : <ChevronDown size={14} className="text-gray-400" />}
            </div>
            {expanded && (
              <div className="px-3 py-2 space-y-2 text-sm">
                <p className="text-xs text-gray-600 dark:text-gray-400">{item.description}</p>
                <div className="grid grid-cols-2 gap-2 text-xs text-gray-500 dark:text-gray-400">
                  {item.provider && <span>Provider: {item.provider}</span>}
                  {item.consumer && <span>Consumer: {item.consumer}</span>}
                  {item.endpoint && <span className="font-mono">Endpoint: {item.endpoint}</span>}
                  {item.method && <span>Method: {item.method}</span>}
                </div>
                {item.linked_api_contracts && item.linked_api_contracts.length > 0 && (
                  <div className="flex flex-wrap gap-1">
                    <span className="text-[10px] text-gray-400 mr-1">Contracts:</span>
                    {item.linked_api_contracts.map((id) => <span key={id} className="text-[10px] px-1.5 py-0.5 rounded bg-cyan-50 text-cyan-700 dark:bg-cyan-900/20 dark:text-cyan-300">{id}</span>)}
                  </div>
                )}
                {item.notes && <p className="text-xs text-gray-500 dark:text-gray-400 italic border-l-2 border-gray-300 dark:border-gray-600 pl-2">{item.notes}</p>}
                {item.linked_task_ids && item.linked_task_ids.length > 0 && (
                  <div className="flex flex-wrap gap-1">
                    <span className="text-[10px] text-gray-400 mr-1">Linked Tasks:</span>
                    {item.linked_task_ids.map((taskId) => (
                      canLinkTask && onUnlinkTask ? (
                        <button key={taskId} onClick={() => onUnlinkTask(item.id, taskId)} className="text-[10px] px-1.5 py-0.5 rounded bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-300 inline-flex items-center gap-1">
                          {taskId.slice(0, 8)} <Unlink size={9} />
                        </button>
                      ) : (
                        <span key={taskId} className="text-[10px] px-1.5 py-0.5 rounded bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-300">
                          {taskId.slice(0, 8)}
                        </span>
                      )
                    ))}
                  </div>
                )}
                {canLinkTask && onLinkTask && <LinkTaskPicker requirementId={item.id} linkedIds={item.linked_task_ids || []} cards={specCards} onLink={onLinkTask} />}
              </div>
            )}
          </div>
        );
      })}

      {adding ? (
        renderForm(handleAdd, 'Add IR', () => { setAdding(false); resetForm(); })
      ) : canCreate ? (
        <button onClick={() => { if (editor.begin()) setAdding(true); }} disabled={editor.saving || !readCurrent} className="w-full py-2 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg text-sm text-gray-500 hover:border-sky-400 hover:text-sky-500 transition-colors flex items-center justify-center gap-1">
          <Plus size={14} />
          Add Integration Requirement
        </button>
      ) : null}
    </div>
  );
}

import { loadEffectiveResourceItems } from '@/services/effectiveResources';
/**
 * MockupsTab — Renders screen mockups as HTML iframes with Tailwind CDN.
 * Supports viewing existing mockups and creating new ones via HTML editor.
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Monitor, Smartphone, MessageSquare, Plus, X, Eye, Code } from 'lucide-react';
import { useDashboardApi } from '@/services/api';
import type { KnowledgeWorkspaceItem, ResourceGateEntityType, ScreenMockup } from '@/types';

function sanitizeHtml(html: string): string {
  // Strip <script> tags and on* event handlers
  let clean = html.replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '');
  clean = clean.replace(/\s+on\w+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, '');
  return clean;
}

function buildSrcDoc(html: string): string {
  return `<!DOCTYPE html><html><head><script src="https://cdn.tailwindcss.com"><\/script></head><body class="p-4 bg-white">${sanitizeHtml(html)}</body></html>`;
}

const SCREEN_TYPES = [
  { value: 'page', label: 'Page' },
  { value: 'modal', label: 'Modal' },
  { value: 'drawer', label: 'Drawer' },
  { value: 'popover', label: 'Popover' },
  { value: 'panel', label: 'Panel' },
] as const;

interface MockupsTabProps {
  screenMockups: ScreenMockup[] | null;
  expanded?: boolean;
  onUpdate?: (mockups: ScreenMockup[], base?: { expectedVersion?: number; expectedSnapshot?: string }) => Promise<void | { version: number }>;
  version?: number;
  snapshot?: string;
  revision?: string | number;
  active?: boolean;
  readCurrent?: boolean;
  onReload?: (minimumVersion?: number) => Promise<void>;
  boardId?: string | null;
  entityType?: ResourceGateEntityType;
  entityId?: string | null;
}

type EffectiveScreenMockup = ScreenMockup & {
  inherited?: boolean;
  read_only?: boolean;
  source_entity_type?: string | null;
  source_entity_id?: string | null;
  source_entity_title?: string | null;
};

function effectiveMockupToScreen(item: KnowledgeWorkspaceItem): EffectiveScreenMockup | null {
  const resource = item.body && typeof item.body === 'object'
    ? item.body as Partial<ScreenMockup>
    : {} as Partial<ScreenMockup>;
  const id = String(item.representative_resource_id || resource.id || '');
  if (!id || !resource.html_content) return null;
  return {
    id,
    title: String(resource.title || item.title || 'Inherited mockup'),
    description: typeof resource.description === 'string' ? resource.description : null,
    screen_type: resource.screen_type || 'page',
    html_content: String(resource.html_content),
    annotations: resource.annotations ?? null,
    order: typeof resource.order === 'number' ? resource.order : 9999,
    origin_id: resource.origin_id ?? null,
    origin_story_id: resource.origin_story_id ?? null,
    origin_entity_type: resource.origin_entity_type ?? null,
    design_system_ref: resource.design_system_ref ?? null,
    design_system_evidence: resource.design_system_evidence ?? null,
    inherited: item.inherited,
    read_only: item.inherited,
    source_entity_type: item.provenance.source_entity_type ?? null,
    source_entity_id: item.provenance.source_entity_id ?? null,
    source_entity_title: item.provenance.source_entity_title ?? null,
  };
}

function sourceLabel(screen: EffectiveScreenMockup): string {
  const type = screen.source_entity_type || 'source';
  const title = screen.source_entity_title || screen.source_entity_id || 'parent';
  return `${type}: ${title}`;
}

function statusOf(error: unknown): number {
  return typeof error === 'object' && error !== null && 'status' in error ? Number(error.status) : 0;
}

export function MockupsTab({ screenMockups, expanded = false, onUpdate, boardId, entityType, entityId,
  version, snapshot, revision, active = true, readCurrent = true, onReload }: MockupsTabProps) {
  const api = useDashboardApi();
  const apiRef = useRef(api);
  const directScreens = useMemo(
    () => [...(screenMockups || [])].sort((a, b) => a.order - b.order),
    [screenMockups],
  );
  const [effectiveMockups, setEffectiveMockups] = useState<KnowledgeWorkspaceItem[]>([]);
  const screens = useMemo<EffectiveScreenMockup[]>(() => {
    const directIds = new Set(directScreens.map((item) => item.id));
    const inherited = effectiveMockups
      .filter((item) => item.inherited && !directIds.has(String(item.representative_resource_id || '')))
      .map(effectiveMockupToScreen)
      .filter((item): item is EffectiveScreenMockup => Boolean(item))
      .sort((a, b) => a.order - b.order || a.title.localeCompare(b.title));
    return [...directScreens, ...inherited];
  }, [directScreens, effectiveMockups]);
  const [selectedId, setSelectedId] = useState<string>(screens[0]?.id || '');
  const [viewMode, setViewMode] = useState<'desktop' | 'mobile'>('desktop');
  const selected = screens.find((s) => s.id === selectedId);

  // Create form state
  const [showForm, setShowForm] = useState(false);
  const [formTitle, setFormTitle] = useState('');
  const [formDescription, setFormDescription] = useState('');
  const [formType, setFormType] = useState<ScreenMockup['screen_type']>('page');
  const [formHtml, setFormHtml] = useState('');
  const [formPreview, setFormPreview] = useState(false);
  const [saving, setSaving] = useState(false);
  // Design System consumption (spec 3a006f65 / card 0192f58d). When the board enforces
  // a Design System (blocking), these feed the server-side MockupDesignSystemGate.
  const [formDsRef, setFormDsRef] = useState('');
  const [formDsVersion, setFormDsVersion] = useState('');
  const [formDsEvidence, setFormDsEvidence] = useState('');
  const [gateError, setGateError] = useState<string | null>(null);
  const [base, setBase] = useState<{ version?: number; snapshot?: string; screens: ScreenMockup[] } | null>(null);
  const [draftId, setDraftId] = useState('');
  const [reviewingBase, setReviewingBase] = useState(false);
  const [versionConflict, setVersionConflict] = useState(false);
  const [confirmed, setConfirmed] = useState<{ version?: number; selectedId: string } | null>(null);
  const [uncertain, setUncertain] = useState(false);
  const [inspected, setInspected] = useState(false);
  const [accessDenied, setAccessDenied] = useState(false);
  const [resourceError, setResourceError] = useState<string | null>(null);
  const [resourceLoading, setResourceLoading] = useState(false);
  const [readGeneration, setReadGeneration] = useState(0);
  const scope = `${boardId || ''}:${entityType || ''}:${entityId || ''}`;
  const context = useRef({ scope, generation: 0 });
  if (context.current.scope !== scope) context.current = { scope, generation: context.current.generation + 1 };
  const busy = useRef(false);
  const baseChanged = Boolean(base && (base.version !== version || base.snapshot !== snapshot || JSON.stringify(base.screens) !== JSON.stringify(directScreens)));
  const blocked = !active || !readCurrent || accessDenied || saving || Boolean(confirmed) || uncertain
    || Boolean(resourceError) || resourceLoading;

  const clearForm = useCallback(() => {
    setShowForm(false); setFormTitle(''); setFormDescription(''); setFormType('page');
    setFormHtml(''); setFormPreview(false); setFormDsRef(''); setFormDsVersion(''); setFormDsEvidence('');
    setBase(null); setDraftId(''); setReviewingBase(false); setVersionConflict(false);
  }, []);
  const denyAccess = useCallback(() => {
    context.current.generation += 1;
    clearForm(); setConfirmed(null); setUncertain(false); setInspected(false);
    setEffectiveMockups([]); setAccessDenied(true); setSaving(false); busy.current = false;
    setGateError(null); setResourceError('Mockup access is no longer available.');
  }, [clearForm]);

  useEffect(() => {
    clearForm(); setConfirmed(null); setUncertain(false); setInspected(false);
    setAccessDenied(false); setGateError(null); setResourceError(null); setSaving(false);
    setEffectiveMockups([]); setSelectedId(''); busy.current = false;
    return () => { context.current.generation += 1; };
  }, [scope, clearForm]);

  useEffect(() => {
    apiRef.current = api;
  }, [api]);

  useEffect(() => {
    if (!active) return;
    if (!boardId || !entityType || !entityId) {
      setEffectiveMockups([]);
      return;
    }
    let cancelled = false;
    const origin = { ...context.current };
    setResourceLoading(true);
    loadEffectiveResourceItems(apiRef.current.getEffectiveResources, boardId, entityType, entityId, 'mockup', 'full')
      .then((response) => {
        if (!cancelled && context.current.generation === origin.generation) {
          setEffectiveMockups(response); setResourceError(null);
        }
      })
      .catch((error: unknown) => {
        if (cancelled || context.current.generation !== origin.generation) return;
        if ([401, 403, 404].includes(statusOf(error))) denyAccess();
        else setResourceError('Effective mockups could not be loaded. Reload before another change.');
      })
      .finally(() => { if (!cancelled) setResourceLoading(false); });
    return () => {
      cancelled = true;
    };
  }, [boardId, entityId, entityType, active, revision, readGeneration, denyAccess]);

  useEffect(() => {
    if (screens.length === 0) {
      if (selectedId) setSelectedId('');
      return;
    }
    if (!selectedId || !screens.some((screen) => screen.id === selectedId)) {
      setSelectedId(screens[0].id);
    }
  }, [screens, selectedId]);

  const openCreate = () => {
    if (blocked || busy.current) return;
    setBase({ version, snapshot, screens: directScreens });
    setDraftId(`mockup_${crypto.randomUUID()}`);
    setGateError(null); setShowForm(true);
  };

  const recoverRead = async (receipt = confirmed) => {
    const origin = { ...context.current };
    const current = () => origin.scope === context.current.scope && origin.generation === context.current.generation;
    setSaving(true); busy.current = true;
    try {
      await onReload?.(receipt?.version);
      if (!current()) return;
      setReadGeneration(value => value + 1);
      if (receipt) { clearForm(); setSelectedId(receipt.selectedId); setConfirmed(null); }
      else if (uncertain) setInspected(true);
      setGateError(null);
    } catch (error) {
      if (!current()) return;
      if ([401, 403, 404].includes(statusOf(error))) denyAccess();
      else setGateError(error instanceof Error ? error.message : 'Could not reload current mockups.');
    } finally { if (current()) { busy.current = false; setSaving(false); } }
  };

  const write = async (next: ScreenMockup[], authoredBase: { version?: number; snapshot?: string; screens: ScreenMockup[] }, nextSelectedId: string) => {
    if (!onUpdate || blocked || busy.current) return;
    const origin = { ...context.current };
    const current = () => origin.scope === context.current.scope && origin.generation === context.current.generation;
    busy.current = true;
    setSaving(true);
    setGateError(null);
    try {
      const result = await onUpdate(next, { expectedVersion: authoredBase.version, expectedSnapshot: authoredBase.snapshot });
      if (!current()) return;
      const receipt = { version: result?.version, selectedId: nextSelectedId };
      setConfirmed(receipt);
      await recoverRead(receipt);
    } catch (error) {
      if (!current()) return;
      const status = statusOf(error);
      if ([401, 403, 404].includes(status)) { denyAccess(); return; }
      const detail = (error as { detail?: { message?: string; code?: string } })?.detail;
      setGateError(detail?.message || detail?.code || (error instanceof Error ? error.message : 'Failed to save mockup.'));
      if (status === 409 && error instanceof Error && ['spec_version_conflict', 'mockup_snapshot_conflict'].includes(error.message)) setVersionConflict(true);
      else if (onReload && (!status || status >= 500)) { setUncertain(true); setInspected(false); }
    } finally { if (current()) { busy.current = false; setSaving(false); } }
  };

  const handleCreate = async () => {
    if (!formTitle.trim() || !formHtml.trim() || !base || blocked || baseChanged || versionConflict) return;
      const newMockup: ScreenMockup = {
        id: draftId,
        title: formTitle.trim(),
        description: formDescription.trim() || null,
        screen_type: formType,
        html_content: formHtml,
        annotations: null,
        order: base.screens.length,
        design_system_ref: formDsRef.trim()
          ? { design_system_id: formDsRef.trim(), version: formDsVersion.trim() ? Number(formDsVersion) : null }
          : null,
        design_system_evidence: formDsEvidence.trim() || null,
      };
      await write([...base.screens, newMockup], base, newMockup.id);
  };

  const handleDelete = async (id: string) => {
    if (!onUpdate || blocked || busy.current || versionConflict) return;
    if (!confirm('Delete this mockup?')) return;
    const updated = directScreens.filter((s) => s.id !== id);
    await write(updated, { version, snapshot, screens: directScreens }, updated[0]?.id || '');
  };

  const notices = <>
    {!readCurrent && <p role="status" className="text-sm text-amber-700 dark:text-amber-300">Current mockups could not be verified. Your input is preserved; reload before another change.</p>}
    {resourceError && <p role="alert" className="text-sm text-amber-700 dark:text-amber-300">{resourceError}</p>}
    {gateError && <p role="alert" data-testid="mockup-gate-error" className="text-xs text-red-600 dark:text-red-400">{gateError}</p>}
    {confirmed && <p role="status" className="text-sm text-amber-700 dark:text-amber-300">Mockup changes were saved. Reload the saved result before another change.</p>}
    {uncertain && <div role="alert" className="space-y-2 rounded-lg border border-amber-300 p-3 text-sm dark:border-amber-800">
      <p>The response was not confirmed. The write will not be repeated automatically. Inspect current mockups before discarding this attempt.</p>
      {inspected && <ul>{directScreens.map(item => <li key={item.id}>{item.title} · {item.id}</li>)}</ul>}
      <button type="button" className="btn btn-secondary text-xs" disabled={!inspected || saving || !readCurrent || Boolean(resourceError)} onClick={() => {
        setUncertain(false); setInspected(false); setGateError(null); clearForm();
      }}>I reviewed mockups; discard local attempt</button>
    </div>}
    {(confirmed || uncertain || versionConflict || resourceError || !readCurrent) && !accessDenied && <button type="button" className="btn btn-secondary text-xs" disabled={!active || saving} onClick={() => { void recoverRead(); }}>
      {confirmed ? 'Reload saved mockups' : 'Reload current mockups'}
    </button>}
    {(baseChanged || versionConflict) && !uncertain && !confirmed && <div role="status" className="space-y-2 rounded-lg border border-amber-300 p-3 text-sm dark:border-amber-800">
      <p>Mockup authoring base changed. Your input is preserved.</p>
      <button type="button" className="btn btn-secondary text-xs" disabled={!readCurrent || saving || Boolean(resourceError)} onClick={() => setReviewingBase(true)}>Review mockup base</button>
      {reviewingBase && <div className="space-y-2">
        <p>Current version: {version ?? 'unversioned'}. This operation will use only the current collection below.</p>
        <ul>{directScreens.map(item => <li key={item.id}>{item.title} · {item.id}</li>)}</ul>
        <button type="button" className="btn btn-primary text-xs" disabled={!readCurrent || saving || Boolean(resourceError)} onClick={() => {
          setBase({ version, snapshot, screens: directScreens }); setVersionConflict(false); setReviewingBase(false); setGateError(null);
        }}>Use reviewed mockup base</button>
      </div>}
    </div>}
  </>;

  if (accessDenied) return <div role="alert">Mockup access is no longer available.</div>;

  // Empty state
  if (screens.length === 0 && !showForm) {
    return (
      <div className="text-center py-12">
        {notices}
        <Monitor size={32} className="mx-auto text-gray-300 dark:text-gray-600 mb-2" />
        <p className="text-sm text-gray-500 dark:text-gray-400">No screen mockups yet</p>
        {onUpdate && (
          <button
            onClick={openCreate}
            disabled={blocked || versionConflict}
            className="mt-3 text-sm text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300 flex items-center gap-1 mx-auto"
          >
            <Plus size={14} /> Add Mockup
          </button>
        )}
      </div>
    );
  }

  // Create form
  if (showForm) {
    return (
      <div className="space-y-3">
        {notices}
        <fieldset disabled={saving || Boolean(confirmed) || uncertain} className="min-w-0 space-y-3">
        <div className="flex items-center justify-between">
          <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300">New Mockup</h4>
          <button aria-label="Cancel mockup" onClick={clearForm} className="p-1 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 rounded">
            <X size={16} />
          </button>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Title *</label>
            <input
              value={formTitle}
              onChange={(e) => setFormTitle(e.target.value)}
              placeholder="e.g. Login Page"
              className="w-full px-2.5 py-1.5 text-sm border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Type</label>
            <select
              value={formType}
              onChange={(e) => setFormType(e.target.value as ScreenMockup['screen_type'])}
              className="w-full px-2.5 py-1.5 text-sm border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
            >
              {SCREEN_TYPES.map((t) => (
                <option key={t.value} value={t.value}>{t.label}</option>
              ))}
            </select>
          </div>
        </div>

        <div>
          <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Description</label>
          <input
            value={formDescription}
            onChange={(e) => setFormDescription(e.target.value)}
            placeholder="Brief description of this screen"
            className="w-full px-2.5 py-1.5 text-sm border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
          />
        </div>

        {/* Design System consumption — required by boards that enforce a Design System */}
        <div className="grid grid-cols-3 gap-2" data-testid="mockup-design-system-fields">
          <div className="col-span-2">
            <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Design System ref</label>
            <input
              value={formDsRef}
              onChange={(e) => setFormDsRef(e.target.value)}
              placeholder="Design System id (board effective)"
              data-testid="mockup-ds-ref"
              className="w-full px-2.5 py-1.5 text-sm border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
            />
          </div>
          <div>
            <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Version</label>
            <input
              value={formDsVersion}
              onChange={(e) => setFormDsVersion(e.target.value)}
              placeholder="e.g. 1"
              data-testid="mockup-ds-version"
              className="w-full px-2.5 py-1.5 text-sm border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
            />
          </div>
          <div className="col-span-3">
            <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Design System evidence</label>
            <input
              value={formDsEvidence}
              onChange={(e) => setFormDsEvidence(e.target.value)}
              placeholder="Link/notes proving the screen consumes the Design System"
              data-testid="mockup-ds-evidence"
              className="w-full px-2.5 py-1.5 text-sm border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
            />
          </div>
        </div>

        <div>
          <div className="flex items-center justify-between mb-1">
            <label className="block text-xs font-medium text-gray-500 dark:text-gray-400">HTML Content * <span className="font-normal text-gray-400">(Tailwind CSS available)</span></label>
            <div className="flex items-center gap-1 border border-gray-200 dark:border-gray-700 rounded p-0.5">
              <button
                onClick={() => setFormPreview(false)}
                className={`p-1 rounded text-xs flex items-center gap-1 ${!formPreview ? 'bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300' : 'text-gray-400'}`}
              >
                <Code size={12} /> Code
              </button>
              <button
                onClick={() => setFormPreview(true)}
                className={`p-1 rounded text-xs flex items-center gap-1 ${formPreview ? 'bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300' : 'text-gray-400'}`}
              >
                <Eye size={12} /> Preview
              </button>
            </div>
          </div>

          {formPreview ? (
            <iframe
              srcDoc={buildSrcDoc(formHtml)}
              sandbox="allow-same-origin allow-scripts"
              className="w-full border border-gray-200 dark:border-gray-700 rounded-lg"
              style={{ height: '300px' }}
              title="Mockup preview"
            />
          ) : (
            <textarea
              value={formHtml}
              onChange={(e) => setFormHtml(e.target.value)}
              placeholder='<div class="max-w-md mx-auto bg-white rounded-xl shadow-md p-6">&#10;  <h1 class="text-2xl font-bold text-gray-900">Title</h1>&#10;  <p class="text-gray-500 mt-2">Description</p>&#10;</div>'
              rows={12}
              className="w-full px-3 py-2 text-xs font-mono border border-gray-300 dark:border-gray-600 rounded-lg bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 resize-y"
            />
          )}
        </div>

        <div className="flex justify-end gap-2">
          <button onClick={clearForm} className="btn btn-secondary text-sm">Cancel</button>
          <button
            onClick={handleCreate}
            disabled={!formTitle.trim() || !formHtml.trim() || blocked || baseChanged || versionConflict}
            className="btn btn-primary text-sm disabled:opacity-50"
          >
            {saving ? 'Saving...' : 'Add Mockup'}
          </button>
        </div>
        </fieldset>
      </div>
    );
  }

  // View mode
  const sanitizedHtml = selected ? sanitizeHtml(selected.html_content) : '';
  const srcDoc = buildSrcDoc(sanitizedHtml);

  return (
    <div className="space-y-3">
      {notices}
      {/* Screen selector + controls */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1 flex-wrap">
          {screens.map((s) => (
            <button
              key={s.id}
              onClick={() => setSelectedId(s.id)}
              className={`px-2.5 py-1 rounded text-xs flex items-center gap-1.5 transition-colors ${
                s.id === selectedId
                  ? 'bg-violet-100 text-violet-700 dark:bg-violet-900/40 dark:text-violet-300 font-medium'
                  : 'bg-gray-100 dark:bg-gray-800 text-gray-500 hover:bg-gray-200 dark:hover:bg-gray-700'
              }`}
            >
              {s.title}
              <span className="text-[9px] text-gray-400">{s.screen_type}</span>
              {s.inherited && (
                <span
                  data-testid="mockup-inherited-tab-badge"
                  className="rounded bg-slate-200 px-1 py-0.5 text-[9px] font-medium text-slate-600 dark:bg-slate-700 dark:text-slate-200"
                >
                  inherited
                </span>
              )}
            </button>
          ))}
          {onUpdate && (
            <button
              onClick={openCreate}
              disabled={blocked || versionConflict}
              className="px-2 py-1 rounded text-xs text-indigo-500 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 flex items-center gap-1"
            >
              <Plus size={12} /> Add
            </button>
          )}
        </div>
        <div className="flex items-center gap-1">
          {onUpdate && selected && !selected.read_only && (
            <button
              onClick={() => handleDelete(selected.id)}
              disabled={blocked || versionConflict}
              className="p-1 text-gray-400 hover:text-red-500 rounded mr-1"
              title="Delete mockup"
            >
              <X size={14} />
            </button>
          )}
          <div className="flex items-center gap-1 border border-gray-200 dark:border-gray-700 rounded-lg p-0.5">
            <button
              onClick={() => setViewMode('desktop')}
              className={`p-1 rounded ${viewMode === 'desktop' ? 'bg-gray-200 dark:bg-gray-700' : ''}`}
              title="Desktop view"
            >
              <Monitor size={14} className={viewMode === 'desktop' ? 'text-gray-700 dark:text-gray-300' : 'text-gray-400'} />
            </button>
            <button
              onClick={() => setViewMode('mobile')}
              className={`p-1 rounded ${viewMode === 'mobile' ? 'bg-gray-200 dark:bg-gray-700' : ''}`}
              title="Mobile view"
            >
              <Smartphone size={14} className={viewMode === 'mobile' ? 'text-gray-700 dark:text-gray-300' : 'text-gray-400'} />
            </button>
          </div>
        </div>
      </div>

      {/* Iframe viewport */}
      {selected && (
        <div className={`mx-auto transition-all ${viewMode === 'mobile' ? 'max-w-sm' : 'w-full'}`}>
          {selected.inherited && (
            <div
              data-testid="mockup-inherited-origin"
              className="mb-2 inline-flex items-center gap-1 rounded border border-slate-200 bg-slate-50 px-1.5 py-0.5 text-[10px] font-medium text-slate-600 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-300"
            >
              Read-only inherited from {sourceLabel(selected)}
            </div>
          )}
          {selected.description && (
            <p className="text-xs text-gray-500 dark:text-gray-400 mb-2 italic">{selected.description}</p>
          )}
          {selected.design_system_ref?.design_system_id && (
            <div data-testid="mockup-ds-badge" className="mb-2 inline-flex items-center gap-1 rounded bg-violet-100 px-1.5 py-0.5 text-[10px] text-violet-700 dark:bg-violet-900/40 dark:text-violet-300">
              DS {selected.design_system_ref.design_system_id}
              {selected.design_system_ref.version != null && ` v${selected.design_system_ref.version}`}
              {selected.design_system_evidence ? ' · evidence ✓' : ' · evidence ✗'}
            </div>
          )}
          <iframe
            srcDoc={srcDoc}
            sandbox="allow-same-origin allow-scripts"
            className="w-full border border-gray-200 dark:border-gray-700 rounded-lg"
            style={{ height: expanded ? '70vh' : '400px' }}
            title={selected.title}
          />
        </div>
      )}

      {/* Annotations */}
      {selected?.annotations && selected.annotations.length > 0 && (
        <div className="space-y-1">
          <p className="text-[10px] font-semibold text-gray-400 uppercase tracking-wider">Annotations</p>
          {selected.annotations.map((a) => (
            <div key={a.id} className="flex items-start gap-1.5 text-[10px] text-gray-500 dark:text-gray-400">
              <MessageSquare size={10} className="shrink-0 mt-0.5 text-amber-400" />
              <span>{a.text}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useSpecCollectionEditor } from './useSpecCollectionEditor';
import { SpecCollectionDraftNotice } from './SpecCollectionDraftNotice';
import { useEffect, useMemo, useState } from 'react';
import { CheckCircle, ChevronDown, ChevronUp, Gauge, Link, Pencil, Plus, Trash2, Unlink, XCircle } from 'lucide-react';
import type { CardSummaryForSpec, ObservabilityRequirement, ObservabilitySignalType, Spec } from '@/types';

interface ObservabilityRequirementsTabProps {
  spec: Spec;
  onUpdate: (requirements: ObservabilityRequirement[], expectedVersion: number) => void | Promise<void>;
  readCurrent?: boolean;
  onSpecUpdate?: (patch: Record<string, unknown>) => Promise<void>;
  specCards?: CardSummaryForSpec[];
  onLinkTask?: (requirementId: string, cardId: string) => Promise<void>;
  onUnlinkTask?: (requirementId: string, cardId: string) => Promise<void>;
  canCreate?: boolean;
  canEdit?: boolean;
  canDelete?: boolean;
  canLinkTask?: boolean;
  canEditCoverageFlags?: boolean;
  focusEditId?: string | null;
  focusCreateToken?: number | null;
  onFocusHandled?: () => void;
}

const SIGNAL_TYPES: ObservabilitySignalType[] = ['metric', 'log', 'trace', 'dashboard', 'alert', 'slo', 'other'];

const SIGNAL_LABELS: Record<ObservabilitySignalType, string> = {
  metric: 'Metric',
  log: 'Log',
  trace: 'Trace',
  dashboard: 'Dashboard',
  alert: 'Alert',
  slo: 'SLO',
  other: 'Other',
};

function LinkTaskPicker({
  requirementId,
  linkedIds,
  cards,
  onLink,
}: {
  requirementId: string;
  linkedIds: string[];
  cards: CardSummaryForSpec[];
  onLink: (requirementId: string, cardId: string) => Promise<void>;
}) {
  const [open, setOpen] = useState(false);
  const available = cards.filter((card) => !linkedIds.includes(card.id));
  if (available.length === 0) return null;
  return (
    <div className="mt-1">
      <button onClick={() => setOpen(!open)} className="text-[10px] text-blue-500 hover:text-blue-600 dark:text-blue-400">
        {open ? 'Cancel' : '+ Link task'}
      </button>
      {open && (
        <div className="mt-1 border border-gray-200 dark:border-gray-700 rounded p-1.5 max-h-32 overflow-y-auto space-y-0.5">
          {available.map((card) => (
            <button
              key={card.id}
              onClick={async () => { await onLink(requirementId, card.id); setOpen(false); }}
              className="w-full text-left px-2 py-1 rounded text-[11px] text-gray-600 dark:text-gray-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 truncate flex items-center gap-1"
            >
              <Link size={9} className="shrink-0 text-gray-400" />
              {card.title}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

export function ObservabilityRequirementsTab(props: ObservabilityRequirementsTabProps) {
  return <ObservabilityRequirementsTabEditor key={`${props.spec.board_id}:${props.spec.id}:${props.canCreate}:${props.canEdit}`} {...props} />;
}

function ObservabilityRequirementsTabEditor({
  spec,
  onUpdate,
  readCurrent = true,
  onSpecUpdate,
  specCards = [],
  onLinkTask,
  onUnlinkTask,
  canCreate = true,
  canEdit = true,
  canDelete = true,
  canLinkTask = true,
  canEditCoverageFlags = true,
  focusEditId = null,
  focusCreateToken = null,
  onFocusHandled,
}: ObservabilityRequirementsTabProps) {
  const editor = useSpecCollectionEditor(spec, readCurrent);
  const begin = editor.begin;
  const [adding, setAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [formTitle, setFormTitle] = useState('');
  const [formSignalType, setFormSignalType] = useState<ObservabilitySignalType>('metric');
  const [formDescription, setFormDescription] = useState('');
  const [formTarget, setFormTarget] = useState('');
  const [formMetricName, setFormMetricName] = useState('');
  const [formThreshold, setFormThreshold] = useState('');
  const [formSeverity, setFormSeverity] = useState('');
  const [formOwner, setFormOwner] = useState('');
  const [formLinkedFRs, setFormLinkedFRs] = useState<string[]>([]);
  const [formLinkedIRs, setFormLinkedIRs] = useState<string[]>([]);
  const [formNotes, setFormNotes] = useState('');

  const requirements = (spec.observability_requirements || []).filter((item) => item.status === 'active');
  const activeRequirements = requirements.filter((item) => item.status === 'active');
  const frs = spec.functional_requirements || [];
  const integrationRequirements = spec.integration_requirements || [];

  const coverage = useMemo(() => {
    const linked = activeRequirements.filter((item) => (item.linked_task_ids?.length ?? 0) > 0).length;
    return {
      linked,
      total: activeRequirements.length,
      pct: activeRequirements.length > 0 ? Math.round((linked / activeRequirements.length) * 100) : 0,
    };
  }, [activeRequirements]);

  const resetForm = () => {
    setFormTitle('');
    setFormSignalType('metric');
    setFormDescription('');
    setFormTarget('');
    setFormMetricName('');
    setFormThreshold('');
    setFormSeverity('');
    setFormOwner('');
    setFormLinkedFRs([]);
    setFormLinkedIRs([]);
    setFormNotes('');
  };

  const buildRequirement = (id: string, current?: ObservabilityRequirement): ObservabilityRequirement => ({
    ...current,
    id,
    title: formTitle.trim(),
    signal_type: formSignalType,
    description: formDescription.trim(),
    target: formTarget.trim() || null,
    metric_name: formMetricName.trim() || null,
    threshold: formThreshold.trim() || null,
    severity: formSeverity.trim() || null,
    owner: formOwner.trim() || null,
    linked_requirements: formLinkedFRs.length > 0 ? formLinkedFRs : null,
    linked_integration_requirements: formLinkedIRs.length > 0 ? formLinkedIRs : null,
    linked_task_ids: current?.linked_task_ids || null,
    status: current?.status || 'active',
    notes: formNotes.trim() || null,
  });

  const handleAdd = async () => {
    if (!formTitle.trim() || !formDescription.trim()) return;
    if (missing.length || !canCreate || !await editor.save(version => onUpdate([...requirements, buildRequirement(`or_${Date.now()}`)], version))) return;
    setAdding(false);
    resetForm();
  };

  const handleEdit = (item: ObservabilityRequirement) => {
    if (!canEdit || !editor.begin()) return;
    setEditingId(item.id);
    setFormTitle(item.title);
    setFormSignalType(item.signal_type || 'metric');
    setFormDescription(item.description || '');
    setFormTarget(item.target || '');
    setFormMetricName(item.metric_name || '');
    setFormThreshold(item.threshold || '');
    setFormSeverity(item.severity || '');
    setFormOwner(item.owner || '');
    setFormLinkedFRs(item.linked_requirements || []);
    setFormLinkedIRs(item.linked_integration_requirements || []);
    setFormNotes(item.notes || '');
  };

  useEffect(() => {
    if (!focusEditId || !canEdit || editingId || adding) return;
    const target = requirements.find((item) => item.id === focusEditId);
    if (!target) return;
    handleEdit(target);
    setExpandedId(null);
    onFocusHandled?.();
  }, [focusEditId, canEdit, spec.observability_requirements, onFocusHandled, editingId, adding]);

  useEffect(() => {
    if (!focusCreateToken || !canCreate || editingId || adding) return;
    if (!begin()) return;
    resetForm();
    setAdding(true);
    setEditingId(null);
    onFocusHandled?.();
  }, [focusCreateToken, canCreate, onFocusHandled, editingId, adding, begin]);

  const handleSaveEdit = async () => {
    if (!editingId || !formTitle.trim() || !formDescription.trim()) return;
    if (removed || missing.length || !canEdit || !await editor.save(version => onUpdate(requirements.map((item) => item.id === editingId ? buildRequirement(editingId, item) : item), version))) return;
    setEditingId(null);
    resetForm();
  };

  const handleRemove = async (id: string) => {
    if (!confirm('Remove this observability requirement?')) return;
    if (canDelete) await editor.save(version => onUpdate(requirements.filter((item) => item.id !== id), version), true);
  };

  const toggleFR = (frIndex: string) => {
    setFormLinkedFRs((current) => current.includes(frIndex) ? current.filter((item) => item !== frIndex) : [...current, frIndex]);
  };

  const toggleIR = (irId: string) => {
    setFormLinkedIRs((current) => current.includes(irId) ? current.filter((item) => item !== irId) : [...current, irId]);
  };

  const currentRequirement = requirements.find(item => item.id === editingId);
  const removed = !!editingId && !requirements.some(item => item.id === editingId);
  const missing = [
    ...formLinkedFRs.filter(id => !frs.some(fr => fr.id === id && (fr.status || 'active') === 'active')),
    ...formLinkedIRs.filter(id => !integrationRequirements.some(item => item.id === id && (item.status || 'active') === 'active')),
  ];

  const isFormValid = Boolean(formTitle.trim() && formDescription.trim());

  const renderForm = (onSubmit: () => void, submitLabel: string, onCancel: () => void) => (
    <fieldset disabled={editor.saving} className="border border-emerald-200 dark:border-emerald-700 rounded-lg p-3 space-y-2 bg-emerald-50/50 dark:bg-emerald-900/10">
      <div className="grid grid-cols-[150px_minmax(0,1fr)] gap-2">
        <select value={formSignalType} onChange={(event) => setFormSignalType(event.target.value as ObservabilitySignalType)} className="px-2 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600">
          {SIGNAL_TYPES.map((type) => <option key={type} value={type}>{SIGNAL_LABELS[type]}</option>)}
        </select>
        <input value={formTitle} onChange={(event) => setFormTitle(event.target.value)} placeholder="Observability requirement title" className="px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" autoFocus />
      </div>
      <textarea value={formDescription} onChange={(event) => setFormDescription(event.target.value)} placeholder="Dashboard, metric, alert, log, trace, or SLO expectation" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600 resize-none" rows={2} />
      <div className="grid grid-cols-2 gap-2">
        <input value={formTarget} onChange={(event) => setFormTarget(event.target.value)} placeholder="Target component or flow" className="px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" />
        <input value={formMetricName} onChange={(event) => setFormMetricName(event.target.value)} placeholder="Metric/query/dashboard" className="px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" />
        <input value={formThreshold} onChange={(event) => setFormThreshold(event.target.value)} placeholder="Threshold or SLO" className="px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" />
        <input value={formSeverity} onChange={(event) => setFormSeverity(event.target.value)} placeholder="Severity" className="px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" />
      </div>
      <input value={formOwner} onChange={(event) => setFormOwner(event.target.value)} placeholder="Owner" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" />
      <textarea value={formNotes} onChange={(event) => setFormNotes(event.target.value)} placeholder="Notes (optional)" className="w-full px-2 py-1.5 border border-gray-300 rounded-lg text-xs dark:bg-gray-700 dark:border-gray-600 resize-none" rows={1} />

      {frs.length > 0 && (
        <div>
          <span className="text-[10px] text-gray-500 dark:text-gray-400 block mb-1">Link to functional requirements:</span>
          <div className="flex flex-wrap gap-1">
            {frs.map((fr, index) => {
              const key = fr.id;
              const linked = formLinkedFRs.includes(key);
              return (
                <button key={key} onClick={() => toggleFR(key)} className={`text-[10px] px-1.5 py-0.5 rounded transition-colors ${linked ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300 ring-1 ring-emerald-400' : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 hover:bg-gray-200'}`}>
                  FR{index}: {fr.text.length > 42 ? fr.text.slice(0, 39) + '...' : fr.text}
                </button>
              );
            })}
          </div>
        </div>
      )}

      {integrationRequirements.length > 0 && (
        <div>
          <span className="text-[10px] text-gray-500 dark:text-gray-400 block mb-1">Link to integration requirements:</span>
          <div className="flex flex-wrap gap-1">
            {integrationRequirements.map((item) => {
              const linked = formLinkedIRs.includes(item.id);
              return (
                <button key={item.id} onClick={() => toggleIR(item.id)} className={`text-[10px] px-1.5 py-0.5 rounded transition-colors ${linked ? 'bg-sky-100 text-sky-700 dark:bg-sky-900/40 dark:text-sky-300 ring-1 ring-sky-400' : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 hover:bg-gray-200'}`}>
                  {item.title.length > 42 ? item.title.slice(0, 39) + '...' : item.title}
                </button>
              );
            })}
          </div>
        </div>
      )}

      <div className="flex justify-end gap-2">
        <button onClick={() => { editor.cancel(); onCancel(); }} className="btn btn-secondary text-xs">Cancel</button>
        <button onClick={onSubmit} disabled={!isFormValid || editor.blocked || removed || missing.length > 0} className="btn btn-primary text-xs">{submitLabel}</button>
      </div>
    </fieldset>
  );

  return (
    <div className="space-y-4">
      <SpecCollectionDraftNotice editor={editor} active={adding || !!editingId} removed={removed} missing={missing}
        currentText={currentRequirement && [currentRequirement.title, currentRequirement.description, currentRequirement.notes].filter(Boolean).join('\n')}
        onRemoveMissing={() => { setFormLinkedFRs(formLinkedFRs.filter(id => !missing.includes(id))); setFormLinkedIRs(formLinkedIRs.filter(id => !missing.includes(id))); }} />
      {removed && renderForm(handleSaveEdit, 'Save', () => { setEditingId(null); resetForm(); })}
      {activeRequirements.length > 0 && (
        <div className="border border-gray-200 dark:border-gray-700 rounded-lg p-3">
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">OR Task Coverage ({coverage.linked}/{coverage.total})</h4>
            <span className={`text-[10px] px-1.5 py-0.5 rounded font-medium ${coverage.linked === coverage.total ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300' : 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300'}`}>
              {coverage.pct}% linked
            </span>
          </div>
          <div className="h-2 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
            <div className={`h-full transition-all duration-500 rounded-full ${coverage.linked === coverage.total ? 'bg-green-500' : 'bg-amber-500'}`} style={{ width: `${coverage.pct}%` }} />
          </div>
        </div>
      )}

      {onSpecUpdate && canEditCoverageFlags && (
        <div className="flex items-center justify-between px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-700/20">
          <div>
            <span className="text-xs font-medium text-gray-700 dark:text-gray-300">Skip OR coverage requirement</span>
            <p className="text-[10px] text-gray-400">Allow validation without full OR-to-task coverage</p>
          </div>
          <button onClick={() => onSpecUpdate({ skip_or_coverage: !spec.skip_or_coverage })} className={`relative w-10 h-5 rounded-full transition-colors ${spec.skip_or_coverage ? 'bg-amber-500' : 'bg-gray-300 dark:bg-gray-600'}`}>
            <span className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white transition-transform ${spec.skip_or_coverage ? 'translate-x-5' : ''}`} />
          </button>
        </div>
      )}

      {requirements.length === 0 && !adding && (
        <div className="text-center py-6">
          <Gauge size={32} className="mx-auto text-gray-300 dark:text-gray-600 mb-2" />
          <p className="text-sm text-gray-500 dark:text-gray-400">No observability requirements defined</p>
        </div>
      )}

      {requirements.map((item) => {
        const expanded = expandedId === item.id;
        const editing = editingId === item.id;
        const taskCount = item.linked_task_ids?.length ?? 0;
        if (editing) {
          return <div key={item.id}>{renderForm(handleSaveEdit, 'Save', () => { setEditingId(null); resetForm(); })}</div>;
        }
        return (
          <div key={item.id} data-readiness-ref={`or:${item.id}`} tabIndex={-1} className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden focus-visible:outline focus-visible:outline-2 focus-visible:outline-sky-500">
            <div data-readiness-expand aria-expanded={expanded} className="flex items-center gap-2 px-3 py-2 cursor-pointer bg-gray-50 dark:bg-gray-700/50" onClick={() => setExpandedId(expanded ? null : item.id)}>
              {taskCount > 0 ? <CheckCircle size={14} className="text-green-500 shrink-0" /> : <XCircle size={14} className="text-gray-300 dark:text-gray-600 shrink-0" />}
              <span className="text-[10px] px-1.5 py-0.5 rounded bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300 font-medium">{SIGNAL_LABELS[item.signal_type]}</span>
              <span className="text-sm font-medium text-gray-900 dark:text-white truncate flex-1">{item.title}</span>
              <span className={`text-[10px] px-1.5 py-0.5 rounded ${taskCount > 0 ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300' : 'bg-gray-100 text-gray-400 dark:bg-gray-700 dark:text-gray-500'}`}>{taskCount} tasks</span>
              {canEdit && (
                <button disabled={editor.saving || !readCurrent || adding} title="Edit" onClick={(event) => { event.stopPropagation(); handleEdit(item); }} className="p-0.5 text-gray-400 hover:text-blue-500"><Pencil size={12} /></button>
              )}
              {canDelete && (
                <button disabled={editor.saving || !readCurrent || adding || !!editingId} title="Remove" onClick={(event) => { event.stopPropagation(); handleRemove(item.id); }} className="p-0.5 text-gray-400 hover:text-red-500"><Trash2 size={12} /></button>
              )}
              {expanded ? <ChevronUp size={14} className="text-gray-400" /> : <ChevronDown size={14} className="text-gray-400" />}
            </div>
            {expanded && (
              <div className="px-3 py-2 space-y-2 text-sm">
                <p className="text-xs text-gray-600 dark:text-gray-400">{item.description}</p>
                <div className="grid grid-cols-2 gap-2 text-xs text-gray-500 dark:text-gray-400">
                  {item.target && <span>Target: {item.target}</span>}
                  {item.metric_name && <span>Metric: {item.metric_name}</span>}
                  {item.threshold && <span>Threshold: {item.threshold}</span>}
                  {item.severity && <span>Severity: {item.severity}</span>}
                  {item.owner && <span>Owner: {item.owner}</span>}
                </div>
                {item.linked_integration_requirements && item.linked_integration_requirements.length > 0 && (
                  <div className="flex flex-wrap gap-1">
                    <span className="text-[10px] text-gray-400 mr-1">IRs:</span>
                    {item.linked_integration_requirements.map((id) => <span key={id} className="text-[10px] px-1.5 py-0.5 rounded bg-sky-50 text-sky-700 dark:bg-sky-900/20 dark:text-sky-300">{id}</span>)}
                  </div>
                )}
                {item.notes && <p className="text-xs text-gray-500 dark:text-gray-400 italic border-l-2 border-gray-300 dark:border-gray-600 pl-2">{item.notes}</p>}
                {item.linked_task_ids && item.linked_task_ids.length > 0 && (
                  <div className="flex flex-wrap gap-1">
                    <span className="text-[10px] text-gray-400 mr-1">Linked Tasks:</span>
                    {item.linked_task_ids.map((taskId) => (
                      canLinkTask && onUnlinkTask ? (
                        <button key={taskId} onClick={() => onUnlinkTask(item.id, taskId)} className="text-[10px] px-1.5 py-0.5 rounded bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-300 inline-flex items-center gap-1">
                          {taskId.slice(0, 8)} <Unlink size={9} />
                        </button>
                      ) : (
                        <span key={taskId} className="text-[10px] px-1.5 py-0.5 rounded bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-300">
                          {taskId.slice(0, 8)}
                        </span>
                      )
                    ))}
                  </div>
                )}
                {canLinkTask && onLinkTask && <LinkTaskPicker requirementId={item.id} linkedIds={item.linked_task_ids || []} cards={specCards} onLink={onLinkTask} />}
              </div>
            )}
          </div>
        );
      })}

      {adding ? (
        renderForm(handleAdd, 'Add OR', () => { setAdding(false); resetForm(); })
      ) : canCreate ? (
        <button onClick={() => { if (editor.begin()) setAdding(true); }} disabled={editor.saving || !readCurrent} className="w-full py-2 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg text-sm text-gray-500 hover:border-emerald-400 hover:text-emerald-500 transition-colors flex items-center justify-center gap-1">
          <Plus size={14} />
          Add Observability Requirement
        </button>
      ) : null}
    </div>
  );
}

/**
 * RulesTab - Business rules management for specs
 */

import { useState, useMemo } from 'react';
import { Plus, Trash2, ChevronDown, ChevronUp, Scale, Pencil, CheckCircle, XCircle } from 'lucide-react';
import type { Spec, BusinessRule } from '@/types';
import { useSpecCollectionEditor } from './useSpecCollectionEditor';
import { SpecCollectionDraftNotice } from './SpecCollectionDraftNotice';

interface RulesTabProps {
  spec: Spec;
  onUpdate: (rules: BusinessRule[], expectedVersion: number) => void | Promise<void>;
  readCurrent?: boolean;
  onSpecUpdate?: (patch: Record<string, any>) => void;
  canCreate?: boolean;
  canEdit?: boolean;
  canDelete?: boolean;
}

export function RulesTab(props: RulesTabProps) {
  return <RulesTabEditor key={`${props.spec.board_id}:${props.spec.id}:${props.canCreate}:${props.canEdit}`} {...props} />;
}

function RulesTabEditor({ spec, onUpdate, onSpecUpdate, readCurrent = true, canCreate = true, canEdit = true, canDelete = true }: RulesTabProps) {
  const editor = useSpecCollectionEditor(spec, readCurrent);
  const [adding, setAdding] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);

  // Form state
  const [formTitle, setFormTitle] = useState('');
  const [formRule, setFormRule] = useState('');
  const [formWhen, setFormWhen] = useState('');
  const [formThen, setFormThen] = useState('');
  const [formNotes, setFormNotes] = useState('');
  const [formLinkedFRs, setFormLinkedFRs] = useState<string[]>([]);

  const rules = (spec.business_rules || []).filter((rule) => (rule.status || 'active') === 'active');
  const frOptions = (spec.functional_requirements || []).map((fr, index) => ({
    key: fr.id,
    index,
    text: fr.text,
  }));
  const frs = frOptions.map((fr) => fr.text);

  const resetForm = () => {
    setFormTitle('');
    setFormRule('');
    setFormWhen('');
    setFormThen('');
    setFormNotes('');
    setFormLinkedFRs([]);
  };

  const handleAdd = async () => {
    if (!formTitle.trim() || !formRule.trim() || !formWhen.trim() || !formThen.trim()) return;
    const id = `br_${Date.now()}`;
    const rule: BusinessRule = {
      id,
      title: formTitle.trim(),
      rule: formRule.trim(),
      when: formWhen.trim(),
      then: formThen.trim(),
      linked_requirements: formLinkedFRs.length > 0 ? formLinkedFRs : null,
      linked_task_ids: null,
      notes: formNotes.trim() || null,
    };
    if (missing.length || !canCreate || !await editor.save(version => onUpdate([...rules, rule], version))) return;
    setAdding(false);
    resetForm();
  };

  const handleEdit = (rule: BusinessRule) => {
    if (!canEdit || !editor.begin()) return;
    setEditingId(rule.id);
    setFormTitle(rule.title);
    setFormRule(rule.rule);
    setFormWhen(rule.when);
    setFormThen(rule.then);
    setFormNotes(rule.notes || '');
    setFormLinkedFRs(rule.linked_requirements || []);
  };

  const handleSaveEdit = async () => {
    if (!editingId || !formTitle.trim() || !formRule.trim() || !formWhen.trim() || !formThen.trim()) return;
    if (removed || missing.length || !canEdit || !await editor.save(version => onUpdate(rules.map((r) =>
      r.id === editingId
        ? {
            ...r,
            title: formTitle.trim(),
            rule: formRule.trim(),
            when: formWhen.trim(),
            then: formThen.trim(),
            linked_requirements: formLinkedFRs.length > 0 ? formLinkedFRs : null,
            notes: formNotes.trim() || null,
          }
        : r
    ), version))) return;
    setEditingId(null);
    resetForm();
  };

  const handleRemove = async (id: string) => {
    if (!confirm('Remove this business rule?')) return;
    if (canDelete) await editor.save(version => onUpdate(rules.filter((r) => r.id !== id), version), true);
  };

  const toggleFR = (fr: string) => {
    setFormLinkedFRs((prev) =>
      prev.includes(fr) ? prev.filter((x) => x !== fr) : [...prev, fr]
    );
  };

  const isFormValid = formTitle.trim() && formRule.trim() && formWhen.trim() && formThen.trim();
  const removed = !!editingId && !rules.some(item => item.id === editingId);
  const missing = formLinkedFRs.filter(id => !(spec.functional_requirements || []).some(fr => fr.id === id && (fr.status || 'active') === 'active'));
  const currentRule = rules.find(item => item.id === editingId);

  const renderForm = (onSubmit: () => void, submitLabel: string, onCancel: () => void) => (
    <fieldset disabled={editor.saving} className="border border-indigo-200 dark:border-indigo-700 rounded-lg p-3 space-y-2 bg-indigo-50/50 dark:bg-indigo-900/10">
      <input
        type="text"
        value={formTitle}
        onChange={(e) => setFormTitle(e.target.value)}
        placeholder="Rule title"
        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
        autoFocus
      />
      <textarea
        value={formRule}
        onChange={(e) => setFormRule(e.target.value)}
        placeholder="Rule description — what must be enforced"
        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600 resize-none"
        rows={2}
      />
      <div className="grid grid-cols-2 gap-2">
        <input
          type="text"
          value={formWhen}
          onChange={(e) => setFormWhen(e.target.value)}
          placeholder="When: condition..."
          className="px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
        />
        <input
          type="text"
          value={formThen}
          onChange={(e) => setFormThen(e.target.value)}
          placeholder="Then: action/result..."
          className="px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
        />
      </div>
      <textarea
        value={formNotes}
        onChange={(e) => setFormNotes(e.target.value)}
        placeholder="Notes (optional)"
        className="w-full px-2 py-1.5 border border-gray-300 rounded-lg text-xs dark:bg-gray-700 dark:border-gray-600 resize-none"
        rows={1}
      />
      {frs.length > 0 && (
        <div>
          <span className="text-[10px] text-gray-500 dark:text-gray-400 block mb-1">Link to functional requirements:</span>
          <div className="flex flex-wrap gap-1">
            {frOptions.map((fr) => {
              const key = fr.key;
              const isLinked = formLinkedFRs.includes(key);
              return (
                <button
                  key={key}
                  onClick={() => toggleFR(key)}
                  className={`text-[10px] px-1.5 py-0.5 rounded transition-colors ${
                    isLinked
                      ? 'bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300 ring-1 ring-indigo-400'
                      : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 hover:bg-gray-200'
                  }`}
                >
                  FR{fr.index}: {fr.text.length > 50 ? fr.text.slice(0, 47) + '...' : fr.text}
                </button>
              );
            })}
          </div>
        </div>
      )}
      <div className="flex justify-end gap-2">
        <button onClick={() => { editor.cancel(); onCancel(); }} className="btn btn-secondary text-xs">Cancel</button>
        <button onClick={onSubmit} disabled={!isFormValid || editor.blocked || removed || missing.length > 0} className="btn btn-primary text-xs">{submitLabel}</button>
      </div>
    </fieldset>
  );

  // Coverage uses current identities; text and positions are presentation only.
  const frCoverage = useMemo(() => {
    const coveredIds = new Set(rules.flatMap((rule) => rule.linked_requirements || []));
    return frOptions.map((fr) => ({
      index: fr.index, text: fr.text, covered: coveredIds.has(fr.key),
    }));
  }, [rules, frOptions]);

  const coveredCount = frCoverage.filter(f => f.covered).length;

  return (
    <div className="space-y-4">
      <SpecCollectionDraftNotice editor={editor} active={adding || !!editingId} removed={removed} missing={missing}
        currentText={currentRule && [currentRule.title, currentRule.rule, currentRule.when, currentRule.then, currentRule.notes].filter(Boolean).join('\n')}
        onRemoveMissing={() => setFormLinkedFRs(formLinkedFRs.filter(id => !missing.includes(id)))} />
      {removed && renderForm(handleSaveEdit, 'Save', () => { setEditingId(null); resetForm(); })}
      {/* FR Coverage summary */}
      {frs.length > 0 && (
        <div className="border border-gray-200 dark:border-gray-700 rounded-lg p-3">
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">
              FR Coverage ({coveredCount}/{frs.length})
            </h4>
            {coveredCount === frs.length ? (
              <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300 font-medium">
                100% covered
              </span>
            ) : (
              <span className="text-[10px] px-1.5 py-0.5 rounded bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300 font-medium">
                {frs.length > 0 ? Math.round((coveredCount / frs.length) * 100) : 0}% covered
              </span>
            )}
          </div>
          {/* Progress bar */}
          <div className="h-2 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden mb-2">
            <div
              className={`h-full transition-all duration-500 rounded-full ${coveredCount === frs.length ? 'bg-green-500' : 'bg-amber-500'}`}
              style={{ width: `${frs.length > 0 ? (coveredCount / frs.length) * 100 : 0}%` }}
            />
          </div>
          {/* FR list */}
          <div className="space-y-1 max-h-48 overflow-y-auto">
            {frCoverage.map((fr) => (
              <div key={fr.index} className="flex items-start gap-2 text-xs">
                {fr.covered ? (
                  <CheckCircle className="w-3.5 h-3.5 text-green-500 shrink-0 mt-0.5" />
                ) : (
                  <XCircle className="w-3.5 h-3.5 text-gray-300 dark:text-gray-600 shrink-0 mt-0.5" />
                )}
                <span className={`${fr.covered ? 'text-gray-700 dark:text-gray-300' : 'text-gray-400 dark:text-gray-500'} line-clamp-1`}>
                  <span className="font-medium">FR{fr.index}:</span> {fr.text}
                </span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Skip rules coverage toggle */}
      {onSpecUpdate && (
        <div className="flex items-center justify-between px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-700/20">
          <div>
            <span className="text-xs font-medium text-gray-700 dark:text-gray-300">Skip rules coverage requirement</span>
            <p className="text-[10px] text-gray-400">Allow starting cards without full FR→BR coverage</p>
          </div>
          <button
            onClick={() => onSpecUpdate({ skip_rules_coverage: !(spec as any).skip_rules_coverage })}
            className={`relative w-10 h-5 rounded-full transition-colors ${(spec as any).skip_rules_coverage ? 'bg-amber-500' : 'bg-gray-300 dark:bg-gray-600'}`}
          >
            <span className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white transition-transform ${(spec as any).skip_rules_coverage ? 'translate-x-5' : ''}`} />
          </button>
        </div>
      )}

      {/* Rules list */}
      {rules.length === 0 && !adding && (
        <div className="text-center py-6">
          <Scale size={32} className="mx-auto text-gray-300 dark:text-gray-600 mb-2" />
          <p className="text-sm text-gray-500 dark:text-gray-400">No business rules defined</p>
          <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">Business rules capture validations and conditional behaviors from requirements</p>
        </div>
      )}

      {rules.map((rule) => {
        const isExpanded = expandedId === rule.id;
        const isEditing = editingId === rule.id;

        if (isEditing) {
          return (
            <div key={rule.id}>
              {renderForm(handleSaveEdit, 'Save', () => { setEditingId(null); resetForm(); })}
            </div>
          );
        }

        return (
          <div key={rule.id} data-readiness-ref={`br:${rule.id}`} tabIndex={-1} className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden focus-visible:outline focus-visible:outline-2 focus-visible:outline-sky-500">
            <div
              className="flex items-center gap-2 px-3 py-2 cursor-pointer bg-gray-50 dark:bg-gray-700/50"
              onClick={() => setExpandedId(isExpanded ? null : rule.id)}
              data-readiness-expand aria-expanded={isExpanded}
            >
              <Scale size={14} className="text-indigo-500 shrink-0" />
              <span className="text-sm font-medium text-gray-900 dark:text-white truncate flex-1">{rule.title}</span>
              {rule.linked_requirements && rule.linked_requirements.length > 0 && (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-indigo-100 text-indigo-700 dark:bg-indigo-900/40 dark:text-indigo-300">
                  {rule.linked_requirements.length} FR{rule.linked_requirements.length !== 1 ? 's' : ''}
                </span>
              )}
              {(rule.linked_task_ids?.length ?? 0) > 0 ? (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300">
                  {rule.linked_task_ids!.length} task{rule.linked_task_ids!.length !== 1 ? 's' : ''}
                </span>
              ) : (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-gray-100 text-gray-400 dark:bg-gray-700 dark:text-gray-500">
                  0 tasks
                </span>
              )}
              <button
                onClick={(e) => { e.stopPropagation(); handleEdit(rule); }}
                disabled={!canEdit || editor.saving || !readCurrent}
                className={`p-0.5 ${canEdit ? 'text-gray-400 hover:text-blue-500' : 'text-gray-300 cursor-not-allowed'}`}
                title={canEdit ? 'Edit' : 'Requires spec.structured_entity.business_rule.update'}
              >
                <Pencil size={12} />
              </button>
              <button
                onClick={(e) => { e.stopPropagation(); handleRemove(rule.id); }}
                disabled={!canDelete || editor.saving || !readCurrent || adding || !!editingId}
                className={`p-0.5 ${canDelete ? 'text-gray-400 hover:text-red-500' : 'text-gray-300 cursor-not-allowed'}`}
                title={canDelete ? 'Remove' : 'Requires spec.structured_entity.business_rule.revoke'}
              >
                <Trash2 size={12} />
              </button>
              {isExpanded ? <ChevronUp size={14} className="text-gray-400" /> : <ChevronDown size={14} className="text-gray-400" />}
            </div>
            {isExpanded && (
              <div className="px-3 py-2 space-y-2 text-sm">
                <p className="text-xs text-gray-600 dark:text-gray-400">{rule.rule}</p>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <span className="text-[10px] font-semibold text-amber-600 uppercase">When</span>
                    <p className="text-xs text-gray-600 dark:text-gray-400 mt-0.5">{rule.when}</p>
                  </div>
                  <div>
                    <span className="text-[10px] font-semibold text-green-600 uppercase">Then</span>
                    <p className="text-xs text-gray-600 dark:text-gray-400 mt-0.5">{rule.then}</p>
                  </div>
                </div>
                {rule.notes && (
                  <p className="text-xs text-gray-500 dark:text-gray-400 italic border-l-2 border-gray-300 dark:border-gray-600 pl-2">{rule.notes}</p>
                )}
                {rule.linked_requirements && rule.linked_requirements.length > 0 && (
                  <div className="flex flex-wrap gap-1">
                    <span className="text-[10px] text-gray-400 mr-1">Linked FRs:</span>
                    {rule.linked_requirements.map((idx, i) => {
                      const ref = idx;
                      const byId = frOptions.find((fr) => fr.key === ref);
                      const frText = byId?.text;
                      return (
                        <span key={i} className="text-[10px] px-1.5 py-0.5 rounded bg-indigo-50 text-indigo-700 dark:bg-indigo-900/20 dark:text-indigo-300">
                          {ref}{frText ? `: ${frText.length > 40 ? frText.slice(0, 37) + '...' : frText}` : ''}
                        </span>
                      );
                    })}
                  </div>
                )}
                {rule.linked_task_ids && rule.linked_task_ids.length > 0 && (
                  <div className="flex flex-wrap gap-1">
                    <span className="text-[10px] text-gray-400 mr-1">Linked Tasks:</span>
                    {rule.linked_task_ids.map((taskId, i) => (
                      <span key={i} className="text-[10px] px-1.5 py-0.5 rounded bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-300">
                        {taskId.slice(0, 8)}…
                      </span>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>
        );
      })}

      {/* Add form */}
      {adding ? (
        renderForm(handleAdd, 'Add Rule', () => { setAdding(false); resetForm(); })
      ) : (
        !editingId && (
          <button
            onClick={() => { if (editor.begin()) setAdding(true); }}
            disabled={!canCreate || editor.saving || !readCurrent}
            title={canCreate ? 'Add Business Rule' : 'Requires spec.structured_entity.business_rule.create'}
            className={`flex items-center gap-1 text-sm ${canCreate ? 'text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300' : 'text-gray-300 cursor-not-allowed'}`}
          >
            <Plus size={14} /> Add Business Rule
          </button>
        )
      )}
    </div>
  );
}

/**
 * Single source for the frontend's supported scenario_type runtime list and the
 * type badge (spec ac16b3c9, card bf52c32f). Mirrors the backend authoritative
 * enum VALID_SCENARIO_TYPES.
 *
 * A persisted value OUTSIDE the supported enum (historical/legacy data, e.g.
 * `regression`) is rendered EXPLICITLY as `<value> (unsupported)` with a warning
 * style and tooltip — it is never shown as a plain supported-looking label. This
 * surfaces stale data for deliberate remediation instead of hiding it (FR5/AC5);
 * new writes already fail closed on the backend (card 58844a26).
 */

import type { TestScenarioType } from '@/types';

export const SCENARIO_TYPES = [
  'unit',
  'integration',
  'e2e',
  'manual',
  'negative',
] as const;

const SCENARIO_TYPE_COLORS: Record<string, string> = {
  unit: 'bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-300',
  integration: 'bg-violet-50 text-violet-600 dark:bg-violet-900/30 dark:text-violet-300',
  e2e: 'bg-amber-50 text-amber-600 dark:bg-amber-900/30 dark:text-amber-300',
  manual: 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400',
  negative: 'bg-rose-50 text-rose-600 dark:bg-rose-900/30 dark:text-rose-300',
};

const UNSUPPORTED_CLASS =
  'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300';

export function isSupportedScenarioType(value: string): value is TestScenarioType {
  return (SCENARIO_TYPES as readonly string[]).includes(value);
}

export function ScenarioTypeBadge({ scenarioType }: { scenarioType: string }) {
  const known = isSupportedScenarioType(scenarioType);
  return (
    <span
      data-testid="scenario-type-badge"
      data-unsupported={known ? undefined : 'true'}
      className={`text-[10px] px-1.5 py-0.5 rounded ${
        known ? SCENARIO_TYPE_COLORS[scenarioType] : UNSUPPORTED_CLASS
      }`}
      title={
        known
          ? undefined
          : `Unsupported scenario_type — supported: ${SCENARIO_TYPES.join(', ')}`
      }
    >
      {known ? scenarioType : `${scenarioType} (unsupported)`}
    </span>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import {
  AlertTriangle,
  CheckCircle2,
  ChevronLeft,
  ChevronRight,
  ListChecks,
  Loader2,
  Play,
  RefreshCw,
  Send,
} from 'lucide-react';
import toast from 'react-hot-toast';

import { PreviousResultsSection } from '@/components/validation-cycle/ValidationCyclePrimitives';
import { AuthenticatedFetchError } from '@/lib/authFetch';
import { useDashboardApi } from '@/services/api';
import type {
  ChecklistExecutionStartResult,
  ChecklistItemResult,
  ChecklistOutcome,
  ChecklistReceiptPage,
  ChecklistSpecState,
  ChecklistTemplate,
} from '@/types';

interface SpecChecklistPanelProps {
  boardId: string;
  specId: string;
  expectedSpecVersion: number;
  expectedSpecEdition: number;
  canRead?: boolean;
  canExecute?: boolean;
  /** Checklist writes are allowed only while the Spec is in Validation. */
  validationStageActive?: boolean;
  showHistory?: boolean;
  /** Suppresses the repeated title inside the unified Spec workspace. */
  embedded?: boolean;
  refreshKey?: number;
  active?: boolean;
  onStateChange?: (state: ChecklistSpecState | null) => void;
}

type ItemDraft = {
  outcome: ChecklistOutcome | '';
  anchor: string;
  rationale: string;
};

const STATUS_STYLES: Record<ChecklistSpecState['status'], string> = {
  off: 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300',
  not_started:
    'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300',
  current: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300',
  stale: 'bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-200',
  failed: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300',
};

const OUTCOME_STYLES: Record<ChecklistOutcome, string> = {
  pass: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-300',
  fail: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-300',
  not_applicable:
    'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300',
};

export function SpecChecklistPanel({
  boardId,
  specId,
  expectedSpecVersion,
  expectedSpecEdition,
  canRead = true,
  canExecute = true,
  validationStageActive = true,
  showHistory = false,
  embedded = false,
  refreshKey = 0,
  active = true,
  onStateChange,
}: SpecChecklistPanelProps) {
  const api = useDashboardApi();
  const apiRef = useRef(api);
  apiRef.current = api;
  const onStateChangeRef = useRef(onStateChange);
  onStateChangeRef.current = onStateChange;

  const [state, setState] = useState<ChecklistSpecState | null>(null);
  const [template, setTemplate] = useState<ChecklistTemplate | null>(null);
  const [execution, setExecution] =
    useState<ChecklistExecutionStartResult | null>(null);
  const [drafts, setDrafts] = useState<Record<string, ItemDraft>>({});
  const [history, setHistory] = useState<ChecklistReceiptPage | null>(null);
  const [historyExpanded, setHistoryExpanded] = useState(false);
  const [historyLoading, setHistoryLoading] = useState(false);
  const [historyError, setHistoryError] = useState<string | null>(null);
  const [historyRefreshKey, setHistoryRefreshKey] = useState(0);
  const historyLoadKeyRef = useRef<string | null>(null);
  const [offset, setOffset] = useState(0);
  const [limit, setLimit] = useState<25 | 50 | 100>(25);
  const [loading, setLoading] = useState(true);
  const [starting, setStarting] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [readError, setReadError] = useState<string | null>(null);
  const [pendingState, setPendingState] = useState<ChecklistSpecState | null>(null);
  const executionBasis = useRef<ChecklistSpecState | null>(null);
  const accessGeneration = useRef(0);
  const readGeneration = useRef(0);
  const scope = `${boardId}:${specId}`;
  const scopeRef = useRef(scope);
  scopeRef.current = scope;
  const writeScope = `${scope}:${expectedSpecVersion}:${expectedSpecEdition}:${canRead}:${canExecute}`;
  const writeScopeRef = useRef(writeScope);
  writeScopeRef.current = writeScope;
  const basisKey = (value: ChecklistSpecState) => JSON.stringify([
    value.subject, value.binding, value.current_receipt?.id ?? null,
  ]);

  const loadState = useCallback(async () => {
    const generation = ++readGeneration.current;
    const requestedScope = `${boardId}:${specId}`;
    const current = () => generation === readGeneration.current && scopeRef.current === requestedScope;
    if (!canRead) {
      accessGeneration.current += 1;
      setState(null);
      setTemplate(null);
      setExecution(null);
      executionBasis.current = null;
      setDrafts({});
      setHistory(null);
      setPendingState(null);
      onStateChangeRef.current?.(null);
      setLoading(false);
      return;
    }
    setLoading(true);
    setReadError(null);
    try {
      if (!Number.isInteger(expectedSpecEdition) || expectedSpecEdition < 1) {
        throw new Error('A positive validation edition is required.');
      }
      const [resolvedState, templates] = await Promise.all([
        apiRef.current.getSpecChecklistState(boardId, specId),
        apiRef.current.listChecklistTemplates(),
      ]);
      if (!current()) return;
      if (
        resolvedState.subject.board_id !== boardId
        || resolvedState.subject.spec_id !== specId
        || resolvedState.subject.spec_edition !== expectedSpecEdition
        || (resolvedState.current_receipt !== null && (
          !Number.isInteger(resolvedState.current_receipt.spec_edition)
          || resolvedState.current_receipt.spec_edition < 1
          || resolvedState.current_receipt.spec_edition > expectedSpecEdition
          || resolvedState.current_receipt.source !== 'native'
          || resolvedState.current_receipt.board_id !== boardId
          || resolvedState.current_receipt.spec_id !== specId
        ))
      ) {
        throw new Error('The checklist state does not match this subject edition.');
      }
      const resolvedTemplate =
        templates.items.find(
          (item) =>
            item.version === resolvedState.binding.template_version_id,
        ) ?? null;
      if (executionBasis.current) {
        setPendingState(basisKey(executionBasis.current) !== basisKey(resolvedState) ? resolvedState : null);
        onStateChangeRef.current?.(resolvedState);
        return;
      }
      setState(resolvedState);
      setTemplate(resolvedTemplate);
      onStateChangeRef.current?.(resolvedState);
    } catch (error: any) {
      if (!current()) return;
      const accessLost = error instanceof AuthenticatedFetchError && [401, 403, 404].includes(error.status);
      if (!executionBasis.current || accessLost) setState(null);
      if (accessLost) {
        accessGeneration.current += 1;
        executionBasis.current = null;
        setExecution(null);
        setDrafts({});
        setTemplate(null);
        setHistory(null);
        setPendingState(null);
      }
      setReadError(error?.message || 'Failed to load the curated checklist');
      onStateChangeRef.current?.(null);
      toast.error(error?.message || 'Failed to load the curated checklist');
    } finally {
      if (current()) setLoading(false);
    }
  }, [
    boardId,
    canRead,
    expectedSpecEdition,
    specId,
  ]);

  useEffect(() => {
    if (active || !canRead) void loadState();
    return () => { readGeneration.current += 1; };
  }, [loadState, active, refreshKey, expectedSpecVersion]);

  useEffect(() => {
    setExecution(null);
    executionBasis.current = null;
    setDrafts({});
    setPendingState(null);
  }, [boardId, specId]);

  useEffect(() => {
    setHistory(null);
    setHistoryError(null);
    setHistoryExpanded(false);
    setOffset(0);
    historyLoadKeyRef.current = null;
  }, [boardId, expectedSpecEdition, showHistory, specId]);

  useEffect(() => {
    const shouldLoad = active && showHistory && historyExpanded;
    if (!canRead || !shouldLoad) return undefined;
    const loadKey = [boardId, specId, expectedSpecEdition, offset, limit, historyRefreshKey, refreshKey].join(':');
    if (historyLoadKeyRef.current === loadKey) return undefined;
    let cancelled = false;
    setHistoryLoading(true);
    setHistoryError(null);
    apiRef.current.listChecklistExecutions(boardId, specId, offset, limit)
      .then((resolvedHistory) => {
        if (cancelled) return;
        if (resolvedHistory.items.some(({ receipt }) => (
          !Number.isInteger(receipt.spec_edition)
          || receipt.spec_edition < 1
          || receipt.spec_edition > expectedSpecEdition
          || receipt.source !== 'native'
          || receipt.board_id !== boardId
          || receipt.spec_id !== specId
        ))) {
          throw new Error('The previous checklist results do not match this subject edition.');
        }
        historyLoadKeyRef.current = loadKey;
        setHistory(resolvedHistory);
      })
      .catch((error: unknown) => {
        if (cancelled) return;
        setHistoryError(
          error instanceof Error
            ? error.message
            : 'Previous checklist results could not be loaded.',
        );
      })
      .finally(() => {
        if (!cancelled) setHistoryLoading(false);
      });
    return () => { cancelled = true; };
  }, [
    boardId,
    active,
    canRead,
    expectedSpecEdition,
    historyExpanded,
    historyRefreshKey,
    refreshKey,
    limit,
    offset,
    showHistory,
    specId,
  ]);

  const refreshAfterMutation = useCallback(async () => {
    historyLoadKeyRef.current = null;
    setHistoryRefreshKey((value) => value + 1);
    await loadState();
  }, [loadState]);

  const start = async (reviewedState?: ChecklistSpecState) => {
    const basis = reviewedState ?? state;
    if (
      !basis
      || basis.binding.mode === 'off'
      || !validationStageActive
      || !canExecute
      || starting
    ) return;
    const requestedScope = writeScope;
    const requestedAccess = accessGeneration.current;
    const requestedVersion = expectedSpecVersion;
    const requestedEdition = expectedSpecEdition;
    setStarting(true);
    try {
      const started = await apiRef.current.startChecklistExecution(
        boardId,
        specId,
        {
          spec_edition: expectedSpecEdition,
          expected_spec_version: expectedSpecVersion,
          binding_version: basis.binding.version,
        },
      );
      if (writeScopeRef.current !== requestedScope || accessGeneration.current !== requestedAccess) return;
      if (started.spec_edition !== requestedEdition || basis.subject.spec_version !== requestedVersion) {
        throw new Error('The checklist execution does not match this subject edition.');
      }
      setExecution(started);
      executionBasis.current = basis;
      setState(basis);
      setPendingState(null);
      setReadError(null);
      if (!reviewedState) setDrafts(
        Object.fromEntries(
          (template?.items ?? []).map((item) => [
            item.item_id,
            { outcome: '', anchor: '', rationale: '' },
          ]),
        ),
      );
    } catch (error: any) {
      if (writeScopeRef.current !== requestedScope || accessGeneration.current !== requestedAccess) return;
      toast.error(error?.message || 'Failed to start checklist execution');
      await loadState();
    } finally {
      setStarting(false);
    }
  };

  const updateDraft = (itemId: string, patch: Partial<ItemDraft>) => {
    setDrafts((current) => {
      const existing = current[itemId] ?? {
        outcome: '',
        anchor: '',
        rationale: '',
      };
      return {
        ...current,
        [itemId]: { ...existing, ...patch },
      };
    });
  };

  const itemComplete = (itemId: string): boolean => {
    const draft = drafts[itemId];
    return Boolean(
      draft?.outcome &&
        draft.anchor.trim() &&
        (draft.outcome !== 'not_applicable' || draft.rationale.trim()),
    );
  };

  const allItemsComplete = Boolean(
    template?.items.length === 10 &&
      template.items.every((item) => itemComplete(item.item_id)),
  );

  const submit = async () => {
    if (
      !state || !execution || !template || !allItemsComplete || submitting
      || pendingState || readError || loading || starting
      || !canExecute || !validationStageActive
      || execution.spec_edition !== expectedSpecEdition
      || executionBasis.current?.subject.spec_version !== expectedSpecVersion
    ) return;
    setSubmitting(true);
    const requestedScope = writeScope;
    const requestedAccess = accessGeneration.current;
    try {
      const results: ChecklistItemResult[] = template.items.map((item) => {
        const draft = drafts[item.item_id];
        return {
          item_id: item.item_id,
          outcome: draft.outcome as ChecklistOutcome,
          anchor: draft.anchor.trim(),
          rationale: draft.rationale.trim() || null,
        };
      });
      await apiRef.current.submitChecklistExecution(
        boardId,
        specId,
        {
          spec_edition: expectedSpecEdition,
          expected_spec_version: expectedSpecVersion,
          execution_id: execution.execution_id,
          item_results: results,
        },
      );
      if (writeScopeRef.current !== requestedScope || accessGeneration.current !== requestedAccess) return;
      toast.success('Checklist result recorded');
      setExecution(null);
      executionBasis.current = null;
      setDrafts({});
      await refreshAfterMutation();
    } catch (error: any) {
      if (writeScopeRef.current !== requestedScope || accessGeneration.current !== requestedAccess) return;
      toast.error(error?.message || 'Failed to submit checklist');
      await loadState();
    } finally {
      setSubmitting(false);
    }
  };

  if (!canRead) {
    return (
      <section className="rounded-lg border border-gray-200 p-4 text-xs text-gray-500 dark:border-gray-700 dark:text-gray-400">
        The `spec.checklist.read` permission is required to view this checklist.
      </section>
    );
  }

  if ((loading && !state) || (state && (state.subject.board_id !== boardId || state.subject.spec_id !== specId))) {
    return (
      <section className="flex items-center gap-2 rounded-lg border border-gray-200 p-4 text-xs text-gray-500 dark:border-gray-700 dark:text-gray-400">
        <Loader2 size={13} className="animate-spin" />
        Loading curated checklist…
      </section>
    );
  }

  if (!state || !template) {
    return (
      <section className="rounded-lg border border-red-200 bg-red-50 p-4 text-xs text-red-700 dark:border-red-800 dark:bg-red-900/20 dark:text-red-300">
        Checklist readiness is unavailable. Validation remains fail-closed.
        <button type="button" className="btn btn-secondary mt-2 text-xs" onClick={() => void loadState()}>Retry checklist refresh</button>
      </section>
    );
  }

  const lifecycleEdition = expectedSpecEdition;
  const currentReceipt = state.subject.spec_edition === lifecycleEdition
    && state.current_receipt?.spec_edition === lifecycleEdition
    && state.currentness?.current === true
    && state.status !== 'stale'
    ? state.current_receipt
    : null;
  const displayStatus = state.binding.mode === 'off'
    ? 'off'
    : !currentReceipt
      ? 'not_started'
      : state.status === 'failed'
        ? 'failed'
        : 'current';
  const gateAllowed = Boolean(currentReceipt && state.gate.allowed);
  const currentResultByItemId = new Map(
    (currentReceipt?.results ?? []).map((result) => [
      result.item_id,
      result,
    ]),
  );

  return (
    <section
      className="space-y-4 rounded-lg border border-gray-200 bg-white p-4 dark:border-gray-700 dark:bg-gray-900/40"
      data-testid="spec-checklist-panel"
    >
      {(readError || pendingState) && <div role="alert" className="space-y-2 rounded-lg border border-amber-300 bg-amber-50 p-3 text-xs text-amber-900 dark:border-amber-700 dark:bg-amber-950/40 dark:text-amber-200">
        <p>{readError || 'Planning inputs changed. Your checklist draft is preserved; review the current Spec before recording a result.'}</p>
        {readError && <button type="button" className="btn btn-secondary text-xs" onClick={() => void loadState()}>Retry checklist refresh</button>}
        {pendingState && !readError && pendingState.subject.spec_edition === execution?.spec_edition
          && pendingState.binding.template_version_id === template.version
          && canExecute && validationStageActive && <button type="button" className="btn btn-secondary text-xs" disabled={loading || starting || submitting}
            onClick={() => void start(pendingState)}>I reviewed the current plan — keep my checklist draft</button>}
        {execution && <button type="button" className="btn btn-secondary text-xs" disabled={starting || submitting} onClick={() => {
          executionBasis.current = null; setExecution(null); setDrafts({}); setPendingState(null); void loadState();
        }}>Discard checklist draft</button>}
      </div>}
      {!embedded && (
      <div className="flex items-start justify-between gap-3">
        <div>
          <h4 className="flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wide text-gray-800 dark:text-gray-100">
            <ListChecks size={13} />
            Curated Spec Checklist
          </h4>
          <p className="mt-1 text-[11px] text-gray-500 dark:text-gray-400">
            {`Current result for Edition ${lifecycleEdition}`}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <span
            className={`rounded px-2 py-1 text-[10px] font-bold uppercase ${STATUS_STYLES[displayStatus]}`}
            data-testid="checklist-state-status"
          >
            {displayStatus.replace('_', ' ')}
          </span>
          <button
            type="button"
            onClick={() => void loadState()}
            aria-label="Refresh checklist state"
            disabled={loading || starting || submitting}
            className="rounded p-1 text-gray-400 hover:bg-gray-100 hover:text-gray-600 disabled:opacity-50 dark:hover:bg-gray-800"
          >
            <RefreshCw size={13} className={loading ? 'animate-spin' : ''} />
          </button>
        </div>
      </div>
      )}

      <div
        className={`rounded border p-3 ${
          gateAllowed
            ? 'border-green-200 bg-green-50 dark:border-green-800 dark:bg-green-900/20'
            : 'border-amber-200 bg-amber-50 dark:border-amber-800 dark:bg-amber-900/20'
        }`}
      >
        <div className="flex items-start gap-2">
          {gateAllowed ? (
            <CheckCircle2 size={14} className="mt-0.5 shrink-0 text-green-600" />
          ) : (
            <AlertTriangle size={14} className="mt-0.5 shrink-0 text-amber-600" />
          )}
          <div>
            <p className="text-xs font-medium text-gray-800 dark:text-gray-100">
              {state.binding.mode === 'blocking'
                ? gateAllowed
                  ? 'Spec Validation gate is satisfied'
                  : 'Spec Validation is blocked'
                : state.binding.mode === 'advisory'
                  ? 'Advisory evidence'
                  : 'Checklist policy is off'}
            </p>
            <p className="mt-0.5 text-[10px] text-gray-500 dark:text-gray-400">
              {gateAllowed
                ? 'The checklist result is available for this edition.'
                : 'Complete the checklist for this edition before submitting validation.'}
            </p>
          </div>
        </div>
      </div>

      {currentReceipt && !execution && (
        <div className="rounded border border-gray-100 bg-gray-50 p-3 dark:border-gray-800 dark:bg-gray-800/60">
          <div className="flex items-center justify-between gap-2">
            <p className="text-[11px] font-semibold text-gray-700 dark:text-gray-200">
              Current result
            </p>
          </div>
          <div className="mt-2 grid grid-cols-3 gap-2 text-center text-[10px]">
            {(['pass', 'fail', 'not_applicable'] as ChecklistOutcome[]).map(
              (outcome) => (
                <div
                  key={outcome}
                  className="rounded bg-white p-1.5 dark:bg-gray-900"
                >
                  <span className="block font-bold text-gray-800 dark:text-gray-100">
                    {
                      currentReceipt.results.filter(
                        (item) => item.outcome === outcome,
                      ).length
                    }
                  </span>
                  <span className="text-gray-400">
                    {outcome.replace('_', ' ')}
                  </span>
                </div>
              ),
            )}
          </div>
        </div>
      )}

      {!execution && (
        <div
          className="space-y-2"
          data-testid={
            currentReceipt
              ? 'checklist-receipt-results'
              : 'checklist-template-preview'
          }
        >
          <div>
            <h5 className="text-[11px] font-semibold uppercase text-gray-600 dark:text-gray-300">
              Checklist items
            </h5>
            <p className="mt-0.5 text-[10px] text-gray-400">
              {currentReceipt
                ? 'Recorded outcomes and evidence for the current edition.'
                : 'Immutable template preview. Start the checklist to record outcomes and evidence.'}
            </p>
          </div>
          {template.items.map((item, index) => {
            const result = currentResultByItemId.get(item.item_id);
            return (
              <div
                key={item.item_id}
                className="rounded border border-gray-200 p-3 dark:border-gray-700"
              >
                <div className="flex items-start gap-2">
                  <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-gray-100 text-[10px] font-bold text-gray-600 dark:bg-gray-800 dark:text-gray-300">
                    {index + 1}
                  </span>
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <p className="text-xs font-semibold text-gray-800 dark:text-gray-100">
                        {item.title_en}
                      </p>
                      {result ? (
                        <span
                          className={`rounded px-2 py-0.5 text-[9px] font-bold uppercase ${OUTCOME_STYLES[result.outcome]}`}
                        >
                          {result.outcome.replace('_', ' ')}
                        </span>
                      ) : (
                        <span className="rounded bg-gray-100 px-2 py-0.5 text-[9px] font-medium text-gray-500 dark:bg-gray-800 dark:text-gray-400">
                          Not evaluated
                        </span>
                      )}
                    </div>
                    <p className="mt-0.5 text-[10px] leading-4 text-gray-500 dark:text-gray-400">
                      {item.description_en}
                    </p>
                    {result ? (
                      <div className="mt-2 space-y-1 text-[10px]">
                        <p className="break-words text-gray-600 dark:text-gray-300">
                          <span className="font-semibold">Anchor:</span>{' '}
                          {result.anchor}
                        </p>
                        {result.rationale && (
                          <p className="break-words text-gray-500 dark:text-gray-400">
                            <span className="font-semibold">Rationale:</span>{' '}
                            {result.rationale}
                          </p>
                        )}
                      </div>
                    ) : item.allow_na ? (
                      <p className="mt-1 text-[9px] text-gray-400">
                        Not applicable is allowed with a rationale.
                      </p>
                    ) : null}
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {!execution &&
        state.binding.mode !== 'off' &&
        (!validationStageActive ? (
          <p className="text-[11px] text-gray-500 dark:text-gray-400">
            Checklist results can be recorded only during this Spec&apos;s validation stage.
          </p>
        ) : canExecute ? (
          <button
            type="button"
            onClick={() => void start()}
            disabled={starting}
            className="inline-flex items-center gap-1.5 rounded bg-violet-600 px-3 py-2 text-xs font-medium text-white hover:bg-violet-700 disabled:bg-gray-400"
          >
            {starting ? (
              <Loader2 size={13} className="animate-spin" />
            ) : (
              <Play size={13} />
            )}
            {currentReceipt ? 'Run checklist again' : 'Start checklist'}
          </button>
        ) : (
          <p className="text-[11px] text-gray-500 dark:text-gray-400">
            The `spec.checklist.execute` permission is required to run the
            checklist.
          </p>
        ))}

      {execution && (
        <div className="space-y-3" data-testid="checklist-execution-form">
          <div className="rounded bg-violet-50 px-3 py-2 text-[10px] text-violet-700 dark:bg-violet-900/20 dark:text-violet-200">
            {`Checklist in progress for Edition ${execution.spec_edition}. Submit all 10 ordered results together.`}
          </div>
          {template.items.map((item, index) => {
            const draft = drafts[item.item_id] ?? {
              outcome: '',
              anchor: '',
              rationale: '',
            };
            return (
              <div
                key={item.item_id}
                className="rounded border border-gray-200 p-3 dark:border-gray-700"
              >
                <div className="flex items-start gap-2">
                  <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-gray-100 text-[10px] font-bold text-gray-600 dark:bg-gray-800 dark:text-gray-300">
                    {index + 1}
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="text-xs font-semibold text-gray-800 dark:text-gray-100">
                      {item.title_en}
                    </p>
                    <p className="mt-0.5 text-[10px] leading-4 text-gray-500 dark:text-gray-400">
                      {item.description_en}
                    </p>
                    <div className="mt-2 grid gap-2 sm:grid-cols-[150px_minmax(0,1fr)]">
                      <select
                        aria-label={`${item.title_en} outcome`}
                        value={draft.outcome}
                        onChange={(event) =>
                          updateDraft(item.item_id, {
                            outcome: event.target.value as
                              | ChecklistOutcome
                              | '',
                          })
                        }
                        className="rounded border border-gray-300 bg-white px-2 py-1.5 text-xs dark:border-gray-600 dark:bg-gray-800 dark:text-gray-100"
                      >
                        <option value="">Choose outcome</option>
                        <option value="pass">Pass</option>
                        <option value="fail">Fail</option>
                        {item.allow_na && (
                          <option value="not_applicable">Not applicable</option>
                        )}
                      </select>
                      <input
                        aria-label={`${item.title_en} anchor`}
                        value={draft.anchor}
                        onChange={(event) =>
                          updateDraft(item.item_id, {
                            anchor: event.target.value,
                          })
                        }
                        placeholder="Required evidence anchor (FR/AC/section)"
                        className="rounded border border-gray-300 bg-white px-2 py-1.5 text-xs dark:border-gray-600 dark:bg-gray-800 dark:text-gray-100"
                      />
                    </div>
                    {(draft.outcome === 'not_applicable' ||
                      draft.outcome === 'fail') && (
                      <textarea
                        aria-label={`${item.title_en} rationale`}
                        value={draft.rationale}
                        onChange={(event) =>
                          updateDraft(item.item_id, {
                            rationale: event.target.value,
                          })
                        }
                        rows={2}
                        placeholder={
                          draft.outcome === 'not_applicable'
                            ? 'Required N/A rationale'
                            : 'Optional failure rationale'
                        }
                        className="mt-2 w-full rounded border border-gray-300 bg-white px-2 py-1.5 text-xs dark:border-gray-600 dark:bg-gray-800 dark:text-gray-100"
                      />
                    )}
                  </div>
                </div>
              </div>
            );
          })}
          <div className="flex items-center justify-between gap-3">
            <span className="text-[10px] text-gray-500 dark:text-gray-400">
              {template.items.filter((item) => itemComplete(item.item_id)).length}
              /10 complete
            </span>
            <button
              type="button"
              onClick={() => void submit()}
              disabled={!allItemsComplete || submitting || starting || loading || Boolean(pendingState || readError)
                || execution.spec_edition !== expectedSpecEdition
                || executionBasis.current?.subject.spec_version !== expectedSpecVersion
                || !canExecute || !validationStageActive}
              className="inline-flex items-center gap-1.5 rounded bg-violet-600 px-3 py-2 text-xs font-medium text-white hover:bg-violet-700 disabled:cursor-not-allowed disabled:bg-gray-400"
            >
              {submitting ? (
                <Loader2 size={13} className="animate-spin" />
              ) : (
                <Send size={13} />
              )}
              Submit complete checklist
            </button>
          </div>
        </div>
      )}

      {showHistory && (
        <PreviousResultsSection
          expanded={historyExpanded}
          onToggle={() => setHistoryExpanded((value) => !value)}
          count={history
            ? Math.max(
                0,
                history.total_filtered
                  - (currentReceipt ? 1 : 0),
              )
            : undefined}
          title="Previous checklist results"
          description="Earlier attempts and editions are loaded only when opened."
          testId="checklist-previous-results"
        >
          {historyLoading && !history ? (
            <p className="text-xs text-surface-500 dark:text-surface-400">
              Loading previous checklist results…
            </p>
          ) : historyError ? (
            <p role="alert" className="text-xs text-red-700 dark:text-red-300">
              Previous checklist results could not be loaded. {historyError}
            </p>
          ) : !history ? (
            <p className="text-xs text-surface-500 dark:text-surface-400">
              Open this section to load previous checklist results.
            </p>
          ) : history.items.filter(
              (view) => view.receipt.id !== currentReceipt?.id,
            ).length === 0 ? (
            <p className="text-xs text-surface-500 dark:text-surface-400">
              No previous checklist results are available.
            </p>
          ) : (
            <div className="space-y-2">
              {history.items
                .filter((view) =>
                  view.receipt.id !== currentReceipt?.id
                )
                .map((view) => (
                  <div
                    key={view.receipt.id}
                    className="flex flex-wrap items-center justify-between gap-2 rounded-lg border border-surface-200 bg-surface-50/70 p-3 text-xs dark:border-surface-700 dark:bg-surface-800/40"
                  >
                    <span>
                      <span className="font-semibold text-surface-800 dark:text-surface-100">
                        {`Edition ${view.receipt.spec_edition}`}
                      </span>
                      <span className="ml-2 text-surface-500 dark:text-surface-400">
                        {new Date(view.receipt.created_at).toLocaleString()}
                      </span>
                    </span>
                    <span className={view.receipt.outcome === 'pass'
                      ? 'font-semibold text-emerald-700 dark:text-emerald-300'
                      : 'font-semibold text-red-700 dark:text-red-300'}
                    >
                      {view.receipt.outcome === 'pass' ? 'Passed' : 'Failed'}
                    </span>
                  </div>
                ))}
            </div>
          )}
          {history && (
            <div className="flex items-center justify-end gap-2">
            <select
              aria-label="Checklist history page size"
              value={limit}
              onChange={(event) => {
                setLimit(Number(event.target.value) as 25 | 50 | 100);
                setOffset(0);
              }}
              className="rounded border border-gray-300 bg-white px-1.5 py-1 text-[10px] dark:border-gray-600 dark:bg-gray-800 dark:text-gray-100"
            >
              <option value={25}>25</option>
              <option value={50}>50</option>
              <option value={100}>100</option>
            </select>
              <button
                type="button"
                aria-label="Previous checklist results page"
                onClick={() => setOffset(Math.max(0, offset - limit))}
                disabled={offset === 0}
                className="rounded p-1 text-surface-500 hover:bg-surface-100 disabled:opacity-30 dark:hover:bg-surface-800"
              >
                <ChevronLeft size={13} />
              </button>
              <span className="text-[10px] text-surface-400">
                {history.total_filtered === 0 ? 0 : offset + 1}–
                {Math.min(offset + limit, history.total_filtered)}
              </span>
              <button
                type="button"
                aria-label="Next checklist results page"
                onClick={() => setOffset(offset + limit)}
                disabled={offset + limit >= history.total_filtered}
                className="rounded p-1 text-surface-500 hover:bg-surface-100 disabled:opacity-30 dark:hover:bg-surface-800"
              >
                <ChevronRight size={13} />
              </button>
            </div>
          )}
        </PreviousResultsSection>
      )}
    </section>
  );
}

import type { SpecDecompositionInput } from '@/types';

export const decompositionFields = [
  { score: 'breakdown_completeness', justification: 'breakdown_justification', label: 'Breakdown completeness' },
  { score: 'granularity', justification: 'granularity_justification', label: 'Granularity' },
  { score: 'dependency_coherence', justification: 'dependency_justification', label: 'Dependency coherence' },
  { score: 'test_coverage_quality', justification: 'test_coverage_justification', label: 'Test coverage quality' },
  { score: 'overall_score', justification: 'overall_justification', label: 'Overall decomposition' },
] as const;

export function emptyDecomposition(): SpecDecompositionInput {
  return { breakdown_completeness: 0, breakdown_justification: '', granularity: 0,
    granularity_justification: '', dependency_coherence: 0, dependency_justification: '',
    test_coverage_quality: 0, test_coverage_justification: '', overall_score: 0,
    overall_justification: '', recommendation: 'request_changes' };
}

export function decompositionReady(value: SpecDecompositionInput) {
  return decompositionFields.every(({ score, justification }) =>
    Number.isInteger(value[score]) && value[score] >= 0 && value[score] <= 100
    && value[justification].trim().length >= 10);
}

export function SpecDecompositionFields({ value, onChange, disabled = false }: {
  value: SpecDecompositionInput; onChange: (value: SpecDecompositionInput) => void; disabled?: boolean;
}) {
  return <fieldset disabled={disabled} className="space-y-3">
    <legend className="mb-2 text-sm font-semibold text-surface-900 dark:text-white">Your decomposition assessment</legend>
    <p className="text-xs text-surface-600 dark:text-surface-300">
      Review the planned Tasks, Tests and their dependencies. Each score needs its own justification; this opinion retains your authorship.
    </p>
    <div className="grid gap-3 sm:grid-cols-2">
      {decompositionFields.map(({ score, justification, label }) => <div key={score}
        className="space-y-2 rounded-lg border border-surface-200 p-3 dark:border-surface-700">
        <label className="block text-xs font-semibold text-surface-800 dark:text-surface-100">
          {label} <span className="float-right tabular-nums">{value[score]}/100</span>
          <input aria-label={`${label} score`} type="range" min={0} max={100} step={1}
            className="mt-2 w-full accent-violet-500" value={value[score]}
            onChange={event => onChange({ ...value, [score]: Number(event.target.value) })} />
        </label>
        <label className="block text-xs text-surface-600 dark:text-surface-300">{label} justification
          <textarea aria-label={`${label} justification`} rows={2} value={value[justification]}
            onChange={event => onChange({ ...value, [justification]: event.target.value })}
            className="mt-1 w-full rounded border border-surface-300 bg-white p-2 text-xs dark:border-surface-600 dark:bg-surface-900" />
        </label>
      </div>)}
    </div>
    <label className="block text-xs font-medium text-surface-700 dark:text-surface-200">Decomposition recommendation
      <select aria-label="Decomposition recommendation" value={value.recommendation}
        onChange={event => onChange({ ...value, recommendation: event.target.value as SpecDecompositionInput['recommendation'] })}
        className="mt-1 block rounded border border-surface-300 bg-white p-2 dark:border-surface-600 dark:bg-surface-900">
        <option value="request_changes">Request changes</option><option value="approve">Approve</option><option value="reject">Reject</option>
      </select>
    </label>
  </fieldset>;
}

