function TestScenariosTab({
  spec,
  focusReceipt,
  onUpdate,
  onSpecUpdate,
  onReload,
  canReadPolicyCompliance,
  policyRefreshKey,
  readCurrent,
}: {
  spec: Spec;
  focusReceipt?: string | null;
  onUpdate: (scenarios: TestScenario[], expectedVersion: number, expectedSnapshot: string) => Promise<void>;
  onSpecUpdate: (data: Record<string, unknown>) => Promise<void>;
  onReload: () => Promise<Spec>;
  canReadPolicyCompliance: boolean;
  policyRefreshKey: number;
  readCurrent: boolean;
}) {
  const api = useDashboardApi();
  const scenarioPermissions = usePermissions(spec.board_id);
  const [adding, setAdding] = useState(false);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [linkingScenarioId, setLinkingScenarioId] = useState<string | null>(null);
  const [scenarioSaving, setScenarioSaving] = useState(false);
  const [scenarioError, setScenarioError] = useState('');
  const [scenarioBase, setScenarioBase] = useState<{ version: number; edition: number; snapshot?: string } | null>(null);
  const [scenarioConflictVersion, setScenarioConflictVersion] = useState<string | null>(null);
  const [scenarioReadPending, setScenarioReadPending] = useState(false);
  const [scenarioReadFailed, setScenarioReadFailed] = useState(false);
  const [uncertainWrite, setUncertainWrite] = useState<ScenarioWriteAttempt | null>(null);
  const [writeObservation, setWriteObservation] = useState<'unchecked' | 'unchanged' | 'changed'>('unchecked');
  const [methodDrafts, setMethodDrafts] = useState<Record<string, TestScenario>>({});
  const [reportDrafts, setReportDrafts] = useState<Record<string, TestScenario>>({});
  const [operationPending, setOperationPending] = useState(false);
  const [operationNeedsRead, setOperationNeedsRead] = useState(false);
  const operating = useRef(false);
  const scenarioWritePending = useRef(false);
  const scenarioEditorMounted = useRef(true);
  useEffect(() => {
    scenarioEditorMounted.current = true;
    return () => { scenarioEditorMounted.current = false; };
  }, []);

  // New scenario form
  const [newTitle, setNewTitle] = useState('');
  const [newType, setNewType] = useState<TestScenarioType>('integration');
  const [newGiven, setNewGiven] = useState('');
  const [newWhen, setNewWhen] = useState('');
  const [newThen, setNewThen] = useState('');
  const [newNotes, setNewNotes] = useState('');
  const [newCriteria, setNewCriteria] = useState<string[]>([]);

  const scenarios = spec.test_scenarios || [];
  const criteria = normalizeAcceptanceCriteria((spec.acceptance_criteria || []) as unknown[]);
  const scenarioBaseChanged = scenarioBase !== null
    && (scenarioBase.version !== spec.version || scenarioBase.edition !== spec.edition
      || scenarioBase.snapshot !== spec.scenario_snapshot);
  const scenarioReadCurrent = readCurrent && !scenarioReadPending && !scenarioReadFailed
    && typeof spec.scenario_snapshot === 'string' && /^[0-9a-f]{64}$/.test(spec.scenario_snapshot);

  const runScenarioOperation = async (write: () => Promise<unknown>, message: string) => {
    if (operating.current || operationNeedsRead || !scenarioReadCurrent) return;
    operating.current = true; setOperationPending(true); setScenarioError('');
    let confirmed = false;
    try {
      await write(); confirmed = true;
      if (!scenarioEditorMounted.current) return;
      setLinkingScenarioId(null);
      await reloadScenarios();
      if (scenarioEditorMounted.current) toast.success(message);
    } catch (error) {
      if (!scenarioEditorMounted.current) return;
      const rejected = error instanceof AuthenticatedFetchError && error.status >= 400 && error.status < 500 && error.status !== 408;
      setOperationNeedsRead(confirmed || !rejected);
      setScenarioError(confirmed ? 'The change was saved, but its current state could not be loaded. Reload; do not submit it again.'
        : error instanceof Error ? error.message : 'Could not confirm the scenario change.');
      if (error instanceof AuthenticatedFetchError && [401, 403, 404].includes(error.status)) {
        try { await reloadScenarios(); } catch { /* Parent removes denied content. */ }
      }
    } finally { operating.current = false; if (scenarioEditorMounted.current) setOperationPending(false); }
  };

  const reloadScenarios = async () => {
    setScenarioReadPending(true);
    try {
      const updated = await onReload();
      if (updated.id !== spec.id || updated.board_id !== spec.board_id || !updated.scenario_snapshot) {
        throw new Error('The current scenario collection could not be verified. Reload before continuing.');
      }
      if (scenarioEditorMounted.current) { setScenarioReadFailed(false); setScenarioError(''); }
      return updated;
    } catch (error) {
      if (scenarioEditorMounted.current) {
        setScenarioReadFailed(true);
        setScenarioError(error instanceof Error ? error.message : 'Could not load current scenarios. Your draft is preserved.');
      }
      throw error;
    } finally {
      if (scenarioEditorMounted.current) setScenarioReadPending(false);
    }
  };

  const finishScenarioWrite = (attempt: ScenarioWriteAttempt) => {
    setUncertainWrite(null); setWriteObservation('unchecked'); setScenarioError('');
    if (attempt.kind === 'create') {
      setAdding(false); setScenarioBase(null);
      setNewTitle(''); setNewType('integration'); setNewGiven(''); setNewWhen(''); setNewThen(''); setNewNotes(''); setNewCriteria([]);
    }
  };

  const saveScenarioAttempt = async (attempt: ScenarioWriteAttempt) => {
    if (scenarioWritePending.current || operationPending || operationNeedsRead || !scenarioReadCurrent) return false;
    scenarioWritePending.current = true;
    setScenarioSaving(true); setScenarioError('');
    try {
      await onUpdate(attempt.next, attempt.expectedVersion, attempt.expectedSnapshot);
      if (scenarioEditorMounted.current) finishScenarioWrite(attempt);
      return scenarioEditorMounted.current;
    } catch (error) {
      if (scenarioEditorMounted.current) {
        setScenarioError(error instanceof Error ? error.message : 'Could not save the scenario. Your draft is preserved.');
        const definiteRejection = error instanceof ScenarioAuthoringInputError
          || (error instanceof AuthenticatedFetchError && error.status >= 400 && error.status < 500 && error.status !== 408);
        setUncertainWrite(definiteRejection ? null : attempt);
        setWriteObservation('unchecked');
        if (error instanceof AuthenticatedFetchError && error.status === 409
          && ['spec_version_conflict', 'scenario_snapshot_conflict'].includes(error.message)) {
          setScenarioConflictVersion(`${attempt.expectedVersion}:${attempt.expectedSnapshot}`);
        }
      }
      return false;
    } finally {
      scenarioWritePending.current = false;
      if (scenarioEditorMounted.current) setScenarioSaving(false);
    }
  };

  const checkScenarioWrite = async () => {
    if (!uncertainWrite || scenarioReadPending || scenarioWritePending.current) return;
    setWriteObservation('unchecked');
    try {
      const current = await reloadScenarios();
      if (!scenarioEditorMounted.current) return;
      const result = inspectScenarioWrite(uncertainWrite, current);
      if (result === 'observed') finishScenarioWrite(uncertainWrite);
      else setWriteObservation(result);
    } catch { /* Reload keeps the draft and the unresolved request. */ }
  };

  const handleAdd = async () => {
    if (!scenarioBase?.snapshot || scenarioBaseChanged || scenarioConflictVersion !== null || uncertainWrite) return;
    if (!newTitle.trim() || !newGiven.trim() || !newWhen.trim() || !newThen.trim()) return;
    const id = `ts_${Date.now()}`;
    const scenario: TestScenario = {
      id,
      title: newTitle.trim(),
      linked_criteria: newCriteria.length > 0 ? newCriteria : null,
      scenario_type: newType,
      given: newGiven.trim(),
      when: newWhen.trim(),
      then: newThen.trim(),
      notes: newNotes.trim() || null,
      status: 'draft',
      linked_task_ids: null,
    };
    await saveScenarioAttempt({ next: JSON.parse(JSON.stringify([...scenarios, scenario])) as TestScenario[],
      expectedVersion: scenarioBase.version, expectedSnapshot: scenarioBase.snapshot, kind: 'create', scenarioId: id });
  };

  const handleRemove = async (id: string) => {
    if (uncertainWrite || !spec.scenario_snapshot) return;
    await saveScenarioAttempt({ next: JSON.parse(JSON.stringify(scenarios.filter((s) => s.id !== id))) as TestScenario[],
      expectedVersion: spec.version, expectedSnapshot: spec.scenario_snapshot, kind: 'remove', scenarioId: id });
  };

  // Coverage matrix
  const coverageMap = new Map<string, string[]>();
  criteria.forEach((criterion) => {
    const covering = scenarios.filter((scenario) =>
      isAcceptanceCriterionLinked(scenario.linked_criteria, criterion, criteria)
    );
    coverageMap.set(criterion.key, covering.map((scenario) => scenario.id));
  });
  const uncoveredCriteria = criteria.filter((criterion) => !coverageMap.get(criterion.key)?.length);

  return (
    <div className="space-y-4">
      {scenarioError && <p role="alert" className="text-sm text-red-600 dark:text-red-400">{scenarioError}</p>}
      {!readCurrent && <p role="status" className="text-sm text-amber-600">Current scenarios could not be verified. Your drafts are preserved; reload before another write.</p>}
      {operationNeedsRead && <div role="status" className="text-sm text-amber-600">
        <p>Check the current scenario state before another action. No operation will be repeated automatically.</p>
        <button type="button" className="btn btn-secondary text-xs" disabled={scenarioReadPending || operationPending}
          onClick={() => { void reloadScenarios().then(() => { if (scenarioEditorMounted.current) setOperationNeedsRead(false); }).catch(() => {}); }}>Reload scenario state</button>
      </div>}
      {uncertainWrite && <div role="status" className="rounded-lg border border-amber-300 p-3 text-sm text-amber-700 dark:text-amber-300 space-y-2">
        <p>The write response was lost. The operation may have been saved. Check the current scenarios before doing anything again.</p>
        {writeObservation === 'changed' && <p>The collection changed and the requested result could not be confirmed. Inspect the current scenarios; this operation will not be repeated over a new base.</p>}
        {writeObservation === 'unchanged' && <p>The original collection is still current. You can retry the exact request with its original identity and preconditions.</p>}
        <button type="button" className="btn btn-secondary text-xs" disabled={scenarioReadPending || scenarioSaving}
          onClick={() => void checkScenarioWrite()}>{scenarioReadPending ? 'Checking scenario write…' : 'Check scenario write'}</button>
        {writeObservation === 'unchanged' && <button type="button" className="btn btn-primary text-xs ml-2"
          disabled={!scenarioReadCurrent || scenarioSaving} onClick={() => void saveScenarioAttempt(uncertainWrite)}>Retry original write</button>}
        {writeObservation === 'changed' && <button type="button" className="btn btn-secondary text-xs ml-2"
          disabled={!scenarioReadCurrent || scenarioSaving} onClick={() => { setUncertainWrite(null); setWriteObservation('unchecked'); setAdding(false); setScenarioBase(null); setScenarioError(''); }}>Discard unresolved operation</button>}
      </div>}
      {adding && (scenarioBaseChanged || scenarioConflictVersion !== null) && (
        <div role="status" className="rounded-lg border border-amber-300 p-3 text-sm text-amber-700 dark:text-amber-300">
          <p>The Spec changed while you were writing. Your draft is preserved. Review the current scenarios and criteria before saving.</p>
          <button type="button" className="btn btn-secondary text-xs mt-2"
            disabled={scenarioSaving || Boolean(uncertainWrite) || !scenarioReadCurrent || scenarioConflictVersion === `${spec.version}:${spec.scenario_snapshot}`}
            onClick={() => { setScenarioBase({ version: spec.version, edition: spec.edition, snapshot: spec.scenario_snapshot }); setScenarioConflictVersion(null); setScenarioError(''); }}>
            Review scenario base
          </button>
        </div>
      )}
      {!operationNeedsRead && (!readCurrent || scenarioConflictVersion !== null || scenarioReadFailed || !spec.scenario_snapshot) && (
        <button type="button" className="btn btn-secondary text-xs" disabled={scenarioSaving || scenarioReadPending}
          onClick={() => { void reloadScenarios().catch(() => { /* Inline error preserves the draft. */ }); }}>
          {scenarioReadPending ? 'Loading scenarios…' : 'Reload scenarios'}
        </button>
      )}
      {/* Coverage summary */}
      {criteria.length > 0 && (() => {
        const coveredCount = criteria.length - uncoveredCriteria.length;
        const coveragePct = Math.round((coveredCount / criteria.length) * 100);
        return (
          <div className="border border-gray-200 dark:border-gray-700 rounded-lg p-3">
            <div className="flex items-center justify-between mb-2">
              <h4 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">
                AC Coverage ({coveredCount}/{criteria.length})
              </h4>
              {coveredCount === criteria.length ? (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300 font-medium">
                  100% covered
                </span>
              ) : (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300 font-medium">
                  {coveragePct}% covered
                </span>
              )}
            </div>
            {/* Progress bar */}
            <div className="h-2 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden mb-2">
              <div
                className={`h-full transition-all duration-500 rounded-full ${coveredCount === criteria.length ? 'bg-green-500' : 'bg-amber-500'}`}
                style={{ width: `${coveragePct}%` }}
              />
            </div>
            <div className="space-y-1 max-h-48 overflow-y-auto">
              {criteria.map((criterion) => {
                const covering = coverageMap.get(criterion.key) || [];
                const covered = covering.length > 0;
                return (
                  <div key={criterion.key} className="flex items-start gap-2 text-xs">
                    <span className={`mt-0.5 w-3 h-3 rounded-full shrink-0 ${covered ? 'bg-green-500' : 'bg-red-400'}`} />
                    <span className={`flex-1 line-clamp-1 ${covered ? 'text-gray-600 dark:text-gray-400' : 'text-red-600 dark:text-red-400 font-medium'}`}>
                      {criterion.label}
                    </span>
                    <span className="text-gray-400 shrink-0">{covering.length} test{covering.length !== 1 ? 's' : ''}</span>
                  </div>
                );
              })}
            </div>
          </div>
        );
      })()}

      {/* Skip test coverage toggle */}
      <div className="flex items-center justify-between px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-700/20">
        <div>
          <span className="text-xs font-medium text-gray-700 dark:text-gray-300">Skip test coverage requirement</span>
          <p className="text-[10px] text-gray-400">Allow moving spec to Done without full test coverage</p>
        </div>
        <button
          aria-label="Skip test coverage requirement"
          disabled={operationPending || operationNeedsRead || !scenarioReadCurrent}
          onClick={() => void runScenarioOperation(() => onSpecUpdate({ skip_test_coverage: !spec.skip_test_coverage }), 'Coverage setting saved')}
          className={`relative w-10 h-5 rounded-full transition-colors ${spec.skip_test_coverage ? 'bg-amber-500' : 'bg-gray-300 dark:bg-gray-600'}`}
        >
          <span className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white transition-transform ${spec.skip_test_coverage ? 'translate-x-5' : ''}`} />
        </button>
      </div>

      {focusReceipt && <ScenarioReceiptDetails scenarios={scenarios} receipt={focusReceipt} />}

      {/* Scenarios list */}
      {scenarios.length === 0 && !adding && (
        <div className="text-center py-6">
          <FlaskConical size={32} className="mx-auto text-gray-300 dark:text-gray-600 mb-2" />
          <p className="text-sm text-gray-500 dark:text-gray-400">No test scenarios</p>
          <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">Define test scenarios to validate acceptance criteria</p>
        </div>
      )}

      {[...scenarios, ...Object.values({ ...methodDrafts, ...reportDrafts }).filter(draft => !scenarios.some(item => item.id === draft.id))].map((scenario) => {
        const missing = !scenarios.some(item => item.id === scenario.id);
        const isExpanded = expandedId === scenario.id;
        const linkedCards = scenario.linked_task_ids?.length || 0;
        return (
          <div key={scenario.id} data-readiness-ref={`scenario:${scenario.id}`} tabIndex={-1} className={`border rounded-lg overflow-hidden focus-visible:outline focus-visible:outline-2 focus-visible:outline-sky-500 ${linkedCards > 0 ? 'border-gray-200 dark:border-gray-700' : 'border-amber-300 dark:border-amber-700 border-dashed'}`}>
            <div
              className={`flex items-center gap-2 px-3 py-2 cursor-pointer ${linkedCards > 0 ? 'bg-gray-50 dark:bg-gray-700/50' : 'bg-amber-50/50 dark:bg-amber-900/10'}`}
              onClick={() => setExpandedId(isExpanded ? null : scenario.id)}
              data-readiness-expand aria-expanded={isExpanded}
            >
              <FlaskConical size={14} className={linkedCards > 0 ? 'text-violet-500 shrink-0' : 'text-amber-500 shrink-0'} />
              <span className="text-sm font-medium text-gray-900 dark:text-white truncate flex-1">{scenario.title}</span>
              {missing && <span className="text-xs text-amber-600">Removed · retained draft</span>}
              <ScenarioTypeBadge scenarioType={scenario.scenario_type} />
              <TestScenarioStatusBadge status={scenario.status} />
              <EvidenceBadge scenario={scenario} />
              {linkedCards > 0 ? (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300 font-medium">
                  {linkedCards} task{linkedCards !== 1 ? 's' : ''}
                </span>
              ) : (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-amber-100 text-amber-600 dark:bg-amber-900/40 dark:text-amber-400 font-medium animate-pulse">
                  no tasks
                </span>
              )}
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  void handleRemove(scenario.id);
                }}
                disabled={missing || scenarioSaving || operationPending || operationNeedsRead || Boolean(uncertainWrite) || adding || !scenarioReadCurrent}
                className="p-0.5 text-gray-400 hover:text-red-500"
                aria-label={`Delete test scenario ${scenario.title}`}
              >
                <Trash2 size={12} />
              </button>
            </div>
            {(isExpanded || Boolean(methodDrafts[scenario.id]) || Boolean(reportDrafts[scenario.id])) && (
              <div hidden={!isExpanded && !missing} className="px-3 py-2 space-y-2 text-sm">
                <ScenarioVerificationMethodEditor boardId={spec.board_id} specId={spec.id} version={spec.version} scenario={scenario}
                  canEdit={!spec.archived && spec.status === 'draft' && hasPermissionWithState(scenarioPermissions.has, 'spec.tests.edit', 'spec', spec.status)}
                  readCurrent={scenarioReadCurrent && !uncertainWrite && !operationPending && !operationNeedsRead}
                  missing={missing}
                  onDraftChange={dirty => setMethodDrafts(current => {
                    if (dirty) return current[scenario.id] ? current : { ...current, [scenario.id]: scenario };
                    if (!current[scenario.id]) return current;
                    const next = { ...current }; delete next[scenario.id]; return next;
                  })}
                  onReload={reloadScenarios}
                  onSaved={async () => { await reloadScenarios(); }} />
                {missing && <button type="button" className="btn btn-secondary text-xs" onClick={() => setMethodDrafts(current => {
                  const next = { ...current }; delete next[scenario.id]; return next;
                })}>Discard removed scenario draft</button>}
                {!missing && isExpanded && <>
                <VerificationReportDetails evidence={scenario.evidence} />
                <div className="grid grid-cols-3 gap-3">
                  <div>
                    <span className="text-[10px] font-semibold text-green-600 uppercase">Given</span>
                    <p className="text-xs text-gray-600 dark:text-gray-400 mt-0.5">{scenario.given}</p>
                  </div>
                  <div>
                    <span className="text-[10px] font-semibold text-blue-600 uppercase">When</span>
                    <p className="text-xs text-gray-600 dark:text-gray-400 mt-0.5">{scenario.when}</p>
                  </div>
                  <div>
                    <span className="text-[10px] font-semibold text-violet-600 uppercase">Then</span>
                    <p className="text-xs text-gray-600 dark:text-gray-400 mt-0.5">{scenario.then}</p>
                  </div>
                </div>
                {scenario.notes && (
                  <p className="text-xs text-gray-500 dark:text-gray-400 italic border-l-2 border-gray-300 dark:border-gray-600 pl-2">{scenario.notes}</p>
                )}
                {scenario.linked_criteria && scenario.linked_criteria.length > 0 && (
                  <div className="flex flex-wrap gap-1">
                    <span className="text-[10px] text-gray-400 mr-1">Validates:</span>
                    {scenario.linked_criteria.map((reference, i) => {
                      const label = getAcceptanceCriterionLabel(reference, criteria);
                      return (
                        <span key={`${reference}-${i}`} className="text-[10px] px-1.5 py-0.5 rounded bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-300">
                          {label.length > 60 ? label.slice(0, 57) + '...' : label}
                        </span>
                      );
                    })}
                  </div>
                )}
                {/* Linked tasks */}
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-[10px] text-gray-400">Linked tasks:</span>
                    <button
                      disabled={operationPending || operationNeedsRead || !scenarioReadCurrent}
                      onClick={() => setLinkingScenarioId(linkingScenarioId === scenario.id ? null : scenario.id)}
                      className="text-[10px] text-blue-500 hover:text-blue-600 dark:text-blue-400"
                    >
                      {linkingScenarioId === scenario.id ? 'Cancel' : '+ Link task'}
                    </button>
                  </div>
                  {scenario.linked_task_ids && scenario.linked_task_ids.length > 0 && (
                    <div className="space-y-1">
                      {scenario.linked_task_ids.map((taskId) => {
                        const card = spec.cards?.find((c) => c.id === taskId);
                        return (
                          <div key={taskId} className="flex items-center justify-between px-2 py-1 rounded bg-blue-50 dark:bg-blue-900/10 text-xs group">
                            <span className="text-gray-700 dark:text-gray-300 truncate">
                              {card ? card.title : taskId.slice(0, 12) + '...'}
                            </span>
                            <div className="flex items-center gap-1">
                              {card && (
                                <span className={`text-[10px] px-1 py-0.5 rounded ${
                                  CARD_STATUS_COLORS[card.status]
                                }`}>
                                  {card.status.replace('_', ' ')}
                                </span>
                              )}
                              <button
                                disabled={operationPending || operationNeedsRead || !scenarioReadCurrent}
                                onClick={() => void runScenarioOperation(() => api.unlinkTaskFromScenario(spec.id, scenario.id, taskId), 'Task unlinked')}
                                className="p-0.5 text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                title="Unlink task"
                              >
                                <Unlink size={10} />
                              </button>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}
                  {(!scenario.linked_task_ids || scenario.linked_task_ids.length === 0) && (
                    <p className="text-[10px] text-gray-400 italic">No tasks linked to this scenario yet</p>
                  )}
                  {/* Task picker */}
                  {linkingScenarioId === scenario.id && spec.cards && spec.cards.length > 0 && (
                    <div className="mt-1 border border-gray-200 dark:border-gray-700 rounded p-1.5 max-h-32 overflow-y-auto space-y-0.5">
                      {spec.cards
                        .filter((c) => !(scenario.linked_task_ids || []).includes(c.id))
                        .map((c) => (
                          <button
                            key={c.id}
                            disabled={operationPending || operationNeedsRead || !scenarioReadCurrent}
                            onClick={() => void runScenarioOperation(() => api.linkTaskToScenario(spec.id, scenario.id, c.id), 'Task linked')}
                            className="w-full text-left px-2 py-1 rounded text-[11px] text-gray-600 dark:text-gray-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 truncate flex items-center gap-1"
                          >
                            <Link size={9} className="shrink-0 text-gray-400" />
                            {c.title}
                          </button>
                        ))}
                      {spec.cards.filter((c) => !(scenario.linked_task_ids || []).includes(c.id)).length === 0 && (
                        <p className="text-[10px] text-gray-400 italic px-1">All cards already linked</p>
                      )}
                    </div>
                  )}
                </div>
                </>}
                {(isExpanded || Boolean(reportDrafts[scenario.id])) && <TestScenarioPolicyCompliance
                  readCurrent={scenarioReadCurrent && !operationPending && !operationNeedsRead && !uncertainWrite}
                  missing={missing}
                  onReportDraftChange={dirty => setReportDrafts(current => {
                    if (dirty) return current[scenario.id] ? current : { ...current, [scenario.id]: scenario };
                    if (!current[scenario.id]) return current;
                    const next = { ...current }; delete next[scenario.id]; return next;
                  })}
                  canSubmitVerificationReport={scenarioPermissions.has('spec.tests.execute')}
                  boardId={spec.board_id}
                  specId={spec.id}
                  specArchived={Boolean(spec.archived)}
                  scenario={scenario}
                  canReadPolicyCompliance={canReadPolicyCompliance}
                  refreshKey={policyRefreshKey}
                  onReload={reloadScenarios}
                />}
              </div>
            )}
          </div>
        );
      })}

      {/* Add scenario form */}
      {adding ? (
        <fieldset disabled={scenarioSaving || operationPending || operationNeedsRead || Boolean(uncertainWrite)} className="border border-violet-200 dark:border-violet-700 rounded-lg p-3 space-y-2 bg-violet-50/50 dark:bg-violet-900/10">
          <div className="flex gap-2">
            <input type="text" value={newTitle} onChange={(e) => setNewTitle(e.target.value)} placeholder="Scenario title" className="flex-1 px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" autoFocus />
            <select
              value={newType}
              onChange={(e) => {
                if (isSupportedScenarioType(e.target.value)) {
                  setNewType(e.target.value);
                }
              }}
              className="px-2 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
            >
              {SCENARIO_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>
          <div className="grid grid-cols-3 gap-2">
            <textarea value={newGiven} onChange={(e) => setNewGiven(e.target.value)} placeholder="Given: precondition..." className="px-2 py-1.5 border border-gray-300 rounded-lg text-xs dark:bg-gray-700 dark:border-gray-600 resize-none" rows={2} />
            <textarea value={newWhen} onChange={(e) => setNewWhen(e.target.value)} placeholder="When: action..." className="px-2 py-1.5 border border-gray-300 rounded-lg text-xs dark:bg-gray-700 dark:border-gray-600 resize-none" rows={2} />
            <textarea value={newThen} onChange={(e) => setNewThen(e.target.value)} placeholder="Then: expected result..." className="px-2 py-1.5 border border-gray-300 rounded-lg text-xs dark:bg-gray-700 dark:border-gray-600 resize-none" rows={2} />
          </div>
          <textarea value={newNotes} onChange={(e) => setNewNotes(e.target.value)} placeholder="Notes (optional)" className="w-full px-2 py-1.5 border border-gray-300 rounded-lg text-xs dark:bg-gray-700 dark:border-gray-600 resize-none" rows={1} />
          {/* Link to acceptance criteria */}
          {criteria.length > 0 && (
            <div>
              <span className="text-[10px] text-gray-500 dark:text-gray-400 block mb-1">Link to acceptance criteria:</span>
              <div className="flex flex-wrap gap-1">
                {criteria.map((criterion) => {
                  const isLinked = newCriteria.includes(criterion.reference);
                  return (
                    <button
                      key={criterion.key}
                      onClick={() => setNewCriteria(
                        isLinked
                          ? newCriteria.filter((reference) => reference !== criterion.reference)
                          : [...newCriteria, criterion.reference]
                      )}
                      className={`text-[10px] px-1.5 py-0.5 rounded transition-colors ${
                        isLinked
                          ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300 ring-1 ring-green-400'
                          : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400 hover:bg-gray-200'
                      }`}
                    >
                      {criterion.label.length > 60 ? criterion.label.slice(0, 57) + '...' : criterion.label}
                    </button>
                  );
                })}
              </div>
            </div>
          )}
          <div className="flex justify-end gap-2">
            <button onClick={() => setAdding(false)} className="btn btn-secondary text-xs">Cancel</button>
            <button onClick={() => void handleAdd()} disabled={scenarioSaving || !scenarioReadCurrent || scenarioBaseChanged || scenarioConflictVersion !== null || !newTitle.trim() || !newGiven.trim() || !newWhen.trim() || !newThen.trim()} className="btn btn-primary text-xs">{scenarioSaving ? 'Saving scenario…' : 'Add Scenario'}</button>
          </div>
        </fieldset>
      ) : (
        <button disabled={scenarioSaving || Boolean(uncertainWrite) || !scenarioReadCurrent} onClick={() => { setAdding(true); setScenarioError(''); setScenarioConflictVersion(null); setScenarioBase({ version: spec.version, edition: spec.edition, snapshot: spec.scenario_snapshot }); }} className="flex items-center gap-1 text-sm text-violet-600 dark:text-violet-400 hover:text-violet-800 dark:hover:text-violet-300">
          <Plus size={14} /> Add Test Scenario
        </button>
      )}
    </div>
  );
}

/* ============================================================
   History Tab
   ============================================================ */

function HistoryTab({ specId }: { specId: string }) {
  const api = useDashboardApi();
  const [entries, setEntries] = useState<SpecHistoryEntry[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => { load(); }, [specId]);

  const load = async () => {
    setLoading(true);
    try {
      const data = await api.listSpecHistory(specId);
      setEntries(data);
    } catch { /* ignore */ } finally { setLoading(false); }
  };

  return (
    <ActivityHistoryList
      entries={entries}
      loading={loading}
      versionLabel={(version) => ({
        text: `r${version}`,
        title: `Technical revision r${version}`,
      })}
    />
  );
}

/* ============================================================
   Q&A Tab
   ============================================================ */

function ChoiceOptionsDisplay({ choices, selected }: { choices: SpecQAItem['choices']; selected: string[] | null }) {
  if (!choices) return null;
  return (
    <div className="space-y-1 mt-1">
      {choices.map((opt) => {
        const isSelected = selected?.includes(opt.id);
        return (
          <div key={opt.id} className={`flex items-center gap-2 text-sm px-2 py-1 rounded ${
            isSelected
              ? 'bg-blue-100 text-blue-800 dark:bg-blue-900/40 dark:text-blue-300 font-medium'
              : 'text-gray-600 dark:text-gray-400'
          }`}>
            <span className={`w-4 h-4 rounded-full border-2 flex items-center justify-center shrink-0 ${
              isSelected ? 'border-blue-500 bg-blue-500' : 'border-gray-300 dark:border-gray-600'
            }`}>
              {isSelected && <CheckCircle2 size={12} className="text-white" />}
            </span>
            {opt.label}
          </div>
        );
      })}
    </div>
  );
}

function ChoiceAnswerForm({
  qa,
  onAnswer,
  onCancel,
  submitting = false,
}: {
  qa: SpecQAItem;
  onAnswer: (qaId: string, answer: string | null, selected: string[] | null) => void;
  onCancel: () => void;
  /** True while an answer for this question is in flight; blocks double submits. */
  submitting?: boolean;
}) {
  const [sel, setSel] = useState<string[]>([]);
  const [freeText, setFreeText] = useState('');

  const toggleOption = (optId: string) => {
    // `single_choice` is an alias of `choice` — accept both for single-select.
    const isSingle = qa.question_type === 'choice' || qa.question_type === 'single_choice';
    if (isSingle) {
      setSel([optId]);
    } else {
      setSel((prev) => prev.includes(optId) ? prev.filter((s) => s !== optId) : [...prev, optId]);
    }
  };

  const canSubmit = sel.length > 0 || (qa.allow_free_text && freeText.trim());

  return (
    <div className="mt-2 space-y-2">
      <div className="space-y-1">
        {qa.choices?.map((opt) => (
          <button
            key={opt.id}
            onClick={() => toggleOption(opt.id)}
            className={`flex items-center gap-2 w-full text-sm text-left px-2 py-1.5 rounded transition-colors ${
              sel.includes(opt.id)
                ? 'bg-blue-100 text-blue-800 dark:bg-blue-900/40 dark:text-blue-300'
                : 'bg-gray-50 dark:bg-gray-700/50 text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700'
            }`}
          >
            <span className={`w-4 h-4 rounded-full border-2 flex items-center justify-center shrink-0 ${
              sel.includes(opt.id) ? 'border-blue-500 bg-blue-500' : 'border-gray-300 dark:border-gray-600'
            }`}>
              {sel.includes(opt.id) && <CheckCircle2 size={10} className="text-white" />}
            </span>
            {opt.label}
          </button>
        ))}
      </div>
      {qa.allow_free_text && (
        <input
          type="text"
          value={freeText}
          onChange={(e) => setFreeText(e.target.value)}
          placeholder="Additional comment..."
          className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
        />
      )}
      <div className="flex justify-end gap-2">
        <button onClick={onCancel} className="btn btn-secondary text-xs">Cancel</button>
        <button
          onClick={() => onAnswer(qa.id, freeText.trim() || null, sel.length > 0 ? sel : null)}
          disabled={!canSubmit || submitting}
          className="btn btn-primary text-xs"
        >
          Submit
        </button>
      </div>
    </div>
  );
}

export function QATab({
  specId,
  mentionables,
  onChanged,
}: {
  specId: string;
  mentionables: Mentionable[];
  onChanged: () => void;
}) {
  const api = useDashboardApi();
  const [items, setItems] = useState<SpecQAItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [answeringId, setAnsweringId] = useState<string | null>(null);
  const [answerDraft, setAnswerDraft] = useState('');
  // Single-in-flight guard, keyed by qa_id. The ref is the authority (it is
  // updated synchronously, so two clicks in the same tick cannot both pass the
  // guard); the state exists only to drive the disabled rendering.
  const [answeringInFlight, setAnsweringInFlight] = useState<string | null>(null);
  const answeringInFlightRef = useRef<string | null>(null);

  // Ask question form
  const [askMode, setAskMode] = useState<'text' | 'choice'>('text');
  const [newQuestion, setNewQuestion] = useState('');
  const [newOptions, setNewOptions] = useState('');
  const [newMulti, setNewMulti] = useState(false);
  const [newAllowFreeText, setNewAllowFreeText] = useState(false);

  useEffect(() => { load(); }, [specId]);

  const load = async () => {
    setLoading(true);
    try {
      const data = await api.listSpecQA(specId);
      setItems(data);
    } catch { /* ignore */ } finally { setLoading(false); }
  };

  const handleAskText = async () => {
    if (!newQuestion.trim()) return;
    try {
      await api.createSpecQuestion(specId, newQuestion.trim());
      setNewQuestion('');
      toast.success('Question posted');
      await load();
      onChanged();
    } catch { toast.error('Failed to post question'); }
  };

  const handleAskChoice = async () => {
    if (!newQuestion.trim() || !newOptions.trim()) return;
    const optLabels = newOptions.split(',').map((o) => o.trim()).filter(Boolean);
    if (optLabels.length < 2) { toast.error('Need at least 2 options'); return; }
    try {
      await api.createSpecChoiceQuestion(specId, {
        question: newQuestion.trim(),
        question_type: (newMulti ? 'multi_choice' : 'choice') as 'choice' | 'multi_choice',
        choices: optLabels.map((label, i) => ({ id: `opt_${i}`, label })),
        allow_free_text: newAllowFreeText,
      });
      setNewQuestion(''); setNewOptions(''); setNewMulti(false); setNewAllowFreeText(false);
      toast.success('Choice question posted');
      await load();
      onChanged();
    } catch { toast.error('Failed to post choice question'); }
  };

  const handleAnswer = async (qaId: string, answer: string | null, selected: string[] | null) => {
    // Ignore a second submit for the same question while one is in flight.
    if (answeringInFlightRef.current === qaId) return;
    answeringInFlightRef.current = qaId;
    setAnsweringInFlight(qaId);
    try {
      await submitQaAnswerWithRetry({
        send: () => api.answerSpecQuestion(specId, qaId, answer || '', selected),
        reload: load,
      });
      setAnsweringId(null);
      setAnswerDraft('');
      toast.success('Answer posted');
      await load();
      onChanged();
    } catch (err) {
      toast.error(answerErrorMessage(err));
    } finally {
      answeringInFlightRef.current = null;
      setAnsweringInFlight(null);
    }
  };

  const handleTextAnswer = async (qaId: string) => {
    if (!answerDraft.trim()) return;
    await handleAnswer(qaId, answerDraft.trim(), null);
  };

  const handleDelete = async (qaId: string) => {
    if (!confirm('Delete this Q&A?')) return;
    try {
      await api.deleteSpecQuestion(specId, qaId);
      await load();
      onChanged();
    } catch { toast.error('Failed to delete'); }
  };

  if (loading) return <div className="text-sm text-gray-500 dark:text-gray-400 py-4 text-center">Loading Q&A...</div>;

  const isAnswered = (qa: SpecQAItem) => Boolean(qa.answered_at);
  const unanswered = items.filter((q) => !isAnswered(q));
  const answered = items.filter((q) => isAnswered(q));

  return (
    <div className="space-y-4">
      {/* Ask mode toggle + form */}
      <div className="space-y-2">
        <div className="flex items-center gap-2">
          <button
            onClick={() => setAskMode('text')}
            className={`text-xs px-2 py-1 rounded ${askMode === 'text' ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'}`}
          >
            Free Text
          </button>
          <button
            onClick={() => setAskMode('choice')}
            className={`text-xs px-2 py-1 rounded ${askMode === 'choice' ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400'}`}
          >
            Choice / Form
          </button>
        </div>

        {askMode === 'text' ? (
          <div className="flex gap-2">
            <MentionInput
              value={newQuestion}
              onChange={setNewQuestion}
              onSubmit={handleAskText}
              placeholder="Ask a question... (type @ to mention)"
              mentionables={mentionables}
              className="flex-1"
            />
            <button onClick={handleAskText} disabled={!newQuestion.trim()} className="btn btn-primary flex items-center gap-1 text-sm shrink-0">
              <Send size={14} /> Ask
            </button>
          </div>
        ) : (
          <div className="border border-blue-200 dark:border-blue-700 rounded-lg p-3 space-y-2 bg-blue-50/30 dark:bg-blue-900/10">
            <MentionInput
              value={newQuestion}
              onChange={setNewQuestion}
              placeholder="Question... (type @ to mention)"
              mentionables={mentionables}
              className="w-full"
            />
            <input type="text" value={newOptions} onChange={(e) => setNewOptions(e.target.value)} placeholder="Options (comma-separated): OAuth2, API Keys, Both" className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600" />
            <div className="flex items-center gap-4">
              <label className="flex items-center gap-1.5 text-xs text-gray-600 dark:text-gray-400">
                <input type="checkbox" checked={newMulti} onChange={(e) => setNewMulti(e.target.checked)} className="rounded" />
                Multi-select
              </label>
              <label className="flex items-center gap-1.5 text-xs text-gray-600 dark:text-gray-400">
                <input type="checkbox" checked={newAllowFreeText} onChange={(e) => setNewAllowFreeText(e.target.checked)} className="rounded" />
                Allow free text
              </label>
            </div>
            <div className="flex justify-end">
              <button onClick={handleAskChoice} disabled={!newQuestion.trim() || !newOptions.trim()} className="btn btn-primary flex items-center gap-1 text-sm">
                <Send size={14} /> Post Choice
              </button>
            </div>
          </div>
        )}
      </div>

      {items.length === 0 && (
        <div className="text-center py-6">
          <MessageCircleQuestion size={32} className="mx-auto text-gray-300 dark:text-gray-600 mb-2" />
          <p className="text-sm text-gray-500 dark:text-gray-400">No questions yet</p>
          <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">Ask questions to clarify spec requirements before work begins</p>
        </div>
      )}

      {/* Unanswered */}
      {unanswered.length > 0 && (
        <div>
          <h4 className="text-xs font-semibold text-amber-600 dark:text-amber-400 uppercase tracking-wide mb-2">
            Unanswered ({unanswered.length})
          </h4>
          <div className="space-y-2">
            {unanswered.map((qa) => (
              <div key={qa.id} className="border border-amber-200 dark:border-amber-700/50 rounded-lg p-3 bg-amber-50/50 dark:bg-amber-900/10">
                <div className="flex items-start justify-between gap-2">
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <p className="text-sm text-gray-900 dark:text-white">{qa.question}</p>
                      {qa.question_type !== 'text' && (
                        <span className="text-[10px] px-1 py-0.5 rounded bg-blue-100 text-blue-600 dark:bg-blue-900/40 dark:text-blue-300">
                          {qa.question_type === 'multi_choice' ? 'multi-select' : 'single-select'}
                        </span>
                      )}
                    </div>
                    {qa.question_type !== 'text' && qa.choices && (
                      <div className="mt-1 space-y-0.5">
                        {qa.choices.map((opt) => (
                          <div key={opt.id} className="text-xs text-gray-500 dark:text-gray-400 pl-2">
                            &bull; {opt.label}
                          </div>
                        ))}
                      </div>
                    )}
                    <span className="text-[10px] text-gray-400 mt-1 block">
                      Asked by {qa.asked_by.slice(0, 12)}... &middot; {new Date(qa.created_at).toLocaleDateString()}
                    </span>
                  </div>
                  <button onClick={() => handleDelete(qa.id)} className="p-1 text-gray-400 hover:text-red-500 shrink-0">
                    <Trash2 size={12} />
                  </button>
                </div>
                {answeringId === qa.id ? (
                  qa.question_type !== 'text' ? (
                    <ChoiceAnswerForm qa={qa} onAnswer={handleAnswer} onCancel={() => setAnsweringId(null)} submitting={answeringInFlight === qa.id} />
                  ) : (
                    <div className="mt-2 flex gap-2">
                      <MentionInput
                        value={answerDraft}
                        onChange={setAnswerDraft}
                        onSubmit={() => handleTextAnswer(qa.id)}
                        placeholder="Type your answer... (@ to mention)"
                        mentionables={mentionables}
                        className="flex-1"
                        autoFocus
                      />
                      <button onClick={() => handleTextAnswer(qa.id)} disabled={!answerDraft.trim() || answeringInFlight === qa.id} className="btn btn-primary text-xs">Answer</button>
                      <button onClick={() => { setAnsweringId(null); setAnswerDraft(''); }} className="btn btn-secondary text-xs">Cancel</button>
                    </div>
                  )
                ) : (
                  <button
                    onClick={() => { setAnsweringId(qa.id); setAnswerDraft(''); }}
                    className="mt-2 text-xs text-blue-600 dark:text-blue-400 hover:underline"
                  >
                    Answer this question
                  </button>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Answered */}
      {answered.length > 0 && (
        <div>
          <h4 className="text-xs font-semibold text-green-600 dark:text-green-400 uppercase tracking-wide mb-2">
            Answered ({answered.length})
          </h4>
          <div className="space-y-2">
            {answered.map((qa) => (
              <div key={qa.id} className="border border-gray-200 dark:border-gray-700 rounded-lg p-3">
                <div className="flex items-start justify-between gap-2">
                  <div className="flex items-center gap-2">
                    <p className="text-sm text-gray-900 dark:text-white">{qa.question}</p>
                    {qa.question_type !== 'text' && (
                      <span className="text-[10px] px-1 py-0.5 rounded bg-blue-100 text-blue-600 dark:bg-blue-900/40 dark:text-blue-300">
                        {qa.question_type === 'multi_choice' ? 'multi' : 'choice'}
                      </span>
                    )}
                  </div>
                  <button onClick={() => handleDelete(qa.id)} className="p-1 text-gray-400 hover:text-red-500 shrink-0">
                    <Trash2 size={12} />
                  </button>
                </div>
                <span className="text-[10px] text-gray-400 block mt-0.5">Asked by {qa.asked_by.slice(0, 12)}...</span>
                <div className="mt-2 pl-3 border-l-2 border-green-300 dark:border-green-600">
                  {qa.question_type !== 'text' && qa.choices && (
                    <ChoiceOptionsDisplay choices={qa.choices} selected={qa.selected} />
                  )}
                  {qa.answer && <p className="text-sm text-gray-700 dark:text-gray-300 mt-1">{qa.answer}</p>}
                  <span className="text-[10px] text-gray-400 block mt-0.5">
                    Answered by {qa.answered_by?.slice(0, 12)}... &middot; {qa.answered_at ? new Date(qa.answered_at).toLocaleDateString() : ''}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/* ============================================================
   Knowledge Base Tab
   ============================================================ */

/* ============================================================
   Validation Error Display — parses gate errors into readable items
   ============================================================ */

/* ============================================================
   Main SpecModal
   ============================================================ */

export function SpecModal({
  specId,
  boardId: _boardId,
  initialTab,
  focusProjectNodeId,
  focusReadinessRef,
  onClose,
  onEscape,
  onChanged,
}: SpecModalProps) {
  const api = useDashboardApi();
  const modalStack = useOptionalModalStack();
  const currentBoard = useCurrentBoard();
  const perms = usePermissions(_boardId || currentBoard?.id);
  const canStructured = (
    entityType: SpecStructuredEntityType,
    operation: SpecStructuredEntityOperation,
  ) => perms.has(`spec.structured_entity.${entityType}.${operation}`);
  const canReadIR = perms.has('spec.integration_requirements.read');
  const canCreateIR = canStructured('integration_requirement', 'create');
  const canEditIR = canStructured('integration_requirement', 'update');
  const canDeleteIR = canStructured('integration_requirement', 'revoke');
  const canLinkIRTasks = canStructured('integration_requirement', 'link_task') && perms.has('card.link_to.ir');
  const canReadOR = perms.has('spec.observability_requirements.read');
  const canCreateOR = canStructured('observability_requirement', 'create');
  const canEditOR = canStructured('observability_requirement', 'update');
  const canDeleteOR = canStructured('observability_requirement', 'revoke');
  const canLinkORTasks = canStructured('observability_requirement', 'link_task') && perms.has('card.link_to.or');
  const canEditCoverageFlags = perms.has('spec.entity.edit_coverage_flags');
  const canReadQuality = perms.has('spec.quality.read');
  const canReadChecklist = perms.has('spec.checklist.read');
  const canExecuteChecklist = perms.has('spec.checklist.execute');
  const canReadSpecValidation = perms.has('spec.validation.read');
  const canReadDecomposition = perms.has('spec.evaluations.read');
  const canReadDependencies = perms.has('spec.entity.read');
  const canReadCoverage = ['board.read', 'spec.entity.read', 'card.entity.read', 'spec.tests.read',
    'spec.integration_requirements.read', 'spec.observability_requirements.read'].every(flag => perms.has(flag));
  const canReadProjectStructure = perms.has('spec.entity.read');
  const canReadPolicyCompliance = perms.has(
    'guidelines.assessments.read',
  );
  const { canReadProjection: canReadCodeTraceability } =
    useCodeTraceabilityAuthority(_boardId || currentBoard?.id);
  const [spec, setSpec] = useState<Spec | null>(null);
  const hasProjectStructurePermission = (operation: SpecStructuredEntityOperation) => (
    hasPermissionWithState(
      perms.has,
      `spec.structured_entity.project_structure_node.${operation}`,
      'spec',
      spec?.status,
    )
  );
  const canMutateProjectStructure = (operation: SpecStructuredEntityOperation) => (
    canMutateProjectStructureInStatus(
      hasProjectStructurePermission(operation),
      spec?.status,
    )
  );
  const canRelateProjectStructure = (operation: SpecStructuredEntityOperation) => (
    canRelateProjectStructureInStatus(
      hasProjectStructurePermission(operation),
      spec?.status,
    )
  );
  const canCreateProjectStructure = canMutateProjectStructure('create');
  const canUpdateProjectStructure = canMutateProjectStructure('update');
  const canRevokeProjectStructure = canMutateProjectStructure('revoke');
  const canRestoreProjectStructure = canMutateProjectStructure('restore');
  const canReorderProjectStructure = canMutateProjectStructure('reorder');
  const canLinkProjectStructureTask = canRelateProjectStructure('link_task');
  const canUnlinkProjectStructureTask = canRelateProjectStructure('unlink_task');
  const canLinkProjectStructureTest = canRelateProjectStructure('link_test');
  const canUnlinkProjectStructureTest = canRelateProjectStructure('unlink_test');
  // Evidence changes alter the authored AS-IS boundary and remain Draft-only.
  const canLinkProjectStructureEvidence = canMutateProjectStructure('link_evidence');
  const canUnlinkProjectStructureEvidence = canMutateProjectStructure('unlink_evidence');
  const showProjectStructure = shouldShowProjectStructureTab(
    canReadProjectStructure,
  );
  const canEditCodeEvidenceCoverage = !spec?.archived && spec?.status === 'draft' && hasPermissionWithState(
    perms.has,
    'spec.entity.edit_coverage_flags',
    'spec',
    spec.status,
  );
  const canManageDependencies = hasPermissionWithState(
    perms.has,
    'spec.entity.manage_dependencies',
    'spec',
    spec?.status,
  );
  const specAnchorTexts = useMemo(() => {
    if (!spec) return undefined;
    const withOrdinal = (prefix: string, ordinal: number, text: string) => {
      const normalized = text.trim();
      if (new RegExp(`^${prefix}[-\\s]?\\d+\\s*:`, 'iu').test(normalized)) {
        return normalized;
      }
      return `${prefix}-${ordinal}: ${normalized}`;
    };
    const map: Record<string, string> = {
      [spec.id]: `Spec: ${spec.title}`,
      title: `Title: ${spec.title}`,
      description: spec.description?.trim()
        ? `Description: ${spec.description.trim()}`
        : 'Description',
      context: spec.context?.trim()
        ? `Context: ${spec.context.trim()}`
        : 'Context',
    };
    const collect = (items: unknown, prefix: 'FR' | 'AC' | 'TR') => {
      if (!Array.isArray(items)) return;
      let ordinal = 0;
      for (const item of items) {
        if (
          item
          && typeof item === 'object'
          && typeof (item as { id?: unknown }).id === 'string'
          && typeof (item as { text?: unknown }).text === 'string'
          && (
            typeof (item as { status?: unknown }).status !== 'string'
            || (item as { status: string }).status === 'active'
          )
        ) {
          ordinal += 1;
          map[(item as { id: string }).id] = withOrdinal(
            prefix,
            ordinal,
            (item as { text: string }).text,
          );
        }
      }
    };
    collect(spec.functional_requirements, 'FR');
    collect(spec.acceptance_criteria, 'AC');
    collect(spec.technical_requirements, 'TR');
    for (const [index, item] of (spec.business_rules ?? [])
      .filter((entry) => (entry.status ?? 'active') === 'active').entries()) {
      map[item.id] = withOrdinal('BR', index + 1, `${item.title}: ${item.rule}`);
    }
    for (const [index, item] of (spec.api_contracts ?? [])
      .filter((entry) => (entry.status ?? 'active') === 'active').entries()) {
      map[item.id] = withOrdinal(
        'API',
        index + 1,
        `${item.method} ${item.path}: ${item.description}`,
      );
    }
    for (const [index, item] of (spec.integration_requirements ?? [])
      .filter((entry) => entry.status === 'active').entries()) {
      map[item.id] = withOrdinal('IR', index + 1, `${item.title}: ${item.description}`);
    }
    for (const [index, item] of (spec.observability_requirements ?? [])
      .filter((entry) => entry.status === 'active').entries()) {
      map[item.id] = withOrdinal('OR', index + 1, `${item.title}: ${item.description}`);
    }
    for (const [index, item] of (spec.decisions ?? [])
      .filter((entry) => entry.status === 'active').entries()) {
      map[item.id] = withOrdinal('DEC', index + 1, `${item.title}: ${item.rationale}`);
    }
    for (const [index, item] of (spec.test_scenarios ?? []).entries()) {
      map[item.id] = withOrdinal(
        'TS',
        index + 1,
        `${item.title}: Given ${item.given} When ${item.when} Then ${item.then}`,
      );
    }
    for (const item of spec.qa_items ?? []) {
      map[item.id] = item.answer?.trim()
        ? `${item.question} — ${item.answer}`
        : item.question;
    }
    return map;
  }, [spec]);
  const [loading, setLoading] = useState(true);
  const [movingTo, setMovingTo] = useState<SpecStatus | null>(null);
  const [nextStatuses, setNextStatuses] = useState<SpecStatus[]>([]);
  const [
    policyTransitionPreview,
    setPolicyTransitionPreview,
  ] = useState<PolicyTransitionPreviewLoadState>({
    status: 'loading',
    transitions: [],
    error: null,
  });
  const [
    policyTransitionRejection,
    setPolicyTransitionRejection,
  ] = useState<PolicyTransitionRejection | null>(null);
  const lastTransitionSubjectKey = useRef<string | null>(null);
  const transitionRequestId = useRef(0);
  const specReloadGeneration = useRef(0);
  const currentSpecId = useRef(specId);
  currentSpecId.current = specId;
  const [activeTab, setActiveTab] = useState<ModalTab>(initialTab ?? 'details');
  const nativeReferenceRoot = useRef<HTMLDivElement>(null);
  const [readinessReference, setReadinessReference] = useState(focusReadinessRef);
  useNativeReferenceFocus(nativeReferenceRoot, readinessReference, `${specId}:${loading}:${activeTab}`);
  useEffect(() => {
    const origin = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    return () => { if (origin?.isConnected) origin.focus(); };
  }, [specId]);
  const [resourceTab, setResourceTab] =
    useState<ResourceSubTab>('mockups');
  const [referenceTab, setReferenceTab] =
    useState<ReferenceSubTab>('origin');
  const [resourceGateRefreshKey, setResourceGateRefreshKey] =
    useState(0);
  const [
    testScenarioPolicyRefreshKey,
    setTestScenarioPolicyRefreshKey,
  ] = useState(0);
  const [detailsStructuredEditor, setDetailsStructuredEditor] = useState<{
    tab: ModalTab;
    mode: 'add' | 'edit';
    entityId?: string;
    token: number;
  } | null>(null);
  const [expanded, setExpanded] = useState(false);
  const [showValidateModal, setShowValidateModal] = useState(false);
  const [validateResult, setValidateResult] = useState<{ success: boolean; error: string | null }>({ success: false, error: null });
  const [validating, setValidating] = useState(false);
  const [cancelDialogOpen, setCancelDialogOpen] = useState(false);
  const [validationHistoryRefreshKey, setValidationHistoryRefreshKey] =
    useState(0);

  useEscapeToClose(onEscape ?? onClose);
  useEscapeToClose(() => setShowValidateModal(false), {
    enabled: showValidateModal,
    canClose: !validating,
    priority: 10,
  });

  useEffect(() => {
    const validationAvailable =
      canReadQuality
      || canReadPolicyCompliance
      || canReadChecklist
      || canReadSpecValidation
      || canReadDecomposition;
    if (
      activeTab === 'validation' &&
      !validationAvailable
    ) {
      setActiveTab('details');
    }
  }, [
    activeTab,
    canReadChecklist,
    canReadPolicyCompliance,
    canReadQuality,
    canReadSpecValidation,
    canReadDecomposition,
  ]);

  useEffect(() => {
    if (activeTab === 'evidence-matrix' && !canReadCodeTraceability) {
      setActiveTab('details');
    }
  }, [activeTab, canReadCodeTraceability]);

  useEffect(() => {
    if (activeTab === 'dependencies' && !canReadDependencies) {
      setActiveTab('details');
    }
  }, [activeTab, canReadDependencies]);

  useEffect(() => {
    if (spec && activeTab === 'project-structure' && !showProjectStructure) {
      setActiveTab('details');
    }
  }, [activeTab, showProjectStructure, spec]);

  // Build mentionables from board agents + owner
  const mentionables: Mentionable[] = [];
  if (currentBoard) {
    if (currentBoard.owner_id) {
      mentionables.push({ id: currentBoard.owner_id, name: 'Owner', type: 'user' });
    }
    for (const agent of currentBoard.agents) {
      mentionables.push({ id: agent.id, name: agent.name, type: 'agent' });
    }
  }

  const [parentIdeation, setParentIdeation] = useState<{ id: string; title: string; version: number } | null>(null);
  const [parentRefinement, setParentRefinement] = useState<{ id: string; title: string; version: number } | null>(null);
  const [viewingIdeationId, setViewingIdeationId] = useState<string | null>(null);
  const [viewingRefinementId, setViewingRefinementId] = useState<string | null>(null);
  const [viewingSpecId, setViewingSpecId] = useState<string | null>(null);
  const [dependencyDirectionRequest, setDependencyDirectionRequest] = useState<{
    direction: SpecDependencyDirection;
    token: number;
  }>({ direction: 'depends_on', token: 0 });

  const openIdeationReference = (id: string) => {
    if (modalStack) {
      modalStack.push({ type: 'ideation', id });
    } else {
      setViewingIdeationId(id);
    }
  };

  const openRefinementReference = (id: string) => {
    if (modalStack) {
      modalStack.push({ type: 'refinement', id });
    } else {
      setViewingRefinementId(id);
    }
  };

  const openSpecReference = (id: string) => {
    if (modalStack) {
      modalStack.push({ type: 'spec', id });
    } else {
      setViewingSpecId(id);
    }
  };

  const openDependencies = (direction: SpecDependencyDirection) => {
    setDependencyDirectionRequest((current) => ({
      direction,
      token: current.token + 1,
    }));
    setActiveTab('dependencies');
  };

  useEffect(() => {
    void loadSpec();
    return () => {
      specReloadGeneration.current += 1;
    };
  }, [specId]);

  const loadAllowedTransitions = useCallback(async (
    data: Spec,
    isCurrent: () => boolean = () => currentSpecId.current === data.id,
  ) => {
    if (!isCurrent()) {
      return;
    }
    const requestId = transitionRequestId.current + 1;
    transitionRequestId.current = requestId;
    lastTransitionSubjectKey.current = [
      data.id,
      data.version,
      data.status,
    ].join(':');
    setPolicyTransitionRejection(null);
    setNextStatuses([]);
    setPolicyTransitionPreview({
      status: 'loading',
      transitions: [],
      error: null,
    });
    try {
      const response = await api.getAllowedTransitions(data.board_id, {
        entity_type: 'spec',
        entity_id: data.id,
      });
      if (transitionRequestId.current !== requestId || !isCurrent()) {
        return;
      }
      const transitions = requirePolicyTransitionEnvelope(response, {
        boardId: data.board_id,
        entityType: 'spec',
        subjectId: data.id,
        currentStatus: data.status,
      });
      setPolicyTransitionPreview({
        status: 'ready',
        transitions,
        error: null,
      });
      setNextStatuses(
        transitions
          .filter(isAllowedTransitionActionable)
          .map((item) => item.to_status)
          .filter((status): status is SpecStatus => SPEC_STATUSES.includes(status as SpecStatus))
      );
    } catch (caught) {
      if (transitionRequestId.current !== requestId || !isCurrent()) {
        return;
      }
      setNextStatuses([]);
      setPolicyTransitionPreview({
        status: 'error',
        transitions: [],
        error: caught instanceof Error
          ? caught.message
          : 'The server transition contract could not be loaded.',
      });
    }
  }, [api]);

  useEffect(() => {
    if (!spec) {
      return;
    }
    const subjectKey = [
      spec.id,
      spec.version,
      spec.status,
    ].join(':');
    if (lastTransitionSubjectKey.current === subjectKey) {
      return;
    }
    void loadAllowedTransitions(spec);
  }, [loadAllowedTransitions, spec]);

  const reloadSpecSnapshot = async ({
    includeRelated,
    notifyChanged,
    showLoading,
    minimumVersion = 0,
  }: SpecSnapshotReloadOptions): Promise<Spec | null> => {
    const requestedSpecId = specId;
    const generation = specReloadGeneration.current + 1;
    specReloadGeneration.current = generation;
    const isCurrent = () => (
      specReloadGeneration.current === generation
      && currentSpecId.current === requestedSpecId
    );

    setLoading(showLoading);
    try {
      const data = await api.getSpec(requestedSpecId);
      if (!isCurrent()) {
        return null;
      }
      const expectedBoardId = _boardId || (spec?.id === requestedSpecId ? spec.board_id : undefined);
      if (data.id !== requestedSpecId || (expectedBoardId && data.board_id !== expectedBoardId)) {
        throw new Error('The Spec response does not match the requested identity.');
      }
      if (data.version < minimumVersion) {
        throw new Error('The Spec response predates the confirmed change. Reload the current Spec.');
      }
      setSpec(data);
      await loadAllowedTransitions(data, isCurrent);
      if (!isCurrent()) {
        return null;
      }

      if (includeRelated) {
        if (data.ideation_id) {
          try {
            const ideation = await api.getIdeation(data.ideation_id);
            if (!isCurrent()) return null;
            setParentIdeation({ id: ideation.id, title: ideation.title, version: ideation.version });
          } catch {
            if (!isCurrent()) return null;
            setParentIdeation(null);
          }
        } else {
          setParentIdeation(null);
        }
        if (data.refinement_id) {
          try {
            const refinement = await api.getRefinement(data.refinement_id);
            if (!isCurrent()) return null;
            setParentRefinement({ id: refinement.id, title: refinement.title, version: refinement.version });
          } catch {
            if (!isCurrent()) return null;
            setParentRefinement(null);
          }
        } else {
          setParentRefinement(null);
        }
      }

      if (notifyChanged && isCurrent()) {
        onChanged();
      }
      return isCurrent() ? data : null;
    } catch (error) {
      if (!isCurrent()) {
        return null;
      }
      if (showLoading) {
        toast.error('Failed to load spec');
        return null;
      }
      throw error;
    } finally {
      if (isCurrent()) {
        setLoading(false);
      }
    }
  };

  const loadSpec = async () => {
    await reloadSpecSnapshot({
      includeRelated: true,
      notifyChanged: false,
      showLoading: true,
    });
  };

  const reloadSpecAfterStructuredEdit = async () => reloadSpecSnapshot({
    includeRelated: false,
    notifyChanged: true,
    showLoading: false,
  });

  const reloadSpecAfterDependencyMutation = async (minimumVersion?: number) => {
    await reloadWorkspaceSnapshot(minimumVersion);
    onChanged();
  };

  const applyImpactAwareOperation = async (
    entityType: SpecStructuredEntityType,
    entityId: string,
    operation: Extract<SpecStructuredEntityOperation, 'revoke' | 'supersede' | 'reorder'>,
    version: number | null,
    payload: Record<string, unknown> = {},
  ): Promise<number | null> => {
    const preview = await api.previewSpecEntityImpact(specId, entityType, entityId, operation, {
      payload,
      expected_spec_version: version,
    });
    const impacted = preview.impact_report?.impacted_refs || [];
    let ackToken = preview.ack_token || preview.impact_report?.ack_token || null;
    if (impacted.length > 0) {
      const counts = Object.entries(preview.impact_report?.counts_by_type || {})
        .map(([type, count]) => `${count} ${type}`)
        .join(', ');
      const accepted = window.confirm(
        `This ${operation.replace('_', ' ')} impacts ${counts || `${impacted.length} item(s)`}. Continue?`,
      );
      if (!accepted) {
        throw new Error('Operation cancelled');
      }
    }

    const result = await api.operateSpecEntity(specId, entityType, entityId, operation, {
      payload,
      expected_spec_version: version,
      ack_token: ackToken,
    });

    if (!result.success && result.error_code === 'impact_ack_required') {
      ackToken = result.ack_token || result.impact_report?.ack_token || null;
      const impactedRefs = result.impact_report?.impacted_refs || [];
      const accepted = window.confirm(
        `This ${operation.replace('_', ' ')} impacts ${impactedRefs.length} item(s). Continue?`,
      );
      if (!accepted || !ackToken) {
        throw new Error('Operation cancelled');
      }
      const acknowledged = await api.operateSpecEntity(specId, entityType, entityId, operation, {
        payload,
        expected_spec_version: version,
        ack_token: ackToken,
      });
      if (!acknowledged.success) {
        throw specEntityMutationError(acknowledged, 'Structured operation failed');
      }
      return acknowledged.spec_version;
    }

    if (!result.success) {
      throw specEntityMutationError(result, 'Structured operation failed');
    }
    return result.spec_version;
  };

  const saveTextRequirement = async (
    entityType: 'functional_requirement' | 'acceptance_criterion',
    id: string | null,
    draft: TextRequirementDraft,
    expectedVersion: number,
  ) => {
    if (!spec) throw new Error('Current Spec is unavailable.');
    const result = id
      ? await api.updateSpecEntity(specId, entityType, id, { ...draft }, expectedVersion)
      : await api.createSpecEntity(specId, entityType, { ...draft }, expectedVersion);
    if (!result.success) throw specEntityMutationError(result, 'Could not save requirement');
    if (currentSpecId.current !== specId) return;
    // The write already succeeded. A read failure must not offer a duplicate create.
    try { await reloadSpecAfterStructuredEdit(); }
    catch { toast.error('Requirement saved. Refresh the Spec to see its current state.'); }
  };

  const syncStructuredCollection = async (
    field: StructuredCollectionField,
    currentItems: StructuredObjectEntity[] | null,
    nextItems: StructuredObjectEntity[],
    expectedVersion: number,
  ) => {
    if (!spec) throw new Error('Current Spec is unavailable.');
    if (spec.version !== expectedVersion) {
      throw Object.assign(new Error('The Spec changed. Review the current base before saving.'), { code: 'version_conflict' });
    }
    const completed: string[] = [];
    try {
      let version: number | null = expectedVersion;
      const entityType = STRUCTURED_ENTITY_BY_FIELD[field];
      const currentById = new Map((currentItems || []).map((item) => [item.id, item]));
      const nextById = new Map(nextItems.map((item) => [item.id, item]));

      for (const current of currentItems || []) {
        const currentStatus = String((stableEntityPayload(current).status as string | undefined) || 'active');
        if (currentStatus !== 'active' && !nextById.has(current.id)) {
          continue;
        }
        if (!nextById.has(current.id)) {
          version = await applyImpactAwareOperation(entityType, current.id, 'revoke', version);
          completed.push(`revoke ${current.id}`);
        }
      }

      for (const next of nextItems) {
        const current = currentById.get(next.id);
        if (!current) {
          const result = await api.createSpecEntity(specId, entityType, stableEntityPayload(next), version);
          if (!result.success) throw specEntityMutationError(result, 'Structured create failed');
          version = result.spec_version;
          completed.push(`create ${next.id}`);
          continue;
        }

        const currentPayload = stableEntityPayload(current);
        const nextPayload = stableEntityPayload(next);
        const currentStatus = String(currentPayload.status || 'active');
        const nextStatus = String(nextPayload.status || 'active');
        if (currentStatus !== nextStatus) {
          if (nextStatus === 'revoked') {
            version = await applyImpactAwareOperation(entityType, next.id, 'revoke', version);
          } else if (nextStatus === 'superseded') {
            version = await applyImpactAwareOperation(entityType, next.id, 'supersede', version, {
              supersedes_decision_id: nextPayload.supersedes_decision_id,
            });
          } else if (nextStatus === 'active') {
            const result = await api.operateSpecEntity(specId, entityType, next.id, 'restore', {
              expected_spec_version: version,
            });
            if (!result.success) throw specEntityMutationError(result, 'Structured restore failed');
            version = result.spec_version;
          }
          completed.push(`${nextStatus} ${next.id}`);
          delete currentPayload.status;
          delete nextPayload.status;
        }

        if (JSON.stringify(currentPayload) !== JSON.stringify(nextPayload)) {
          const result = await api.updateSpecEntity(specId, entityType, next.id, nextPayload, version);
          if (!result.success) throw specEntityMutationError(result, 'Structured update failed');
          version = result.spec_version;
          completed.push(`update ${next.id}`);
        }
      }

      const currentIds = (currentItems || []).map((item) => item.id);
      const nextIds = nextItems.map((item) => item.id);
      const sameSet = currentIds.length === nextIds.length && currentIds.every((id) => nextIds.includes(id));
      const sameOrder = currentIds.length === nextIds.length && currentIds.every((id, index) => id === nextIds[index]);
      if (sameSet && !sameOrder && nextIds.length > 0) {
        version = await applyImpactAwareOperation(entityType, '__collection__', 'reorder', version, {
          ordered_entity_ids: nextIds,
        });
        completed.push('reorder');
      }

    } catch (error) {
      if (completed.length) {
        try { await reloadSpecAfterStructuredEdit(); } catch { /* Preserve the confirmed write report even if reading fails. */ }
        throw Object.assign(new Error(`Some changes were saved (${completed.join(', ')}). ${error instanceof Error ? error.message : 'The remaining change failed.'} Your draft is preserved. Refresh and reopen the editor to review the saved state before another submission.`), { code: 'partial_collection_write' });
      }
      throw error;
    }
    // Writes succeeded. A subsequent read failure must never offer another create.
    if (currentSpecId.current !== specId) return;
    try { await reloadSpecAfterStructuredEdit(); }
    catch { toast.error('Changes saved. Refresh the Spec to see its current state.'); }
  };

  const boardSettings = (currentBoard?.settings || {}) as BoardSettings;
  const requireSpecValidation = boardSettings.require_spec_validation ?? true;
  const [showSubmitValidationModal, setShowSubmitValidationModal] = useState(false);
  const [permissionCheckPending, setPermissionCheckPending] = useState(false);
  const [workspaceSyncError, setWorkspaceSyncError] = useState<string | null>(null);
  const [workspaceReadPending, setWorkspaceReadPending] = useState(false);
  const workspaceLoadGeneration = useRef(0);
  const validationLive = ['validation', 'frs', 'acs', 'rules', 'contracts', 'ors', 'trs', 'irs', 'decisions', 'tests', 'project-structure', 'coverage', 'references', 'dependencies', 'resources'].includes(activeTab) || showSubmitValidationModal;
  useEffect(() => {
    setPermissionCheckPending(false);
    setWorkspaceReadPending(false);
    return () => {
      workspaceLoadGeneration.current += 1;
      specReloadGeneration.current += 1;
    };
  }, [specId, validationLive]);
  const syncState = useWorkspaceRevisions({
    boardId: validationLive ? spec?.board_id : undefined,
    subjects: [{ subject_type: 'spec', subject_id: specId }],
    onAccessLost: () => {
      workspaceLoadGeneration.current += 1;
      specReloadGeneration.current += 1;
      setSpec(null);
      setShowSubmitValidationModal(false);
      onClose();
    },
    onChange: async ({ authorityChanged }) => {
      if (!spec) return;
      const generation = ++workspaceLoadGeneration.current;
      const id = spec.id;
      const current = () => generation === workspaceLoadGeneration.current && currentSpecId.current === id;
      try {
        setWorkspaceSyncError(null);
        setWorkspaceReadPending(true);
        if (authorityChanged) {
          setPermissionCheckPending(true);
          const permissions = await refreshBoardPermissions(spec.board_id);
          if (!current()) return;
          if (permissions.board_id !== spec.board_id) throw new Error('Permission response does not match the Board.');
          if (!hasEffectivePermission(permissions, 'spec.entity.read')) {
            setSpec(null); setShowSubmitValidationModal(false); onClose(); return;
          }
        }
        await reloadSpecSnapshot({ includeRelated: activeTab === 'references', notifyChanged: false, showLoading: false });
        if (!current()) return;
        setValidationHistoryRefreshKey(value => value + 1);
        setTestScenarioPolicyRefreshKey(value => value + 1);
        setResourceGateRefreshKey(value => value + 1);
      } catch (error) {
        if (!current()) return;
        if (authorityChanged || (error instanceof AuthenticatedFetchError && [401, 403, 404].includes(error.status))) {
          setSpec(null); setShowSubmitValidationModal(false); onClose();
        } else setWorkspaceSyncError('The Spec changed, but its current data could not be loaded. Refresh to retry.');
      } finally {
        if (current()) { setPermissionCheckPending(false); setWorkspaceReadPending(false); }
      }
    },
  });
  const reloadWorkspaceSnapshot = async (minimumVersion = spec?.version ?? 0) => {
    const generation = ++workspaceLoadGeneration.current;
    const id = specId;
    const current = () => generation === workspaceLoadGeneration.current && currentSpecId.current === id;
    setWorkspaceReadPending(true);
    try {
      const updated = await reloadSpecSnapshot({ includeRelated: activeTab === 'references', notifyChanged: false, showLoading: false, minimumVersion: Math.max(minimumVersion, spec?.version ?? 0) });
      if (!updated || !current()) throw new Error('The workspace reload was superseded. Refresh to confirm its current state.');
      setWorkspaceSyncError(null);
    } catch (error) {
      if (current()) {
        if (error instanceof AuthenticatedFetchError && [401, 403, 404].includes(error.status)) {
          setSpec(null); onClose();
        } else setWorkspaceSyncError('The current Spec could not be loaded. Unsaved input is preserved; refresh to retry.');
      }
      throw error;
    } finally {
      if (current()) setWorkspaceReadPending(false);
    }
  };
  const reloadResources = async (minimumVersion?: number) => {
    const origin = specId;
    await reloadWorkspaceSnapshot(minimumVersion);
    if (currentSpecId.current !== origin) throw new Error('The resource owner changed during reload.');
    setResourceGateRefreshKey(value => value + 1);
    onChanged();
  };
  const resourcesReadCurrent = !permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current';
  const specValidationSubmissionRequired = (
    policyTransitionPreview.status === 'ready'
    && policyTransitionPreview.transitions.some(
      requiresSpecValidationSubmission,
    )
  );

  const handleMoveSpec = async (status: SpecStatus, cancellationReason?: string) => {
    if (!spec) return;
    // ITEM 17: cancelling requires a justification — intercept with the dialog.
    if (status === 'cancelled' && !cancellationReason) {
      setCancelDialogOpen(true);
      return;
    }
    // Spec Validation Gate: when the board opts in, intercept approved→validated
    // to show the new SubmitSpecValidationModal. The modal calls the backend gate
    // which runs coverage checks and then computes outcome — on success the spec
    // is promoted to validated automatically, so we just refetch after.
    if (
      status === 'validated'
      && spec.status === 'approved'
      && (
        requireSpecValidation
        || specValidationSubmissionRequired
      )
    ) {
      setShowSubmitValidationModal(true);
      return;
    }
    // Legacy path (pre-gate): direct move_spec with coverage gate feedback in the
    // existing validate modal.
    if (status === 'validated' && spec.status === 'approved') {
      setShowValidateModal(true);
      setValidateResult({ success: false, error: null });
      setValidating(true);
      try {
        const updated = await api.moveSpec(specId, { status });
        setSpec(updated);
        await loadAllowedTransitions(updated);
        onChanged();
        setValidateResult({ success: true, error: null });
      } catch (err: any) {
        setValidateResult({ success: false, error: err?.message || 'Validation failed' });
        await loadAllowedTransitions(spec);
      } finally {
        setValidating(false);
      }
      return;
    }
    setMovingTo(status);
    setPolicyTransitionRejection(null);
    try {
      const updated = await api.moveSpec(specId, {
        status,
        ...(cancellationReason ? { cancellation_reason: cancellationReason } : {}),
      });
      setSpec(updated);
      await loadAllowedTransitions(updated);
      onChanged();
      toast.success(`Spec moved to ${SPEC_STATUS_LABELS[status]}`);
    } catch (err) {
      const rejection = readPolicyTransitionRejection(err, {
        boardId: spec.board_id,
        entityType: 'spec',
        subjectId: spec.id,
        currentStatus: spec.status,
        toStatus: status,
      });
      toast.error(
        rejection
          ? policyTransitionRejectionMessage(rejection, 'lifecycle-edition')
          : getErrorMessage(err),
      );
      await loadAllowedTransitions(spec);
      setPolicyTransitionRejection(rejection);
    } finally { setMovingTo(null); }
  };

  const handleDelete = async () => {
    if (!spec) return;
    if (!confirm(`Delete spec "${spec.title}"? Linked cards will be unlinked but not deleted.`)) return;
    try {
      await api.deleteSpec(specId);
      toast.success('Spec deleted');
      onChanged();
      onClose();
    } catch (error) {
      if (
        error instanceof AuthenticatedFetchError
        && error.code?.startsWith('spec_dependency_')
      ) {
        openDependencies('required_by');
        toast.error(`${error.message} Review the Specs that require this one.`);
      } else {
        toast.error(getErrorMessage(error));
      }
    }
  };

  if (loading) {
    return (
      <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
        <div className="bg-white dark:bg-gray-800 rounded-xl p-8">
          <div className="text-gray-500 dark:text-gray-400">Loading spec...</div>
        </div>
      </div>
    );
  }

  if (!spec) return null;

  const statusFlowStatuses = nextStatuses.filter((s) => !(s === 'validated' && spec.status === 'approved'));
  const dependencyReadiness = canReadDependencies
    ? spec.dependency_readiness ?? null
    : null;
  const archivedDependencyBlockerCount = (
    dependencyReadiness?.archived_blocking_count ?? 0
  );
  const blockedStartTransition = policyTransitionPreview.status === 'ready'
    ? policyTransitionPreview.transitions.find((transition) => (
      transition.to_status === 'in_progress'
      && (
        transition.reason_codes.includes('spec_dependencies_incomplete')
        || transition.reason_codes.includes('spec_dependency_incomplete')
        || (dependencyReadiness?.blocking_count ?? 0) > 0
      )
      && !isAllowedTransitionActionable(transition)
    )) ?? null
    : null;
  const canSubmitValidation = (
    nextStatuses.includes('validated')
    || specValidationSubmissionRequired
  );
  const clearDetailsStructuredEditor = () => setDetailsStructuredEditor(null);

  const unansweredQA = spec.qa_items?.filter((q) => !q.answered_at).length || 0;
  const showValidationTab =
    canReadQuality
    || canReadPolicyCompliance
    || canReadChecklist
    || canReadSpecValidation
    || canReadDecomposition;
  const allTabs: { id: ModalTab; label: string; icon: React.ReactNode; count?: number; highlight?: boolean; permission?: string }[] = [
    { id: 'details', label: 'Details', icon: <FileText size={14} /> },
    ...((canReadCoverage || canReadCodeTraceability) ? [{ id: 'coverage' as ModalTab, label: 'Coverage', icon: <GitBranch size={14} /> }] : []),
    ...(canReadCodeTraceability
      ? [{ id: 'evidence-matrix' as ModalTab, label: 'Code Evidence Matrix', icon: <Grid3X3 size={14} /> }]
      : []),
    ...(showProjectStructure
      ? [{
        id: 'project-structure' as ModalTab,
        label: 'Project Structure',
        icon: <FolderTree size={14} />,
        count: spec.project_structure?.filter((node) => node.status === 'active').length || undefined,
      }]
      : []),
    { id: 'frs', label: 'Functional', icon: <Circle size={14} />, count: spec.functional_requirements?.length || 0 },
    { id: 'acs', label: 'AC', icon: <Target size={14} />, count: spec.acceptance_criteria?.length || 0 },
    { id: 'tests', label: 'Tests', icon: <FlaskConical size={14} />, count: spec.test_scenarios?.length || 0 },
    { id: 'rules', label: 'Business', icon: <Scale size={14} />, count: spec.business_rules?.length || 0 },
    ...(canReadDependencies
      ? [{
        id: 'dependencies' as ModalTab,
        label: 'Dependencies',
        icon: <GitBranch size={14} />,
        count: dependencyReadiness?.blocking_count || 0,
        highlight: (dependencyReadiness?.blocking_count || 0) > 0,
      }]
      : []),
    { id: 'contracts', label: 'Contracts', icon: <FileCode size={14} />, count: spec.api_contracts?.length || 0 },
    { id: 'irs', label: 'Integration', icon: <Network size={14} />, count: spec.integration_requirements?.length || 0, permission: 'spec.integration_requirements.read' },
    { id: 'ors', label: 'Observability', icon: <Gauge size={14} />, count: spec.observability_requirements?.length || 0, permission: 'spec.observability_requirements.read' },
    { id: 'trs', label: 'Technical', icon: <Settings size={14} />, count: spec.technical_requirements?.length || 0 },
    { id: 'decisions', label: 'Decisions', icon: <GitBranch size={14} />, count: spec.decisions?.length || 0 },
    { id: 'resources', label: 'Resources', icon: <BookOpen size={14} /> },
    { id: 'qa', label: 'Q&A', icon: <MessageCircleQuestion size={14} />, count: spec.qa_items?.length || 0, highlight: unansweredQA > 0 },
    { id: 'references', label: 'References', icon: <Link2 size={14} />, count: spec.cards?.length || 0 },
    { id: 'kg', label: 'KG Graph', icon: <Network size={14} /> },
    ...(showValidationTab
      ? [{ id: 'validation' as ModalTab, label: 'Validation', icon: <ShieldCheck size={14} /> }]
      : []),
    { id: 'activity', label: 'Activity', icon: <History size={14} /> },
  ];
  const tabs = allTabs.filter((tab) => !tab.permission || perms.has(tab.permission));
  const requirementSections: ModalTab[] = ['frs', 'rules', 'irs', 'ors', 'trs', 'contracts', 'decisions'];
  const verificationSections: ModalTab[] = ['tests', 'acs'];
  const requirementTabs = requirementSections.flatMap(id => tabs.filter(tab => tab.id === id));
  const verificationTabs = verificationSections.flatMap(id => tabs.filter(tab => tab.id === id));
  const primaryTab: ModalTab = requirementSections.includes(activeTab) ? 'requirements'
    : verificationSections.includes(activeTab) ? 'tests-verifications' : activeTab;
  const primaryTabs = tabs.filter(tab => !requirementSections.includes(tab.id) && !verificationSections.includes(tab.id));
  primaryTabs.splice(1, 0,
    { id: 'requirements', label: 'Requirements & Decisions', icon: <FileText size={14} /> },
    { id: 'tests-verifications', label: 'Tests & Verifications', icon: <FlaskConical size={14} /> });
  const primaryOrder: ModalTab[] = ['details', 'coverage', 'project-structure', 'evidence-matrix', 'resources', 'requirements', 'tests-verifications', 'qa', 'dependencies', 'references', 'kg', 'validation', 'activity'];
  primaryTabs.sort((a, b) => primaryOrder.indexOf(a.id) - primaryOrder.indexOf(b.id));
  const subTabs = primaryTab === 'requirements' ? requirementTabs : primaryTab === 'tests-verifications' ? verificationTabs : [];


  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
      style={permissionCheckPending ? { visibility: 'hidden' } : undefined}>
      {permissionCheckPending && <div role="status" style={{ visibility: 'visible' }} className="fixed inset-0 z-[80] flex items-center justify-center bg-black/50 text-sm text-white">Rechecking Board access…</div>}
      <div
        role="dialog"
        ref={nativeReferenceRoot}
        aria-modal="true"
        aria-labelledby={`spec-${spec.id}-title`}
        className={`bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full ${expanded ? 'max-w-[95vw] h-[95vh]' : 'max-w-3xl h-[90vh]'} flex flex-col`}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200 dark:border-gray-700">
          <div className="flex items-center gap-3 min-w-0">
            <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium ${STATUS_COLORS[spec.status]}`}>
              {STATUS_ICON[spec.status]}
              {SPEC_STATUS_LABELS[spec.status]}
            </span>
            <h2 id={`spec-${spec.id}-title`} className="text-lg font-semibold text-gray-900 dark:text-white truncate">{spec.title}</h2>
            <SpecEditionLabel
              edition={spec.edition}
              technicalRevision={spec.version}
              className="text-xs text-gray-400 shrink-0"
            />
          </div>
          <div className="flex items-center gap-1">
            <button
              onClick={() => openLineageGraph('spec', spec.id)}
              className="p-1.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors"
              title="Open lineage graph"
            >
              <GitBranch size={16} />
            </button>
            <EntityExportButton
              boardId={spec.board_id || _boardId}
              entityType="spec"
              entityId={spec.id}
              entityTitle={spec.title}
              disabled={loading}
            />
            <button onClick={loadSpec} className="p-1.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors" title="Refresh">
              <RefreshCw size={16} className={loading ? 'animate-spin' : ''} />
            </button>
            <button onClick={() => setExpanded(!expanded)} className="p-1.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg transition-colors" title={expanded ? 'Collapse' : 'Expand'}>
              {expanded ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
            </button>
            <button aria-label="Close spec" onClick={onClose} className="p-1 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300">
              <X size={20} />
            </button>
          </div>
        </div>

        {/* Status flow */}
        {(statusFlowStatuses.length > 0 || blockedStartTransition) && (
          <div className="px-6 py-2.5 border-b border-gray-100 dark:border-gray-700/50 flex items-center gap-2 flex-wrap">
            <span className="text-xs text-gray-500 dark:text-gray-400">Move to:</span>
            {statusFlowStatuses.map((status) => (
              <button
                key={status}
                onClick={() => handleMoveSpec(status)}
                disabled={movingTo !== null}
                className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium transition-colors
                  ${STATUS_COLORS[status]} hover:ring-2 hover:ring-offset-1 hover:ring-gray-300 dark:hover:ring-gray-600
                  disabled:opacity-50`}
              >
                <ChevronRight size={12} />
                {SPEC_STATUS_LABELS[status]}
                {movingTo === status && '...'}
              </button>
            ))}
            {blockedStartTransition && (
              <button
                type="button"
                disabled
                aria-describedby={`spec-${spec.id}-dependency-blocked-reason`}
                className={`inline-flex cursor-not-allowed items-center gap-1 rounded-full px-2.5 py-1 text-xs font-medium opacity-55 ${STATUS_COLORS.in_progress}`}
              >
                <ChevronRight size={12} />
                {SPEC_STATUS_LABELS.in_progress}
              </button>
            )}
            {blockedStartTransition && dependencyReadiness && (
              <button
                type="button"
                id={`spec-${spec.id}-dependency-blocked-reason`}
                onClick={() => openDependencies('depends_on')}
                className="inline-flex items-center gap-1 rounded-full border border-amber-200 bg-amber-50 px-2.5 py-1 text-xs font-semibold text-amber-800 hover:bg-amber-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-500 dark:border-amber-900 dark:bg-amber-950/40 dark:text-amber-300 dark:hover:bg-amber-900/40"
                title={
                  archivedDependencyBlockerCount > 0
                    ? 'Restore archived prerequisites or remove their dependencies before starting.'
                    : blockedStartTransition.blocked_reason ?? 'Review unfinished dependencies'
                }
              >
                <AlertTriangle size={12} />
                {dependencyReadiness.blocking_count} dependenc{dependencyReadiness.blocking_count === 1 ? 'y' : 'ies'}{' '}
                {archivedDependencyBlockerCount > 0
                  ? `blocked · ${archivedDependencyBlockerCount} archived`
                  : 'unfinished'}
              </button>
            )}
          </div>
        )}

        {/* Provenance breadcrumb */}
        {(parentIdeation || parentRefinement) && (
          <div className="px-6 py-2 border-b border-gray-100 dark:border-gray-700/50 flex items-center gap-1.5 text-xs text-gray-500 dark:text-gray-400">
            <span className="text-gray-400">From:</span>
            {parentIdeation && (
              <button
                onClick={() => openIdeationReference(parentIdeation.id)}
                className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-amber-50 text-amber-700 dark:bg-amber-900/20 dark:text-amber-300 hover:ring-2 hover:ring-amber-300 dark:hover:ring-amber-600 transition-all cursor-pointer"
              >
                <Lightbulb size={11} />
                {parentIdeation.title}
                <span className="text-[10px] text-amber-500 dark:text-amber-400">v{parentIdeation.version}</span>
              </button>
            )}
            {parentIdeation && parentRefinement && <ChevronRight size={12} className="text-gray-300" />}
            {parentRefinement && (
              <button
                onClick={() => openRefinementReference(parentRefinement.id)}
                className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-blue-50 text-blue-700 dark:bg-blue-900/20 dark:text-blue-300 hover:ring-2 hover:ring-blue-300 dark:hover:ring-blue-600 transition-all cursor-pointer"
              >
                <Layers size={11} />
                {parentRefinement.title}
                <span className="text-[10px] text-blue-500 dark:text-blue-400">v{parentRefinement.version}</span>
              </button>
            )}
          </div>
        )}

        {/* Tabs */}
        <div data-tour-id="specs.resources.tabs" className="shrink-0">
          <AccessibleTabList
            idBase={`spec-${specId}`}
            ariaLabel="Spec sections"
            items={primaryTabs.map((tab) => ({
              id: tab.id,
              label: tab.label,
              icon: tab.icon,
              count: tab.count,
              attention: tab.highlight,
            }))}
            value={primaryTab}
            onValueChange={id => setActiveTab(id === 'requirements' ? requirementTabs[0].id
              : id === 'tests-verifications' ? verificationTabs[0].id : id)}
            className="px-6 pt-3 scrollbar-hide"
          />
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto px-6 py-4">
          <MissingLinkNotice context={spec.missing_link_context} />
          {['coverage', 'references', 'dependencies'].includes(activeTab) && (workspaceSyncError || ['offline', 'unavailable'].includes(syncState)) && (
            <div role="status" className="mb-3 rounded-lg border border-amber-300 p-3 text-xs text-amber-700 dark:text-amber-300">
              <p>{workspaceSyncError || 'Live updates are unavailable. Displayed data may be out of date.'}</p>
              <button type="button" className="btn btn-secondary mt-2 text-xs" disabled={workspaceReadPending || permissionCheckPending}
                onClick={() => { void reloadWorkspaceSnapshot().then(() => setValidationHistoryRefreshKey(value => value + 1)).catch(() => { /* Keep the visible recovery state. */ }); }}>Reload current workspace</button>
            </div>
          )}
          <AccessibleTabPanel
            idBase={`spec-${specId}`}
            tabId={primaryTab}
            value={primaryTab}
            className="outline-none"
          >
          {subTabs.length > 0 && <AccessibleTabList idBase={`spec-${specId}-${primaryTab}`}
            ariaLabel={primaryTab === 'requirements' ? 'Requirements and decisions sections' : 'Tests and verifications sections'}
            items={subTabs} value={activeTab} onValueChange={setActiveTab} variant="secondary" className="mb-4" />}
          <AccessibleTabPanel idBase={subTabs.length ? `spec-${specId}-${primaryTab}` : `spec-${specId}-content`}
            tabId={activeTab} value={activeTab} className="space-y-4">
          {activeTab === 'details' && (
            <div className="space-y-5">
              {spec.status === 'cancelled' && (
                <CancellationDetails
                  id="cancellation-panel"
                  entityLabel="spec"
                  reason={spec.cancellation_reason}
                  cancelledBy={spec.cancelled_by}
                  cancelledAt={spec.cancelled_at}
                />
              )}
              <div>
                <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">Description</h4>
                <MarkdownContent content={spec.description || 'No description'} />
              </div>
              <div>
                <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">Context</h4>
                <MarkdownContent content={spec.context || 'No context'} />
              </div>
              {spec.labels && spec.labels.length > 0 && (
                <div className="flex flex-wrap gap-1">
                  {spec.labels.map((label, i) => (
                    <span key={i} className="text-xs px-1.5 py-0.5 rounded bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300">{label}</span>
                  ))}
                </div>
              )}

              <section aria-label="Task Validation Gate" className="space-y-2">
                <h4 className="text-sm font-semibold text-gray-700 dark:text-gray-300">Task Validation Gate</h4>
                <p className="text-xs text-gray-500">Controls whether cards derived from this spec must pass Task Validation. These settings do not change the Spec Validation Gate.</p>
                <dl className="grid grid-cols-2 gap-3 text-xs">
                  {[
                    ['Validation', spec.require_task_validation == null ? 'Board default' : spec.require_task_validation ? 'Required' : 'Disabled'],
                    ['Minimum confidence', spec.validation_min_confidence ?? 'Board default'],
                    ['Minimum completeness', spec.validation_min_completeness ?? 'Board default'],
                    ['Maximum drift', spec.validation_max_drift ?? 'Board default'],
                  ].map(([label, value]) => <div key={label}><dt className="text-gray-500">{label}</dt><dd className="mt-1 text-gray-700 dark:text-gray-300">{value}</dd></div>)}
                </dl>
              </section>

            </div>
          )}

          {(activeTab === 'frs' || activeTab === 'acs') && (() => {
            const type = activeTab === 'frs' ? 'functional_requirement' : 'acceptance_criterion';
            return <TextRequirementsTab
              key={`${spec.id}:${type}:${canStructured(type, 'create')}:${canStructured(type, 'update')}:${canStructured(type, 'revoke')}`}
              version={spec.version}
              readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
              kind={activeTab === 'frs' ? 'FR' : 'AC'}
              items={(activeTab === 'frs' ? spec.functional_requirements : spec.acceptance_criteria) || []}
              canCreate={canStructured(type, 'create')}
              canEdit={canStructured(type, 'update')}
              canRevoke={canStructured(type, 'revoke')}
              renderDetails={activeTab === 'acs' && perms.has('spec.entity.read') ? item => <>
                <CriterionVerificationDetails
                  specId={spec.id} version={spec.version} value={item}
                  readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
                  options={verificationRequirementOptions(spec, canReadIR, canReadOR)}
                  canEdit={!spec.archived && spec.status === 'draft'
                    && hasPermissionWithState(perms.has, 'spec.structured_entity.acceptance_criterion.update', 'spec', spec.status)}
                  onSaved={async () => { await reloadSpecAfterStructuredEdit(); }}
                />
                {perms.has('spec.tests.read') && <section aria-label="Verification scenarios" className="space-y-2 border-t border-gray-200 pt-3 dark:border-gray-700">
                  <div className="flex items-center justify-between gap-2"><h4 className="font-semibold">How to verify</h4>
                    <button type="button" className="text-blue-600 hover:underline dark:text-blue-400" onClick={() => setActiveTab('tests')}>Manage scenarios</button></div>
                  {(spec.test_scenarios || []).filter(scenario => scenario.linked_criteria?.includes(item.id)).map(scenario => <div key={scenario.id} className="rounded-lg bg-gray-50 p-2 dark:bg-gray-900/40">
                    <p className="font-medium">{scenario.title}</p>
                    <p>Method: {scenario.verification_method || 'Not defined'}</p>
                    <p className="whitespace-pre-wrap">Expected observation: {scenario.then}</p>
                  </div>)}
                  {!(spec.test_scenarios || []).some(scenario => scenario.linked_criteria?.includes(item.id)) && <p>No scenario linked. Define how this condition will be observed in Tests.</p>}
                  <p className="text-gray-500">Execution evidence and current verification results are available in Coverage → Implementation.</p>
                </section>}
              </> : undefined}
              onSave={(id, draft, expectedVersion) => saveTextRequirement(type, id, draft, expectedVersion)}
              onRevoke={async id => {
                await applyImpactAwareOperation(type, id, 'revoke', spec.version);
                await reloadSpecAfterStructuredEdit();
              }}
            />;
          })()}
          {activeTab === 'acs' && <div className="mt-6">
              <RequirementVerificationPanel
                key={JSON.stringify([spec.board_id, spec.id, spec.status, spec.archived, perms.has('spec.entity.read'), canReadIR, canReadOR,
                  ...(['functional_requirement', 'technical_requirement', 'integration_requirement', 'observability_requirement', 'business_rule'] as const).map(type => canStructured(type, 'update'))])}
                scope={{ boardId: spec.board_id, specId: spec.id, version: spec.version, edition: spec.edition }}
                readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
                canRead={perms.has('spec.entity.read') && canReadIR && canReadOR}
                canReadPlanning={perms.has('spec.tests.read') && perms.has('card.entity.read')}
                canEdit={type => !spec.archived && spec.status === 'draft'
                  && hasPermissionWithState(perms.has, `spec.structured_entity.${type}.update`, 'spec', spec.status)}
                options={verificationRequirementOptions(spec, canReadIR, canReadOR)}
                criteria={(spec.acceptance_criteria || []) as unknown[]}
                onSaved={async () => { await reloadSpecAfterStructuredEdit(); }}
              />
          </div>}
          {activeTab === 'evidence-matrix' && spec && canReadCodeTraceability && (
            <EvidenceMatrixPanel
              boardId={spec.board_id}
              subjectId={spec.id}
              subjectVersion={spec.version}
              boardSkipCoverage={boardSettings.skip_code_evidence_coverage_global ?? false}
              skipCoverage={spec.skip_code_evidence_coverage}
              canEditCoverageFlags={canEditCodeEvidenceCoverage}
              obligationTitles={specAnchorTexts}
              onSkipCoverageChange={async (skip) => {
                try {
                  const updated = await api.updateSpec(specId, {
                    skip_code_evidence_coverage: skip,
                  });
                  setSpec(updated);
                } catch (err) {
                  toast.error(err instanceof Error && err.message
                    ? err.message
                    : 'Failed to update Code Evidence coverage');
                }
              }}
            />
          )}
          {activeTab === 'coverage' && spec.id === specId && (canReadCoverage || canReadCodeTraceability) && (
            <SpecCoveragePanel boardId={spec.board_id} specId={spec.id} revision={`${spec.edition}:${spec.version}:${spec.updated_at}:${validationHistoryRefreshKey}`}
              focusExceptionId={readinessReference?.startsWith('exception:') ? readinessReference.slice('exception:'.length) : null}
              canReadSummary={canReadCoverage} canReadImplementation={canReadCodeTraceability}
              canManageTaskRequirements={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'
                && (perms.has('code_traceability.waiver.create') || perms.has('code_traceability.waiver.clear'))}
              skipDeliveryEvidence={spec.skip_delivery_evidence}
              onSkipDeliveryEvidenceChange={canEditCodeEvidenceCoverage && !permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current' ? async (value) => {
                try {
                  const updated = await api.updateSpec(specId, { skip_delivery_evidence: value } as any);
                  if (currentSpecId.current === specId && updated.id === specId && updated.board_id === spec.board_id) setSpec(updated);
                } catch (err) {
                  toast.error(err instanceof Error && err.message ? err.message : 'Failed to update spec');
                }
              } : undefined}
              onOpenSection={setActiveTab}
              onOpenReadinessSpec={location => { setReadinessReference(location.ref); setActiveTab(location.tab); }}
              canCorrect={!spec.archived && spec.status === 'draft' ? [
                ...(hasPermissionWithState(perms.has, 'spec.tests.edit', 'spec', spec.status) ? ['tests' as const] : []),
                ...(hasPermissionWithState(perms.has, 'spec.structured_entity.business_rule.update', 'spec', spec.status) ? ['rules' as const] : []),
              ] : []} />
          )}
          {activeTab === 'project-structure' && spec && showProjectStructure && (
            <ProjectStructureErrorBoundary>
              <ProjectStructureTab
                boardId={spec.board_id || _boardId}
                spec={spec}
                refreshKey={validationHistoryRefreshKey}
                readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
                onReload={() => reloadWorkspaceSnapshot()}
                onAccessLost={() => {
                  if (currentSpecId.current !== spec.id) return;
                  workspaceLoadGeneration.current += 1;
                  specReloadGeneration.current += 1;
                  setSpec(null); onClose();
                }}
                focusNodeId={focusProjectNodeId}
                canCreate={canCreateProjectStructure}
                canUpdate={canUpdateProjectStructure}
                canRevoke={canRevokeProjectStructure}
                canRestore={canRestoreProjectStructure}
                canReorder={canReorderProjectStructure}
                canLinkTask={canLinkProjectStructureTask}
                canUnlinkTask={canUnlinkProjectStructureTask}
                canLinkTest={canLinkProjectStructureTest}
                canUnlinkTest={canUnlinkProjectStructureTest}
                canLinkEvidence={canLinkProjectStructureEvidence}
                canUnlinkEvidence={canUnlinkProjectStructureEvidence}
                canReadEvidence={canReadCodeTraceability}
                onStructureChange={({ nodes, specVersion, structureRevision, source }) => {
                  if (currentSpecId.current !== spec.id) return;
                  // A tree snapshot is not a full Spec snapshot. A new version
                  // must reload the workspace rather than certify cached fields.
                  if (source === 'mutation' || specVersion > spec.version) {
                    if (source === 'mutation') onChanged();
                    void reloadWorkspaceSnapshot(specVersion).catch(() => { /* Read failure is shown; never repeat the confirmed mutation. */ });
                    return;
                  }
                  setSpec((current) => current && current.id === spec.id && current.board_id === spec.board_id
                    && current.version === specVersion && (current.project_structure_revision ?? 0) <= (structureRevision ?? 0)
                    ? {
                      ...current,
                      project_structure: nodes,
                      project_structure_revision: structureRevision,
                    }
                    : current);
                }}
              />
            </ProjectStructureErrorBoundary>
          )}

          {activeTab === 'tests' && spec && (
            <TestScenariosTab
              key={`${spec.board_id}:${spec.id}`}
              focusReceipt={readinessReference?.startsWith('receipt:') ? readinessReference.slice('receipt:'.length) : null}
              spec={spec}
              canReadPolicyCompliance={canReadPolicyCompliance}
              policyRefreshKey={testScenarioPolicyRefreshKey}
              readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
              onUpdate={async (scenarios, expectedVersion, expectedSnapshot) => {
                const generation = ++specReloadGeneration.current;
                try {
                  const updated = await persistTestScenariosWithWriteGuard(
                    api.updateSpec,
                    specId,
                    scenarios,
                    expectedVersion,
                    expectedSnapshot,
                  );
                  if (currentSpecId.current !== specId) return;
                  if (updated.id !== specId || updated.board_id !== spec.board_id) throw new Error('The scenario write response does not match its Spec. Reload to check the result.');
                  if (generation === specReloadGeneration.current) setSpec(updated);
                  else await reloadSpecSnapshot({ includeRelated: false, notifyChanged: false, showLoading: false });
                  setTestScenarioPolicyRefreshKey((value) => value + 1);
                  try { onChanged(); } catch { toast.error('Scenario saved. Refresh to update related views.'); }
                } catch (err) {
                  // Surface the backend validation message (e.g. the strict
                  // scenario_type contract) instead of a generic string so a
                  // stale client/agent can correct the request (spec ac16b3c9).
                  if (currentSpecId.current === specId) toast.error(err instanceof Error && err.message ? err.message : 'Failed to update test scenarios');
                  if (currentSpecId.current === specId && err instanceof AuthenticatedFetchError && [401, 403, 404].includes(err.status)) {
                    setSpec(null); onClose();
                  }
                  throw err;
                }
              }}
              onReload={async () => {
                try {
                  const updated = await reloadSpecSnapshot({ includeRelated: false, notifyChanged: false, showLoading: false });
                  if (!updated) throw new Error('The scenario reload was superseded. Reload to confirm the current base.');
                  setTestScenarioPolicyRefreshKey(value => value + 1);
                  setWorkspaceSyncError(null);
                  return updated;
                } catch (error) {
                  if (currentSpecId.current === specId && error instanceof AuthenticatedFetchError && [401, 403, 404].includes(error.status)) {
                    setSpec(null); onClose();
                  }
                  throw error;
                }
              }}
              onSpecUpdate={async (data) => {
                await api.updateSpec(specId, data);
              }}
            />
          )}
          {activeTab === 'rules' && spec && (
            <RulesTab
              spec={spec}
              readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
              canCreate={canStructured('business_rule', 'create')}
              canEdit={canStructured('business_rule', 'update')}
              canDelete={canStructured('business_rule', 'revoke')}
              onUpdate={async (rules, expectedVersion) => {
                await syncStructuredCollection('business_rules', spec.business_rules || [], rules, expectedVersion);
              }}
              onSpecUpdate={async (patch) => {
                try {
                  const updated = await api.updateSpec(specId, patch as any);
                  setSpec(updated);
                } catch { toast.error('Failed to update spec'); }
              }}
            />
          )}
          {activeTab === 'dependencies' && spec && canReadDependencies && (
            <SpecDependenciesTab
              boardId={spec.board_id}
              refreshKey={validationHistoryRefreshKey}
              readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
              onAccessLost={() => {
                if (currentSpecId.current !== spec.id) return;
                workspaceLoadGeneration.current += 1;
                specReloadGeneration.current += 1;
                setSpec(null); onClose();
              }}
              spec={{
                id: spec.id,
                title: spec.title,
                version: spec.version,
                edition: spec.edition,
                status: spec.status,
                ideation_id: spec.ideation_id,
              }}
              readiness={dependencyReadiness}
              readinessLoading={false}
              readinessError={dependencyReadiness
                ? null
                : 'The authoritative readiness projection was not included in this Spec context.'}
              canAdd={canManageDependencies && !spec.archived}
              addDisabledReason={
                spec.archived
                  ? 'Restore this Spec before adding dependencies.'
                  : canManageDependencies
                    ? null
                    : 'Adding dependencies is not authorized.'
              }
              canRemove={canManageDependencies}
              requestedDirection={dependencyDirectionRequest.direction}
              directionRequestToken={dependencyDirectionRequest.token}
              onRetryReadiness={() => { void reloadWorkspaceSnapshot().catch(() => { /* Workspace retains its visible recovery state. */ }); }}
              onOpenSpec={openSpecReference}
              onMutated={reloadSpecAfterDependencyMutation}
            />
          )}
          {activeTab === 'contracts' && spec && (
            <ContractsTab
              spec={spec}
              readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
              canCreate={canStructured('api_contract', 'create')}
              canEdit={canStructured('api_contract', 'update')}
              canDelete={canStructured('api_contract', 'revoke')}
              canLinkTask={canStructured('api_contract', 'link_task')}
              onUpdate={async (contracts, expectedVersion) => {
                await syncStructuredCollection('api_contracts', spec.api_contracts || [], contracts, expectedVersion);
              }}
              onSpecUpdate={async (data) => {
                try {
                  const updated = await api.updateSpec(specId, data as any);
                  setSpec(updated);
                } catch { toast.error('Failed to update spec'); }
              }}
              specCards={spec.cards || []}
              onLinkTask={async (contractId, cardId) => {
                const updated = await api.linkTaskToSpecItem(specId, 'api_contracts', contractId, cardId);
                setSpec(updated);
              }}
              onUnlinkTask={async (contractId, cardId) => {
                const updated = await api.unlinkTaskFromSpecItem(specId, 'api_contracts', contractId, cardId);
                setSpec(updated);
              }}
            />
          )}
          {activeTab === 'irs' && spec && canReadIR && (
            <>
            <IntegrationRequirementsTab
              spec={spec}
              readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
              canCreate={canCreateIR}
              canEdit={canEditIR}
              canDelete={canDeleteIR}
              canLinkTask={canLinkIRTasks}
              canEditCoverageFlags={canEditCoverageFlags}
              focusEditId={detailsStructuredEditor?.tab === 'irs' && detailsStructuredEditor.mode === 'edit' ? detailsStructuredEditor.entityId || null : null}
              focusCreateToken={detailsStructuredEditor?.tab === 'irs' && detailsStructuredEditor.mode === 'add' ? detailsStructuredEditor.token : null}
              onFocusHandled={clearDetailsStructuredEditor}
              onUpdate={async (requirements, expectedVersion) => {
                await syncStructuredCollection('integration_requirements', spec.integration_requirements || [], requirements, expectedVersion);
              }}
              onSpecUpdate={async (patch) => {
                try {
                  const updated = await api.updateSpec(specId, patch as any);
                  setSpec(updated);
                } catch { toast.error('Failed to update spec'); }
              }}
              specCards={spec.cards || []}
              onLinkTask={canLinkIRTasks ? async (requirementId, cardId) => {
                const updated = await api.linkTaskToSpecItem(specId, 'integration_requirements', requirementId, cardId);
                setSpec(updated);
              } : undefined}
              onUnlinkTask={canLinkIRTasks ? async (requirementId, cardId) => {
                const updated = await api.unlinkTaskFromSpecItem(specId, 'integration_requirements', requirementId, cardId);
                setSpec(updated);
              } : undefined}
            />
            <ArchitectureClassificationsPanel integrated
              boardId={spec.board_id}
              specId={spec.id}
              specVersion={spec.version}
              readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
              canRead={canReadIR && perms.has('spec.architecture.read') && perms.has('spec.entity.read')}
              authoring={{
                canClassify: !spec.archived && spec.status === 'draft' && canReadIR
                  && perms.has('spec.architecture.read') && perms.has('spec.entity.read')
                  && hasPermissionWithState(perms.has, 'spec.entity.edit_fields', 'spec', spec.status),
                canPromote: hasPermissionWithState(perms.has, 'spec.structured_entity.integration_requirement.create', 'spec', spec.status),
                canAssociate: hasPermissionWithState(perms.has, 'spec.structured_entity.integration_requirement.update', 'spec', spec.status),
                specEdition: spec.edition,
                requirements: spec.integration_requirements || [],
                onApplied: async () => { await reloadSpecAfterStructuredEdit(); },
              }}
            />
            </>
          )}
          {activeTab === 'ors' && spec && canReadOR && (
            <ObservabilityRequirementsTab
              spec={spec}
              readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
              canCreate={canCreateOR}
              canEdit={canEditOR}
              canDelete={canDeleteOR}
              canLinkTask={canLinkORTasks}
              canEditCoverageFlags={canEditCoverageFlags}
              focusEditId={detailsStructuredEditor?.tab === 'ors' && detailsStructuredEditor.mode === 'edit' ? detailsStructuredEditor.entityId || null : null}
              focusCreateToken={detailsStructuredEditor?.tab === 'ors' && detailsStructuredEditor.mode === 'add' ? detailsStructuredEditor.token : null}
              onFocusHandled={clearDetailsStructuredEditor}
              onUpdate={async (requirements, expectedVersion) => {
                await syncStructuredCollection('observability_requirements', spec.observability_requirements || [], requirements, expectedVersion);
              }}
              onSpecUpdate={async (patch) => {
                try {
                  const updated = await api.updateSpec(specId, patch as any);
                  setSpec(updated);
                } catch { toast.error('Failed to update spec'); }
              }}
              specCards={spec.cards || []}
              onLinkTask={canLinkORTasks ? async (requirementId, cardId) => {
                const updated = await api.linkTaskToSpecItem(specId, 'observability_requirements', requirementId, cardId);
                setSpec(updated);
              } : undefined}
              onUnlinkTask={canLinkORTasks ? async (requirementId, cardId) => {
                const updated = await api.unlinkTaskFromSpecItem(specId, 'observability_requirements', requirementId, cardId);
                setSpec(updated);
              } : undefined}
            />
          )}
          {activeTab === 'trs' && spec && (
            <TechnicalRequirementsTab
              spec={spec}
              readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
              canCreate={canStructured('technical_requirement', 'create')}
              canEdit={canStructured('technical_requirement', 'update')}
              canDelete={canStructured('technical_requirement', 'revoke')}
              canLinkTask={canStructured('technical_requirement', 'link_task')}
              focusEditId={detailsStructuredEditor?.tab === 'trs' && detailsStructuredEditor.mode === 'edit' ? detailsStructuredEditor.entityId || null : null}
              focusCreateToken={detailsStructuredEditor?.tab === 'trs' && detailsStructuredEditor.mode === 'add' ? detailsStructuredEditor.token : null}
              onFocusHandled={clearDetailsStructuredEditor}
              onUpdate={async (trs, expectedVersion) => {
                const currentTRs = spec.technical_requirements || [];
                await syncStructuredCollection('technical_requirements', currentTRs, trs, expectedVersion);
              }}
              specCards={spec.cards || []}
              onLinkTask={async (trId, cardId) => {
                const updated = await api.linkTaskToSpecItem(specId, 'technical_requirements', trId, cardId);
                setSpec(updated);
              }}
              onUnlinkTask={async (trId, cardId) => {
                const updated = await api.unlinkTaskFromSpecItem(specId, 'technical_requirements', trId, cardId);
                setSpec(updated);
              }}
              onSpecUpdate={async (patch) => {
                try {
                  const updated = await api.updateSpec(specId, patch as any);
                  setSpec(updated);
                } catch { toast.error('Failed to update spec'); }
              }}
            />
          )}
          {activeTab === 'decisions' && spec && (
            <DecisionsTab
              spec={spec}
              readCurrent={!permissionCheckPending && !workspaceReadPending && !workspaceSyncError && syncState === 'current'}
              focusInspectionId={readinessReference?.startsWith('inspection:') ? readinessReference.slice('inspection:'.length) : null}
              canCreate={canStructured('decision', 'create')}
              canEdit={canStructured('decision', 'update')}
              canDelete={canStructured('decision', 'revoke')}
              canLinkTask={canStructured('decision', 'link_task')}
              canReview={!perms.isLoading && !perms.error && perms.has('spec.validation.submit')
                && perms.has('spec.entity.read') && perms.has('code_traceability.evidence.read')
                && perms.has(`spec.interact_in.${spec.status}`)}
              focusEditId={detailsStructuredEditor?.tab === 'decisions' && detailsStructuredEditor.mode === 'edit' ? detailsStructuredEditor.entityId || null : null}
              focusCreateToken={detailsStructuredEditor?.tab === 'decisions' && detailsStructuredEditor.mode === 'add' ? detailsStructuredEditor.token : null}
              onFocusHandled={clearDetailsStructuredEditor}
              onUpdate={async (decisions, expectedVersion) => {
                await syncStructuredCollection('decisions', spec.decisions || [], decisions, expectedVersion);
              }}
              onSpecUpdate={async (patch) => {
                try {
                  const updated = await api.updateSpec(specId, patch as any);
                  setSpec(updated);
                } catch { toast.error('Failed to update spec'); }
              }}
              specCards={spec.cards || []}
              onLinkTask={async (decisionId, cardId) => {
                const updated = await api.linkTaskToSpecItem(specId, 'decisions', decisionId, cardId);
                setSpec(updated);
              }}
              onUnlinkTask={async (decisionId, cardId) => {
                const updated = await api.unlinkTaskFromSpecItem(specId, 'decisions', decisionId, cardId);
                setSpec(updated);
              }}
            />
          )}
          {activeTab === 'resources' && spec && (
            <div className="space-y-4" data-testid="spec-resources-panel">
              {!resourcesReadCurrent && <div role="status" className="space-y-2 rounded-lg border border-amber-300 p-3 text-sm dark:border-amber-800">
                <p>{workspaceSyncError || 'Checking current resources. Unsaved input is preserved; writes wait for an authorized current read.'}</p>
                <button type="button" className="btn btn-secondary text-xs" disabled={workspaceReadPending || permissionCheckPending}
                  onClick={() => { void reloadResources().catch(() => undefined); }}>Reload resource workspace</button>
              </div>}
              <ResourceGateDisclosure
                boardId={spec.board_id || _boardId}
                entityType="spec"
                entityId={specId}
                refreshKey={resourceGateRefreshKey}
                active={resourcesReadCurrent}
              />
              <AccessibleTabList
                idBase={`spec-${specId}-resources`}
                ariaLabel="Spec resources"
                items={[
                  {
                    id: 'mockups',
                    label: 'Mockups',
                    icon: <Monitor size={13} />,
                    count: spec.screen_mockups?.length || 0,
                  },
                  {
                    id: 'knowledge',
                    label: 'Knowledge',
                    icon: <BookOpen size={13} />,
                    count: spec.knowledge_bases?.length || 0,
                  },
                  {
                    id: 'architecture',
                    label: 'Architecture',
                    icon: <Network size={13} />,
                    count: spec.architecture_designs?.length || 0,
                  },
                ] satisfies {
                  id: ResourceSubTab;
                  label: string;
                  icon: React.ReactNode;
                  count: number;
                }[]}
                value={resourceTab}
                onValueChange={setResourceTab}
                variant="secondary"
                className="max-w-full"
              />

              <AccessibleTabPanel
                idBase={`spec-${specId}-resources`}
                tabId="mockups"
                value={resourceTab}
                mount="lazy-keep"
              >
                  <MockupsTab
                    screenMockups={spec.screen_mockups}
                    boardId={spec.board_id}
                    entityType="spec"
                    entityId={specId}
                    expanded={expanded}
                    version={spec.version}
                    snapshot={spec.mockup_snapshot}
                    revision={resourceGateRefreshKey}
                    active={resourceTab === 'mockups'}
                    readCurrent={resourcesReadCurrent && Boolean(spec.mockup_snapshot)}
                    onReload={reloadResources}
                    onUpdate={async (mockups, base) => {
                      if (!base?.expectedVersion || !base.expectedSnapshot) throw new Error('Reload the Spec before editing mockups.');
                      const origin = specId;
                      const updated = await api.updateSpec(origin, { screen_mockups: mockups, expected_spec_version: base.expectedVersion,
                        expected_mockup_snapshot: base.expectedSnapshot });
                      if (currentSpecId.current !== origin) throw new Error('The mockup owner changed during save.');
                      setSpec(current => current?.id === origin && current.version <= updated.version ? updated : current);
                      return { version: updated.version };
                    }}
                  />
              </AccessibleTabPanel>
              <AccessibleTabPanel
                idBase={`spec-${specId}-resources`}
                tabId="knowledge"
                value={resourceTab}
                mount="lazy-keep"
              >
                  <SpecKnowledgeResources
                    specId={specId}
                    boardId={spec.board_id}
                    revision={resourceGateRefreshKey}
                    active={resourceTab === 'knowledge'}
                    readCurrent={resourcesReadCurrent}
                    onReload={reloadResources}
                  />
              </AccessibleTabPanel>
              <AccessibleTabPanel
                idBase={`spec-${specId}-resources`}
                tabId="architecture"
                value={resourceTab}
                mount="lazy-keep"
              >
                  <ArchitectureTab
                    parentType="spec"
                    parentId={specId}
                    boardId={spec.board_id}
                    entityType="spec"
                    entityId={specId}
                    expanded={expanded}
                    locked={['validated', 'in_progress', 'done'].includes(spec.status)}
                    screenMockups={spec.screen_mockups || []}
                    revision={resourceGateRefreshKey}
                    active={resourceTab === 'architecture'}
                    readCurrent={resourcesReadCurrent}
                    onChanged={async () => { await reloadResources(); }}
                  />
              </AccessibleTabPanel>
            </div>
          )}
          {activeTab === 'validation' && spec && (
            <>
            {(workspaceSyncError || ['offline', 'unavailable'].includes(syncState)) && <p role="status" className="mx-4 mt-3 rounded-lg border border-amber-300 bg-amber-50 p-3 text-xs text-amber-900 dark:border-amber-700 dark:bg-amber-950/40 dark:text-amber-200">
              {workspaceSyncError || 'Live updates are unavailable. Displayed results may be out of date; reconnect or refresh before concluding validation.'}
            </p>}
            <SpecValidationPanel
              onReviewPlanningComponent={key => {
                const destinations: Record<string, ModalTab> = {
                  acceptance_coverage: 'acs', test_card_coverage: 'tests', business_coverage: 'frs',
                  technical_coverage: 'trs', contract_coverage: 'contracts', integration_coverage: 'irs',
                  observability_coverage: 'ors', task_requirement_links: 'coverage',
                  decision_verification: 'decisions', code_evidence: 'evidence-matrix',
                  architecture: 'resources', resource_coverage: 'resources',
                };
                if (destinations[key]) setActiveTab(destinations[key]);
              }}
              anchorTexts={specAnchorTexts}
              boardId={spec.board_id}
              specId={specId}
              specVersion={spec.version}
              specEdition={spec.edition}
              specStatus={spec.status}
              canReadChecklist={canReadChecklist}
              canExecuteChecklist={canExecuteChecklist}
              canReadValidation={canReadSpecValidation}
              canReadDecomposition={canReadDecomposition}
              canSubmitDecomposition={hasPermissionWithState(perms.has, 'spec.evaluations.submit', 'spec', spec.status)}
              canReadQuality={canReadQuality}
              canReadPolicyCompliance={canReadPolicyCompliance}
              policyTransitionPreview={policyTransitionPreview}
              policyTransitionRejection={policyTransitionRejection}
              specArchived={spec.archived ?? false}
              validationHistoryRefreshKey={
                validationHistoryRefreshKey
              }
              onAssessmentRecorded={onChanged}
              onPolicyEvaluated={() => {
                void loadAllowedTransitions(spec);
              }}
              onOpenRequirementLintHelp={() =>
                openContextualHelp('requirement-lint')}
              canSubmitValidation={
                spec.status === 'approved'
                && canSubmitValidation
                && perms.has('spec.validation.submit')
              }
              onSubmitValidation={() =>
                void handleMoveSpec('validated' as SpecStatus)}
            />
            </>
          )}
          {activeTab === 'kg' && spec && (
            <KGValidationTab boardId={spec.board_id} specId={specId} />
          )}
          {activeTab === 'activity' && <HistoryTab specId={specId} />}
          {activeTab === 'qa' && (
            <QATab
              specId={specId}
              mentionables={mentionables}
              onChanged={onChanged}
            />
          )}



          {activeTab === 'references' && (
            <div className="space-y-4" data-testid="spec-references-panel">
              <AccessibleTabList
                idBase={`spec-${specId}-references`}
                ariaLabel="Spec references"
                items={[
                  { id: 'origin', label: 'Origin' },
                  {
                    id: 'cards',
                    label: 'Derived cards',
                    count: spec.cards?.length || 0,
                  },
                ] satisfies {
                  id: ReferenceSubTab;
                  label: string;
                  count?: number;
                }[]}
                value={referenceTab}
                onValueChange={setReferenceTab}
                variant="secondary"
                className="max-w-full"
              />

              <AccessibleTabPanel
                idBase={`spec-${specId}-references`}
                tabId="origin"
                value={referenceTab}
                className="space-y-3"
              >
                  {!parentIdeation && !parentRefinement ? (
                    <div className="rounded-xl border border-dashed border-gray-300 px-4 py-8 text-center dark:border-gray-700">
                      <GitBranch size={28} className="mx-auto mb-2 text-gray-300 dark:text-gray-600" />
                      <p className="text-sm text-gray-500 dark:text-gray-400">
                        {spec.ideation_id || spec.refinement_id ? 'The registered origin could not be loaded.' : 'No origin is registered for this spec.'}
                      </p>
                    </div>
                  ) : (
                    <div className="space-y-2">
                      {parentIdeation && (
                        <button
                          type="button"
                          onClick={() => openIdeationReference(parentIdeation.id)}
                          className="flex w-full items-center justify-between gap-3 rounded-xl border border-amber-200 bg-amber-50/60 px-3 py-3 text-left hover:bg-amber-100/70 dark:border-amber-900/60 dark:bg-amber-950/20 dark:hover:bg-amber-950/35"
                        >
                          <span className="flex min-w-0 items-center gap-2">
                            <Lightbulb size={15} className="shrink-0 text-amber-600" />
                            <span className="truncate text-sm font-medium text-gray-800 dark:text-gray-100">
                              {parentIdeation.title}
                            </span>
                          </span>
                          <span className="shrink-0 text-xs text-amber-600 dark:text-amber-300">
                            Ideation · v{parentIdeation.version}
                          </span>
                        </button>
                      )}
                      {parentRefinement && (
                        <button
                          type="button"
                          onClick={() => openRefinementReference(parentRefinement.id)}
                          className="flex w-full items-center justify-between gap-3 rounded-xl border border-blue-200 bg-blue-50/60 px-3 py-3 text-left hover:bg-blue-100/70 dark:border-blue-900/60 dark:bg-blue-950/20 dark:hover:bg-blue-950/35"
                        >
                          <span className="flex min-w-0 items-center gap-2">
                            <Layers size={15} className="shrink-0 text-blue-600" />
                            <span className="truncate text-sm font-medium text-gray-800 dark:text-gray-100">
                              {parentRefinement.title}
                            </span>
                          </span>
                          <span className="shrink-0 text-xs text-blue-600 dark:text-blue-300">
                            Refinement · v{parentRefinement.version}
                          </span>
                        </button>
                      )}
                    </div>
                  )}
              </AccessibleTabPanel>

              <AccessibleTabPanel
                idBase={`spec-${specId}-references`}
                tabId="cards"
                value={referenceTab}
                className="space-y-2"
              >
                  {(!spec.cards || spec.cards.length === 0) ? (
                    <div className="text-center py-6">
                      <Link2 size={32} className="mx-auto text-gray-300 dark:text-gray-600 mb-2" />
                      <p className="text-sm text-gray-500 dark:text-gray-400">No linked cards</p>
                      <p className="text-xs text-gray-400 mt-1">Cards are created manually and linked to this spec</p>
                    </div>
                  ) : (
                    spec.cards.map((card) => {
                      const content = (
                        <>
                          <span className="text-sm text-gray-700 dark:text-gray-300 truncate">{card.title}</span>
                          <span className={`text-xs px-1.5 py-0.5 rounded ${CARD_STATUS_COLORS[card.status] || ''}`}>
                            {card.status.replace('_', ' ')}
                          </span>
                        </>
                      );
                      return modalStack ? (
                        <button
                          key={card.id}
                          type="button"
                          onClick={() => modalStack.push({ type: 'card', id: card.id, boardId: spec.board_id })}
                          className="flex w-full items-center justify-between gap-3 rounded bg-gray-50 px-2 py-1.5 text-left hover:bg-blue-50 dark:bg-gray-700/50 dark:hover:bg-blue-950/20"
                        >
                          {content}
                        </button>
                      ) : (
                        <div key={card.id} className="flex items-center justify-between gap-3 rounded bg-gray-50 px-2 py-1.5 dark:bg-gray-700/50">
                          {content}
                        </div>
                      );
                    })
                  )}
              </AccessibleTabPanel>
            </div>
          )}
          </AccessibleTabPanel>
          </AccessibleTabPanel>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between px-6 py-4 border-t border-gray-200 dark:border-gray-700">
          <button onClick={handleDelete} className="text-sm text-red-500 hover:text-red-700 dark:hover:text-red-400">
            Delete spec
          </button>
          <div className="flex items-center gap-2">
            {spec.status === 'approved' && canSubmitValidation && perms.has('spec.validation.submit') && (
              <button
                onClick={() => handleMoveSpec('validated' as SpecStatus)}
                disabled={validating}
                className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg text-sm font-semibold transition-colors
                  bg-purple-500 text-white hover:bg-purple-600 shadow-sm hover:shadow-md
                  disabled:opacity-50"
              >
                <CheckCircle2 size={16} />
                {validating ? 'Validating...' : 'Validate'}
              </button>
            )}
            <button onClick={onClose} className="btn btn-secondary">Close</button>
          </div>
        </div>
      </div>

      {/* Parent modals */}
      {viewingIdeationId && (
        <IdeationModal
          ideationId={viewingIdeationId}
          boardId={_boardId}
          onClose={() => setViewingIdeationId(null)}
          onChanged={loadSpec}
        />
      )}
      {viewingRefinementId && (
        <RefinementModal
          refinementId={viewingRefinementId}
          boardId={_boardId}
          onClose={() => setViewingRefinementId(null)}
          onChanged={loadSpec}
        />
      )}
      {viewingSpecId && (
        <SpecModal
          specId={viewingSpecId}
          boardId={_boardId}
          onClose={() => setViewingSpecId(null)}
          onEscape={() => setViewingSpecId(null)}
          onChanged={loadSpec}
        />
      )}

      {/* Validation Gate Results Modal */}
      {showValidateModal && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[60]" onClick={() => !validating && setShowValidateModal(false)}>
          <div className="bg-white dark:bg-gray-800 rounded-xl shadow-2xl w-full max-w-lg p-6" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center gap-3 mb-4">
              {validating ? (
                <>
                  <RefreshCw size={20} className="text-purple-500 animate-spin" />
                  <h3 className="text-lg font-semibold text-gray-900 dark:text-white">Running validation gates...</h3>
                </>
              ) : validateResult.success ? (
                <>
                  <CheckCircle2 size={20} className="text-green-500" />
                  <h3 className="text-lg font-semibold text-green-700 dark:text-green-400">Validation Passed</h3>
                </>
              ) : (
                <>
                  <Ban size={20} className="text-red-500" />
                  <h3 className="text-lg font-semibold text-red-700 dark:text-red-400">Validation Failed</h3>
                </>
              )}
            </div>

            {!validating && (
              <div className="space-y-3">
                {validateResult.success ? (
                  <p className="text-sm text-gray-600 dark:text-gray-400">
                    All coverage gates passed. Spec has been moved to <span className="font-semibold text-purple-600">Validated</span>.
                  </p>
                ) : (
                  <ValidationErrorDisplay error={validateResult.error || ''} />
                )}
                <div className="flex justify-end gap-2 pt-2">
                  <button
                    onClick={() => setShowValidateModal(false)}
                    className="btn btn-secondary text-sm"
                  >
                    Close
                  </button>
                  {!validateResult.success && (
                    <button
                      onClick={() => { setShowValidateModal(false); setActiveTab('tests'); }}
                      className="btn btn-primary text-sm"
                    >
                      Review Coverage
                    </button>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Spec Validation Gate — submission modal (opens when board opts in and user clicks Validate) */}
      {showSubmitValidationModal && spec && perms.has('spec.validation.submit') && (
        <SubmitSpecValidationModal
          refreshKey={validationHistoryRefreshKey}
          specId={spec.id}
          specTitle={spec.title}
          boardId={spec.board_id}
          specVersion={spec.version}
          specEdition={spec.edition}
          settings={boardSettings}
          canReadChecklist={canReadChecklist}
          canExecuteChecklist={canExecuteChecklist}
          canSubmitDecomposition={hasPermissionWithState(perms.has, 'spec.evaluations.submit', 'spec', spec.status)}
          onClose={() => setShowSubmitValidationModal(false)}
          onSubmitted={async () => {
            setShowSubmitValidationModal(false);
            await loadSpec();
            setValidationHistoryRefreshKey((current) => current + 1);
            onChanged();
          }}
        />
      )}

      {/* Cancellation justification (ITEM 17) */}
      <CancellationReasonDialog
        open={cancelDialogOpen}
        entityLabel="spec"
        submitting={movingTo === 'cancelled'}
        onConfirm={async (reason) => {
          setCancelDialogOpen(false);
          await handleMoveSpec('cancelled' as SpecStatus, reason);
        }}
        onCancel={() => setCancelDialogOpen(false)}
      />
    </div>
  );
}

/**
 * TechnicalRequirementsTab - TR management with task linkage coverage
 */

import { useEffect, useState, useMemo } from 'react';
import { Plus, Trash2, Settings, CheckCircle, XCircle, Link, Unlink, Pencil } from 'lucide-react';
import toast from 'react-hot-toast';
import type { Spec, TechnicalRequirement } from '@/types';
import { useSpecCollectionEditor } from './useSpecCollectionEditor';
import { SpecCollectionDraftNotice } from './SpecCollectionDraftNotice';

interface TechnicalRequirementsTabProps {
  spec: Spec;
  onUpdate: (trs: TechnicalRequirement[], expectedVersion: number) => void | Promise<void>;
  readCurrent?: boolean;
  specCards?: { id: string; title: string; status: string }[];
  onLinkTask?: (trId: string, cardId: string) => Promise<void>;
  onUnlinkTask?: (trId: string, cardId: string) => Promise<void>;
  onSpecUpdate?: (patch: Record<string, any>) => void;
  canCreate?: boolean;
  canEdit?: boolean;
  canDelete?: boolean;
  canLinkTask?: boolean;
  focusEditId?: string | null;
  focusCreateToken?: number | null;
  onFocusHandled?: () => void;
}

export function TechnicalRequirementsTab(props: TechnicalRequirementsTabProps) {
  return <TechnicalRequirementsTabEditor key={`${props.spec.board_id}:${props.spec.id}:${props.canCreate}:${props.canEdit}`} {...props} />;
}

function TechnicalRequirementsTabEditor({
  spec,
  onUpdate,
  readCurrent = true,
  specCards,
  onLinkTask,
  onUnlinkTask,
  onSpecUpdate,
  canCreate = true,
  canEdit = true,
  canDelete = true,
  canLinkTask = true,
  focusEditId = null,
  focusCreateToken = null,
  onFocusHandled,
}: TechnicalRequirementsTabProps) {
  const editor = useSpecCollectionEditor(spec, readCurrent);
  const begin = editor.begin;
  const [draft, setDraft] = useState('');
  const [adding, setAdding] = useState(false);
  const [editingTrId, setEditingTrId] = useState<string | null>(null);
  const [editDraft, setEditDraft] = useState('');
  const [linkingTrId, setLinkingTrId] = useState<string | null>(null);

  const rawTRs = spec.technical_requirements || [];
  if (rawTRs.some((tr) => !tr || typeof tr !== 'object'
    || typeof tr.id !== 'string' || !tr.id.trim()
    || typeof tr.text !== 'string' || !tr.text.trim())) {
    throw new Error('Incompatible technical requirement: id and text are required');
  }
  const trs = rawTRs.filter((tr) => (tr.status || 'active') === 'active');
  const removed = !!editingTrId && !trs.some(item => item.id === editingTrId);

  // Coverage: TRs with at least one linked task
  const coverage = useMemo(() => {
    const withTasks = trs.filter(tr => tr.linked_task_ids && tr.linked_task_ids.length > 0);
    return {
      covered: withTasks.length,
      total: trs.length,
      pct: trs.length > 0 ? Math.round((withTasks.length / trs.length) * 100) : 0,
    };
  }, [trs]);

  const handleAdd = async () => {
    const text = draft.trim();
    if (!text) return;
    const id = `tr_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`;
    const newTR: TechnicalRequirement = { id, text, linked_task_ids: null };
    if (!canCreate || !await editor.save(version => onUpdate([...rawTRs, newTR], version))) return;
    setDraft('');
    setAdding(false);
  };

  const handleRemove = async (id: string) => {
    if (canDelete) await editor.save(version => onUpdate(rawTRs.filter(tr => tr.id !== id), version), true);
  };

  const startEdit = (tr: TechnicalRequirement) => {
    if (!canEdit || !editor.begin()) return;
    setEditingTrId(tr.id);
    setEditDraft(tr.text);
  };

  useEffect(() => {
    if (!focusEditId || !canEdit) return;
    if (editingTrId || adding) return;
    const target = trs.find((tr) => tr.id === focusEditId);
    if (!target) return;
    startEdit(target);
    onFocusHandled?.();
  }, [focusEditId, canEdit, spec.technical_requirements, onFocusHandled, editingTrId, adding]);

  useEffect(() => {
    if (!focusCreateToken || !canCreate) return;
    if (editingTrId || adding) return;
    if (!begin()) return;
    setAdding(true);
    onFocusHandled?.();
  }, [focusCreateToken, canCreate, onFocusHandled, editingTrId, adding, begin]);

  const cancelEdit = () => {
    if (editor.saving) return;
    editor.cancel();
    setEditingTrId(null);
    setEditDraft('');
  };

  const saveEdit = async () => {
    if (!editingTrId || !editDraft.trim()) return;
    if (removed || !canEdit || !await editor.save(version => onUpdate(rawTRs.map((tr) => tr.id === editingTrId ? { ...tr, text: editDraft.trim() } : tr), version))) return;
    setEditingTrId(null); setEditDraft('');
  };

  return (
    <div className="space-y-4">
      <SpecCollectionDraftNotice editor={editor} active={adding || !!editingTrId} removed={removed} currentText={trs.find(item => item.id === editingTrId)?.text} />
      {removed && <div className="space-y-2">
        <input aria-label="Removed requirement draft" value={editDraft} onChange={event => setEditDraft(event.target.value)} className="w-full input" />
        <button disabled className="btn btn-primary text-xs">Save</button>
        <button onClick={cancelEdit} className="btn btn-secondary text-xs">Cancel</button>
      </div>}
      {/* TR Task Linkage Coverage */}
      {trs.length > 0 && (
        <div className="border border-gray-200 dark:border-gray-700 rounded-lg p-3">
          <div className="flex items-center justify-between mb-2">
            <h4 className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">
              TR Task Coverage ({coverage.covered}/{coverage.total})
            </h4>
            {coverage.covered === coverage.total && coverage.total > 0 ? (
              <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300 font-medium">
                100% linked
              </span>
            ) : (
              <span className="text-[10px] px-1.5 py-0.5 rounded bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300 font-medium">
                {coverage.pct}% linked
              </span>
            )}
          </div>
          {/* Progress bar */}
          <div className="h-2 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden mb-2">
            <div
              className={`h-full transition-all duration-500 rounded-full ${coverage.covered === coverage.total && coverage.total > 0 ? 'bg-green-500' : 'bg-amber-500'}`}
              style={{ width: `${coverage.pct}%` }}
            />
          </div>
          {/* TR list with coverage */}
          <div className="space-y-1 max-h-48 overflow-y-auto">
            {trs.map((tr) => {
              const taskCount = tr.linked_task_ids?.length ?? 0;
              const linked = taskCount > 0;
              return (
                <div key={tr.id} className="flex items-start gap-2 text-xs">
                  {linked ? (
                    <CheckCircle className="w-3.5 h-3.5 text-green-500 shrink-0 mt-0.5" />
                  ) : (
                    <XCircle className="w-3.5 h-3.5 text-gray-300 dark:text-gray-600 shrink-0 mt-0.5" />
                  )}
                  <span className={`flex-1 line-clamp-1 ${linked ? 'text-gray-700 dark:text-gray-300' : 'text-gray-400 dark:text-gray-500'}`}>
                    {tr.text}
                  </span>
                  {linked && (
                    <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300 shrink-0">
                      {taskCount} task{taskCount !== 1 ? 's' : ''}
                    </span>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Skip TRs coverage toggle */}
      {onSpecUpdate && (
        <div className="flex items-center justify-between px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-700 bg-gray-50/50 dark:bg-gray-700/20">
          <div>
            <span className="text-xs font-medium text-gray-700 dark:text-gray-300">Skip TRs coverage requirement</span>
            <p className="text-[10px] text-gray-400">Allow starting cards without full TR→Task coverage</p>
          </div>
          <button
            onClick={() => onSpecUpdate({ skip_trs_coverage: !(spec as any).skip_trs_coverage })}
            className={`relative w-10 h-5 rounded-full transition-colors ${(spec as any).skip_trs_coverage ? 'bg-amber-500' : 'bg-gray-300 dark:bg-gray-600'}`}
          >
            <span className={`absolute top-0.5 left-0.5 w-4 h-4 rounded-full bg-white transition-transform ${(spec as any).skip_trs_coverage ? 'translate-x-5' : ''}`} />
          </button>
        </div>
      )}

      {/* TR list */}
      {trs.length === 0 && !adding && (
        <div className="text-center py-6">
          <Settings size={32} className="mx-auto text-gray-300 dark:text-gray-600 mb-2" />
          <p className="text-sm text-gray-500 dark:text-gray-400">No technical requirements</p>
          <p className="text-xs text-gray-400 dark:text-gray-500 mt-1">Technical constraints and architectural decisions</p>
        </div>
      )}

      {trs.map((tr) => {
        const taskCount = tr.linked_task_ids?.length ?? 0;
        const linkedTaskIds = new Set(tr.linked_task_ids || []);
        const availableCards = (specCards || []).filter(c => !linkedTaskIds.has(c.id));
        return (
          <div key={tr.id} data-readiness-ref={`tr:${tr.id}`} tabIndex={-1} className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden focus-visible:outline focus-visible:outline-2 focus-visible:outline-sky-500">
            <div className="flex items-start gap-2 px-3 py-2 group">
              <Settings size={14} className="text-gray-400 shrink-0 mt-0.5" />
              {editingTrId === tr.id ? (
                <fieldset disabled={editor.saving} className="flex-1 flex gap-2">
                  <input
                    type="text"
                    value={editDraft}
                    onChange={(event) => setEditDraft(event.target.value)}
                    onKeyDown={(event) => {
                      if (event.key === 'Enter') saveEdit();
                      if (event.key === 'Escape') {
                        event.preventDefault();
                        event.stopPropagation();
                        cancelEdit();
                      }
                    }}
                    className="flex-1 px-2 py-1 border border-gray-300 rounded-md text-sm dark:bg-gray-700 dark:border-gray-600"
                    autoFocus
                  />
                  <button onClick={saveEdit} disabled={!editDraft.trim() || editor.blocked || removed} className="btn btn-primary text-xs">Save</button>
                  <button onClick={cancelEdit} className="btn btn-secondary text-xs">Cancel</button>
                </fieldset>
              ) : (
                <span className="text-sm text-gray-700 dark:text-gray-300 flex-1">{tr.text}</span>
              )}
              {taskCount > 0 ? (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300 shrink-0">
                  {taskCount} task{taskCount !== 1 ? 's' : ''}
                </span>
              ) : (
                <span className="text-[10px] px-1.5 py-0.5 rounded bg-gray-100 text-gray-400 dark:bg-gray-700 dark:text-gray-500 shrink-0">
                  0 tasks
                </span>
              )}
              {canLinkTask && onLinkTask && availableCards.length > 0 && (
                <button onClick={() => setLinkingTrId(linkingTrId === tr.id ? null : tr.id)} className="p-0.5 text-blue-400 hover:text-blue-600 shrink-0" title="Link task">
                  <Link size={12} />
                </button>
              )}
              {canEdit && editingTrId !== tr.id && (
                <button
                  onClick={() => startEdit(tr)}
                  disabled={editor.saving || !readCurrent || adding}
                  title="Edit"
                  className="opacity-0 group-hover:opacity-100 p-0.5 text-blue-400 hover:text-blue-600 transition-opacity shrink-0"
                >
                  <Pencil size={12} />
                </button>
              )}
              <button
                onClick={() => handleRemove(tr.id)}
                disabled={!canDelete || editor.saving || !readCurrent || adding || !!editingTrId}
                title={canDelete ? 'Remove' : 'Requires spec.structured_entity.technical_requirement.revoke'}
                className={`opacity-0 group-hover:opacity-100 p-0.5 transition-opacity shrink-0 ${canDelete ? 'text-red-400 hover:text-red-600' : 'text-gray-300 cursor-not-allowed'}`}
              >
                <Trash2 size={12} />
              </button>
            </div>
            {/* Linked tasks */}
            {taskCount > 0 && (
              <div className="px-3 pb-2 space-y-1">
                {(tr.linked_task_ids || []).map(taskId => {
                  const card = (specCards || []).find(c => c.id === taskId);
                  return (
                    <div key={taskId} className="flex items-center justify-between text-xs px-2 py-1 rounded bg-green-50 dark:bg-green-900/10 group/task">
                      <span className="text-gray-600 dark:text-gray-400 truncate">{card?.title || taskId.slice(0, 8) + '…'}</span>
                      {canLinkTask && onUnlinkTask && (
                        <button onClick={async () => { try { await onUnlinkTask(tr.id, taskId); toast.success('Task unlinked'); } catch { toast.error('Failed'); } }} className="p-0.5 text-gray-400 hover:text-red-500 opacity-0 group-hover/task:opacity-100 shrink-0">
                          <Unlink size={10} />
                        </button>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
            {/* Card picker */}
            {linkingTrId === tr.id && availableCards.length > 0 && (
              <div className="px-3 pb-2 border-t border-gray-100 dark:border-gray-700 pt-2 space-y-1 max-h-32 overflow-y-auto">
                <p className="text-[10px] text-gray-400">Click to link:</p>
                {availableCards.map(card => (
                  <button key={card.id} onClick={async () => { try { await onLinkTask!(tr.id, card.id); setLinkingTrId(null); toast.success('Task linked'); } catch { toast.error('Failed'); } }} className="w-full flex items-center gap-2 px-2 py-1 rounded text-xs text-left hover:bg-blue-50 dark:hover:bg-blue-900/20">
                    <span className="text-gray-600 dark:text-gray-400 truncate">{card.title}</span>
                    <Link size={10} className="text-gray-400 shrink-0 ml-auto" />
                  </button>
                ))}
              </div>
            )}
          </div>
        );
      })}

      {/* Add form */}
      {adding ? (
        <fieldset disabled={editor.saving} className="flex gap-2">
          <input
            type="text"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleAdd()}
            placeholder="Add a technical constraint..."
            className="flex-1 px-3 py-2 border border-gray-300 rounded-lg text-sm dark:bg-gray-700 dark:border-gray-600"
            autoFocus
          />
          <button onClick={handleAdd} disabled={!draft.trim() || editor.blocked} className="btn btn-primary text-xs">Add</button>
          <button onClick={() => { editor.cancel(); setAdding(false); setDraft(''); }} className="btn btn-secondary text-xs">Cancel</button>
        </fieldset>
      ) : (
        <button
          onClick={() => { if (editor.begin()) setAdding(true); }}
          disabled={!canCreate || editor.saving || !readCurrent || !!editingTrId}
          title={canCreate ? 'Add Technical Requirement' : 'Requires spec.structured_entity.technical_requirement.create'}
          className={`flex items-center gap-1 text-sm ${canCreate ? 'text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-300' : 'text-gray-300 cursor-not-allowed'}`}
        >
          <Plus size={14} /> Add Technical Requirement
        </button>
      )}
    </div>
  );
}

import { AlertTriangle, ShieldAlert, Wrench } from 'lucide-react';

interface ResourceGateBlocker {
  resource_type?: string;
  resource_id?: string;
  resource_title?: string | null;
  source_entity_type?: string | null;
  source_entity_title?: string | null;
  reason?: string;
  remediation?: string;
}

interface ParsedValidationError {
  gateType: string;
  gateTypeCode: string | null;
  issue: string;
  action: string | null;
  resources: ResourceGateBlocker[];
  requiredTool: string | null;
  followUpTool: string | null;
  blockedTransition: string | null;
  requiredStatus: string | null;
  enforcementMode: string | null;
  enforcementActive: boolean | null;
  wouldBlockDone: boolean | null;
  // True when the backend supplied a structured gate contract (R4): the UI then
  // renders the REAL gate instead of inferring one from the message text.
  structured: boolean;
  blockingCandidateIds: string[];
  blockingCandidatesTruncated: boolean;
}

const RESOURCE_LABELS: Record<string, string> = {
  architecture: 'Architecture',
  mockup: 'Mockup',
  knowledge_base: 'Knowledge Base',
};

// R4-IMP2: map the structured gate_type to a human label so the UI never shows a
// fixed "spec must be validated" copy for a qualitative-evaluation / resource /
// cognitive-readiness / test-card block.
const GATE_TYPE_LABELS: Record<string, string> = {
  spec_validation: 'Spec Validation',
  spec_checklist: 'Spec Checklist',
  spec_architecture_classification: 'Architecture Classification',
  spec_qualitative_evaluation: 'Qualitative Evaluation',
  test_card_completion: 'Test Card Completion',
  resource_gate: 'Resource Coverage',
  code_evidence_disposition_required: 'Code Evidence Coverage',
  code_evidence_disposition: 'Code Evidence Coverage',
  spec_evidence_disposition: 'Code Evidence Coverage',
  cognitive_readiness: 'Cognitive Readiness',
  state_transition: 'State Transition',
};

function asObject(value: unknown): Record<string, any> | null {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? (value as Record<string, any>)
    : null;
}

function tryParseJson(raw: string): unknown | null {
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

function resourceLabel(resourceType?: string): string {
  if (!resourceType) return 'Resource';
  return RESOURCE_LABELS[resourceType] ?? resourceType.replace(/_/g, ' ');
}

function reasonLabel(reason?: string): string {
  if (reason === 'covered_only_by_cancelled_task') {
    return 'Covered only by cancelled task';
  }
  if (reason === 'uncovered') {
    return 'Uncovered';
  }
  return reason ? reason.replace(/_/g, ' ') : 'Blocked';
}

function gateTypeLabel(code: string): string {
  return GATE_TYPE_LABELS[code] ?? code.replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

function _str(value: unknown): string | null {
  return typeof value === 'string' && value ? value : null;
}

function _bool(value: unknown): boolean | null {
  return typeof value === 'boolean' ? value : null;
}

const _EMPTY: Omit<ParsedValidationError, 'gateType' | 'gateTypeCode' | 'issue' | 'action' | 'resources' | 'structured'> = {
  requiredTool: null,
  followUpTool: null,
  blockedTransition: null,
  requiredStatus: null,
  enforcementMode: null,
  enforcementActive: null,
  wouldBlockDone: null,
  blockingCandidateIds: [],
  blockingCandidatesTruncated: false,
};

export function parseValidationErrorMessage(error: string): ParsedValidationError {
  const parsed = tryParseJson(error);
  const obj = asObject(parsed);
  const detail = asObject(obj?.detail) ?? obj;
  const code = typeof detail?.error === 'string' ? detail.error : null;
  const message = typeof detail?.message === 'string' ? detail.message : error;
  const details = asObject(detail?.details);
  const policyReasons: Record<string, string> = {
    policy_subject_required: 'The authoritative policy subject could not be verified.',
    policy_compliance_receipt_missing: 'An applicable policy has no accepted assessment for this edition.',
    policy_compliance_receipt_stale: 'An applicable policy assessment is no longer current.',
    policy_compliance_blocked: 'An applicable policy assessment does not satisfy its required criteria.',
    policy_assessment_unavailable: 'The policy assessment could not be verified. This does not count as approval.',
  };
  const policyTransition = asObject(detail?.transition);
  if (code && Object.prototype.hasOwnProperty.call(policyReasons, code) && detail?.policy_compliance_required === true
    && Array.isArray(detail.reason_codes) && detail.reason_codes.includes(code)
    && policyTransition?.entity_type === 'spec') {
    const reasons = detail.reason_codes.filter((reason): reason is string =>
      typeof reason === 'string' && Object.prototype.hasOwnProperty.call(policyReasons, reason));
    const from = _str(policyTransition.from_status);
    const to = _str(policyTransition.to_status);
    return {
      ..._EMPTY,
      gateType: 'Policy Compliance', gateTypeCode: 'policy_compliance',
      issue: reasons.map(reason => policyReasons[reason]).join(' '),
      action: 'Open Policy Compliance in Validation to review the applicable assessment and its findings.',
      resources: [], structured: true,
      blockedTransition: from && to ? `${from}->${to}` : null,
    };
  }
  const resources =
    (Array.isArray(details?.uncovered_resources) ? details?.uncovered_resources : null) ??
    (Array.isArray(detail?.uncovered_resources) ? detail?.uncovered_resources : null) ??
    [];
  const fromDetails = (key: string): unknown => details?.[key] ?? detail?.[key];
  const blockerObjects = (Array.isArray(fromDetails('blockers')) ? fromDetails('blockers') : []) as unknown[];
  const codeEvidenceBlocker = blockerObjects
    .map(asObject)
    .find((blocker) => blocker?.code === 'code_evidence_disposition_required');
  const hintedGateType = _str(fromDetails('gate_type'));
  const isCodeEvidenceCoverage = (
    code === 'code_evidence_disposition_required'
    || Boolean(codeEvidenceBlocker)
    || hintedGateType === 'code_evidence_disposition_required'
    || hintedGateType === 'code_evidence_disposition'
    || hintedGateType === 'spec_evidence_disposition'
    || /Code Evidence Matrix/i.test(message)
    || /active inherited Evidence.*(?:link|final disposition)/i.test(message)
  );

  if (isCodeEvidenceCoverage) {
    return {
      gateType: 'Code Evidence Coverage',
      gateTypeCode: 'code_evidence_disposition_required',
      issue: _str(codeEvidenceBlocker?.message) ?? message,
      action:
        'Open the Code Evidence Matrix tab and link each pending inherited Evidence item to the Spec entities it supports, or record a final disposition. While the Spec is in Draft, an authorized user may intentionally enable Skip Code Evidence coverage for this obligation only.',
      resources: [],
      ...(_EMPTY),
      structured: Boolean(codeEvidenceBlocker || hintedGateType),
    };
  }

  // R4-IMP2: prefer the STRUCTURED gate contract (gate_contracts.GateContractError
  // envelope) when present — render the real gate, its required tool, operator
  // action, blocked transition, enforcement mode and would_block_done. Read each
  // field from `details` first, falling back to `detail` so we are robust whether
  // the envelope is wrapped under `details` or flattened on the error object.
  const gateTypeCode = _str(fromDetails('gate_type'));
  if (gateTypeCode) {
    const reqIdx = message.indexOf('REQUIRED ACTION:');
    const legacyAction = reqIdx > 0 ? message.slice(reqIdx + 16).trim() : null;
    // operator_action preferred; required_action accepted as alias; legacy last.
    const structuredAction =
      _str(fromDetails('operator_action')) ?? _str(fromDetails('required_action'));
    const enforcementActive = _bool(fromDetails('enforcement_active'));
    let enforcementMode = _str(fromDetails('enforcement_mode'));
    if (!enforcementMode && enforcementActive !== null) {
      // Derive a label from the boolean so the badge shows even without a mode.
      enforcementMode = enforcementActive ? 'enforced' : 'advisory';
    }
    return {
      gateType: gateTypeLabel(gateTypeCode),
      gateTypeCode,
      issue: message,
      action: structuredAction ?? legacyAction,
      resources: resources as ResourceGateBlocker[],
      requiredTool: _str(fromDetails('required_tool')),
      followUpTool: _str(fromDetails('follow_up_tool')),
      blockedTransition: _str(fromDetails('blocked_transition')),
      requiredStatus: _str(fromDetails('required_status')),
      enforcementMode,
      enforcementActive,
      wouldBlockDone: _bool(fromDetails('would_block_done')),
      structured: true,
      blockingCandidateIds: gateTypeCode === 'spec_architecture_classification'
        && Array.isArray(fromDetails('blocking_candidate_ids'))
        ? (fromDetails('blocking_candidate_ids') as unknown[])
          .filter((id): id is string => typeof id === 'string' && id.length > 0).slice(0, 25)
        : [],
      blockingCandidatesTruncated: fromDetails('blocking_candidates_truncated') === true,
    };
  }

  // Resource Gate (ResourceGateError) — has uncovered_resources but no gate_type.
  if (code === 'resource_gate_spec_task_coverage' || resources.length > 0 || /resource/i.test(message)) {
    return {
      gateType: 'Resource Coverage',
      gateTypeCode: 'resource_gate',
      issue: message,
      action:
        'Attach or copy each listed spec resource directly to at least one non-cancelled task, or disable the board Resource Gate setting if this check should not apply.',
      resources: resources as ResourceGateBlocker[],
      ...(_EMPTY),
      structured: false,
    };
  }

  // Legacy free-text fallback — infer the gate from the message copy.
  const reqIdx = message.indexOf('REQUIRED ACTION:');
  const issue = reqIdx > 0 ? message.slice(0, reqIdx).trim() : message;
  const action = reqIdx > 0 ? message.slice(reqIdx + 16).trim() : null;

  let gateType = 'unknown';
  if (message.includes('test scenario')) { gateType = 'Test Coverage'; }
  else if (message.includes('business rule')) { gateType = 'Rules Coverage'; }
  else if (message.includes('technical requirement') || message.includes('TR')) { gateType = 'TRs Coverage'; }
  else if (message.includes('api contract') || message.includes('contract')) { gateType = 'Contract Coverage'; }
  else if (message.includes('evaluation') || message.includes('approval')) { gateType = 'Qualitative Validation'; }
  else if (message.includes('state machine') || message.includes('transition')) { gateType = 'State Transition'; }

  return {
    gateType,
    gateTypeCode: null,
    issue,
    action,
    resources: [],
    ...(_EMPTY),
    structured: false,
  };
}

export function ValidationErrorDisplay({ error }: { error: string }) {
  const parsed = parseValidationErrorMessage(error);

  // R4-IMP2: header reflects the REAL gate — no fixed "before the spec can be
  // validated" copy when the block is evaluation / resource / cognitive / test-card.
  const headerText =
    parsed.gateTypeCode === 'spec_validation'
      ? 'This spec validation gate must be satisfied before the spec can be validated:'
      : 'The following gate must be satisfied before this action can proceed:';

  return (
    <div className="space-y-3">
      <p className="text-sm text-gray-500 dark:text-gray-400">{headerText}</p>

      <div className="flex flex-wrap items-center gap-2 mb-2">
        <span className="text-[10px] px-2 py-0.5 rounded-full bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300 font-semibold uppercase tracking-wide">
          {parsed.gateType}
        </span>
        {parsed.enforcementMode && (
          <span
            className="text-[10px] px-2 py-0.5 rounded-full bg-gray-200 text-gray-700 dark:bg-gray-700 dark:text-gray-200 font-semibold uppercase tracking-wide inline-flex items-center gap-1"
            title={parsed.enforcementActive === false ? 'Advisory: surfaced but not enforced by board policy' : 'Enforced by board policy'}
          >
            <ShieldAlert size={11} />
            {parsed.enforcementMode}
          </span>
        )}
        {parsed.wouldBlockDone && (
          <span className="text-[10px] px-2 py-0.5 rounded-full bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-200 font-semibold uppercase tracking-wide">
            Blocks done
          </span>
        )}
      </div>

      {(parsed.blockedTransition || parsed.requiredStatus) && (
        <p className="text-xs text-gray-500 dark:text-gray-400">
          {parsed.blockedTransition && (
            <>Blocked transition: <code className="text-gray-700 dark:text-gray-300">{parsed.blockedTransition}</code></>
          )}
          {parsed.blockedTransition && parsed.requiredStatus ? ' · ' : ''}
          {parsed.requiredStatus && (
            <>Required status: <code className="text-gray-700 dark:text-gray-300">{parsed.requiredStatus}</code></>
          )}
        </p>
      )}

      <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-lg p-4">
        <p className="text-sm text-red-800 dark:text-red-200 leading-relaxed">
          {parsed.issue}
        </p>
      </div>

      {parsed.blockingCandidateIds.length > 0 && (
        <div className="text-xs text-gray-700 dark:text-gray-300">
          <p>Architecture candidates requiring review</p>
          <ul>{parsed.blockingCandidateIds.map((id) => <li key={id}><code>{id}</code></li>)}</ul>
          {parsed.blockingCandidatesTruncated && <p>More candidates require review. Open Architecture Classifications for the full list.</p>}
        </div>
      )}

      {parsed.resources.length > 0 && (
        <div className="bg-gray-50 dark:bg-gray-900/40 border border-gray-200 dark:border-gray-700 rounded-lg p-3 space-y-2">
          <p className="text-[10px] font-semibold text-gray-600 dark:text-gray-300 uppercase tracking-wide">
            Uncovered resources
          </p>
          <div className="space-y-2">
            {parsed.resources.map((resource, index) => (
              <div
                key={`${resource.resource_type}-${resource.resource_id ?? index}`}
                className="rounded border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 p-2"
              >
                <div className="flex items-start justify-between gap-2">
                  <div className="min-w-0">
                    <p className="text-xs font-semibold text-gray-900 dark:text-gray-100 truncate">
                      {resourceLabel(resource.resource_type)}
                      {resource.resource_title ? `: ${resource.resource_title}` : ''}
                    </p>
                    {(resource.source_entity_title || resource.source_entity_type) && (
                      <p className="text-[11px] text-gray-500 dark:text-gray-400 truncate">
                        From {resource.source_entity_title || resource.source_entity_type}
                      </p>
                    )}
                  </div>
                  <span className="shrink-0 text-[10px] px-2 py-0.5 rounded bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-200">
                    {reasonLabel(resource.reason)}
                  </span>
                </div>
                {resource.remediation && (
                  <p className="mt-1 text-[11px] text-gray-600 dark:text-gray-300 leading-relaxed">
                    {resource.remediation}
                  </p>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      {(parsed.action || parsed.requiredTool) && (
        <div className="bg-amber-50 dark:bg-amber-900/10 border border-amber-200 dark:border-amber-800 rounded-lg p-4">
          <p className="text-[10px] font-semibold text-amber-700 dark:text-amber-300 uppercase tracking-wide mb-1 flex items-center gap-1.5">
            <AlertTriangle size={12} />
            Required Action
          </p>
          {parsed.action && (
            <p className="text-sm text-amber-800 dark:text-amber-200 leading-relaxed">
              {parsed.action}
            </p>
          )}
          {parsed.requiredTool && (
            <p className="mt-2 text-[11px] text-amber-700 dark:text-amber-300 inline-flex items-center gap-1.5">
              <Wrench size={11} />
              Use <code className="font-mono">{parsed.requiredTool}</code>
              {parsed.followUpTool && (
                <>, then <code className="font-mono">{parsed.followUpTool}</code></>
              )}
            </p>
          )}
        </div>
      )}
    </div>
  );
}

