/**
 * API Context - provides authenticated API client to components
 */

import React, { createContext, useContext, useMemo, useCallback, useEffect } from 'react';
import { AuthenticatedFetch, initAuthFetch } from '@/lib/authFetch';
import { authAdapter } from '@/adapters';

const API_BASE_URL = (typeof window !== 'undefined' && (window as any).OKTO_PULSE_CONFIG?.API_URL) || import.meta.env.VITE_API_URL || '/api/v1';

interface ApiContextValue {
  apiClient: AuthenticatedFetch;
  getFreshToken: () => Promise<string | null>;
  getToken: () => Promise<string | null>;
  isReady: boolean;
}

const ApiContext = createContext<ApiContextValue | null>(null);

interface ApiProviderProps {
  children: React.ReactNode;
  onAuthFailure?: () => void;
}

export function ApiProvider({ children }: ApiProviderProps) {
  const { getToken: adapterGetToken, isLoaded, isSignedIn, identityKey } = authAdapter.useAuth();

  const tokenGetter = useCallback(
    async (options?: { skipCache?: boolean }): Promise<string | null> => {
      if (!isLoaded || !isSignedIn) {
        return null;
      }

      try {
        const token = await adapterGetToken({
          skipCache: options?.skipCache ?? false,
        });
        return token;
      } catch (error) {
        console.error('[ApiProvider] Error getting token:', error);
        return null;
      }
    },
    [adapterGetToken, isLoaded, isSignedIn]
  );

  const apiClient = useMemo(() => {
    return new AuthenticatedFetch(tokenGetter, API_BASE_URL);
  }, [tokenGetter, identityKey]);

  useEffect(() => {
    initAuthFetch(tokenGetter, API_BASE_URL);
  }, [tokenGetter]);

  const getFreshToken = useCallback(async (): Promise<string | null> => {
    return tokenGetter({ skipCache: true });
  }, [tokenGetter]);

  const getToken = useCallback(async (): Promise<string | null> => {
    return tokenGetter();
  }, [tokenGetter]);

  const value = useMemo(
    () => ({
      apiClient,
      getFreshToken,
      getToken,
      isReady: isLoaded,
    }),
    [apiClient, getFreshToken, getToken, isLoaded]
  );

  return <ApiContext.Provider value={value}>{children}</ApiContext.Provider>;
}

export function useApiContext(): ApiContextValue {
  const context = useContext(ApiContext);
  if (!context) {
    throw new Error('useApiContext must be used within an ApiProvider');
  }
  return context;
}

export function useApiClient(): AuthenticatedFetch {
  const { apiClient } = useApiContext();
  return apiClient;
}

/**
 * ModalStackContext — drill-down navigation stack for entity modals.
 *
 * Ideação c13f7bd3. Previously, clicking a "Find similar" result inside a
 * modal (e.g. NodeDetailModal) either did nothing or replaced the current
 * modal's content in place — the user lost the path they were tracing and
 * had no way back. This context gives every modal a shared stack:
 *
 *   - `push({type, id})` opens a new modal layered on top of the current
 *     one. The previous entry is kept intact.
 *   - `pop()` dismisses the top modal, revealing the one beneath. Wired
 *     to the "← back" button rendered by `ModalStackRenderer` whenever
 *     `stack.length > 1`.
 *   - `clear()` closes the entire stack. Wired to every modal's own
 *     close/X control — "X fecha todas as modais, independente do nível
 *     de drill down".
 *
 * Entities supported today: card, story, spec, ideation, refinement,
 * kg_node. New entity types just need an entry in ModalStackRenderer.
 */

import { createContext, useCallback, useContext, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import type { ReadinessCardLocation, ReadinessSpecTab } from '@/components/code-traceability/readinessNavigation';

export type ModalStackEntry = { boardId?: string } & (
  | { type: 'card'; id: string; target?: ReadinessCardLocation }
  | { type: 'story'; id: string }
  | {
    type: 'spec';
    id: string;
    initialTab?: 'evidence-matrix' | 'project-structure' | ReadinessSpecTab;
    focusProjectNodeId?: string | null;
    focusReadinessRef?: string | null;
  }
  | { type: 'ideation'; id: string }
  | { type: 'refinement'; id: string }
  | { type: 'kg_node'; id: string });

interface ModalStackContextValue {
  stack: ModalStackEntry[];
  push: (entry: ModalStackEntry) => void;
  pop: () => void;
  clear: () => void;
}

const ModalStackContext = createContext<ModalStackContextValue | null>(null);

export function ModalStackProvider({ children }: { children: ReactNode }) {
  const [stack, setStack] = useState<ModalStackEntry[]>([]);

  const push = useCallback((entry: ModalStackEntry) => {
    // Old links or external graph data must not open an unsupported modal.
    if (!['card', 'story', 'spec', 'ideation', 'refinement', 'kg_node'].includes(entry.type)) return;
    setStack((prev) => {
      // Dedupe: if the top of the stack is the same entity, don't push
      // twice (avoids double-click creating phantom layers).
      const top = prev[prev.length - 1];
      const scopedEntry = entry.boardId === undefined && top?.boardId
        ? { ...entry, boardId: top.boardId } : entry;
      if (top && top.type === scopedEntry.type && top.id === scopedEntry.id && top.boardId === scopedEntry.boardId) {
        if (top.type === 'card' && scopedEntry.type === 'card' && scopedEntry.target
          && JSON.stringify(top.target) !== JSON.stringify(scopedEntry.target)) return [...prev.slice(0, -1), scopedEntry];
        if (top.type === 'spec' && scopedEntry.type === 'spec' && scopedEntry.initialTab
          && (top.initialTab !== scopedEntry.initialTab || top.focusReadinessRef !== scopedEntry.focusReadinessRef
            || top.focusProjectNodeId !== scopedEntry.focusProjectNodeId)) return [...prev.slice(0, -1), scopedEntry];
        return prev;
      }
      return [...prev, scopedEntry];
    });
  }, []);

  const pop = useCallback(() => {
    setStack((prev) => prev.slice(0, -1));
  }, []);

  const clear = useCallback(() => {
    setStack([]);
  }, []);

  const value = useMemo(
    () => ({ stack, push, pop, clear }),
    [stack, push, pop, clear],
  );

  return (
    <ModalStackContext.Provider value={value}>
      {children}
    </ModalStackContext.Provider>
  );
}

export function useModalStack(): ModalStackContextValue {
  const ctx = useContext(ModalStackContext);
  if (!ctx) {
    throw new Error(
      'useModalStack must be used inside <ModalStackProvider>. ' +
        'Wrap the app (App.tsx) with the provider.',
    );
  }
  return ctx;
}

/** Non-throwing variant — used by components that may render outside the
 * provider (e.g. on standalone pages where drill-down is not expected). */
export function useOptionalModalStack(): ModalStackContextValue | null {
  return useContext(ModalStackContext);
}

import { useEffect, useRef, useState } from 'react';
import { useApiClient } from '@/contexts/ApiContext';
import { useDashboardApi } from '@/services/api';
import { AuthenticatedFetchError } from '@/lib/authFetch';
import { useDashboardStore } from '@/store/dashboard';
import type { WorkspaceSubjectRef } from '@/types';
import { WorkspaceRevisionWatch, type WorkspaceChange, type WorkspaceSyncState } from './workspaceRevisionWatch';

const watches = new WeakMap<object, Map<string, WorkspaceRevisionWatch>>();

export function useWorkspaceRevisions({ boardId, subjects, onChange, onAccessLost }: {
  boardId: string | undefined;
  subjects: WorkspaceSubjectRef[];
  onChange: (change: WorkspaceChange) => void;
  onAccessLost: () => void;
}) {
  const client = useApiClient();
  const api = useDashboardApi();
  const callbacks = useRef({ onChange, onAccessLost });
  callbacks.current = { onChange, onAccessLost };
  const [state, setState] = useState<WorkspaceSyncState>('connecting');
  const identity = JSON.stringify(subjects);
  useEffect(() => {
    if (!boardId || subjects.length === 0) return;
    let byBoard = watches.get(client);
    if (!byBoard) { byBoard = new Map(); watches.set(client, byBoard); }
    let watch = byBoard.get(boardId);
    if (!watch) {
      watch = new WorkspaceRevisionWatch(boardId, api.getWorkspaceRevisions, isCurrent => {
        // A subject-read denial does not imply loss of Board access. Confirm
        // through its native read before removing shell/navigation caches.
        void api.getBoard(boardId).catch(error => {
          if (isCurrent() && error instanceof AuthenticatedFetchError
            && [401, 403, 404].includes(error.status)) {
            useDashboardStore.getState().removeInaccessibleBoard(boardId);
          }
        });
      });
      byBoard.set(boardId, watch);
    }
    return watch.subscribe({
      subjects: JSON.parse(identity) as WorkspaceSubjectRef[],
      onChange: change => callbacks.current.onChange(change),
      onState: setState,
      onAccessLost: () => callbacks.current.onAccessLost(),
    });
  }, [client, api, boardId, identity]);
  return state;
}

