function renderBusinessRules(rules: BusinessRule[] | null | undefined, refs?: SpecReferenceIndex): string {
  if (!rules?.length) return '';
  const items = rules.map((br, i) => {
    let entry = `### ${i + 1}. ${br.title}\n\n`;
    entry += renderKeyValues([
      ['ID', br.id],
      ['Status', br.status],
    ]);
