/** Generate Markdown for a Spec. */
export function exportSpec(spec: Spec): string {
  const warningCollector = createExportWarningCollector();
  const refs = buildSpecReferenceIndex(spec);
  let md = `# ${spec.title}\n\n`;

  md += metaTable([
    ['Status', spec.status],
    ['Edition', `v${spec.edition}`],
    ['Technical revision', `r${spec.version}`],
    ['Assignee', spec.assignee_id || ''],
    ['Created', fmtDate(spec.created_at)],
    ['Updated', fmtDate(spec.updated_at)],
    ['Labels', spec.labels?.join(', ') || ''],
  ]);

  md += section('Description', spec.description);
  md += section('Context', spec.context);
  md += renderKnowledgeResourceCounts(spec);

  let body = '';

  if (spec.functional_requirements?.length) {
    body += `## Functional Requirements\n\n${numberedList(excludeRevoked(spec.functional_requirements))}\n\n`;
  }
  body += renderTechnicalRequirements(spec.technical_requirements, refs);
  if (spec.acceptance_criteria?.length) {
    body += `## Acceptance Criteria\n\n${numberedList(excludeRevoked(spec.acceptance_criteria))}\n\n`;
  }

  body += renderResolvedReferences((spec as any).resolved_references);
  body += renderTestScenarios(spec.test_scenarios, spec.acceptance_criteria, warningCollector, refs);
  body += renderBusinessRules(spec.business_rules, refs);
  body += renderApiContracts(spec.api_contracts, refs);
  body += renderIntegrationRequirements(spec.integration_requirements, refs);
  body += renderObservabilityRequirements(spec.observability_requirements, refs);
  body += renderDecisions(spec.decisions, refs);
  body += renderKnowledgeBases([
    ...knowledgeWorkspaceItems(spec),
    ...(spec.knowledge_bases || []),
  ]);
  body += renderMockups(spec.screen_mockups, warningCollector);
  body += renderArchitectureDesigns(spec.architecture_designs, warningCollector);
  body += renderQA(spec.qa_items || []);

  md += renderExportWarnings(warningCollector.toArray());
  md += body;

  return md;
}

/** Generate Markdown for a Card/Task, resolving spec references. */
export function exportCard(card: Card, spec?: Spec | null): string {
  const warningCollector = createExportWarningCollector();
  const refs = spec ? buildSpecReferenceIndex(spec) : undefined;
  const isBug = card.card_type === 'bug';
  const typeLabel = cardTypeLabel(card);
  let md = `# ${isBug ? '[BUG] ' : ''}${card.title}\n\n`;

  md += metaTable([
    ['Status', STATUS_LABELS[card.status]],
    ['Priority', card.priority !== 'none' ? card.priority : ''],
    ['Type', typeLabel],
    ['Assignee', card.assignee_id || ''],
    ['Created', fmtDate(card.created_at)],
    ['Updated', fmtDate(card.updated_at)],
    ['Due date', card.due_date ? fmtDate(card.due_date) : ''],
    ['Labels', card.labels?.join(', ') || ''],
  ]);

  md += section('Description', card.description);
  md += section('Details', card.details);
  md += renderKnowledgeResourceCounts(card);

  let body = '';
  const cardKnowledgeForExport: unknown[] = [
    ...knowledgeWorkspaceItems(card),
  ];

  body += renderCardDependencies(card);
  body += renderTestCardDetails(card);

  if (card.status === 'rejected' && card.card_type !== 'test') {
    const currentRejectionRecord = (card.rejection_records || []).find(
      (record) => (
        record.kind === card.current_rejection_kind
        && record.id === card.current_rejection_id
      ),
    );
    const sourceValidationId = currentRejectionRecord?.source_id;
    const currentAttempt = [...(card.validations || [])]
      .reverse()
      .find((validation) => validation.id === sourceValidationId)
      || [...(card.validations || [])]
        .reverse()
        .find((validation) => (
          validation.card_status === 'rejected'
          || validation.completion_outcome === 'rejected'
          || validation.outcome === 'failed'
          || validation.recommendation === 'reject'
        ));
    body += '## Rework Required\n\n';
    body += card.current_rejection_summary
      || currentAttempt?.rejection_cause?.summary
      || currentAttempt?.general_justification
      || 'The latest governed completion attempt did not pass.';
    if (currentAttempt?.completion_gate_failures?.length) {
      body += '\n\n**Completion gates requiring action:**\n\n';
      body += currentAttempt.completion_gate_failures.map((failure) => {
        const reasons = failure.reason_codes?.length
          ? ` (${failure.reason_codes.join(', ')})`
          : '';
        return `- **${failure.code}:** ${failure.summary}${reasons}`;
      }).join('\n');
    }
    body += '\n\nMove this card to In Progress, complete a new execution attempt, and record a new handoff before returning it to Validation.\n\n';
    if (currentAttempt?.threshold_violations?.length) {
      body += `**Thresholds not met:**\n\n${currentAttempt.threshold_violations.map((violation) => `- ${violation}`).join('\n')}\n\n`;
    }
  }

  // Bug-specific fields
  if (isBug) {
    let bugSection = `## Bug Details\n\n`;
    bugSection += `**Severity:** ${card.severity || 'unknown'}\n\n`;
    if (card.origin_task_id) {
      const origin = refs?.tasks.get(card.origin_task_id);
      bugSection += `**Origin task:** ${origin ? referenceLabel(origin) : card.origin_task_id}\n\n`;
    }
    if (card.expected_behavior) bugSection += `### Expected Behavior\n\n${card.expected_behavior}\n\n`;
    if (card.observed_behavior) bugSection += `### Observed Behavior\n\n${card.observed_behavior}\n\n`;
    if (card.steps_to_reproduce) bugSection += `### Steps to Reproduce\n\n${card.steps_to_reproduce}\n\n`;
    if (card.action_plan) bugSection += `### Action Plan\n\n${card.action_plan}\n\n`;
    if (card.linked_test_task_ids?.length) {
      bugSection += renderLinkedReferences('Linked test tasks', card.linked_test_task_ids as any, refs?.tasks);
    }
    body += bugSection;
  }

  // Conclusions
  if (card.conclusions?.length) {
    const entries = card.conclusions.map((c: ConclusionEntry, i: number) => {
      let e = `### Conclusion ${i + 1}\n\n${c.text}\n\n`;
      if (c.author_id) e += `*Author: ${c.author_id} | ${fmtDate(c.created_at)}*\n\n`;
      if (c.completeness != null) e += `**Completeness:** ${c.completeness}%${c.completeness_justification ? ` — ${c.completeness_justification}` : ''}\n\n`;
      if (c.drift != null) e += `**Drift:** ${c.drift}%${c.drift_justification ? ` — ${c.drift_justification}` : ''}\n\n`;
      if (c.source) e += `**Source:** ${c.source}\n\n`;
      return e;
    }).join('');
    body += `## Conclusions\n\n${entries}`;
  }

  // Validations
  if (card.validations?.length) {
    const entries = card.validations.map((v: ValidationEntry, i: number) => {
      const passed = v.outcome === 'success';
      const completionRejected = v.completion_outcome === 'rejected';
      const completeness = v.estimated_completeness;
      const drift = v.estimated_drift;
      const reviewerName = v.reviewer_name;
      const resultLabel = completionRejected && passed
        ? 'ASSESSMENT PASSED — COMPLETION REJECTED'
        : passed ? 'PASSED' : 'FAILED';
      let e = `### Validation ${i + 1} — ${resultLabel}\n\n`;
      e += `| Metric | Score |\n|--------|-------|\n`;
      e += `| Confidence | ${v.confidence} |\n`;
      e += `| Completeness | ${completeness ?? 'Not reported'} |\n`;
      e += `| Drift | ${drift ?? 'Not reported'} |\n\n`;
      const summary = v.general_justification;
      if (summary) e += `**Summary:** ${summary}\n\n`;
      if (v.completion_gate_failures?.length) {
        e += '**Completion gates requiring action:**\n\n';
        e += `${v.completion_gate_failures.map((failure) => {
          const reasons = failure.reason_codes?.length
            ? ` (${failure.reason_codes.join(', ')})`
            : '';
          return `- **${failure.code}:** ${failure.summary}${reasons}`;
        }).join('\n')}\n\n`;
      }
      e += reviewerName
        ? `*Reviewer: ${reviewerName} | ${fmtDate(v.created_at)}*\n\n`
        : `*Recorded: ${fmtDate(v.created_at)}*\n\n`;
      return e;
    }).join('');
    body += `## Validations\n\n${entries}`;
  }

  // Dependencies
  // Note: Card type doesn't include dependency data directly; we show what we have
  // from comments/QA context

  const explicitResolvedRefs = (card as any).resolved_references;
  body += renderResolvedReferences(explicitResolvedRefs);

  // Resolved spec context
  if (spec && !explicitResolvedRefs) {
    body += `---\n\n## Spec Context: ${spec.title}\n\n`;

    // Linked test scenarios (resolve from IDs)
    let linkedScenarios: TestScenario[] = [];
    if (card.test_scenario_ids?.length && spec.test_scenarios?.length) {
      linkedScenarios = spec.test_scenarios.filter(ts => card.test_scenario_ids!.includes(ts.id));
      if (linkedScenarios.length) {
        body += renderTestScenarios(linkedScenarios, spec.acceptance_criteria, warningCollector, refs);
      }
      const foundIds = new Set(linkedScenarios.map((ts) => ts.id));
      for (const scenarioId of card.test_scenario_ids) {
        if (!foundIds.has(scenarioId)) {
          warningCollector.add({
            kind: 'broken_link',
            severity: 'medium',
            origin: `card:${card.id}:test_scenario_ids`,
            source_ref: scenarioId,
            message: `Linked test scenario could not be resolved: ${scenarioId}`,
          });
        }
      }
    } else if (card.test_scenario_ids?.length) {
      for (const scenarioId of card.test_scenario_ids) {
        warningCollector.add({
          kind: 'unresolved_reference',
          severity: 'medium',
          origin: `card:${card.id}:test_scenario_ids`,
          source_ref: scenarioId,
          message: `Linked test scenario was exported as raw id because parent spec context is unavailable: ${scenarioId}`,
        });
      }
    }

    if (spec.functional_requirements?.length) {
      body += `## Functional Requirements\n\n${numberedList(excludeRevoked(spec.functional_requirements))}\n\n`;
    }
    body += renderTechnicalRequirements(spec.technical_requirements, refs);
    if (spec.acceptance_criteria?.length) {
      body += `## Acceptance Criteria\n\n${numberedList(excludeRevoked(spec.acceptance_criteria))}\n\n`;
    }

    const linkedBusinessRules = (spec.business_rules || []).filter((item: any) => item.linked_task_ids?.includes(card.id));
    const linkedContracts = (spec.api_contracts || []).filter((item: any) => item.linked_task_ids?.includes(card.id));
    const linkedIRs = (spec.integration_requirements || []).filter((item: any) => item.linked_task_ids?.includes(card.id));
    const linkedORs = (spec.observability_requirements || []).filter((item: any) => item.linked_task_ids?.includes(card.id));
    const linkedDecisions = (spec.decisions || []).filter((item: any) => item.linked_task_ids?.includes(card.id));
    body += renderBusinessRules(
      linkedBusinessRules.length ? linkedBusinessRules : spec.business_rules,
      refs
    );
    body += renderApiContracts(linkedContracts.length ? linkedContracts : spec.api_contracts, refs);
    body += renderIntegrationRequirements(linkedIRs.length ? linkedIRs : spec.integration_requirements, refs);
    body += renderObservabilityRequirements(linkedORs.length ? linkedORs : spec.observability_requirements, refs);
    body += renderDecisions(linkedDecisions.length ? linkedDecisions : spec.decisions, refs);
    cardKnowledgeForExport.push(
      ...knowledgeWorkspaceItems(spec),
      ...(spec.knowledge_bases || []),
    );
    body += renderMockups(spec.screen_mockups, warningCollector);
    body += renderArchitectureDesigns(spec.architecture_designs, warningCollector);
  }

  // Render the parent and card snapshots as logical root/version items. This
  // retains every physical reference while printing each body only once.
  cardKnowledgeForExport.push(
    ...(card.knowledge_bases || []),
  );
  body += renderKnowledgeBases(cardKnowledgeForExport, 'Card Knowledge Bases');

  body += renderMockups(card.screen_mockups, warningCollector);
  body += renderArchitectureDesigns(card.architecture_designs, warningCollector);
  body += renderCardAttachments(card);
  body += renderQA(card.qa_items || []);

  // Comments
  if (card.comments?.length) {
    const entries = card.comments.map(c =>
      `**${c.author_id || 'Unknown'}** (${fmtDate(c.created_at)}):\n\n${c.content}\n`
    ).join('\n---\n\n');
    body += `## Comments\n\n${entries}\n`;
  }

  md += renderExportWarnings(warningCollector.toArray());
  md += body;

  return md;
}

