function createDashboardApi(apiClient: ReturnType<typeof useApiClient>) {
  // Selectors need all candidates; the transport always uses the same page envelope.
  async function collectListPages<T>(path: string, params: URLSearchParams): Promise<T[]> {
    const items: T[] = [];
    let offset = 0;
    while (true) {
      params.set('offset', String(offset));
      params.set('limit', '100');
      const page = await apiClient.fetchJson<PageEnvelope<T>>(`${path}?${params.toString()}`);
      if (!Array.isArray(page.items) || page.offset !== offset || page.limit !== 100) {
        throw new Error('Invalid list page response');
      }
      items.push(...page.items);
      offset += page.items.length;
      if (offset >= page.total_filtered) return items;
      if (page.items.length === 0) throw new Error('Incomplete list page response');
    }
  }

  return {
    // ==================== QUALITY ASSESSMENTS ====================

    async getCurrentQualityAssessment(
      subjectType: QualitySubjectType,
      subjectId: string,
      assessmentKind: QualityAssessmentKind,
      signal?: AbortSignal,
      subjectEdition?: number,
    ): Promise<CurrentQualityAssessment | null> {
      const params = new URLSearchParams({ assessment_kind: assessmentKind });
      if (subjectEdition !== undefined) {
        params.set('subject_edition', String(subjectEdition));
      }
      try {
        return await apiClient.fetchJson<CurrentQualityAssessment>(
          `${qualitySubjectPath(subjectType, subjectId)}/quality-assessments/current?${params.toString()}`,
          { signal },
        );
      } catch (error) {
        const details = (
          error instanceof AuthenticatedFetchError
          && typeof error.details === 'object'
          && error.details !== null
        )
          ? error.details as Record<string, unknown>
          : null;
        const reasonCode = error instanceof AuthenticatedFetchError
          ? (error.code === 'assessment_current_not_found'
              ? error.code
              : details?.reason_code)
          : null;
        if (
          error instanceof AuthenticatedFetchError
          && error.status === 404
          && reasonCode === 'assessment_current_not_found'
        ) {
          return null;
        }
        throw error;
      }
    },

    async listQualityAssessments(
      subjectType: QualitySubjectType,
      subjectId: string,
      options: QualityAssessmentPageWindow,
    ): Promise<PageEnvelope<QualityAssessmentListItem>> {
      const params = qualityPageParams(options);
      if (options.assessmentKind) {
        params.set('assessment_kind', options.assessmentKind);
      }
      if (options.state) params.set('state', options.state);
      if (options.subjectEdition !== undefined) {
        params.set('subject_edition', String(options.subjectEdition));
      }
      return apiClient.fetchJson<PageEnvelope<QualityAssessmentListItem>>(
        `${qualitySubjectPath(subjectType, subjectId)}/quality-assessments?${params.toString()}`,
        { signal: options.signal },
      );
    },

